#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define LTE_PHY_RX_TARGET 100
#define MAX_RSSI_THRESHOLD 255
#define MIN_RSSI_THRESHOLD 0

typedef struct {
    LTE_TARGET_RB target_rb;
    LTE_TARGET_TIME_INSTANCE target_time_instance;
    size_t num_subframes;
    LTE_RX_SUBFRAME_INFO *subframe_info;
} LTE_PHY_RX_TARGET_STRUCT;

LTE_PHY_RX_TARGET_STRUCT* initialize_dynamic_array() {
    srand(time(NULL));
    size_t max_subframes = (MAX_RSSI_THRESHOLD - MIN_RSSI_THRESHOLD + 1);
    LTE_PHY_RX_TARGET_STRUCT* targets = malloc(LTE_PHY_RX_TARGET * sizeof(LTE_PHY_RX_TARGET_STRUCT));

    for (size_t i = 0; i < LTE_PHY_RX_TARGET; ++i) {
        size_t rssi_threshold = MIN_RSSI_THRESHOLD + rand() % max_subframes;
        targets[i].num_subframes = rssi_threshold;
        targets[i].subframe_info = malloc(rssi_threshold * sizeof(LTE_RX_SUBFRAME_INFO));
    }

    return targets;
}

void update_dynamic_array(LTE_PHY_RX_TARGET_STRUCT* targets, size_t index, LTE_RX_SUBFRAME_INFO new_subframe) {
    if (index >= LTE_PHY_RX_TARGET || index < 0)
        return;

    size_t rssi_threshold = targets[index].num_subframes;
    if (targets[index].subframe_info[rssi_threshold - 1] != new_subframe) {
        targets[index].subframe_info[rssi_threshold - 1] = new_subframe;

        size_t current_size = targets[index].num_subframes;
        while (current_size > new_subframe.rssi && current_size != 0) {
            --current_size;
            targets[index].subframe_info = realloc(targets[index].subframe_info, current_size * sizeof(LTE_RX_SUBFRAME_INFO));
        }
    }
}

void free_dynamic_array(LTE_PHY_RX_TARGET_STRUCT* targets) {
    for (size_t i = 0; i < LTE_PHY_RX_TARGET; ++i) {
        free(targets[i].subframe_info);
    }
    free(targets);
}
```

