#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    unsigned char flag;
} Record;

struct slab_cache {
    void *slabs[128];
    size_t size;
};

struct slab {
    Record records[1024];
    size_t count;
};

void *slab_allocate(struct slab_cache *cache, size_t size) {
    for (size_t i = 0; i < cache->size; ++i) {
        if (!cache->slabs[i]) {
            void *slab = malloc(sizeof(struct slab));
            if (!slab) return NULL;
            memcpy(slab, cache->slabs[0], sizeof(struct slab));
            cache->slabs[0] = slab;
            (static_cast<struct slab*>(slab))->count = 0;
            continue;
        }
        if ((static_cast<struct slab*>(cache->slabs[i]))->count) {
            Record *rec = &((static_cast<struct slab*>(cache->slabs[i]))->records[(static_cast<struct slab*>(cache->slabs[i]))->count - 1]);
            if (!rec->flag) {
                rec->flag = 1;
                return rec;
            }
        }
    }
    return NULL;
}

void *record_init(Record* record, int value, unsigned char flag) {
    record->value = value;
    record->flag = flag;
    return record;
}

pthread_mutex_t lock;
int threshold = 0;
int min_value = 0;
int max_value = 0;

void generate_records(struct slab_cache *cache) {
    pthread_mutex_lock(&lock);
    int cumulative_sum = 0;
    while (cumulative_sum < threshold) {
        Record *record = static_cast<Record*>(slab_allocate(cache));
        if (!record) break;
        record->value = rand() % (max_value - min_value + 1) + min_value;
        cumulative_sum += record->value;
    }
    pthread_mutex_unlock(&lock);
}

int main(void) {
    srand(time(NULL));

    struct slab_cache cache = { 0 };
    cache.size = sizeof(struct slab) / sizeof(Record);

    pthread_mutex_init(&lock, NULL);

    threshold = 1000;
    min_value = 0;
    max_value = 100;

    generate_records(&cache);

    // Use the records here as needed.

    pthread_mutex_destroy(&lock);
    return 0;
}
```

This code creates a slab allocation system for managing records, with a mutex lock to ensure thread safety during record generation. The `generate_records()` function populates the records with random values within a specified range and ensures that the cumulative sum of all active records' values does not exceed the predefined threshold. The code also includes basic support for handling memory allocation failures by reallocating smaller chunks of memory when necessary. The data structures are optimized for performance under heavy load conditions, considering cache locality and data access patterns."]

