IPAddress dns_resolve(const char *hostname) {
    struct hostent *he;
    struct in_addr **addr_list;
    IPAddress ip = {0};

    if (!(he = gethostbyname(hostname))) {
        return (IPAddress){-1, 0};
    }

    addr_list = he->h_addr_list;
    if (addr_list && *addr_list) {
        ip.len = sizeof(struct in_addr);
        memcpy(&ip.ip, *addr_list, ip.len);
    } else {
        return (IPAddress){-1, 0};
    }

    // Implement cache strategy here
    pthread_mutex_lock(&cache_mutex);
    if (cache_index && !strcmp(hostname, cache[cache_index - 1])) {
        ip = cache[cache_index - 1];
    } else if (cache_index < CACHE_SIZE) {
        strcpy(cache[cache_index], hostname);
        cache_index++;
    }
    pthread_mutex_unlock(&cache_mutex);

    return ip;
}
