#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <sys/socket.h>
#include <unistd.h>

typedef struct {
    int capacity;
    int size;
    int *data;
} IntArray;

IntArray *create_int_array(size_t capacity) {
    IntArray *arr = malloc(sizeof(IntArray));
    arr->capacity = capacity;
    arr->size = 0;
    arr->data = calloc(capacity, sizeof(int));
    return arr;
}

void destroy_int_array(IntArray *arr) {
    free(arr->data);
    free(arr);
}

int is_integer(const char *str) {
    if (*str == '\0') return 0;
    for (const char *p = str; *p != '\0'; ++p) {
        if (*p < '0' || *p > '9') return 0;
    }
    return 1;
}

int deserialize_integer(const char *str, size_t len) {
    int num = 0;
    for (size_t i = 0; i < len; ++i) {
        num = num * 10 + (*(str + i) - '0');
    }
    return num;
}

int filter_and_find_largest(IntArray *arr, int (*deserialize)(const char *, size_t)) {
    int largest = INT_MIN;
    for (int i = 0; i < arr->size; ++i) {
        int num = deserialize((char *)&arr->data[i], sizeof(int));
        if (is_integer((char *)&num)) {
            largest = fmax(largest, num);
        }
    }
    return largest;
}

void* process_stream(void *arg) {
    IntArray *arr = arg;
    char buffer[4096]; // Adjust buffer size as needed for serialization format
    ssize_t bytes_received;
    while ((bytes_received = recv((socket_fd), buffer, sizeof(buffer), 0)) > 0) {
        const char *start = memchr(buffer, '{', bytes_received);
        if (start == NULL) continue; // Ignore non-JSON data
        size_t length = strcspn(start + 1, "}");
        if (length >= sizeof(buffer) - (start - buffer)) continue; // Ignore too large JSON objects

        char *end = start + length + 1;
        int num = deserialize(start + 1, end - start - 1);
        if (is_integer(start + 1)) {
            arr->data[arr->size++] = num;
        }
    }
    return NULL;
}

int process_list(int socket_fd) {
    IntArray *arr = create_int_array(1000);
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, process_stream, (void *) arr);

    char buffer[4096];
    ssize_t bytes_received;
    while ((bytes_received = recv(socket_fd, buffer, sizeof(buffer), 0)) > 0) {
        const char *start = memchr(buffer, '{', bytes_received);
        if (start == NULL) continue; // Ignore non-JSON data
        size_t length = strcspn(start + 1, "}");
        if (length >= sizeof(buffer) - (start - buffer)) continue; // Ignore too large JSON objects

        char *end = start + length + 1;
        int num = deserialize(start + 1, end - start - 1);
        if (is_integer(start + 1)) {
            pthread_mutex_lock(&arr->mutex);
            arr->data[arr->size++] = num;
            pthread_mutex_unlock(&arr->mutex);
        }
    }

    pthread_join(thread_id, NULL);
    destroy_int_array(arr);

    int largest = filter_and_find_largest(arr, deserialize_integer);
    if (arr->size == 0) {
        printf("No valid integers provided\n");
        return -1;
    }
    printf("Largest integer: %d\n", largest);
    return 0;
}
