```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/aes.h>
#include <semaphore.h>
#include <syslog.h>

/* Global variables */
static sem_t lock;
static int num_keys = 0;
AES_KEY *keys;
unsigned char *ivs;

typedef struct {
    unsigned char *key;
    unsigned char *iv;
} EncryptionContext;

/* Logging function */
void custom_log(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(priority, format, args);
    va_end(args);
}

void aes_encrypt(const unsigned char *input, unsigned char *output, const unsigned char *key, const unsigned char *iv) {
    AES_KEY encryptKey;
    AES_set_encrypt_key(key, 256, &encryptKey);
    AES_cbc_encrypt(input, output, AES_BLOCK_SIZE, &encryptKey, iv, AES_ENCRYPT);
}

void aes_decrypt(const unsigned char *input, unsigned char *output, const unsigned char *key, const unsigned char *iv) {
    AES_KEY decryptKey;
    AES_set_encrypt_key(key, 256, &decryptKey);
    AES_cbc_encrypt(input, output, AES_BLOCK_SIZE, &decryptKey, iv, AES_DECRYPT);
}

EncryptionContext *create_context(const unsigned char *key, const unsigned char *iv) {
    EncryptionContext *ctx = (EncryptionContext *) malloc(sizeof(EncryptionContext));
    ctx->key = key;
    ctx->iv = iv;
    return ctx;
}

void destroy_context(EncryptionContext **ctx) {
    free(*ctx);
    *ctx = NULL;
}

/* Thread-safe function to get a context */
EncryptionContext *get_context() {
    sem_wait(&lock);
    EncryptionContext *ctx;

    if (num_keys == 0) {
        ctx = create_context(/* your key retrieval function here */ , /* your IV generation function here */ );
        keys = realloc(keys, ++num_keys * sizeof(AES_KEY));
        ivs = realloc(ivs, num_keys * AES_BLOCK_SIZE);
        memcpy(&keys[num_keys - 1], &encryptKey, sizeof(AES_KEY));
        memcpy(&ivs[num_keys - 1], ctx->iv, AES_BLOCK_SIZE);
    } else {
        ctx = &(keys[num_keys - 1]);
    }

    sem_post(&lock);
    return ctx;
}
```

