void processVector(std::vector<int>& vec, int searchVal, int replaceVal, int appendedVal) {
    auto it = std::find(vec.begin(), vec.end(), searchVal);
    if (it != vec.end()) {
        vec.erase(it);
        vec.insert(it, replaceVal);
    } else {
        vec.emplace_back(appendedVal);
    }
}
