using System;
using System.IO;
using System.Xml;
using System.Linq;
using System.Environment;
using System.Threading;
using System.Threading.Tasks;
using System.Text.RegularExpressions;

public class DirectoryManager
{
    private const string ConfigPathVariableName = "MyConfigPath";
    private const int RetryIntervalMilliseconds = 1000;
    private static readonly Regex ElementMatcher = new Regex("<(.*?)\\s+/>", RegexOptions.Compiled | RegexOptions.IgnoreCase);

    public string CreateDirectoryAndGetConfigValue(string parentFolder, string directoryName, string xpath)
    {
        var configPath = GetConfigPath();

        if (!string.IsNullOrEmpty(configPath))
        {
            Directory.CreateDirectory(Path.Combine(configPath, directoryName));
        }
        else
        {
            Directory.CreateDirectory(Path.Combine(parentFolder, directoryName));
            Environment.SetEnvironmentVariable(ConfigPathVariableName, parentFolder);
        }

        var fullPath = Path.Combine(GetConfigPath(), directoryName);

        Task.Run(() =>
        {
            while (true)
            {
                if (Directory.Exists(fullPath))
                {
                    break;
                }

                Thread.Sleep(RetryIntervalMilliseconds);
            }
        });

        var xmlDocument = new XmlDocument();
        using (var reader = XmlReader.Create(Path.Combine(fullPath, "config.xml")))
        {
            xmlDocument.Load(reader);
        }

        var element = xmlDocument.SelectSingleNode(xpath);

        if (element == null)
        {
            Console.WriteLine($"No element found with xpath: {xpath}");
        }
        else if (xmlDocument.SelectNodes(xpath).Count > 1)
        {
            Console.WriteLine($"Multiple elements found with xpath: {xpath}");
        }

        return element != null ? ElementMatcher.Match(element.OuterXml).Groups[1].Value : string.Empty;
    }

    private static string GetConfigPath() => Environment.GetEnvironmentVariable(ConfigPathVariableName);
}
```']

