import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;

public class StringHashUtil {

    public static final int MAX_STRING_LENGTH = 1024;

    // Custom exception class for input validation errors
    public static class InvalidInputException extends Exception {
        public InvalidInputException(String message) {
            super(message);
        }
    }

    private static MessageDigest getMessageDigest() {
        try {
            return MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    public static String md5Hash(String input) {
        if (input == null || input.length() > MAX_STRING_LENGTH) {
            throw new InvalidInputException("Invalid input: " + input);
        }
        byte[] bytes = getMessageDigest().digest(input.getBytes());
        BigInteger bigInteger = new BigInteger(1, bytes);
        StringBuilder sb = new StringBuilder(bigInteger.toString(16));
        while (sb.length() < 32) {
            sb.insert(0, '0');
        }
        return sb.toString();
    }

    public static String concatAndMd5Hash(List<String> strings) {
        StringBuilder stringBuilder = new StringBuilder();
        for (String str : strings) {
            if (str == null || str.length() > MAX_STRING_LENGTH) {
                throw new InvalidInputException("Invalid input: " + str);
            }
            stringBuilder.append(str);
        }
        return md5Hash(stringBuilder.toString());
    }

