        $this->db = $db;
        $this->apiSource = $apiSource;
        $this->cache = $cache;
    }

    public function processRequest() {
        $data = json_decode(file_get_contents('php://input'), true);

        if (!isset($data['name']) || strlen($data['name']) < 2 ||
            !isset($data['email']) || !filter_var($data['email'], FILTER_VALIDATE_EMAIL) ||
            !isset($data['password']) || !preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/', $data['password']) ||
            (!isset($data['id']) && !isset($data['sub_action']))) {
                return json_encode(['message' => 'error', 'details' => ['invalid input']]);
        }

        $userId = isset($data['id']) ? (int)$data['id'] : null;
        $subAction = isset($data['sub_action']) ? $data['sub_action'] : '';

        if ($this->cache->hasUser($userId)) {
            $userData = $this->cache->getUser($userId);
        } else {
            $userData = $this->db->fetchUserById($userId);

            if (!$userData) {
                if ($this->apiSource->isValidEmail($data['email'])) {
                    $userData = $this->apiSource->getUserByEmail($data['email']);
                }
            }

            if (!$userData) {
                $this->cache->storeUser($userId, []);
                return json_encode(['message' => 'error', 'details' => ['user not found']]);
            }

            $this->cache->storeUser($userId, $userData);
        }

        if ($subAction === 'update') {
            if (!isset($data['name']) || strlen($data['name']) < 2 ||
                !filter_var($data['email'], FILTER_VALIDATE_EMAIL) ||
                !preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/', $data['password'])) {
                    return json_encode(['message' => 'error', 'details' => ['invalid input']]);
            }

            if ($this->apiSource->isValidEmail($data['email']) && $userData['email'] !== $data['email']) {
                if ($this->db->getUserByEmail($data['email'])) {
                    return json_encode(['message' => 'error', 'details' => ['email already in use']]);
                }
            }

            try {
                $this->db->beginTransaction();
                $affectedRows = $this->db->updateUser(
                    $userId,
                    [
                        'name' => $data['name'],
                        'email' => $data['email'],
                        'password' => password_hash($data['password'], PASSWORD_DEFAULT),
                        'version' => $userData['version'] + 1
                    ]
                );
                if ($affectedRows === 0) {
                    throw new Exception('Failed to update user');
                }
                $this->db->commit();
            } catch (Exception $e) {
                $this->db->rollback();
                return json_encode(['message' => 'error', 'details' => ['database error: ' . $e->getMessage()]]);
            }
        } elseif ($subAction === 'delete') {
            try {
                $this->db->beginTransaction();
                $affectedRows = $this->db->deleteUser($userId);
                if ($affectedRows === 0) {
                    throw new Exception('Failed to delete user');
                }
                $this->db->commit();
            } catch (Exception $e) {
                $this->db->rollback();
                return json_encode(['message' => 'error', 'details' => ['database error: ' . $e->getMessage()]]);
            }
        } else {
            try {
                $this->db->beginTransaction();
                if ($this->apiSource->isValidEmail($data['email'])) {
                    $userData['email'] = $data['email'];
                }
                $affectedRows = $this->db->saveUser(
                    [
                        'id' => $userId,
                        'name' => $data['name'],
                        'email' => $userData['email'],
                        'password' => password_hash($data['password'], PASSWORD_DEFAULT),
                        'version' => 1
                    ]
                );
                if ($affectedRows === 0) {
                    throw new Exception('Failed to create user');
                }
                $this->db->commit();
            } catch (Exception $e) {
                $this->db->rollback();
                return json_encode(['message' => 'error', 'details' => ['database error: ' . $e->getMessage()]]);
            }
        }

        return json_encode(['message' => 'success']);
    }
}
```

