    private readonly ILogger<UpdateElementService> _logger;
    private readonly IDatabase _redisDatabase;
    private readonly IDistributedDatabase _distributedDatabase;
    private readonly ICachingLayer _cachingLayer;
    private readonly IElementService _elementService;

    public UpdateElementService(ILogger<UpdateElementService> logger, IDatabase redisDatabase, IDistributedDatabase distributedDatabase, ICachingLayer cachingLayer, IElementService elementService)
    {
        _logger = logger;
        _redisDatabase = redisDatabase;
        _distributedDatabase = distributedDatabase;
        _cachingLayer = cachingLayer;
        _elementService = elementService;
    }

    public async Task<HttpResponseMessage> UpdateElementAsync(string pageSectionId, string elementId, string htmlContent)
    {
        if (string.IsNullOrEmpty(pageSectionId))
            throw new ArgumentNullException(nameof(pageSectionId));
        if (string.IsNullOrEmpty(elementId))
            throw new ArgumentNullException(nameof(elementId));
        if (htmlContent?.Length > 100_000)
            throw new InvalidOperationException("HTML content cannot exceed 100,000 characters");

        // Validate and process input here...

        var validationResult = await _elementService.UpdateElementAsync(pageSectionId, elementId, htmlContent);
        if (!validationResult.Success)
            return new HttpResponseMessage(System.Net.HttpStatusCode.BadRequest) { Content = new StringContent(JsonSerializer.Serialize(validationResult)) };

        await _cachingLayer.UpdateCacheAsync(pageSectionId, elementId, htmlContent);
        await _redisDatabase.KeyDeleteAsync($"cache:_{pageSectionId}:_{elementId}"); // Invalidate cache

        var transaction = _distributedDatabase.CreateTransaction();
        try
        {
            await transaction.ExecuteAsync(async () =>
            {
                await _distributedDatabase.WriteEntryAsync("elements", pageSectionId, elementId, htmlContent);
                await _redisDatabase.KeyExpireAsync($"cache:_{pageSectionId}:_{elementId}", TimeSpan.FromMinutes(5)); // Cache expiration
            });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error while updating element in distributed database");
            throw;
        }

        return new HttpResponseMessage(System.Net.HttpStatusCode.OK);
    }
}
