const generateFooter = (scripts) => {
  let footerHTML = '<footer>\n';

  // Filter out invalid or malformed script objects
  const validScripts = scripts.filter(script => typeof script.id === 'string' && typeof script.type === 'string' && typeof script.code === 'string');

  if (validScripts.length === 0) {
    console.warn('No valid script objects found, skipping footer generation.');
    return footerHTML + '</footer>';
  }

  // Sort scripts by id to ensure consistent order and easier handling of concurrent updates
  validScripts.sort((a, b) => a.id - b.id);

  // Loop through the array of valid script objects and generate corresponding <script> tags
  validScripts.forEach(script => {
    footerHTML += `<script id="${script.id}" type="${script.type}">\n${script.code}\n</script>\n`;
  });

  // Close the footer tag
  footerHTML += '</footer>';

  return footerHTML;
};
