void processList(std::forward_list<std::string>& list, const std::string& resourceID, const std::string& url, const std::vector<std::string>& fieldNames) {
    auto iter = list.begin();
    bool inserted = false;

    // Optimized search using equal_range and forward iteration to avoid reallocation
    auto range = list.equal_range(resourceID);

    // Concurrent access protection using boost interprocess shared memory and synchronization primitives
    boost::interprocess::managed_shared_memory segment(boost::interprocess::create_only, 0x1000000, "JointData");
    boost::interprocess::containers::vector<bool> lock(segment, "Lock");
    int lockIndex = 0;

    for (auto it = range.first; it != range.second; ++it) {
        if (!lock[lockIndex]) {
            lock[lockIndex] = true;

            // Refresh dialog fields using AngularJS function
            angular::Scope scope(url);
            if (scope.exists(resourceID)) {
                auto refreshFunction = scope[resourceID].get<angular::Function>();
                if (refreshFunction) {
                    std::vector<std::string> fieldVec;
                    for (auto& field : fieldNames) {
