            }

            lock[lockIndex] = false;
        }

        if (it != list.begin()) {
            inserted = true;
            iter = it;
            break;
        }
    }

    // Insert the new string if not found earlier
    if (!inserted) {
        iter = list.insert_after(range.second, resourceID);
    }

    // Append the new string to the end of the list if no resource ID was found
