[" Here is a solution using `stream` and `util` modules from Node.js for merging multiple data streams:

```javascript
const { Transform, pipeline } = require('stream');
const { concat } = require('util');

class MergeStream extends Transform {
  constructor() {
    super({ objectMode: true });
    this.streams = [];
  }

  _transform(chunk, encoding, callback) {
    if (!this.isBuffering) {
      // Start buffering a new stream when the current one has been processed
      this.isBuffering = true;
      this.currentStream = new Transform({ objectMode: true });
      this.currentStream._transform = this.chunkHandler.bind(this);
      pipeline([this], this.currentStream, callback);
    }

    // Add the incoming chunk to the current buffer stream
    this.currentStream.push(chunk);
  }

  _flush(callback) {
    if (this.currentStream.length !== 0) {
      // Once the current stream is empty, add it to the master list of streams
      this.streams.push(this.currentStream);
    }
    this.isBuffering = false;
    callback();
  }

  mergeStreams() {
    const mergedChunk = concat(...this.streams);
    return Buffer.concat(mergedChunk);
  }

  chunkHandler(chunk, encoding, callback) {
    // Handle incoming chunks from sub streams and add them to the master buffer
    this.currentStream.push(chunk);
    if (this.currentStream.length === this.highWaterMark) {
      // Flush the current stream when it reaches the high water mark
      this._flush(callback);
    } else {
      callback();
    }
  }
}
```

This code defines a custom `MergeStream` class that extends the built-in `Transform` stream. The constructor initializes an empty array of streams, and the `_transform()` method handles incoming chunks by buffering them in a current stream until it reaches the high water mark (default 16 KB), at which point it is flushed to the master list of streams. The `mergeStreams()` method concatenates all the stored streams using `Buffer.concat()`.

Developers can instantiate this class and pipe multiple data streams into it, like so:

```javascript
const mergeStream = new MergeStream();
stream1.pipe(mergeStream);
stream2.pipe(mergeStream);
// ... repeat for additional streams

mergeStream.on('finish', function() {
  const mergedData = mergeStream.mergeStreams().toString('utf8');
