class PasswordUpdater {
    private $userRepository;
    private $identityProvider;
    private $logger;
    private $cache;

    public function __construct(UserRepository $userRepository, IdentityProvider $identityProvider, Logger $logger, Cache $cache) {
        $this->userRepository = $userRepository;
        $this->identityProvider = $identityProvider;
        $this->logger = $logger;
        $this->cache = $cache;
    }

    public function updatePassword($userId, $newPassword) {
        // Load user from cache first to reduce database load during peak hours
        $user = $this->cache->get('user_' . $userId);

        if (!$user) {
            $user = $this->userRepository->findById($userId);
            $this->cache->set('user_' . $userId, $user, 60); // Cache user for one minute
        }

        if ($this->passwordValidator->validatePasswordStrength($newPassword) !== true) {
            throw new InvalidArgumentException("Password strength is not valid.");
        }

        // Obtain a unique token to prevent concurrency issues
        $token = $this->concurrencyTokenManager->acquire();

        try {
            // Attempt to update the password with the acquired token, and handle external service failures using exponential backoff
            $this->updatePasswordInDB($user, $newPassword, $token);

            $this->identityProvider->verifyCredentials($userId, $token);

            // Log successful password update with timestamp and reason code
            $this->logger->log("PASSWORD_UPDATE", "Successfully updated user password.", array("user_id" => $userId));
        } catch (\Exception $e) {
            // Handle exceptions gracefully, providing meaningful feedback to the user
            if ($e instanceof ExternalServiceUnavailableException) {
                $message = "Error updating password. The external service is currently unavailable.";
            } elseif ($e instanceof ConcurrencyIssueException) {
                $message = "Error updating password. Another update is currently in progress.";
            } else {
                $message = "Error updating password: " . $e->getMessage();
            }

            // Log the error with timestamp and reason code for debugging purposes
            $this->logger->log("PASSWORD_UPDATE", $message, array("user_id" => $userId));
        } finally {
            // Release the token to allow other concurrent updates
            $this->concurrencyTokenManager->release($token);
        }
    }
}
```

