  switch (typeof item) {
    case 'number':
      return acc + item;
    case 'string':
      return acc + item.length;
    default:
      const result = {};
      for (const key in item) {
        result[key] = (result[key] || 0) + item[key];
      }
      return result;
  }
}, { concurrentLimit: 3 });
