#include <stddef.h>
#include <stdbool.h>
#include <string.h>
#include <stdio.h>

typedef struct {
    char paddingChar;
    bool overflowBehavior; // true for truncation, false for return NULL
    int logLevel;
} Config;

char* processString(const char *str, size_t limit, const Config *cfg) {
    size_t strLen = strlen(str);
    if (strLen > limit) return NULL;

    char *result = malloc(limit + 1); // +1 for null terminator
    if (!result) return NULL;

    if (strLen < limit) {
        memcpy(result, str, strLen);
        while (strlen(result) < limit) result[strlen(result)] = cfg->paddingChar;
    } else {
        if (cfg->overflowBehavior) {
            strncpy(result, str, limit - 1); // -1 for null terminator
            result[limit - 1] = '\0';
        } else return NULL;
    }
    result[strlen(result)] = '\0'; // ensure null terminator

    if (cfg->logLevel > 0) printf("Processed string: %s\n", result);
    return result;
}
