JavaScript:
```javascript
function Config(paddingChar, overflowBehavior, logLevel) {
    this.paddingChar = paddingChar || '/';
    this.overflowBehavior = overflowBehavior !== undefined ? overflowBehavior : true;
    this.logLevel = logLevel || 0;
}

Config.prototype.getPaddingChar = function() { return this.paddingChar };
Config.prototype.getOverflowBehavior = function() { return this.overflowBehavior };

function processString(str, limit, config) {
    if (!str || !limit || limit <= 0 || typeof limit !== 'number') throw new Error('Invalid arguments');

    let result = [];
    if (str.length > limit) return [];

    for (let i = 0; i < str.length; i++) {
        result[i] = str[i];
        if (result.length === limit && config.getOverflowBehavior()) {
            result[limit] = config.getPaddingChar();
        }
    }

    if (config.logLevel > 0) console.log(`Processed string: ${result.join('')}`);
    return result;
}

function traverseDOM(root, selector) {
    let matches = [];
    function traverse(node) {
        if (!node || node.nodeType !== Node.ELEMENT_NODE) return;

        let selectResult = document.querySelectorAll(selector).length > 0 ? true : false;
        if (selectResult && !matches.includes(node)) matches.push(node);

        for (let i = 0; i < node.childNodes.length; i++) traverse(node.childNodes[i]);
    }
    traverse(root);
    return matches;
}
