['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>
#include <openssl/md5.h>
#include <sys/mman.h>

typedef struct {
    uint16_t bits_per_sample;
    uint16_t sample_per_pixel;
    uint16_t photometric_interp;
    uint32_t planar_configuration;
    uint32_t compression;
    uint32_t pages_per_strip;
    uint32_t rows_per_strip;
    uint32_t strip_offsets;
    uint32_t strip_bytes;
    uint32_t min_sample_value;
    uint32_t max_sample_value;
    uint16_t num_extra_samples;
} TiffMetadata;

void* map_file(const char *filename, size_t *length) {
    FILE *fp = fopen(filename, "r");
    if (!fp) return NULL;
    fseek(fp, 0, SEEK_END);
    size_t filesize = ftell(fp);
    rewind(fp);
    void* mapped_data = mmap(NULL, filesize, PROT_READ, MAP_PRIVATE, fileno(fp), 0);
    fclose(fp);
    *length = filesize;
    return mapped_data;
}

int parse_tiff_metadata(const void* data, size_t length, TiffMetadata* metadata) {
    if (!TIFFGetFieldU16(data, TIFFTAG_SAMPLESPERPIXEL, &metadata->sample_per_pixel)) return -1;
    if (metadata->sample_per_pixel < 1 || metadata->sample_per_pixel > 8) return -2;

    if (!TIFFGetFieldU16(data, TIFFTAG_BITSPERSAMPLE, &metadata->bits_per_sample)) return -1;
    if (metadata->bits_per_sample < 1 || metadata->bits_per_sample > 16) return -3;

    if (!TIFFGetFieldU16(data, TIFFTAG_PHOTOMETRICINTERPRETATION, &metadata->photometric_interp)) return -1;
    if (!TIFFGetField(data, TIFFTAG_PLANARCONFIGURATION, &(metadata->planar_configuration))) return -1;
    if (!TIFFGetField(data, TIFFTAG_COMPRESSION, &(metadata->compression))) return -1;
    if (!TIFFGetField(data, TIFFTAG_ROWSPERSTRIP, &(metadata->rows_per_strip))) return -1;
    if (!TIFFGetField(data, TIFFTAG_STRIPOFFS, &(metadata->strip_offsets))) return -1;
    if (!TIFFGetField(data, TIFFTAG_STRIPBYTES, &(metadata->strip_bytes))) return -1;
    if (!TIFFGetField(data, TIFFTAG_MINSAMPLEVALUE, &metadata->min_sample_value)) return -1;
    if (!TIFFGetField(data, TIFFTAG_MAXSAMPLEVALUE, &metadata->max_sample_value)) return -1;

    if (TIFFGetFieldU16(data, TIFFTAG_NUMEREXTRASAMPLES, &(metadata->num_extra_samples))) {
        if (metadata->num_extra_samples > 8) return -4;
    } else metadata->num_extra_samples = 0;

    return 0;
}

char* tiff_md5(const void* data, size_t length) {
    unsigned char md5[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, data, length);
    MD5_Final(md5, &ctx);

    char* hash = malloc(sizeof(char) * 33); // 32 for the hash and one null character for the end
    snprintf(hash, sizeof(hash), "%02x%02x%02x%02x%02x%02x%02x%02x"
                               "%02x%02x%02x%02x%02x%02x%02x%02x",
             md5[0], md5[1], md5[2], md5[3], md5[4], md5[5], md5[6], md5[7]
             , md5[8], md5[9], md5[10], md5[11], md5[12], md5[13], md5[14], md5[15]);
    return hash;
}

TiffMetadata* parse_tiff(const char *filename) {
    void* data = map_file(filename, NULL);
    if (!data) return NULL;

    TiffMetadata metadata;
    int result = parse_tiff_metadata(data, strlen(data), &metadata);

    if (result < 0) {
        free(data);
        return NULL;
    }

    char* hash = tiff_md5(data, strlen(data));
    free(data);

    if (!hash) return NULL;

    TiffMetadata *metadata_result = malloc(sizeof(TiffMetadata));
    memcpy(metadata_result, &metadata, sizeof(TiffMetadata));
    metadata_result->num_extra_samples = result == 0 ? metadata.num_extra_samples : -1;
    metadata_result->MD5_hash = hash;

    return metadata_result;
}
```']

