int derive_key_and_init_aes(const unsigned char *password, size_t password_len) {
    SHA1_CTX sha_ctx;
    unsigned char key[32];
    unsigned char iv[AES_BLOCK_SIZE];

    SHA1Init(&sha_ctx);
    SHA1Update(&sha_ctx, password, password_len);
    SHA1Final(key, &sha_ctx);

