#include <muPDF/mupdf.h>

namespace fs = std::filesystem;

#define MAX_IMAGE_SIZE (100 * 1024 * 1024) // 100MB max image size

int convertImageToPdf(const std::string& jpegPath, const std::string& pdfPath) {
    std::string imgTool = "mogrify -format PDF image.jpeg"; // Example: ImageMagick command for converting JPEG to PDF
    std::string pdfValidator = "mupdf --check image.pdf";  // Example: MuPDF command for validating PDF structure
    std::string popplerValidator = "poppler-qcp image.pdf"; // Example: Poppler command for viewing the PDF

    fs::path jpegFile(jpegPath);
    fs::path pdfFile(pdfPath);

    if (!fs::exists(jpegFile) || !fs::is_regular_file(jpegFile)) {
        std::cerr << "Error: JPEG file does not exist or is not a regular file." << std::endl;
        return 1;
    }

    if (jpegFile.file_size() > MAX_IMAGE_SIZE) {
        std::cout << "Warning: The provided image file size exceeds the maximum allowed limit of " << MAX_IMAGE_SIZE / (1024 * 1024) << "MB, consider compressing the image." << std::endl;
    }

    int status = system(imgTool.c_str());
    if (status != 0) {
        std::cerr << "Error: Image conversion tool not found or unavailable." << std::endl;
        return 1;
    }

    status = system(pdfValidator.c_str());
    if (WEXITSTATUS(status) != 0) {
        std::cerr << "Error: The generated PDF file is malformed." << std::endl;
        remove(pdfPath.c_str()); // Remove the invalid PDF file
        return 1;
    }

    status = system(popplerValidator.c_str());
    if (WEXITSTATUS(status) != 0) {
        std::cerr << "Error: The generated PDF file is not compatible with standard PDF viewers." << std::endl;
        remove(pdfPath.c_str()); // Remove the invalid PDF file
        return 1;
    }

    status = system((std::string("cp ") + jpegPath + " " + pdfPath).c_str());
    if (status != 0) {
        std::cerr << "Error: Failed to copy the converted file." << std::endl;
        return 1;
