            {
                throw new ArgumentException("Illegal characters found in the provided site name.");
            }
        }

        var checkPermissionsTask = CheckAndApplyPermissionsAsync(directoryPath);
        await Task.WhenAll(checkPermissionsTask, ValidateSiteNameAsync(siteName));

        if (!checkPermissionsTask.Result)
        {
            return null;
        }

        const int maxRetries = 5;
        var processStarted = false;
        for (var i = 0; i < maxRetries || processStarted; ++i)
        {
            try
            {
                using (var hostingEnvironment = _webHostBuilder.CreateHostBuilder()
                    .SetBasePath(directoryPath)
                    .UseIISIntegration()
                    .ConfigureLogging((hostingBuilderContext, loggingBuilder) =>
                        loggingBuilder.AddConfiguration(_configuration))
                    .Build())
                {
                    hostingEnvironment.WebHost.RunAsync().Wait();
                    processStarted = true;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to start site '{siteName}'. Retrying...");
                await Task.Delay(_configuration["RetryDelay"]);
            }
        }

        if (!processStarted)
        {
            return null;
        }

        // Implement logging and external API notifications here.

        return siteName;
    }

    private async Task<bool> CheckAndApplyPermissionsAsync(string directoryPath)
    {
        var result = true;
        try
        {
            Directory.SetCurrentDirectory(directoryPath);
            if (!Directory.GetAccessControl(directoryPath).HasWritingPermission())
            {
                _logger.LogError($"The provided directory '{directoryPath}' does not have sufficient permissions for writing operations.");
                result = false;
