 }

 private void backupFile(Path source, Path targetDir) throws IOException {
 Path backupPath = targetDir.resolve(source.getFileName() + ".backup");
 Files.copy(source, backupPath);
 logger.info("Backed up file: " + source);
 }

 private void deleteFile(Path file) throws IOException {
 // Implement safe deletion logic here to minimize the risk of errors and ensure fault tolerance
 Files.deleteIfExists(file);
 }

 private String encrypt(String data) throws Exception {
 ByteArrayOutputStream out = new ByteArrayOutputStream();
 cipher.doFinal(data.getBytes(), out);
 return Base64.getEncoder().encodeToString(out.toByteArray());
 }

 private String decrypt(String data) throws Exception {
 byte[] bytes = Base64.getDecoder().decode(data);
 ByteArrayInputStream in = new ByteArrayInputStream(bytes);
 byte[] result = cipher.doFinal(in);
 return new String(result);
 }

 private void copyStreamToLogger(InputStream input, Consumer<String> consumer) {
 try (Scanner scanner = new Scanner(input)) {
 while (scanner.hasNextLine()) {
 consumer.accept(scanner.nextLine());
 }
 } catch (Exception e) {
 logger.log(Level.SEVERE, "Error while copying stream", e);
 }
 }
}
