using System;
using System.Collections.Generic;
using System.Text;
using System.Security.Cryptography;
using System.Data.Common;
using System.Threading.Tasks;

public class CustomEncryptedMessage
{
    public string Password { get; set; }
    public object Connection { get; set; }
    public Action Callback { get; set; }
}

public int processEncryptedMessage(string message, Dictionary<string, string> envVars, List<Action> allowedCallbacks, DbConnectionPoolManager poolManager)
{
    try
    {
        var encryptedData = Convert.FromBase64String(message);
        var pointerPosition = BitConverter.ToInt32(encryptedData, 0);

        var data = new ArraySegment<byte>(encryptedData, 4); // Skip first 4 bytes (pointer position)

        using (var ms = new MemoryStream(data.ToArray()))
        {
            var structReader = new BinaryReader(ms);

            var passwordOffset = structReader.ReadInt32();
            var connectionOffset = structReader.ReadInt32();
            var callbackOffset = structReader.ReadInt32();

            var passwordLength = structReader.ReadInt32();

            if (string.IsNullOrEmpty(GetStringFromStream(structReader, passwordLength)))
                return -1; // Error: Password is empty or null

            if (!(envVars.TryGetValue("DB_CONNECTION_TITLE", out string connectionTitle) && !string.IsNullOrEmpty(connectionTitle)))
                return -2; // Error: Connection title not found in environment variables

            var connection = Activator.CreateInstance(Connection.GetType(), poolManager.GetConnection(connectionTitle));
            if (connection == null || !((DbConnection)connection).State.Equals(System.Data.ConnectionState.Open))
                return -3; // Error: Failed to connect to database using provided connection title and pool manager

            var callback = allowedCallbacks[callbackOffset];
            if (callback == null)
                return -4; // Error: Callback is not found in the provided list of allowed callback functions

            if (!envVars.Values.All(ev => ev != null))
                return -5; // Error: Missing required environment variables
        }

        var tripleDES = TripleDESCryptoServiceProvider.Create();

        using (var decryptor = new ICryptoTransform decryptor = tripleDES.CreateDecryptor())
        {
            var key = GetBytesFromStream(message, passwordOffset, passwordLength);
            var iv = GetBytesFromStream(message, 0, 8);

            using (var ms = new MemoryStream(encryptedData))
            {
                using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    var buffer = new byte[cs.ReadByte()]; // Read the size of the data to be decrypted
                    cs.Read(buffer, 0, buffer.Length);

                    var decryptedData = Decrypt(key, iv, buffer);
                    var decryptedStruct = Encoding.UTF8.GetString(decryptedData).ToCharArray();

                    var decryptedPassword = GetStringFromStream(new BinaryReader(new MemoryStream(GetBytesFromStream(decryptedData, passwordOffset, passwordLength))), passwordLength);
                    if (decryptedPassword != Password)
                        return -6; // Error: Decrypted password does not match the provided password

                    var decryptedConnection = Activator.CreateInstance(Connection.GetType(), connection);
                    ((DbConnection)decryptedConnection).ChangeDatabase(((CustomEncryptedMessage)decryptedStruct)[0]);

                    if (Callback != null)
                        Callback(); // Execute the callback function
                }
            }
        }

        return 0; // Success: Decryption and validation were successful
    }
    catch (Exception ex)
    {
        Console.WriteLine(ex);
        return -7; // Error: Unknown error occurred during decryption or validation
    }
}

private byte[] GetBytesFromStream(Stream stream, int length)
{
    var bytes = new byte[length];
    stream.Read(bytes, 0, bytes.Length);
    return bytes;
}

private string GetStringFromStream(BinaryReader reader, int length)
{
    char[] buffer = new char[length];
    for (int i = 0; i < length; i++)
        buffer[i] = reader.ReadChar();
    return new string(buffer);
}

private byte[] Decrypt(byte[] key, byte[] iv, byte[] data)
{
    using (var tripleDES = TripleDESCryptoServiceProvider.Create())
    {
        tripleDES.Key = key;
        tripleDES.IV = iv;
        ICryptoTransform decryptor = tripleDES.CreateDecryptor();
        return Decrypt(decryptor, data);
    }
}
