    char username[256];
    time_t expires_at;
    char last_login_ip[INET6_ADDRSTRLEN];
};

typedef struct session_validation_ctx {
    struct auth_service *auth;
    pthread_mutex_t mutex;
} session_validation_ctx;

int is_valid_ip(const char *ip) {
    // Implement IPv4 and IPv6 validation logic here
}

time_t time_diff(const time_t t1, const time_t t2) {
    return t1 > t2 ? (t1 - t2) : (t2 - t1);
}

int validate_session_data(struct session_data *data, struct session_validation_ctx *ctx) {
    if (!data || !data->session_id || !data->username) {
        return 0;
    }

    if (!is_valid_ip(data->last_login_ip)) {
        return 0;
    }

    if (time_diff(data->expires_at, time(NULL)) <= 0) {
        return 0;
    }

    // Fetch additional user details from the external authentication service
    user_details user = ctx->auth->fetch_user_details(data->username);

    if (!user.exists || strcmp(user.session_id, data->session_id)) {
        return 0;
    }

    return 1;
}

int process_session_data(char *json_payload, session_validation_ctx *ctx) {
    json_t *root = json_loads(json_payload, JSON_DECREF | JSON_PARSE_COUNTER);
    struct session_data data;

    if (!root || !json_is_object(root)) {
        return 0;
    }

    pthread_mutex_lock(&ctx->mutex);

    if (json_object_get(root, "session_id") == NULL ||
        json_string_length(json_object_get(root, "session_id")) > 255 ||
        !json_is_string(json_object_get(root, "username")) ||
        json_string_length(json_object_get(root, "username")) > 255 ||
        (json_object_get(root, "expires_at") == NULL &&
         json_object_get(root, "last_login_ip"))) {
        pthread_mutex_unlock(&ctx->mutex);
        return 0;
    }

    strncpy(data.session_id, json_string_value(json_object_get(root, "session_id")), 256);
    strncpy(data.username, json_string_value(json_object_get(root, "username")), 256);

    if (json_object_has_member(root, "expires_at")) {
        data.expires_at = (time_t)json_integer_value(json_object_get(root, "expires_at"));
    } else {
        pthread_mutex_unlock(&ctx->mutex);
        return 0;
    }

    if (json_object_has_member(root, "last_login_ip")) {
        strncpy(data.last_login_ip, json_string_value(json_object_get(root, "last_login_ip")), INET6_ADDRSTRLEN);
    } else {
        data.last_login_ip[0] = '\0';
    }

    pthread_mutex_unlock(&ctx->mutex);

    return validate_session_data(&data, ctx);
}
