using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Linq;
using Org.BouncyCastle.Utilities.Encoders;

public string DecryptMessage(string base64EncodedMessage, byte[] key, byte[] iv)
{
    try
    {
        var bytes = Base64Decoder.Decode(base64EncodedMessage);

        using (var tripledes = TripleDESCryptoServiceProvider.Create())
        {
            tripledes.Key = key;
            tripledes.IV = iv;

            ICryptoTransform transform = tripledes.CreateDecryptor();

            MemoryStream memoryStream = new MemoryStream(bytes);
            CryptoStream cryptoStream = new CryptoStream(memoryStream, transform, CryptoStreamMode.Read);

            byte[] decryptedBytes = new byte[bytes.Length];
            int bytesRead;

            while ((bytesRead = cryptoStream.Read(decryptedBytes, 0, decryptedBytes.Length)) > 0)
                Array.Copy(decryptedBytes, 0, memoryStream.GetBuffer(), 0, bytesRead);

            memoryStream.Seek(0, SeekOrigin.Begin);
            using (var reader = new StreamReader(memoryStream))
            {
                return reader.ReadToEnd();
            }
        }
    }
    catch (Exception ex)
    {
        // Log anomalies and errors for debugging purposes
        Console.WriteLine($"Decryption error: {ex.Message}");

        // Attempt to extract usable data from potentially corrupted input
        var invalidBase64Chars = bytes.Where(b => !Base64Decoder.IsValidBase64Char(b)).ToArray();

        if (invalidBase64Chars.Any())
            Console.WriteLine($"Invalid Base64 characters found: {string.Join(", ", invalidBase64Chars)}");

        return $"Error during decryption: {ex.Message}";
    }
}
```

This function first validates the base64 encoded message and decodes it into bytes. Then it uses Triple DES encryption with the given key and IV to decrypt the message. In case of any errors, the function attempts to extract usable data from potentially corrupted input and logs anomalies for debugging purposes. The performance is optimized by reading the decrypted bytes in chunks and using a MemoryStream for intermediate storage.']

