using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using log4net;

public class DataEncryption
{
    private static readonly ILog Logger = LogManager.GetLogger(typeof(DataEncryption));
    private const string Salt = "your-secret-salt";
    private Rfc2898DeriveBytes _keyGenerator;
    private Aes _aesAlg;

    public DataEncryption()
    {
        _keyGenerator = new Rfc2898DeriveBytes(Password, Salt);
        _aesAlg = Aes.Create();
        _aesAlg.Key = _keyGenerator.GetBytes(32);
        _aesAlg.IV = GenerateIV();
    }

    private byte[] GenerateIV()
    {
        var random = new RNGCryptoServiceProvider();
        var iv = new byte[16];
        random.GetBytes(iv);
        return iv;
    }

    public string Encrypt(string plainText)
    {
        if (string.IsNullOrEmpty(plainText)) throw new ArgumentNullException(nameof(plainText));
        var encryptedData = EncryptData(Encoding.UTF8.GetBytes(plainText), false);
        return Convert.ToBase64String(encryptedData);
    }

    public string Decrypt(string cipherText)
    {
        if (string.IsNullOrEmpty(cipherText)) throw new ArgumentNullException(nameof(cipherText));
        var encryptedData = Convert.FromBase64String(cipherText);
        return DecryptData(encryptedData, false).ToLowerInvariant();
    }

    private byte[] EncryptData(byte[] data, bool forLogging)
    {
        using (var encryptor = _aesAlg.CreateEncryptor(_aesAlg.Key, _aesAlg.IV))
        {
            var memoryStream = new MemoryStream();
            var cryptoStream = new CryptoStream(memoryStream, encryptor, CryptoStreamMode.Write);
            cryptoStream.Write(data, 0, data.Length);
            cryptoStream.FlushFinalBlock();
            if (forLogging) LogEncryptionEvent(true, memoryStream.ToArray());
            return memoryStream.ToArray();
        }
    }

    private byte[] DecryptData(byte[] data, bool forLogging)
    {
        using (var decryptor = _aesAlg.CreateDecryptor(_aesAlg.Key, _aesAlg.IV))
        {
            var memoryStream = new MemoryStream(data);
            var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read);
            var plainTextBytes = new byte[memoryStream.Length];
            var offset = 0;
            while (offset < plainTextBytes.Length)
            {
                var readByteCount = cryptoStream.Read(plainTextBytes, offset, plainTextBytes.Length - offset);
                if (readByteCount <= 0) break;
                offset += readByteCount;
            }
            if (forLogging) LogEncryptionEvent(false, plainTextBytes);
            return plainTextBytes;
        }
    }

    private void LogEncryptionEvent(bool isEncrypt, byte[] data)
    {
        try
        {
            // Implement logging with log4net or any other logging service
