using System;
using System.IO;
using System.IO.Compression;
using System.Runtime.InteropServices;
using System.Threading.Tasks;
using Newtonsoft.Json;
using log4net;

namespace CompressedFileLoader
{
    public class Data
    {
        // Define your data structure here
    }

    public static class CompressedFileHandler
    {
        private static readonly ILog logger = LogManager.GetLogger(typeof(CompressedFileHandler));

        public static async Task<T> LoadDataAsync<T>(string filePath, Endianness endianness)
        {
            using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read))
            {
                using var archiveStream = CompressionMode.Decompress == IsCompressed(fileStream)
                    ? new GZipStream(fileStream, CompressionMode.Decompress)
                    : new ZipArchiveReader(fileStream).GetEntry("data").Open();

                var jsonStream = new StreamReader(archiveStream);
                using var jsonReader = new JsonTextReader(jsonStream);

                var serializer = new JsonSerializer
                {
                    Converters = { new EndiannessConverter(endianness) },
                    FloatingPointBehavior = FloatingPointBehavior.Round,
                    NullValueHandling = NullValueHandling.Ignore
                };

                return serializer.Deserialize<T>(jsonReader);
            }
        }

        private static bool IsCompressed(Stream stream)
        {
            var signatureBytes = new byte[4];

            if (stream.Read(signatureBytes, 0, signatureBytes.Length) != signatureBytes.Length)
                return false;

            var gzipSignature = BitConverter.ToInt32(new [] { signatureBytes[0], signatureBytes[1], signatureBytes[2], 0x00 });
            var zipSignature = BitConverter.ToUInt32(signatureBytes, 0);

            return (gzipSignature == Constants.GZipMagicNumber) || (zipSignature == Constants.ZipLocalFileHeaderSignature);
        }
    }

    public class EndiannessConverter<T> : JsonConverter
    {
        private readonly Endianness _endianness;

        public EndiannessConverter(Endianness endianness) => _endianness = endianness;

        public override bool CanConvert(Type objectType) => true;

        public override void WriteJson(JsonWriter writer, object value, JsonSerializer serializer)
        {
            // Implement writeJson here
        }

        public override object ReadJson(JsonReader reader, Type objectType, object existingValue, JsonSerializer serializer)
        {
            var value = serializer.Deserialize<T>(reader);
            if (value == null) return default;

            using var ms = new MemoryStream();
            using var bw = new BinaryWriter(ms, _endianness == Endianness.Big ? System.ByteOrder.LittleEndian : System.ByteOrder.BigEndian);

            serializer.Serialize(new JsonTextWriter(new StringWriter(null)), value);
            using var br = new BinaryReader(new MemoryStream(ms.ToArray()), _endianness == Endianness.Big ? System.ByteOrder.LittleEndian : System.ByteOrder.BigEndian);

            return serializer.Deserialize(br, objectType);
        }
    }

    public enum Endianness
    {
        Big,
        Little
    }

    // Constants related to compression signatures
    internal static class Constants
    {
        internal const uint GZipMagicNumber = 0x1f, GZipHeaderLength = 10;
        internal const uint ZipLocalFileHeaderSignature = 0x504b0304;
    }
}
```

