use serde::{Deserialize, Serialize};
use tokio::task;
use url::Url;
use log::{error, trace};
use std::fmt::{self, Write as FmtWrite};
use std::ffi::CString;
use std::os::unix::io::AsRawFd;
use libc::{openat, O_WRONLY|O_CREAT|O_APPEND, AT_FDCWD, O_CLOEXEC};
use std::sync::Arc;
use tokio::runtime::Runtime;
use tokio::signal::ctrl_c;
use reqwest::Client;
use serde_json::{Map, Value};

const LOG_FILE: &str = "error.log";
const MAX_TASKS: usize = 1024;

#[derive(Serialize, Deserialize)]
struct TaskConfig {
    name: String,
    args: Vec<String>,
}

async fn execute_task(config: &TaskConfig) {
    // Implement task execution logic here
}

async fn fetch_tasks() -> Result<Vec<TaskConfig>, reqwest::Error> {
    let url = Url::parse("<YOUR CONFIG ENDPOINT>")?;
    Client::new().get(url).send().await?.json::<Value>::serialize_err("Failed to deserialize response")?;
    let tasks: Map<String, Value> = serde_json::from_value(value)?;
    Ok(tasks.into_iter()
        .map(|(k, v)| TaskConfig { name: k, args: v.as_array().unwrap().to_vec() })
        .collect())
}

fn log_error(fmt: &str, args: &[&str]) {
    let mut buf = [0; 4096];
    let len = snprintf(&mut buf, buf.len(), fmt.as_ptr(), args.as_ptr());
    let cbuf = CString::new(buf[..len as usize]).unwrap();
    let fd = openat(AT_FDCWD, LOG_FILE as &str, O_WRONLY|O_CREAT|O_APPEND, 0o644).unwrap() as i32;
    unsafe {
        libc::write(fd, cbuf.as_bytes().as_ptr(), cbuf.len())
    }
}

fn main() {
    let tasks = Arc::new(Vec::with_capacity(MAX_TASKS));
    let mut runtime = Runtime::new().unwrap();
    let handle = runtime.handle();
    let log_error = log_error;

    ctrl_c().forward<()>(move || {
        log_error("Received CTRL+C, shutting down...");
        drop(tasks);
        std::process::exit(0);
    })
    .layer_at(handle)
    .forget();

    match fetch_tasks().await {
        Ok(mut configs) => {
            for config in &configs {
                tasks.push(task::spawn(execute_task(config)));
                if tasks.len() >= MAX_TASKS {
                    break;
                }
            }
            drop(configs);
        },
        Err(e) => log_error("Failed to fetch tasks: {}", e),
    };

    runtime.block_on(tasks.into_iter().collect::<Vec<_>>()).unwrap();
}
