import json
import logging
import functools
from concurrent.futures import ThreadPoolExecutor, as_completed
from collections import defaultdict, namedtuple
from weakref import WeakKeyDictionary
from abc import ABC, abstractmethod

class Logger(logging.Logger):
    def __init__(self, name: str):
        super().__init__(name)

class JSONObject(namedtuple('JSONObject', 'data')):
    @staticmethod
    def from_json(json_str):
        return JSONObject(json.loads(json_str))

    def to_json(self):
        return json.dumps(self.data)

class FactoryRegistry(defaultdict, metaclass=ABC):
    @abstractmethod
    def create(cls, identifier: str):
        raise NotImplementedError

class SimpleFactoryRegistry(FactoryRegistry):
    def __init__(self):
        super().__init__(WeakKeyDictionary)

    def create(cls, identifier: str):
        factory = self[identifier]
        if not factory:
            raise ValueError(f"No factory registered with identifier '{identifier}'.")
        return factory()

class CachedFactoryRegistry(SimpleFactoryRegistry):
    def __init__(self, cache_size: int = 128):
        super().__init__()
        self._cache = {}
        self._cache_size = cache_size

    def create(cls, identifier: str):
        key = (cls, identifier)
        if key in self._cache:
            return self._cache[key]

        with ThreadPoolExecutor() as executor:
            future = executor.submit(super().create, cls, identifier)
            result = future.result()

            if cache_size > 0 and key not in self._cache:
                self._cache[key] = result

            if len(self._cache) > self._cache_size:
                self._cache.popitem(last=False)

        return result

class JSONConverter:
    def __init__(self, registry: FactoryRegistry = SimpleFactoryRegistry(), logger: logging.Logger = Logger('jsonconverter')):
        self._registry = registry
        self._logger = logger

    def from_json(self, json_str, identifier: str = None):
        if identifier is not None:
            factory = self._registry.create(identifier)
            return factory.parse(json_str)
        else:
            obj = JSONObject.from_json(json_str)
            return obj

    def to_json(self, data):
        if isinstance(data, JSONObject):
            return data.to_json()
        else:
            factory = self._registry.create(type(data).__name__)
            return factory.stringify(data)

def register_factory(registry: FactoryRegistry, identifier: str, factory_function):
    registry[identifier] = factory_function

def invoke_factory(registry: FactoryRegistry, identifier: str):
    return registry.create(identifier)
```

