#include <stdio.h>
#include <resolv.h>
#include <sys/socket.h>
#include <netdb.h>
#include <openssl/ssl.h>
#include <pthread.h>
#include <semaphore.h>
#include <sys/prctl.h> /* for PR_SET_NOCHILD */
#include <limits.h> /* for RLIMIT_NOFILE */
#include <unistd.h> /* for getrlimit and setrlimit */

typedef struct {
    char hostname[256];
    int* status;
} ConnectionParams;

static sem_t resource_lock;
static rlim_t cpu_limit, mem_limit;
static int max_files;

void set_resource_limits() {
    struct rlimit rl;
    getrlimit(RLIMIT_CPU, &rl);
    cpu_limit = rl.rlim_cur;
    getrlimit(RLIMIT_DATA, &rl);
    mem_limit = rl.rlim_cur;
    getrlimit(RLIMIT_NOFILE, &rl);
    max_files = rl.rlim_max;
}

int establish_connection(const char* hostname) {
    struct addrinfo hints, *res;
    int status = 1;
    sem_wait(&resource_lock);
    if (getrlimit(RLIMIT_CPU, &rl) && rl.rlim_cur > cpu_limit) {
        status = -1;
        goto cleanup;
    }

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    int err = getaddrinfo(hostname, NULL, &hints, &res);
    if (err != 0) {
        perror("getaddrinfo");
        status = -2;
        goto cleanup;
    }

    SSL_library_init();
    const SSL_METHOD *method;
    SSL_CTX *ctx;

    // Load certificates and configure SSL context (omitted for brevity)

    ctx = SSL_CTX_new(method);

    int sockfd = socket(res->ai_family, res->ai_socktype, 0);
    if (sockfd == -1) {
        perror("socket");
        status = -3;
        goto cleanup;
    }

    struct timeval tv = {5, 0}; /* 5 seconds for TLS handshake timeout */
    setsockopt(sockfd, SSL_OPT_CONNECT_TIMEOUT, (const char *)&tv, sizeof(tv));

    int rc = connect(sockfd, res->ai_addr, res->ai_addrlen);
    if (rc == -1) {
        perror("connect");
        status = -4;
        goto cleanup;
    }

    SSL *ssl = SSL_new(ctx);
    if (!SSL_set_fd(ssl, sockfd)) {
        ERR_print_errors_fp(stderr);
        status = -5;
        goto cleanup;
    }

    // Perform TLS/SSL handshake (omitted for brevity)

    if (!SSL_get_peer_certificate(ssl) || !SSL_verify_peer_certificate(ssl)) {
        ERR_print_errors_fp(stderr);
        status = -6;
        goto cleanup;
    }

    struct sockaddr_in addr = {};
    socklen_t len = sizeof(addr);
    if (getsockname(sockfd, (struct sockaddr *)&addr, &len) == -1) {
        perror("getsockname");
        status = -7;
        goto cleanup;
    }

cleanup:
    sem_post(&resource_lock);
    if (res != NULL) freeaddrinfo(res);
    if (ctx != NULL) SSL_CTX_free(ctx);
    *status = status;
    return status == 0 ? (int){.ip = addr.sin_addr.s_addr, .port = ntohs(addr.sin_port)} : NULL;
}

void limit_process_capabilities() {
    prctl(PR_SET_NOCHILD, 1, 0, 0, 0);
    set_resource_limits();
    sem_init(&resource_lock, 1, 1);
}
```

