class XPathParser {
public:
    using RandomGenerator = boost::random::mersenne_twister;
    static RandomGenerator rng;

    void parse(const std::string& url, const std::string& xpath, std::function<void(bpt::ptree&)> callback) {
        // Initialize variables and structures for HTTP request and XML parsing
        bs::io_service io_service;
        bs::ip::tcp::socket socket(io_service);
        bs::connect(socket, bs::ip::tcp::resolver(io_service).resolve(url)).wait();

        bpt::ptree xml_tree;
        bpt::read_xml(bs::streambuf(socket), namespace_parser, xml_tree);

        if (xpath.empty()) {
            callback(xml_tree);
            return;
        }

        try {
            auto it = boost::find_if(xml_tree.get_child("root").get_children(),
                [&](const bpt::ptree& node) {
                    return node.get<std::string>("name") == xpath;
                });

            if (it != xml_tree.get_child("root").get_children().end()) {
                callback(*it);
                return;
            }
        } catch (const bpt::xml_parser::xml_parser_error& e) {
            std::cerr << "Error parsing XML: " << e.what() << std::endl;
        } catch (const std::exception& e) {
            std::cerr << "Unexpected error: " << e.what() << std::endl;
        }

        if (callback.has_value()) {
            callback(bpt::ptree{}); // Default value if no element is found
        }
    }

private:
    static bpt::xml_parser::namespace_parser namespace_parser() {
        return {{"", "xmlns"}, {"x", "http://www.w3.org/2005/xpath-functions"}};
    }
};

RandomGenerator XPathParser::rng;
