    let managed_records = manage_records(1000, RECORD_THRESHOLD);
    populate_records(managed_records.clone(), 50);

    let concurrent_requests = Arc::new(Mutex::new(vec![]));
    let mut handles = Vec::new();

    for _ in 0..MAX_CONCURRENT_REQUESTS {
        let client = http_client.clone();
        let managed_records = managed_records.clone();
        let concurrent_requests = concurrent_requests.clone();

        let handle = thread::spawn(move || {
            for (key, _, value) in managed_records.lock().unwrap().values() {
                if **value <= RECORD_THRESHOLD && !*concurrent_requests.lock().unwrap().contains(key) {
                    concurrent_requests.lock().unwrap().push(key);
                    perform_request(&client, format!("http://example.com/{}", key)).unwrap();
                }
            }
        });

        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }
}
