#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

typedef struct _FSA FSA;
struct _FSA {
    int *states;
    int num_states;
    int **next;
    int last_state;
};

typedef struct _UF UF;
struct _UF {
    int *parents;
    int *sizes;
};

UF *new_uf(int n) {
    UF *uf = malloc(sizeof(UF));
    uf->parents = calloc(n, sizeof(int));
    uf->sizes = calloc(n, sizeof(int));
    return uf;
}

int find(UF *uf, int x) {
    if (uf->parents[x] == x) {
        return x;
    }
    return uf->parents[x] = find(uf, uf->parents[x]);
}

void union_set(UF *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf->sizes[rootX] < uf->sizes[rootY]) {
            uf->parents[rootX] = rootY;
            uf->sizes[rootY] += uf->sizes[rootX];
        } else {
            uf->parents[rootY] = rootX;
            uf->sizes[rootX] += uf->sizes[rootY];
        }
    }
}

void destroy_uf(UF *uf) {
    free(uf->parents);
    free(uf->sizes);
    free(uf);
}

clock_t start, end;
double time_diff_millis(clock_t start, clock_t end) {
    return (end - start) * 1000.0 / CLOCKS_PER_SEC;
}

int *state_list(FSA *fsa) {
    int n = fsa->num_states;
    UF *uf = new_uf(n);
    int *state_list = malloc(sizeof(int) * (n + 1));
    state_list[0] = -1; // sentinel value for last state

    for (int i = 0; i < n; ++i) {
        start = clock();
        int root = find(uf, i);
        end = clock();
        if (root != i) {
            continue; // already identified as a disjoint set
        }
        state_list[root] = i;
        for (int j = 0; j < n; ++j) {
            int nextState = fsa->next[i][j];
            if (nextState != -1 && find(uf, nextState) == root) {
                union_set(uf, i, nextState);
                state_list[find(uf, nextState)] = -2; // flagged for update
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        if (state_list[i] == -2) {
            start = clock();
            int root = find(uf, i);
            end = clock();
            state_list[root] = fsa->last_state++;
        }
    }

    destroy_uf(uf);

    printf("Time for disjoint checks: %f ms\n", time_diff_millis(start, end));
    printf("Time for list construction: %f ms\n", time_diff_millis(start, end));

    return state_list;
}
