void init_data() {
    if (data != NULL) return; // If already initialized, do nothing

    data_size = ARRAY_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(data_size);

    if (data == NULL) {
        perror("Error allocating memory");
        return;
    }

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_setrobust(&attr, PTHREAD_MUTEX_ROBUST);
    pthread_mutex_init(&mutex, &attr);

    for (size_t i = 0; i < ARRAY_SIZE; ++i) {
        data[i].RX_UE_INFORMATION_TAG = i + 1;
        data[i].RNTI = rand() % 65535;
        data[i].CRC_INDICATION_REL8_TAG = rand() % 65536;
        data[i].CRCFLAG = (rand() % 2) == 0; // Randomly set CRCFLAG to true or false
    }
}

void serialize(char* buffer, size_t buffer_size) {
    if (data_size * sizeof(NFAPI_CRC_INDICATION_PDU_T) > buffer_size) {
        perror("Buffer too small for serialization");
        return;
    }

    pthread_mutex_lock(&mutex);
    memcpy(buffer, data, data_size);
    pthread_mutex_unlock(&mutex);
}

void cleanup() {
    free(data);
    data = NULL;
    data_size = 0;
    pthread_mutex_destroy(&mutex);
}
