```cpp
#include <iostream>
#include <boost/gil/gil_all.hpp>
#include <boost/log/trivial.hpp>
#include <boost/filesystem.hpp>
#include <unordered_map>
#include <stdexcept>

namespace fs = boost::filesystem;
namespace gil = boost::gil;

struct TiffInfo {
    uint16_t bitsPerSample;
    uint16_t samplePerPixel;
};

std::unordered_map<fs::path, TiffInfo> tiffCache; // Cache for TIFF info

TiffInfo parseTiff(const fs::path& path) {
    if (tiffCache.find(path) != tiffCache.end())
        return tiffCache[path];

    gil::image_t<uint8_t> img;
    try {
        gil::load(img, path.string());
    } catch (const std::exception& e) {
        BOOST_LOG_TRIVIAL(error) << "Error loading image: " << e.what();
        return TiffInfo{0, 0};
    }

    const auto tiffTag = gil::io::tiff_tag_from_channel<0>(img);
    if (tiffTag != gil::tiff_tag::SAMPLES_PER_PIXEL) {
        BOOST_LOG_TRIVIAL(error) << "Invalid TIFF file: samples per pixel tag not found.";
        return TiffInfo{0, 0};
    }

    const auto samplesPerPixel = *tiffTag->value();
    if (samplesPerPixel != 1 && samplesPerPixel != 2 && samplesPerPixel != 4 && samplesPerPixel != 8 && samplesPerPixel != 16) {
        BOOST_LOG_TRIVIAL(error) << "Unsupported bit depth: " << samplesPerPixel;
        return TiffInfo{0, 0};
    }

    const auto bitsPerSampleTag = gil::io::tiff_tag_from_channel<samplesPerPixel>(img);
    if (!bitsPerSampleTag) {
        BOOST_LOG_TRIVIAL(error) << "Invalid TIFF file: bits per sample tag not found.";
        return TiffInfo{0, 0};
    }

    TiffInfo info;
    for (const auto& bitPerSample : *bitsPerSampleTag->value()) {
        info.bitsPerSample = static_cast<uint16_t>(bitPerSample);
        info.samplePerPixel = samplesPerPixel;
        break; // Assuming each sample has the same bits per sample value
    }

    tiffCache[path] = info;
    return info;
}

int main(int argc, char* argv[]) {
    for (const auto& path : fs::recursive_directory_iterator("./")) {
        if (fs::is_regular_file(path) && path.extension() == ".tif" || path.extension() == ".TIF") {
            try {
                const auto info = parseTiff(path);
                std::cout << "Bits per sample: " << info.bitsPerSample << '\n';
                std::cout << "Sample per pixel: " << info.samplePerPixel << '\n';
            } catch (const std::exception& e) {
                BOOST_LOG_TRIVIAL(error) << "Error processing image: " << e.what();
            }
        }
    }
}
```

