    char new_filename[256];
    time_t modification_time;
    off_t file_size;
    char directory_path[256];
} FilenameMetadata;

void generate_unique_filename(const char* original_filename, char* new_filename, size_t max_length) {
    struct stat st;
    stat(original_filename, &st);

    time_t timestamp = time(NULL);
    uint64_t sequence_number = hash((char*)&st, sizeof(st));

    snprintf(new_filename, max_length, "%s-%lu%ld.%s", original_filename, timestamp, sequence_number, get_file_extension(original_filename));
}

uint64_t hash(const char* data, size_t length) {
    uint64_t hash = 0;
    for (size_t i = 0; i < length; ++i) {
        hash = (hash << 5) + hash + data[i];
        hash &= HASH_MODULO;
    }
    return hash;
}

const char* get_file_extension(const char* filename) {
    size_t last_dot = strlen(filename);
    for (size_t i = last_dot - 1; i > 0 && filename[i] != '\\' && filename[i] != '/'; --i) {
        if (filename[i] == '.') {
            last_dot = i;
        }
    }
    return last_dot > 0 ? &filename[last_dot + 1] : NULL;
}

