typedef void (*TestFunc)(void*, const char*, const char*);

int runModuleTests(const char *moduleLabel, int *keyArray, TestFunc *testCases, size_t numTestCases, long randomSeed) {
    void *moduleHandle = dlopen(moduleLabel, RTLD_NOW | RTLD_GLOBAL);

    if (!moduleHandle) {
        fprintf(stderr, "Failed to load module: %s\n", dlerror());
        return 1;
    }

    typedef void* (*CreateRecordFunc)(void*, int);
    typedef void (*DestroyRecordFunc)(void*, void*);
    typedef long (*GetRecordOffsetFunc)(void*, int);
    typedef void* (*SetRecordOffsetFunc)(void*, int, long);
    typedef int (*IndexFindRecordFunc)(void*, int, void***);
    typedef void (*DeleteRecordFunc)(void*, void*);

    CreateRecordFunc createRecord = dlsym(moduleHandle, "createRecord");
    DestroyRecordFunc destroyRecord = dlsym(moduleHandle, "destroyRecord");
    GetRecordOffsetFunc getRecordOffset = dlsym(moduleHandle, "getRecordOffset");
    SetRecordOffsetFunc setRecordOffset = dlsym(moduleHandle, "setRecordOffset");
    IndexFindRecordFunc indexFindRecord = dlsym(moduleHandle, "indexFindRecord");
    DeleteRecordFunc deleteRecord = dlsym(moduleHandle, "deleteRecord");

    if (!createRecord || !destroyRecord || !getRecordOffset || !setRecordOffset || !indexFindRecord || !deleteRecord) {
        fprintf(stderr, "Failed to find function symbols in module: %s\n", dlerror());
        dlclose(moduleHandle);
        return 1;
    }

    pthread_t threads[numTestCases];
    void *recordData;
    long recordOffset;

    srand(randomSeed);

    for (size_t i = 0; i < numTestCases; ++i) {
        testCases[i](moduleHandle, moduleLabel, __func__);
        pthread_create(&threads[i], NULL, [moduleHandle, keyArray, &recordData, &recordOffset, i]() mutable {
            recordOffset = createRecord(moduleHandle, keyArray[i]);
            testCases[(size_t)(i + 1)][moduleHandle, moduleLabel, __func__];
            deleteRecord(moduleHandle, recordData);
        }, NULL);
    }

    for (size_t i = 0; i < numTestCases; ++i) {
        pthread_join(threads[i], NULL);
    }

    dlclose(moduleHandle);
    return 0;
}
