#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int* states;
    int size, capacity;
    pthread_mutex_t lock;
    FSA* fsa;
} StateList;

StateList* create_state_list(int* states, int num_states, FSA* fsa, int last_state) {
    // Allocate memory for new StateList
    StateList* state_list = (StateList*)malloc(sizeof(StateList));
    if (!state_list) return NULL;

    // Initialize mutex and copy input data
    pthread_mutex_init(&state_list->lock, NULL);
    state_list->states = (int*)malloc(num_states * sizeof(int));
    if (!state_list->states) {
        free(state_list);
        return NULL;
    }
    memcpy(state_list->states, states, num_states * sizeof(int));
    state_list->size = num_states;
    state_list->capacity = num_states;
    state_list->fsa = fsa;

    return state_list;
}

void cleanup_state_list(StateList** state_list) {
    if (*state_list) {
        free((*state_list)->states);
        pthread_mutex_destroy(&(*state_list)->lock);
        free(*state_list);
        *state_list = NULL;
    }
}
```

3. Function for adding a new state to the list:

```c
void add_state(StateList* state_list, int state) {
    pthread_mutex_lock(&state_list->lock);
    if (state_list->size == state_list->capacity) {
        state_list->capacity *= 2;
        state_list->states = (int*)realloc(state_list->states, state_list->capacity * sizeof(int));
        if (!state_list->states) {
            pthread_mutex_unlock(&state_list->lock);
            return;
        }
    }
    state_list->states[state_list->size] = state;
    state_list->size++;
    pthread_mutex_unlock(&state_list->lock);
}
```

4. Function for validating and transitioning states:

```c
int validate_and_transition(StateList* state_list, int current_state, char input) {
    // Validate current state against FSA rules
    if (!fsa_valid_state(state_list->fsa, current_state)) return -1;

    // Find the next state based on the current state and input
    int next_state = fsa_transition(state_list->fsa, current_state, input);

    if (next_state == -1) return -1; // Invalid transition

    add_state(state_list, next_state);

    return 0;
}
```']

