['```rust
use std::collections::{HashMap, VecDeque};
use std::io::{self, BufReader, Write};
use std::net::TcpStream;
use std::path::Path;
use std::sync::Mutex;
use rayon::prelude::*;
use reqwest::{Client, RequestBuilder};
use serde_json::{Map, Value};
use tempfile::NamedTempFile;

type Record = (i32, i64, u8);

struct HttpClient {
    client: Client,
    max_concurrent_requests: usize,
    record_range: (i32, i32),
    threshold: i32,
    record_queue: Mutex<VecDeque<Record>>,
}

impl HttpClient {
    fn new(max_concurrent_requests: usize, record_range: (i32, i32), threshold: i32) -> Self {
        let client = Client::new();
        Self {
            client,
            max_concurrent_requests,
            record_range,
            threshold,
            record_queue: Mutex::new(VecDeque::new()),
        }
    }

    fn execute(&self, command: &str) -> io::Result<()> {
        let tempfile = NamedTempFile::new().unwrap();
        if Path::new(tempfile.path()).exists() {
            let _ = std::fs::remove_file(tempfile.path());
        }

        let process = std::process::Command::new("sh")
            .arg("-c")
            .arg(command)
            .arg(tempfile.path())
            .stdout(io::Inherit)
            .stderr(io::Inherit)
            .spawn()?;
        process.wait_with_output()?;
        Ok(())
    }

    fn execute_and_parse(&self, command: &str) -> Result<Value, Box<dyn std::error::Error>> {
        self.execute(command)?
            .stdout(io::BufReader::new(std::io::File::open(command)?))
            .ok_or("Command execution failed")??
            .deserialize()
    }

    fn execute_and_print(&self, command: &str) -> io::Result<()> {
        self.execute(command)?
            .stdout(io::BufReader::new(std::io::File::open(command)?))
            .ok_or("Command execution failed")??
            .lines()
            .for_each(|line| println!("{}", line.unwrap()))
    }

    fn populate_records(&mut self) {
        let total_records = (self.record_range.1 - self.record_range.0 + 1) as usize;
        let mut records: Vec<Record> = self.record_queue.lock().unwrap().drain(..).collect();
        records.resize(total_records, (0, 0, 0));

        for record in records.par_iter_mut() {
            *record = (
                rand::thread_rng().gen_range(self.record_range.0..=self.record_range.1),
                rand::thread_rng().gen(),
                1,
            );
        }
    }

    fn check_sum(&self) -> bool {
        let mut sum = 0;
        for record in self.record_queue.lock().unwrap().iter() {
            if record.2 == 1 && sum + record.0 > self.threshold {
                return false;
            }
            sum += record.0;
        }
        true
    }

    fn send_requests(&self, base_url: &str) -> io::Result<()> {
        let mut active_requests = 0;
        while active_requests < self.max_concurrent_requests {
            if !self.record_queue.lock().unwrap().is_empty() && self.check_sum() {
                let record = self.record_queue.lock().unwrap().pop_front().unwrap();
                let request = RequestBuilder::post(format!("{}/", base_url))
                    .json(&Map::from([
                        ("key".to_string(), Value::Number(record.0 as f64)),
                        ("offset".to_string(), Value::Number(record.1 as f64)),
                        ("active".to_string(), Value::Bool(record.2 != 0))
                    ]))
                    .build()?;
                self.client
                    .execute(request)
                    .map(|res| {
                        if !res.status().is_success() {
                            println!("Request failed: {}", res.status());
                        }
                        active_requests -= 1;
                    })?;
                active_requests += 1;
            } else {
                break;
            }
        }
        Ok(())
    }
}
```

