#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <pthread.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <openssl/md5.h>
#include <semaphore.h>
#include <sys/wait.h>

typedef struct {
    char filename[256];
    char extension[8];
    off_t file_size;
    time_t modification_time;
    int checksum[MD5_DIGEST_LENGTH];
} FileInfo;

static sem_t sem_mutex, sem_counter;
static int counter = 0;

void append_identifier(FileInfo *file_info) {
    char timestamp[16];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", localtime(&now));

    snprintf(file_info->filename, sizeof(file_info->filename),
             "%s_v%03d_%s%s", timestamp, counter++, "checksum", "");
}

int is_valid_filename(const char *filename) {
    return strlen(filename) <= 256;
}

void get_file_info(FileInfo *file_info, const char *filename) {
    FILE *fp = fopen(filename, "rb");
    struct stat file_stat;
    if (fstat(fileno(fp), &file_stat) == -1) {
        perror("Error getting file stats");
        exit(EXIT_FAILURE);
    }

    file_info->file_size = file_stat.st_size;
    file_info->modification_time = file_stat.st_mtime;

    unsigned char buffer[sizeof(MD5_DIGEST_LENGTH)];
    if (fseek(fp, 0, SEEK_SET) != 0 || fread(buffer, sizeof(buffer), 1, fp) != 1) {
        perror("Error reading file");
        exit(EXIT_FAILURE);
    }

    if (fclose(fp) == EOF) {
        perror("Error closing file");
        exit(EXIT_FAILURE);
    }

    memset(file_info->checksum, 0, sizeof(file_info->checksum));
    memcpy(file_info->checksum, buffer, sizeof(buffer));
}

void process_file(FileInfo *file_info) {
    append_identifier(file_info);

    char new_filename[256];
    snprintf(new_filename, sizeof(new_filename), "%s.txt", file_info->filename);

    FILE *fp_old = fopen(file_info->filename, "rb");
    FILE *fp_new = fopen(new_filename, "wb+");

    if (fstat(fileno(fp_old), &file_info->file_size) == -1 ||
        fstat(fileno(fp_new), &file_info->file_size) == -1 ||
        file_info->file_size != ftell(fp_old)) {
        perror("Error checking file sizes");
        exit(EXIT_FAILURE);
    }

    if (fseek(fp_old, 0, SEEK_SET) == -1 || fseek(fp_new, 0, SEEK_SET) == -1) {
        perror("Error seeking files");
        exit(EXIT_FAILURE);
    }

    char *map = mmap(NULL, file_info->file_size, PROT_READ, MAP_PRIVATE, fileno(fp_old), 0);
    if (map == MAP_FAILED) {
        perror("Error mapping file");
        exit(EXIT_FAILURE);
    }

    size_t bytes_read;
    while ((bytes_read = fread(map + ftell(fp_old), 1, file_info->file_size - ftell(fp_old), fp_old)) > 0) {
        if (fwrite(map + ftell(fp_old), 1, bytes_read, fp_new) != bytes_read) {
            perror("Error writing to new file");
            exit(EXIT_FAILURE);
        }
    }

    if (munmap(map, file_info->file_size) == -1) {
        perror("Error unmapping file");
        exit(EXIT_FAILURE);
    }

    if (fclose(fp_old) == EOF || fclose(fp_new) == EOF) {
        perror("Error closing files");
        exit(EXIT_FAILURE);
    }

    unlink(file_info->filename);
    rename(new_filename, file_info->filename);
}

void walk_directory(const char *path) {
    DIR *dir = opendir(path);
    if (dir == NULL) {
        perror("Error opening directory");
        exit(EXIT_FAILURE);
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip '.' and '..' entries and files with incorrect extension.
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0 ||
            strlen(entry->d_name + strlen(entry->d_name) - strlen("txt")) != 4) {
            continue;
        }

        char fullpath[256];
        snprintf(fullpath, sizeof(fullpath), "%s/%s", path, entry->d_name);

        // Concurrent file processing using threads.
        FileInfo file_info;
        strcpy(file_info.filename, fullpath);
        get_file_info(&file_info, fullpath);

        pthread_t thread;
        if (pthread_create(&thread, NULL, process_file, &file_info) != 0) {
            perror("Error creating thread");
            exit(EXIT_FAILURE);
        }
    }

    closedir(dir);
}

void handle_error(int status) {
    if (WIFEXITED(status)) {
        fprintf(stderr, "Child process exited with status %d\n", WEXITSTATUS(status));
    } else if (WIFSIGNALED(status)) {
        fprintf(stderr, "Child process terminated by signal %d\n", WTERMSIG(status));
    } else {
        fprintf(stderr, "Unexpected child process status: %d\n", status);
    }
}

void main_function() {
    sem_init(&sem_mutex, 1, 1);
    sem_init(&sem_counter, 0, 1);

    walk_directory("/path/to/your/directory");

    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, clean_up, NULL) != 0) {
        perror("Error creating cleanup thread");
        exit(EXIT_FAILURE);
    }

    for (pid_t pid = waitpid(-1, NULL, WNOHANG); pid > 0; pid = waitpid(-1, NULL, WNOHANG)) {
        handle_error(WEXITSTATUS(pid));
    }

    sem_destroy(&sem_mutex);
    sem_destroy(&sem_counter);
}

void* clean_up(void *arg) {
    while (1) {
        sem_wait(&sem_counter);
        sem_wait(&sem_mutex);

        // Remove temporary files created by child processes.
        // Integrate with logging framework here.
        ...

        sem_post(&sem_mutex);
        sem_post(&sem_counter);
    }
}
