#define CACHE_SIZE 10000
typedef struct CacheEntry {
    json_t *data;
    time_t timestamp;
} CacheEntry;

CacheEntry *cache = NULL;
size_t cache_count = 0;
size_t cache_capacity = CACHE_SIZE;

pthread_mutex_t cache_lock;

int socket_fd = -1;
struct sockaddr_in server_addr;

void cache_insert(json_t *data, time_t timestamp) {
    if (cache_count >= cache_capacity) {
        free_cache();
        cache_capacity *= 2;
    }

    CacheEntry *entry = realloc(cache, sizeof(CacheEntry) * (cache_count + 1));
    if (!entry) {
        fprintf(stderr, "Failed to allocate memory for cache.\n");
        exit(EXIT_FAILURE);
    }
    cache = entry;

    cache[cache_count].data = data;
    cache[cache_count].timestamp = timestamp;
    ++cache_count;
}

json_t *cache_get(time_t timestamp) {
    pthread_mutex_lock(&cache_lock);
    for (size_t i = 0; i < cache_count; ++i) {
        if (cache[i].timestamp == timestamp) {
            json_t *result = cache[i].data;
            memmove(&cache[i], &cache[cache_count - 1], sizeof(CacheEntry) * (cache_count - 1));
            --cache_count;
            pthread_mutex_unlock(&cache_lock);
            return result;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

void free_cache() {
    if (cache) {
        for (size_t i = 0; i < cache_count; ++i) {
            json_decref(cache[i].data);
        }
        free(cache);
        cache = NULL;
        cache_count = 0;
    }
}

