typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct node *next;
} Node;

Node* head = NULL;
unsigned int capacity = 0, size = 0;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void init() {
    if (capacity) return;
    capacity = 32; // initial capacity
    head = malloc(capacity * sizeof(Node));
    if (!head) exit(1);
    for (unsigned int i = 0; i < capacity; ++i) {
        head[i].next = &head[i + 1];
        head[i].data = NULL;
    }
    head[capacity - 1].next = head;
}

NFAPI_CRC_INDICATION_PDU_T* create_element() {
    NFAPI_CRC_INDICATION_PDU_T *new_elem = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_elem) return NULL;
    new_elem->crc_indication.crcflag = rand() % 2;
    pthread_mutex_init(&new_elem->mutex, NULL);
    return new_elem;
}

void add_element(NFAPI_CRC_INDICATION_PDU_T* elem) {
    pthread_mutex_lock(&list_mutex);
    if (!head || !size) {
        head->data = elem;
        size++;
    } else {
        Node *last = head;
        while (last->next != head && last->next->data) last = last->next;
        last->next->data = elem;
        size++;
    }
    pthread_mutex_unlock(&list_mutex);
}

void remove_element(unsigned int index) {
    if (index >= size || index < 0) return;
    pthread_mutex_lock(&list_mutex);
    Node *curr = head, *prev = NULL;
    for (unsigned int i = 0; i < index; ++i) {
        prev = curr;
        curr = curr->next;
    }
    if (!curr || !size) return;
    if (prev == NULL) head = curr->next;
    else prev->next = curr->next;
    free(curr->data);
    free(curr);
    size--;
    pthread_mutex_unlock(&list_mutex);
}

void serialize(void *buf, unsigned int len) {
    // Implement serialization logic here, optimized for performance and space efficiency.
}

void deserialize(void *buf, unsigned int len) {
    // Implement deserialization logic here, ensuring robustness against buffer overflows.
}

void log_metadata() {
