    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    time_t timestamp; // Time of the last update
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ENTRIES (size_t)1024 // Maximum number of entries in the list
#define CLEANUP_INTERVAL (60)     // Cleanup interval in seconds

typedef struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node* next;
} ListNode;

ListNode** head = NULL;  // Pointer to the first node in the list
size_t num_entries = 0;   // Number of entries in the list
pthread_mutex_t list_mutex; // Mutex for synchronizing access to the list

void cleanup() {
    ListNode* current, * next;
    time_t current_time = time(NULL);

    pthread_mutex_lock(&list_mutex);
    current = *head;
    while (current != NULL) {
        next = current->next;
        if (current->data.timestamp + CLEANUP_INTERVAL < current_time) {
            free(current);
            num_entries--;
        }
        current = next;
    }
    pthread_mutex_unlock(&list_mutex);
}

void add_entry(const NFAPI_CRC_INDICATION_PDU_T* entry) {
    ListNode *new_node, *current;

    new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) return; // Handle memory allocation errors

    memcpy(&new_node->data, entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->timestamp = time(NULL);
    new_node->next = NULL;

    pthread_mutex_lock(&list_mutex);
    if (num_entries >= MAX_ENTRIES) { // Handle maximum list size exceeded
        free(new_node);
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    current = *head;
    while (current != NULL && current->next != NULL) {
        current = current->next;
    }
    if (current == NULL) { // List is empty, new node becomes the head
        *head = new_node;
    } else {
        current->next = new_node;
    }
    num_entries++;
    pthread_mutex_unlock(&list_mutex);
}

void update_entry(uint32_t rnti, const NFAPI_CRC_INDICATION_PDU_T* entry) {
    ListNode *current;

    pthread_mutex_lock(&list_mutex);
    current = *head;
    while (current != NULL && current->data.rnti != rnti) {
        current = current->next;
    }

    if (current == NULL) { // Entry not found
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    memcpy(&current->data, entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    current->timestamp = time(NULL);
    pthread_mutex_unlock(&list_mutex);
}

void remove_entry(uint32_t rnti) {
    ListNode *current, *prev;

    pthread_mutex_lock(&list_mutex);
    current = *head;
    prev = NULL;

    while (current != NULL && current->data.rnti == rnti) {
        if (prev == NULL) { // Entry is the head, update head and move to next node
            *head = current->next;
        } else {
            prev->next = current->next;
        }
        free(current);
        num_entries--;
        current = prev ? prev->next : *head; // Move to the next node if any
    }
    pthread_mutex_unlock(&list_mutex);
}

// Initialize list mutex and setup periodic cleanup thread
void init() {
    pthread_mutex_init(&list_mutex, NULL);
    pthread_t cleanup_thread;
    struct timespec clean_interval = { .tv_sec = CLEANUP_INTERVAL };

    pthread_create(&cleanup_thread, NULL, (void*(*)(void*))cleanup, NULL);
    pthread_mutex_lock(&list_mutex);
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_PERIODIC_NP);
    pthread_attr_setschedpolicy(&attr, SCHED_FIFO);
    pthread_attr_setschedparam(&attr, &clean_interval);
    pthread_create(&cleanup_thread, &attr, (void*(*)(void*))cleanup, NULL);
    pthread_mutex_unlock(&list_mutex);
}
