#include <arpa/inet.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>
#include <time.h>
#include <syslog.h>

typedef struct {
    int min;
    int max;
    int sum;
    size_t count;
    bool valid;
    char buffer[4096]; // Adjust this value according to your needs
} integer_data;

void* process_packet(void *arg) {
    integer_data *data = arg;
    ssize_t bytes_received;

    while ((bytes_received = recv((int)data->min, data->buffer, sizeof(data->buffer), 0)) > 0) {
        data->count = 0;
        data->sum = 0;
        data->valid = true;

        char *token = strtok(data->buffer, ","); // Assuming comma-separated integers

        while (token != NULL) {
            int number = atoi(token);

            if ((number < data->min) || (number > data->max)) {
                data->valid = false;
                break;
            }

            if (data->count >= sizeof(data->buffer) / sizeof(int)) { // Handle buffer overflow risks
                syslog(LOG_ERR, "Buffer overflow occurred while processing the packet");
                data->valid = false;
                break;
            }

            data->sum += number;
            ++data->count;

            token = strtok(NULL, ",");
        }

        if (data->valid) { // Calculate and print the average of valid integers
            double avg = (double)data->sum / data->count;
            printf("Average: %.2f\n", avg);
        }
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <min_value> <max_value>\n", argv[0]);
        exit(1);
    }

    int min = atoi(argv[1]);
    int max = atoi(argv[2]);

    integer_data data = { .min = min, .max = max };

    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(atoi(argv[3])); // Assuming port number is provided as command-line argument
    inet_pton(AF_INET, argv[4], &server_addr.sin_addr); // Assuming IP address is provided as command-line argument

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error connecting to the server");
        exit(1);
    }

    pthread_t thread_id;
    while (1) {
        if (pthread_create(&thread_id, NULL, process_packet, &data) != 0) {
            perror("Error creating a processing thread");
            exit(1);
        }

        // Send the data packet to the server for further processing
        send(sockfd, &data, sizeof(data), 0);

        memset(&data, 0, sizeof(data)); // Clear the data structure after sending it
    }

    close(sockfd);
    return 0;
}
