import os
import subprocess
import sys
import tempfile
import shutil
from getpass import getuser
import hashlib
import hmac
import base64
import dotenv
import yaml

def create_dir(directory):
    try:
        os.makedirs(directory, exist_ok=True)
        os.chmod(directory, 0o700)
    except OSError as e:
        print(f'Error creating directory {directory}: {e}')

def load_env():
    dotenv_path = '.env'
    environment = os.environ['ENVIRONMENT']
    dotenv.load_dotenv(dotenv_path, override=True)

def resolve_placeholders(template, env):
    placeholders = {'{{ ENV }}': environment}
    for key, value in env.items():
        placeholders[f'{{ {key} }}'] = value
    return yaml.safe_load(yaml.safe_dump(template, default_flow_style=False).format_map(placeholders))

def encrypt_credentials(creds):
    key = os.environ['ENCRYPTION_KEY'].encode('utf-8')
    message = json.dumps(creds).encode('utf-8')
    hmac_key = hmac.new(key, digestmod=hashlib.sha256).digest()
    signature = base64.b64encode(hmac_key)
    encrypted_creds = base64.b64encode(hmac.new(key, msg=message, digestmod=hashlib.sha256).digest())
    return {**creds, '__signature__': signature.decode('utf-8'), '__encrypted__': encrypted_creds.decode('utf-8')}

def append_section(config, section):
    if not config or not section:
        return config

    last_key = None
    for key, value in reversed(list(config.items())):
        if isinstance(value, dict):
            last_key = key
        else:
            last_key = None

    if last_key is not None:
        config[last_key] = [section]
    else:
        config['additional'] = [section]

    return config

def execute_sed(config_path, template, env):
    with tempfile.TemporaryDirectory() as tempdir:
        output_path = os.path.join(tempdir, 'output.conf')
        create_dir(os.path.dirname(output_path))
        with open(config_path, 'r') as config_file:
            content = config_file.read()
            updated_content = resolve_placeholders(template, env).get('CONFIG', content)
            with open(output_path, 'w') as output_file:
                output_file.write(updated_content)
        command = f'sed -i "{updated_content}" {config_path}'
        try:
            subprocess.check_call(command, shell=True)
        except subprocess.CalledProcessError as e:
            print(f'Failed to execute sed command: {e}')
    return output_path

def main():
    load_env()
    template = ...  # Load your Kickstart configuration template here
    env = {'ENV': os.environ['ENVIRONMENT']}
    for key, value in os.environ.items():
        if key not in ['ENCRYPTION_KEY', 'ENVIRONMENT']:
            env[key] = value
    credentials = encrypt_credentials({...})  # Load your credentials here
    section = {'my_section': {...}}  # Define the new section you want to add here
    config = resolve_placeholders(template, env)
    config = append_section(config, section)
    output_path = execute_sed('kickstart.conf', config, env)
    shutil.move(output_path, f'{getuser()}/.ssh/kickstart_{os.environ["ENVIRONMENT"]}.conf')

if __name__ == '__main__':
    main()
