        if (pthread_create(&threads[i], NULL, &process_frame_info, array + i)) {
            perror("Thread creation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < ARRAY_SIZE; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("Thread joining failed\n");
            exit(EXIT_FAILURE);
        }
    }

    serialize(array, "dl_frame_info.csv");

    free(array);
    return 0;
}
```

