                    queue.push(next_state);
                    state_list[next_state - 1] = new int(next_state);
                }
            }
        } else {
            // Handle invalid transition and log error.
            log_error("Invalid state transition: from %d to unreachable state.", current_state);
        }
    }

    if (state_list->size() > config.max_list_size) {
