```cpp
#ifndef DATAHANDLER_H
#define DATAHANDLER_H

#include <list>
#include <string>
#include <algorithm>

class DataHandler {
private:
    std::forward_list<std::string> data;
public:
    void insertAfterInForwardList(const std::string& target, const std::string& value);
};

void DataHandler::insertAfterInForwardList(const std::string& target, const std::string& value) {
    auto it = data.begin();

    while (it != data.end() && *it != target)
        ++it;

    if (it == data.end()) {
        data.push_back(value);
        return;
    }

    it++;
    data.insert(it, value);
}

#endif // DATAHANDLER_H
