["```cpp
#include <iostream>
#include <vector>
#include <mutex>
#include <thread>
#include <chrono>
#include <random>

namespace RandomUtils {
    class MersenneTwisterGenerator {
        static constexpr size_t NUM_THREADS = 8; // Adjust as needed for your application's needs
        static constexpr size_t STATE_SIZE = 624;
        static constexpr size_t TEMP_BUFFER_SIZE = 32;
        static constexpr size_t MASK = (1 << 18) - 1; // 18 least significant bits
        static constexpr double TWIST_INTERVAL = 624U; // Period for the twist operation
        static constexpr double UPDATE_INTERVAL = 32U; // Number of updates per twist operation

        std::vector<uint32_t> state;
        std::vector<uint32_t> tempBuffer;
        size_t index;
        size_t twistIndex;
        std::mutex mutex;

    public:
        MersenneTwisterGenerator() {
            state.resize(STATE_SIZE);
            for (size_t i = 0; i < STATE_SIZE; ++i)
                state[i] = static_cast<uint32_t>(rand());
            index = 0;
            twister();
        }

        MersenneTwisterGenerator(const MersenneTwisterGenerator& other) = delete; // Disallow copy constructor
        MersenneTwisterGenerator& operator=(const MersenneTwisterGenerator& other) = delete; // Disallow assignment operator

        static MersenneTwisterGenerator* createInstance() {
            return new MersenneTwisterGenerator();
        }

        uint32_t getRandomNumber(uint32_t seed = 0) {
            std::lock_guard<std::mutex> lock(mutex);
            if (seed != 0) {
                state[index] = seed;
                index = (index + 1) % STATE_SIZE;
                twister();
            }
            uint32_t result = state[index];
            index = (index + 1) % STATE_SIZE;
            return result;
        }

        void resetState() {
            std::lock_guard<std::mutex> lock(mutex);
            for (size_t i = 0; i < STATE_SIZE; ++i)
                state[i] = static_cast<uint32_t>(rand());
            index = 0;
            twister();
        }

    private:
        void twister() {
            for (size_t i = 0; i < TWIST_INTERVAL; ++i) {
                uint32_t y = state[index];
                size_t j = (index + UPDATE_INTERVAL - 1) % STATE_SIZE;
                for (size_t k = 0; k < TEMP_BUFFER_SIZE; ++k) {
                    uint32_t t = (y >> 11) ^ ((y & MASK) << 15) ^ ((y >> 18) ^ static_cast<uint32_t>(y << 18) ^ static_cast<uint32_t>((y & -static_cast<uint32_t>(1)) >> 1));
                    if (k < TEMP_BUFFER_SIZE - 1) {
                        t = (t >> 11) ^ ((t & MASK) << 15) ^ ((t >> 18) ^ static_cast<uint32_t>(t << 18) ^ static_cast<uint32_t>((t & -static_cast<uint32_t>(1)) >> 1);
                        state[j] = state[j] ^ t;
                        j = (j + 1) % STATE_SIZE;
                    } else {
                        tempBuffer[k] = state[j];
                    }
                }
                y = tempBuffer[0];
                for (size_t k = TEMP_BUFFER_SIZE - 1; k > 0; --k)
                    tempBuffer[k] = tempBuffer[k - 1];
                tempBuffer[TEMP_BUFFER_SIZE - 1] = y;
            }
        }
    };
} // namespace RandomUtils
```

This code provides a basic implementation of the Mersenne Twister random number generator. The `MersenneTwisterGenerator` class is thread-safe due to the use of mutexes for accessing and updating shared state. The generator's state is resettable, balancing between performance and statistical quality by providing a configurable twist interval (TWIST_INTERVAL). Additionally, memory usage is optimized by considering trade-offs between static and dynamic allocation for the generator state, using vectors for both storage options. The class provides an intuitive interface for integration into external systems with a `getRandomNumber` method that accepts a seed value for customization purposes."]

