#define MAX_SIZE 100000 // Maximum size limit

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables for thread synchronization and logging
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int total_allocated = 0;
static int max_failed_attempts = 5;
static FILE *log_file;

// Function to initialize logging
void init_logging(const char *filename) {
    log_file = fopen(filename, "w");
}

// Function to write an error message to the log file and exit
void log_error_and_exit(const char *message) {
    fprintf(log_file, "%s\n", message);
    fclose(log_file);
    exit(1);
}

// Thread-safe function to allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_array(int n) {
    if (n <= 0 || n > MAX_SIZE) {
        log_error_and_exit("Invalid array size");
    }

    pthread_mutex_lock(&mutex);
    total_allocated += n;
    pthread_mutex_unlock(&mutex);

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_error_and_exit("Memory allocation failed");
    }

    for (int i = 0; i < n; ++i) {
        array[i].tag.rnti = (RNTI)(i + 1); // Set RNTI based on index
        array[i].crc_indication.crcFlag = rand() % 2; // Randomly set CRCFLAG
    }

    return array;
}

// Cleanup function to free allocated memory and log statistics
void cleanup(NFAPI_CRC_INDICATION_PDU_T *array) {
    pthread_mutex_lock(&mutex);
    total_allocated -= free(array);
    pthread_mutex_unlock(&mutex);
