['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

typedef struct {
    uint32_t eNB_ID;
    uint32_t cell_ID;
    int num_rrc_connections;
    RRC_Connection_State *rrc_connection_states;
    time_t last_update_timestamp;
} UE_Context;

typedef struct Node {
    UE_Context *ue_context;
    struct Node *next;
} Node;

struct DynamicArray {
    Node **nodes;
    int capacity;
    int size;
    pthread_mutex_t mutex;
};

void init_dynamic_array(struct DynamicArray *array, int initial_capacity) {
    array->capacity = initial_capacity;
    array->size = 0;
    array->nodes = calloc(initial_capacity, sizeof(Node*));
    pthread_mutex_init(&array->mutex, NULL);
}

void resize_dynamic_array(struct DynamicArray *array) {
    int new_capacity = array->capacity * 2;
    Node **new_nodes = realloc(array->nodes, new_capacity * sizeof(Node*));
    if (!new_nodes) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    array->nodes = new_nodes;
    array->capacity = new_capacity;
}

UE_Context* find_ue_context_by_eNB_ID_and_cell_ID(struct DynamicArray *array, uint32_t eNB_ID, uint32_t cell_ID) {
    pthread_mutex_lock(&array->mutex);
    for (int i = 0; i < array->size; ++i) {
        if (array->nodes[i]->ue_context->eNB_ID == eNB_ID && array->nodes[i]->ue_context->cell_ID == cell_ID) {
            pthread_mutex_unlock(&array->mutex);
            return array->nodes[i]->ue_context;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return NULL;
}

void add_ue_context(struct DynamicArray *array, UE_Context *ue_context) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        resize_dynamic_array(array);
    }
    array->nodes[array->size] = malloc(sizeof(Node));
    if (!array->nodes[array->size]) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&array->mutex);
        return;
    }
    array->nodes[array->size]->ue_context = ue_context;
    array->nodes[array->size]->next = NULL;
    ++array->size;
    pthread_mutex_unlock(&array->mutex);
}

void update_ue_context(UE_Context *ue_context, time_t current_timestamp) {
    ue_context->last_update_timestamp = current_timestamp;
}

void clean_inactive_contexts(struct DynamicArray *array, time_t threshold_timestamp) {
    pthread_mutex_lock(&array->mutex);
    Node **iter = array->nodes;
    Node **end = iter + array->size;

    for (; iter != end; ) {
        if ((*iter)->ue_context->last_update_timestamp < threshold_timestamp) {
            UE_Context *ue_context = (*iter)->ue_context;
            free(ue_context->rrc_connection_states);
            free(*iter);
            *iter = iter[array->size - 1];
            --array->size;
        } else {
            ++iter;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

int get_active_contexts(struct DynamicArray *array) {
    int count = 0;
    pthread_mutex_lock(&array->mutex);
    Node **iter = array->nodes;
    for (; iter != NULL; iter = iter[1]) {
        if (iter[0]->ue_context->last_update_timestamp > get_current_timestamp() - INACTIVE_THRESHOLD) {
            ++count;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return count;
}
```

This is a basic implementation of the required function. The DynamicArray structure manages an array of UE contexts, allowing for adding new ones and updating existing ones efficiently. Cleanup of inactive contexts is performed periodically based on the last update timestamp. The function is thread-safe using a pthread_mutex to protect data integrity.

The code assumes the existence of an RRC_Connection_State structure, a get_current_timestamp() function, and an INACTIVE_THRESHOLD constant for determining which contexts are considered inactive. This implementation does not include the integration with external data sources or the optimization for high-concurrency conditions, lock-free data structures, and batch updates. Those aspects would require additional work tailored to your specific system requirements.']

