public class UserProfileService
{
    private readonly ILogger _logger;
    private readonly IMemoryCache _cache;
    private readonly int _maxCacheEntries;
    private readonly TimeSpan _cacheEntryDuration;
    private readonly string _connectionString;
    private readonly string _sqlCommand;
    private readonly DbConnection _dbConnection;
    private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1, 1);
    private readonly int _retryLimit;
    private readonly TimeSpan _retryDelay;
    private readonly Func<IDbConnection> _dbConnectionFactory;
    private readonly Func<IEnumerable<int>, IEnumerable<UserProfile>> _userProfileServiceFunc;

    public UserProfileService(ILogger<UserProfileService> logger, IMemoryCache cache, int maxCacheEntries, TimeSpan cacheEntryDuration, string connectionString, string sqlCommand, Func<IDbConnection> dbConnectionFactory, Func<IEnumerable<int>, IEnumerable<UserProfile>> userProfileServiceFunc, int retryLimit = 5, TimeSpan retryDelay = TimeSpan.FromSeconds(5))
    {
        _logger = logger;
        _cache = cache;
        _maxCacheEntries = maxCacheEntries;
        _cacheEntryDuration = cacheEntryDuration;
        _connectionString = connectionString;
        _sqlCommand = sqlCommand;
        _dbConnectionFactory = dbConnectionFactory;
        _userProfileServiceFunc = userProfileServiceFunc;
        _retryLimit = retryLimit;
        _retryDelay = retryDelay;
    }

    public async Task<IEnumerable<UserProfile>> GetUserProfilesByIdsAsync(IEnumerable<int> userIds)
    {
        var key = $"GetUserProfilesByIds_{string.Join(",", userIds)}";
        if (_cache.TryGetValue(key, out IEnumerable<UserProfile> cachedResults))
            return cachedResults;

        await _semaphore.WaitAsync();
        try
        {
            var results = new List<UserProfile>();

            using (var dbConnection = _dbConnectionFactory())
            {
                var sqlQuery = $"{_sqlCommand} WHERE Id IN ({string.Join(",", userIds)})";

                var cachedConnection = dbConnection as IDbCacheConnection;
                if (cachedConnection != null)
                {
                    results = await cachedConnection.QueryMultipleAsync(sqlQuery, userIds.ToArray()).ConfigureAwait(false);
                }
                else
                {
                    var retries = _retryLimit;
                    while (retries > 0)
                    {
                        try
                        {
                            results = await dbConnection.QueryAsync<UserProfile>(sqlQuery, userIds.ToArray()).ConfigureAwait(false);
                            break;
                        }
                        catch (Exception ex) when (retries-- > 0)
                        {
                            _logger.LogError(ex, "Database connection failure during GetUserProfilesByIdsAsync operation.");
                            await Task.Delay(_retryDelay);
                        }
                    }
                }
            }

            results = _userProfileServiceFunc(results).ToList();

            var cacheEntryOptions = new MemoryCacheEntryOptions()
                .SetAbsoluteExpiration(TimeSpan.FromMinutes(10))
                .SetSlidingExpiration(TimeSpan.FromSeconds(30));

            _cache.Set(key, results, cacheEntryOptions);
            return results;
        }
        finally
        {
            _semaphore.Release();
        }
    }
}
```

This code creates a `UserProfileService` class that provides an asynchronous method for retrieving user profiles by IDs, leveraging Dapper as the ORM and Microsoft's MemoryCache for caching frequently accessed user profiles. The service also incorporates batch processing, caching, concurrent access control, database connection retries, and logging.

It accepts a list of user IDs, a SQL command, a database connection factory, and additional configuration parameters such as retry limits and delays. The service is extensible to accommodate future filtering criteria or sorting options, and it can be easily integrated with a third-party user profile service by providing a custom `userProfileServiceFunc`.

The `GetUserProfilesByIdsAsync` method uses a semaphore to control concurrent access, ensuring that no more than one request is processed at a time. It checks the cache for results before executing the SQL query and refreshes the cache if necessary. If the database connection fails, it retries the operation up to a configurable limit with a configurable delay between retries.']

