public class UpdateService
{
    private readonly HttpClient _httpClient;
    private readonly string _apiUrl;

    public UpdateService(HttpClient httpClient, string apiUrl)
    {
        _httpClient = httpClient;
        _apiUrl = apiUrl;
    }

    public async Task<bool> UpdateElementContent(string pageSectionId, string elementId, string htmlContent, string cacheBusterToken = null)
    {
        var requestUri = $"{_apiUrl}/update-element/{pageSectionId}/{elementId}";
        var request = new HttpRequestMessage(HttpMethod.Post, requestUri);
        request.Headers.Add("X-Cache-Buster", cacheBusterToken ?? GenerateMD5Hash(htmlContent));
        request.Content = new StringContent(htmlContent);

        try
        {
            var response = await _httpClient.SendAsync(request).ConfigureAwait(false);
            if (!response.IsSuccessStatusCode) return false;
            return true;
        }
        catch (Exception ex) when (!(ex is TimeoutException || ex is TaskCanceledException)) // Handle timeouts and cancellations gracefully without failing the update process
        {
            return false;
        }
    }

    private static string GenerateMD5Hash(string input)
    {
        using (var md5 = MD5.Create())
        {
            var bytes = Encoding.UTF8.GetBytes(input);
            var hash = md5.ComputeHash(bytes);
            return BitConverter.ToString(hash).Replace("-", "").ToLower();
        }
    }
}
