    regex_t* regexes = malloc(sizeof(regex_t) * config.book_regexes_len);
    for (size_t i = 0; i < config.book_regexes_len; ++i) {
        regcomp(&regexes[i], config.book_regexes[i], REG_EXTENDED | (config.case_sensitive ? REG_CUSTOM : REG_ICASE));
    }
    return regexes;
}

int is_digit(char c) {
    return c >= '0' && c <= '9';
}

void find_books(const char* text, size_t text_length, regex_t** regexes, int* book_counts) {
    for (size_t i = 0; i < regexes_len; ++i) {
        regmatch_t match;
        if (regexec(&regexes[i], text, 1, &match, 0)) {
            size_t start = match.rm_so;
            size_t end = match.rm_eo;
            book_counts[i]++;
            for (size_t j = start + 1; j < end; ++j) {
                if (!isalpha(text[j])) {
                    start = j + 1;
                }
            }
            strncpy(books[i], text + start, end - start);
        }
    }
}

char* get_filename_extension(const char* filename) {
    size_t length = strlen(filename);
    for (size_t i = length - 1; i > 0; --i) {
        if (is_digit(filename[i])) {
            break;
        }
        if (filename[i] == '.') {
            return filename + i;
        }
    }
    return "";
}

char* modify_filename(const char* original, const Config config) {
    // ... Code for checking for conflicts and creating a unique filename if needed ...

    size_t length = strlen(original);
    char* new_extension = get_filename_extension(original);
    if (strlen(new_extension) == 0 || strcmp(new_extension, config.extension) != 0) {
        snprintf(new_extension, sizeof(new_extension), "%s%s", config.extension, new_extension);
    }

    char* new_filename = malloc(length + strlen(new_extension));
    strcpy(new_filename, original);
    strcat(new_filename, new_extension);

    return new_filename;
}

Result processTextAndRenameFile(const char* text, const char* filename, const Config config) {
    Result result;
    size_t text_length = strlen(text);
    regex_t* regexes = create_regexes(config, text_length);
    int* book_counts = calloc(regexes_len, sizeof(int));
    result.books = malloc(regexes_len * sizeof(char*));
    result.counts = malloc(regexes_len * sizeof(int));

    find_books(text, text_length, regexes, book_counts);

    for (size_t i = 0; i < regexes_len; ++i) {
        regfree(&regexes[i]);
    }
    free(regexes);

    for (size_t i = 0; i < regexes_len; ++i) {
        result.books[i] = malloc(strlen(books[i]) + 1);
        strcpy(result.books[i], books[i]);
        result.counts[i] = book_counts[i];
    }

    char* new_filename = modify_filename(filename, config);
    result.new_filename = new_filename;

    return result;
}
