typedef struct {
    uint32_t enb_id;
    uint16_t cell_id;
    uint32_t num_rrc_states; // Number of RRC connection states in the array
    struct RRC_State* rrc_states; // Pointer to an array of RRC_States
} UE_Context;

typedef struct {
    UE_Context** contexts;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} UE_Context_Manager;

UE_Context_Manager* ue_context_manager_init(size_t initial_capacity) {
    UE_Context_Manager* manager = malloc(sizeof(UE_Context_Manager));
    manager->contexts = calloc(initial_capacity, sizeof(UE_Context*));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void ue_context_manager_add(UE_Context_Manager* manager, UE_Context* context) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count == manager->capacity) {
        manager->capacity *= 2;
        manager->contexts = realloc(manager->contexts, manager->capacity * sizeof(UE_Context*));
    }
    manager->contexts[manager->count] = context;
    manager->count++;
    pthread_mutex_unlock(&manager->mutex);
}

UE_Context* ue_context_manager_get(UE_Context_Manager* manager, uint32_t enb_id, uint16_t cell_id) {
    UE_Context** contexts = manager->contexts;
    for (size_t i = 0; i < manager->count; ++i) {
        if (contexts[i]->enb_id == enb_id && contexts[i]->cell_id == cell_id) {
            return contexts[i];
        }
    }
    return NULL;
}

