class ByteCopier {
  constructor(truncate = true, errorOnOverflow = false) {
    this.totalCopiedBytes = 0;
    this.truncate = truncate;
    this.errorOnOverflow = errorOnOverflow;
  }

  async copyBytes(bufferSource, byteOffset, byteCount, bufferDest, destOffset) {
    if (byteCount > bufferSource.length || (!this.truncate && byteCount > bufferSource.byteLength)) {
      return this.errorOnOverflow ? null : Promise.reject(new Error('Requested byte count exceeds available data length'));
    }

    const endIndex = Math.min(bufferSource.length, byteOffset + byteCount);
    const sourceSlice = bufferSource.slice(byteOffset, endIndex);
    if (!sourceSlice.byteLength) return 0;

    let copiedBytes = sourceSlice.copy(bufferDest, destOffset, sourceSlice.byteLength);
    this.totalCopiedBytes += copiedBytes;

    return copiedBytes;
  }
}
```

