['```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class ConfigurableRandomGenerator
{
    private readonly System.Random _random;
    private int _seedValue;
    private (int min, int max) _range;
    private double _mean;
    private double _variance;
    private int _sampleCount;

    public ConfigurableRandomGenerator(int seed = 0, (int min, int max) range = default)
    {
        _seedValue = seed;
        _range = range;
        _random = new System.Random(_seedValue);
        if (_range.min > _range.max)
            throw new ArgumentException("Invalid range boundaries");
    }

    public void SetRange(int min, int max)
    {
        if (min > max)
            throw new ArgumentException("Invalid range boundaries");
        _range = (min, max);
    }

    public void SetSeed(int seed) => _seedValue = seed;

    public int GetInt(bool exclusiveUpperLimit = false)
    {
        var value = _random.Next(_range.min, _range.max + (exclusiveUpperLimit ? 1 : 0));
        IncrementAndUpdateStatistics(value);
        return value;
    }

    public float GetFloat(bool exclusiveUpperLimit = false)
    {
        var fractionalValue = (_random.NextDouble() * (_range.max - _range.min + (exclusiveUpperLimit ? 1 : 0))).ToFloat();
        IncrementAndUpdateStatistics((int)Math.Floor(fractionalValue));
        return fractionalValue;
    }

    private void IncrementAndUpdateStatistics(int value)
    {
        _sampleCount++;
        double deviation = (value - _mean) / _variance;
        _mean += deviation * (1d/_sampleCount);
        _variance += (deviation * deviation - _variance) * (1d/(_sampleCount-1));
    }

    public override string ToString() => $"ConfigurableRandomGenerator({_seedValue}, {_range.min}-{_range.max}, Mean: {_mean}, Variance: {_variance})";
}
```
This code implements a `ConfigurableRandomGenerator` class that leverages the underlying operations of `System.Random` for performance and reproducibility, while providing flexibility in configuring the seed value and range boundaries. The class supports generation of random integers and floats within specified ranges, ensures robust error handling for invalid range inputs, and provides methods to update the average and variance based on generated values. Additionally, the `ToString` method has been overridden to display the current configuration and relevant statistics, making it easier to integrate into larger simulation frameworks or analyze performance.']

