char* conditionalStringWithLimit(const char* str, size_t limit) {
    if (!str || limit == 0) return NULL;

    size_t strLen = strlen(str);
    if (strLen > limit) return NULL;

    char* result = malloc(limit + 1); // +1 for the possible forward slash
    if (!result) return NULL;

    memcpy(result, str, strLen);
