public static SqlDataReader createParameterizedSqlCommand(List<object> values, string connectionString, string sqlCommand) {
    if (string.IsNullOrEmpty(connectionString)) throw new ArgumentNullException(nameof(connectionString));
    if (string.IsNullOrEmpty(sqlCommand)) throw new ArgumentNullException(nameof(sqlCommand));

    using (SqlConnection connection = new SqlConnection(connectionString)) {
        if (connection.State != System.Data.ConnectionState.Open) connection.Open();

        SqlCommand command = new SqlCommand(sqlCommand, connection);
        command.Parameters.AddRange(values.ToArray());

