public class WebsiteManager
{
    private readonly ConcurrentDictionary<Tuple<int, IPAddress>, WebServer> _webServers = new ConcurrentDictionary<Tuple<int, IPAddress>, WebServer>();
    private readonly object _syncLock = new object();
    private const int DefaultPort = 80;
