    public async Task DeployWebsiteAsync(string directoryPath, int? port = null)
    {
        if (!Directory.Exists(directoryPath) || !Directory.GetFiles(directoryPath, "web.config", SearchOption.AllDirectories).Any())
        {
            throw new ArgumentException("Invalid directory path or missing web.config file.");
        }

        var websiteSettings = await FetchConfigurationAsync(directoryPath);

        if (!Directory.Exists(websiteSettings.RootDirectory))
        {
            throw new DirectoryNotFoundException($"The root directory for the website does not exist: {websiteSettings.RootDirectory}");
        }

        var currentPort = port ?? DefaultPort;
        var ipAddress = FindFreeIpAndPort(currentPort);

        if (ipAddress == null)
        {
            throw new Exception($"Could not find a free IP address and port combination.");
        }

        var webServer = new WebServer(Directory.GetFiles(directoryPath, "*.*", SearchOption.AllDirectories), websiteSettings);
        await webServer.StartAsync(ipAddress.Item1, ipAddress.Item2, currentPort);

        lock (_syncLock)
        {
            _webServers[new Tuple<int, IPAddress>(currentPort, ipAddress)] = webServer;
        }
    }

    private async Task<WebsiteConfiguration> FetchConfigurationAsync(string directoryPath)
    {
        var webConfigFiles = Directory.GetFiles(directoryPath, "web.config", SearchOption.AllDirectories);
        var webConfigJson = File.ReadAllText(webConfigFiles.FirstOrDefault());

        if (string.IsNullOrEmpty(webConfigJson))
        {
            Console.WriteLine("The web.config file is empty. Please fill in the required details.");
            await FillInMissingDetailsInteractivelyAsync(directoryPath);
            webConfigJson = File.ReadAllText(webConfigFiles.FirstOrDefault());
        }

        return JsonConvert.DeserializeObject<WebsiteConfiguration>(webConfigJson);
    }

    private async Task FillInMissingDetailsInteractivelyAsync(string directoryPath)
    {
        // Implement interactive prompting for missing details in the web.config file, using Console.ReadLine() and File.WriteAllText() as needed
    }

    private (IPAddress, int) FindFreeIpAndPort(int port = DefaultPort)
    {
        var ipAddresses = NetworkInterface.GetAllNetworkInterfaces().Select(ni => ni.GetIPProperties().UnicastAddresses.FirstOrDefault(ua => ua.Address.AddressFamily == AddressFamily.InterNetwork)).Where(ipa => ipa != null);

        foreach (var ip in ipAddresses)
        {
            var tcpListener = new TcpListener(ip.Address, port);
            try
            {
                tcpListener.Start();
                tcpListener.Stop();

                return (ip.Address, port);
            }
            catch (SocketException)
            {
                // Port is in use, try the next IP address and port
            }
        }

        return (IPAddress.None, 0);
    }
}

public class WebServer
{
    private readonly DirectoryInfo _rootDirectory;
    private readonly WebsiteConfiguration _configuration;

    public WebServer(DirectoryInfo rootDirectory, WebsiteConfiguration configuration)
    {
        _rootDirectory = rootDirectory;
        _configuration = configuration;
    }

    public async Task StartAsync(int port, IPAddress ipAddress, int currentPort)
    {
        var server = new WebRequestHandler(_configuration);
        using var httpServer = new HttpListener(server);
        httpServer.Prefixes.Add($"http://{ipAddress}:{port}/");

        try
        {
            httpServer.Start();

            Console.WriteLine($"Website '{_configuration.Name}' started on IP: {ipAddress}, Port: {port}.");

            await Task.Delay(_timeout);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to start website '{_configuration.Name}'. Error: {ex.Message}");
            throw;
        }
    }
}

public class WebRequestHandler : HttpWebRequestCreator
{
    private readonly WebsiteConfiguration _configuration;

    public WebRequestHandler(WebsiteConfiguration configuration)
    {
        _configuration = configuration;
    }

    protected override WebRequest Create(Uri requestUri)
    {
        var webRequest = base.Create(requestUri);

        if (_configuration.DocumentRoot != null && !webRequest.Url.AbsolutePath.StartsWith(_configuration.DocumentRoot))
        {
            webRequest.Headers["X-Original-URL"] = requestUri.AbsolutePath;
            webRequest.Url = new Uri(new Uri(_configuration.DocumentRoot), requestUri);
        }

        return webRequest;
    }
}

public class WebsiteConfiguration
{
    public string Name { get; set; }
    public string DocumentRoot { get; set; }
    public string RootDirectory { get; set; }
    // Add other properties as needed
}

public interface IConfigurationService
{
    Task<WebsiteConfiguration> FetchWebsiteConfigurationAsync(string websiteName);
}
