#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>

typedef struct {
    time_t expires;
    char *token_type;
    char *access_token;
    char *refresh_token;
} TokenData;

struct ipCache {
    struct hostent cachedHost;
    pthread_mutex_t lock;
    time_t timestamp;
};

static int rateLimitAccessToken = 0;
static int rateLimitDns = 0;

bool processAccessTokenAndResolveAddress(const char *jsonString, const char *hostname, uint32_t dnsTimeLimit) {
    Jsonsson *json = json_loads(jsonString, NULL);
    if (!json || !json_is_object(json)) {
        return false;
    }

    TokenData tokenData;
    json_object_foreach(json, key, value) {
        if (strcmp(key, "access_token") == 0) {
            tokenData.access_token = json_string_value(value);
        } else if (strcmp(key, "expires_in") == 0) {
            int expiresIn = json_integer_value(value);
            if (expiresIn <= 0) {
                return false;
            }
            tokenData.expires = time(NULL) + expiresIn;
        } else if (strcmp(key, "token_type") == 0) {
            tokenData.token_type = json_string_value(value);
            if (strcmp(tokenData.token_type, "Bearer") != 0) {
                return false;
            }
        } else if (strcmp(key, "refresh_token") == 0) {
            tokenData.refresh_token = json_string_value(value);
        }
    }
    json_decref(json);

    if (!tokenData.access_token || !tokenData.expires || !tokenData.token_type ||
        (tokenData.refresh_token && strcmp(tokenData.refresh_token, ""))) {
        return false;
    }

    struct ipCache *ipCache = calloc(1, sizeof(struct ipCache));
    pthread_mutex_init(&ipCache->lock, NULL);
    ipCache->timestamp = time(NULL);

    CURL *curl = curl_easy_init();
    if (!curl) {
        free(ipCache);
        return false;
    }

    struct timeval tvNow;
    gettimeofday(&tvNow, NULL);
    double currentTime = (double)tvNow.tv_sec + ((double)tvNow.tv_usec / 1000000);
    char tokenValidationUrl[256];
    sprintf(tokenValidationUrl, "https://auth-service.example.com/api/v1/tokens/%s?client_ip=%s", tokenData.access_token, getenv("REMOTE_ADDR"));

    if (currentTime - rateLimitAccessToken > 60 && curl_easy_setopt(curl, CURLOPT_URL, tokenValidationUrl) == CURLE_OK) {
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_perform(curl);
        int statusCode = (int)WILL_NOT_PERFORM;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &statusCode);
        if (statusCode != 200) {
            free(ipCache);
            return false;
        }
        rateLimitAccessToken = currentTime;
    } else {
        free(ipCache);
        return false;
    }

    curl_easy_setopt(curl, CURLOPT_URL, "https://dns.google/resolve");
    struct hostent *resolvedHost = NULL;
    if (currentTime - rateLimitDns > 60 && dnsTimeLimit >= time(NULL) + 1000 && curl_easy_setopt(curl, CURLOPT_URL, hostname) == CURLE_OK) {
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, resolveDnsCallback);
        curl_easy_perform(curl);
        if (!resolvedHost) {
            free(ipCache);
            return false;
        }
    } else {
        free(ipCache);
        return false;
    }

    ipCache->cachedHost = *resolvedHost;
    rateLimitDns = currentTime;

    u_char resolvedIp[INET6_ADDRSTRLEN];
    inet_ntop(AF_INET, &ipCache->cachedHost.h_addr, resolvedIp, sizeof(resolvedIp));
    free(ipCache);

    return true;
}

static size_t resolveDnsCallback(void *ptr, size_t size, size_t nmemb, void *userp) {
    struct hostent *resolvedHost = userp;
    memcpy(&resolvedHost->h_addr, ptr, size * nmemb);
    return size * nmemb;
}
