public class MessageHandler
{
    private static readonly Logger _logger = LogManager.GetCurrentClassLogger();
    private readonly ConcurrentQueue<string> _messageQueue;
    private readonly TripleDESCryptoServiceProvider _tripleDES;
    private readonly HMACSHA256 _hmacSHA256;
    private bool _isInitialized;

    public MessageHandler()
    {
        _messageQueue = new ConcurrentQueue<string>();
        Initialize();
    }

    private void Initialize()
    {
        if (_isInitialized) return;

        using (var aesKey = new Rfc2898DeriveBytes(key: "your-secret-key", salt: "your-salt", iterations: 1000))
        {
            _tripleDES = new TripleDESCryptoServiceProvider();
            _tripleDES.Key = aesKey.GetBytes(aesKey.KeySize / 8);
            _tripleDES.IV = aesKey.GetBytes(_tripleDES.IV.Length);
        }

        _hmacSHA256 = new HMACSHA256(Encoding.UTF8.GetBytes("your-hmac-key"));
        _isInitialized = true;
    }

    public void EnqueueMessage(string base64EncodedMessage)
    {
        if (string.IsNullOrWhiteSpace(base64EncodedMessage)) return;

        _messageQueue.Enqueue(base64EncodedMessage);
    }

    public Task ProcessMessagesAsync()
    {
        return Task.Run(() =>
        {
            while (_messageQueue.Count > 0)
            {
                if (!ProcessNextMessage()) break;
            }
        });
    }

    private bool ProcessNextMessage()
    {
        string base64EncodedMessage;
        if (!_messageQueue.TryDequeue(out base64EncodedMessage)) return false;

        try
        {
            var decryptedAndValidatedMessage = DecryptAndValidateMessage(base64EncodedMessage);
            ProcessMessage(decryptedAndValidatedMessage);
            return true;
        }
        catch (Exception ex)
        {
            _logger.Error(ex, "Failed to process message: {Base64EncodedMessage}", base64EncodedMessage);
        }

        return false;
    }

    private string DecryptAndValidateMessage(string base64EncodedMessage)
    {
        var data = Convert.FromBase64String(base64EncodedMessage);
        var decryptedData = _tripleDES.CreateDecryptor().TransformFinalBlock(data, 0, data.Length);
        var hmac = new byte[SHA256.Size];
        Buffer.BlockCopy(decryptedData, decryptedData.Length - SHA256.Size, hmac, 0, SHA256.Size);

        if (!_hmacSHA256.ComputeHash(hmac).SequenceEqual(_hmacSHA256.ComputeHash(data, 0, data.Length - SHA256.Size)))
            throw new Exception("Invalid HMAC!");

        return Encoding.UTF8.GetString(decryptedData);
    }

    private void ProcessMessage(string message)
    {
        // Your custom business logic here
    }
}
