```csharp
using System;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Logging;
using System.Collections.Concurrent;
using System.Threading;

public class HashService
{
    private readonly ConcurrentDictionary<string, byte[]> _cache = new ConcurrentDictionary<string, byte[]>();
    private readonly ILogger<HashService> _logger;
    private int _cacheSize = 1000;

    public HashService(ILogger<HashService> logger)
    {
        _logger = logger;
    }

    public byte[] GetMD5Hash(string input)
    {
        if (input.Length > 1024) throw new ArgumentException("Input string exceeds the maximum length of 1024 characters.");

        if (_cache.TryGetValue(input, out var cachedHash)) return cachedHash;

        using (var md5 = MD5.Create())
        {
            var hashedBytes = md5.ComputeHash(Encoding.UTF8.GetBytes(input));
            _cache.TryAdd(input, hashedBytes);
            Interlocked.Increment(ref _cacheSize);
            if (_cacheSize > _cacheSize) _cache.TryRemoveByKey(GetLeastRecentlyUsed());
        }

        return _cache[input];
    }

    private string GetLeastRecentlyUsed()
    {
        var entryToRemove = default(KeyValuePair<string, byte[]>);
        foreach (var kv in _cache)
        {
            if (Thread.VolatileRead(ref entryToRemove) == kv || !Interlocked.CompareExchange(ref entryToRemove, kv, entryToRemove) == entryToRemove)
                return kv.Key;
        }
        throw new Exception("Unreachable code.");
    }

    public void ClearCache()
    {
        _cache.Clear();
        Interlocked.Exchange(ref _cacheSize, _cacheSize = 0);
    }
}
```

