List* list_init(unsigned int max_size, size_t log_max_kb) {
    List *list = malloc(sizeof(List));
    if (!list) return NULL;

    list->max_size = max_size;
    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

