[' Here is an example implementation using a doubly-linked list with a custom hash table (hashmap) for efficient lookup based on RNTI. This solution uses mutexes for synchronization, but you can explore other concurrency strategies like lock-free data structures if needed.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    time_t timestamp; // Timestamp when the entry was added or updated
} NFAPI_CRC_INDICATION_PDU;

typedef struct NODE {
    NFAPI_CRC_INDICATION_PDU data;
    struct NODE *prev, *next;
} NODE;

#define HASHMAP_SIZE 1024
struct hashmap {
    int size;
    NODE **buckets;
    pthread_mutex_t mutex;
};

void hashmap_init(struct hashmap *map) {
    map->size = HASHMAP_SIZE;
    map->buckets = calloc(HASHMAP_SIZE, sizeof(NODE*));
    if (!map->buckets) return;
    memset(map->buckets, 0, HASHMAP_SIZE * sizeof(NODE*));
    pthread_mutex_init(&map->mutex, NULL);
}

int hash(const char *key, int len) {
    uint32_t h = len, temp;
    for (int i = 0; i < len; ++i) {
        h = (h << 5) + h + key[i];
        temp = h & ~1;
        h ^= temp >> 2;
    }
    return h % HASHMAP_SIZE;
}

void hashmap_put(struct hashmap *map, NODE *node) {
    pthread_mutex_lock(&map->mutex);
    int pos = hash((char *)&node->data.tag, sizeof(RX_UE_INFORMATION_TAG));
    node->next = map->buckets[pos];
    map->buckets[pos] = node;
    pthread_mutex_unlock(&map->mutex);
}

NODE* hashmap_get(struct hashmap *map, const char *key, int len) {
    NODE *result = NULL;
    pthread_mutex_lock(&map->mutex);
    int pos = hash((char *)key, len);
    NODE *current = map->buckets[pos];
    while (current != NULL) {
        if (!memcmp(&current->data.tag, key, len)) {
            result = current;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&map->mutex);
    return result;
}

void list_add(NFAPI_CRC_INDICATION_PDU_T *data, struct hashmap *list) {
    NODE *node = malloc(sizeof(NODE));
    if (!node) return;
    node->data = *data;
    node->prev = NULL;
    node->next = NULL;
    NODE *existing = hashmap_get(list, (char *)&data->tag, sizeof(RX_UE_INFORMATION_TAG));
    if (existing) {
        // Update existing entry
        if (existing->prev) existing->prev->next = node;
        else list->buckets[0] = node;
        node->prev = existing->prev;
        node->next = existing;
        existing->prev = node;
    } else {
        // Add new entry
        hashmap_put(list, node);
    }
}

void list_remove(int rnti, struct hashmap *list) {
    NODE *current = NULL;
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < HASHMAP_SIZE; ++i) {
        current = list->buckets[i];
        while (current != NULL) {
            if (current->data.rnti == rnti) {
                NODE *next = current->next;
                if (current->prev) current->prev->next = next;
                else list->buckets[0] = next;
                free(current);
                break;
            }
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void clean_up(struct hashmap *list, time_t threshold) {
    NODE *current = NULL;
    NODE *tmp;
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < HASHMAP_SIZE; ++i) {
        current = list->buckets[i];
        while (current != NULL) {
            if ((time(NULL) - current->data.timestamp) > threshold) {
                tmp = current->next;
                if (current->prev) current->prev->next = tmp;
                else list->buckets[0] = tmp;
                free(current);
            } else {
                current = current->next;
            }
        }
    }
    pthread_mutex_unlock(&list->mutex);
}
```

This implementation uses a doubly-linked list for dynamic size management and a custom hash table to quickly find entries based on RNTI. Concurrency is handled using mutexes, but you can explore other strategies if needed. The clean-up function removes expired entries periodically.

To use this code, first initialize the hashmap with `hashmap_init()`, then create an instance of the structure and call `list_add()` to add entries. Use `hashmap_get()` or `list_remove()` to find or remove specific entries. Finally, call `clean_up()` to remove expired entries.

This solution is optimized for resource constraints by using a custom hash table and a doubly-linked list. However, you can further optimize it based on your specific requirements and the characteristics of your environment.']

