#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>

#define MAX_RULES 1024
#define BUFFER_SIZE 65536

struct Rule {
    char operation; // Operation to be performed ('r' for read, 'w' for write)
    off_t offset;   // Offset in the file
    size_t length;  // Length of data to be processed
};

typedef struct {
    pthread_mutex_t mutex;
    int fd_input;
    int fd_output;
    int compression;
    int concurrency;
    struct Rule rules[MAX_RULES];
    size_t num_rules;
    double timeout;
} Config;

void* process_file(void* arg);
void load_config(Config* cfg, char* filename);
void log_error(char* message);

int main(int argc, char** argv) {
    if (argc != 7) {
        fprintf(stderr, "Usage: %s <input> <output> <config> <timeout> <compression> <concurrency>\n", argv[0]);
        return 1;
    }

    Config cfg = {};
    cfg.fd_input = open(argv[1], O_RDONLY);
    if (cfg.fd_input == -1) {
        log_error("Failed to open input file");
        return 1;
    }

    cfg.fd_output = open(argv[2], O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (cfg.fd_output == -1) {
        log_error("Failed to open output file");
        close(cfg.fd_input);
        return 1;
    }

    load_config(&cfg, argv[3]);
    cfg.timeout = atof(argv[4]);
    cfg.compression = atoi(argv[5]);
    cfg.concurrency = atoi(argv[6]);

    pthread_t threads[cfg.concurrency];
    for (int i = 0; i < cfg.concurrency; ++i) {
        int result = pthread_create(&threads[i], NULL, process_file, &cfg);
        if (result != 0) {
            log_error("Failed to create thread");
            close(cfg.fd_input);
            close(cfg.fd_output);
            return 1;
        }
    }

    for (int i = 0; i < cfg.concurrency; ++i) {
        pthread_join(threads[i], NULL);
    }

    close(cfg.fd_input);
    close(cfg.fd_output);

    return 0;
}

void* process_file(void* arg) {
    Config* cfg = arg;
    void* buffer = malloc(BUFFER_SIZE);
    size_t bytes_read, i;

    while (1) {
        if (feof(cfg->fd_input)) break;

        bytes_read = read(cfg->fd_input, buffer, BUFFER_SIZE);
        if (bytes_read <= 0) {
            log_error("Error reading input file");
            free(buffer);
            return NULL;
        }

        pthread_mutex_lock(&cfg->mutex);
        for (i = 0; i < cfg->num_rules; ++i) {
            if (cfg->rules[i].offset >= ftell(cfg->fd_input)) continue;

            char* start = buffer + cfg->rules[i].offset;
            size_t len = cfg->rules[i].length < bytes_read - cfg->rules[i].offset ?
                        cfg->rules[i].length : bytes_read - cfg->rules[i].offset;

            if (cfg->rules[i].operation == 'r') {
                memcpy(start, buffer + ftell(cfg->fd_input) + len, cfg->rules[i].length);
            } else if (cfg->rules[i].operation == 'w') {
                write(cfg->fd_output, start, len);
            }
        }
        pthread_mutex_unlock(&cfg->mutex);
    }

    free(buffer);
    return NULL;
}

void load_config(Config* cfg, char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        log_error("Failed to open configuration file");
        return;
    }

    char line[1024];
    size_t num_rules = 0;

    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%c %lld %ld\n", &cfg->rules[num_rules].operation, &cfg->rules[num_rules].offset, &cfg->rules[num_rules].length) != 3) {
            log_error("Invalid rule format");
        } else {
            ++num_rules;
        }
    }

    fclose(file);
    cfg->num_rules = num_rules;
}

void log_error(char* message) {
    fprintf(stderr, "%s\n", message);
    write(STDERR_FILENO, "\n", 1);
}
```
