// Function to process the text file and update the forward list
void processFile(ifstream& file, const set<string>& stopWords, unordered_map<string, int>& wordFrequency, vector<string>& forwardList, string& insertAfter) {
    string line;
    stringstream wordsStream;

    while (getline(file, line)) {
        wordsStream.clear();
        wordsStream << line;

        copy(istream_iterator<string>(wordsStream), {}, back_inserter(wordTokens));

        set_difference(wordTokens.begin(), wordTokens.end(), stopWords.begin(), stopWords.end(), inserter(uniqueWordSet, wordTokens.end()));

        for (auto& word : uniqueWordSet) {
            ++wordFrequency[word];
        }

        copy_if(wordTokens.begin(), wordTokens.end(), back_inserter(forwardList), [&](const auto& word) { return !stopWords.contains(word); });

        if (next(find_if(forwardList.begin(), forwardList.end(), [&](const auto& word) { return word == targetWord; }), forwardList.end()) != forwardList.end()) {
            *next(find_if(forwardList.begin(), forwardList.end(), [&](const auto& word) { return word == targetWord; })) = insertAfter + " ";
        }
    }
}

