#include <vector>
#include <string>
#include <boost/process.hpp>
#include <poppler/qt5/QPoppler.h> // For PDF structure validation (Optional, replace with MuPDF or another library if preferred)

namespace fs = std::filesystem;
using boost::process::child_error_info;

int convertImageToPdf(const fs::path& jpegPath, const fs::path& pdfPath, const fs::path& libPaths) {
    std::vector<std::string> commands;
    bool imageConversionToolFound = false;

    // Iterate through all libraries to find the conversion tool.
    for (const auto& path : fs::recursive_directory_iterator(libPaths)) {
        if (fs::exists(path / "image_conversion_tool")) {
            imageConversionToolFound = true;
            commands.push_back("'" + path.string() + "/image_conversion_tool" + "'");
            break;
        }
    }

    if (!imageConversionToolFound) {
        std::cerr << "Error: Image conversion tool not found in specified libraries." << std::endl;
        return 1;
    }

    // Check JPEG file size and provide a warning if it exceeds the threshold.
    auto jpegFileSize = fs::file_size(jpegPath);
    if (jpegFileSize > 100000000) { // Adjust the size threshold as needed
        std::cout << "Warning: The JPEG file is large. Consider using alternative compression techniques." << std::endl;
    }

    // Configure command for image conversion tool, with parallel processing when handling large images.
    std::vector<std::string> args;
    args.push_back("-t");
    args.push_back("pdf");
    args.push_back(jpegPath.string());
    args.push_back(pdfPath.string());

    // Use boost::process to execute the command asynchronously and manage race conditions gracefully.
    std::vector<boost::process::owned> processes;
    for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
        processes.push_back(boost::process::child(commands[0], args, child_error_info()));
        if (processes.size() == commands.size()) {
            break;
        }
        processes.push_back(boost::process::child(commands[i % commands.size()], args, child_error_info()));
    }

    // Wait for all conversion processes to complete and check their statuses.
    int exitStatus = 0;
    for (auto& process : processes) {
        if (process.wait() == -1) {
            std::cerr << "Error: Failed to execute the image conversion tool." << std::endl;
            return 1;
        }
        exitStatus += process.exit_code();
    }

    // Validate PDF structure and integrate with existing document management systems (Optional)
    QPoppler pdfDocument(pdfPath.string().c_str());
    if (!pdfDocument.isValid()) {
        std::cerr << "Error: Malformed PDF output." << std::endl;
        return 1;
    }

    // Return success if all steps complete without issues, otherwise return a non-zero value.
    return exitStatus != processes.size() ? 1 : 0;
}
```

