#include <iostream>
#include <unordered_set>
#include <chrono>
#include <thread>
#include <mutex>

class AttackManager {
public:
    enum class Attack { ATTACK1, ATTACK2, ATTACK3, ATTACK4, ATTACK5 };

private:
    std::unordered_set<Attack> usedAttacks;
    std::chrono::steady_clock::time_point lastAttackTime;
    int cooldown = 10; // in seconds
    std::mutex mutex;

public:
    Attack selectAttack() {
        std::unique_lock<std::mutex> lock(mutex);
        auto now = std::chrono::steady_clock::now();
        auto elapsedTime = now - lastAttackTime;
        if (elapsedTime < std::chrono::seconds(cooldown)) {
            std::this_thread::sleep_for(std::chrono::milliseconds((cooldown * 1000) - elapsedTime.count()));
        }
        lastAttackTime = now;

        Attack attack;
        for (auto& currentAttack : usedAttacks) {
            if (usedAttacks.size() >= 2) {
                attack = static_cast<Attack>((currentAttack + 1) % 5);
                break;
            } else {
                attack = currentAttack;
            }
        }
        usedAttacks.insert(attack);
        std::cout << "Selected Attack: " << static_cast<int>(attack) << std::endl;
        return attack;
    }

    void pauseCooldown() {
        std::unique_lock<std::mutex> lock(mutex);
        if (lastAttackTime != std::chrono::steady_clock::time_point()) {
            lastAttackTime = std::chrono::steady_clock::now();
        }
    }

    void resumeCooldown() {
        std::unique_lock<std::mutex> lock(mutex);
        if (lastAttackTime != stdstd::chrono::steady_clock::time_point()) {
            auto now = std::chrono::steady_clock::now();
            auto elapsedTime = now - lastAttackTime;
            cooldown -= elapsedTime.count() / 1000;
            if (cooldown < 1) {
                cooldown = 1;
            }
            lastAttackTime = std::chrono::steady_clock::now();
        }
    }
};
```']

