void encrypt_process(unsigned char* data, int len) {
    EVP_MD_CTX md;
    const EVP_CIPHER *sym_enc = EVP_aes_256_cbc(); // AES-256-CBC
    const EVP_MD *digest_md = EVP_sha256();        // SHA-256

    EVP_EncryptInit(&md, sym_enc, NULL, NULL);
    EVP_EncryptUpdate(&md, data, len);
    EVP_EncryptFinal(&md, data, NULL);

    EVP_MD_CTX *digest_ctx = EVP_MD_CTX_new();
    EVP_DigestInit(digest_ctx, digest_md);
    EVP_DigestUpdate(digest_ctx, data, len);
    unsigned char md_value[EVP_MAX_MD_SIZE];
    unsigned int md_len = sizeof(md_value);
    EVP_DigestFinal(digest_ctx, md_value, &md_len);
    EVP_MD_CTX_free(digest_ctx);

