            map.erase(it);
        } else {
            // Handle RNTI not found here
        }
    }

    const NFAPI_CRC_INDICATION_PDU_T* find(uint16_t rnti) const {
        unique_lock<mutex> lock(mtx);
        auto it = map.find(rnti);
        if (it != map.end())
            return &(*it->second);
        else
            return nullptr;
    }

    void updateCRCFLAG(uint16_t rnti, uint8_t newValue) {
        unique_lock<mutex> lock(mtx);
        auto it = map.find(rnti);
        if (it != map.end()) {
            it->second->CRC_INDICATION_REL8_TAG = newValue;
        } else {
            // Handle RNTI not found here
        }
    }

