import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.*;
import javax.script.*;

public class LargeScaleDataProcessor {
    private static final String TEMP_DIR = "temp";
    private static final int MAX_THREADS = Runtime.getRuntime().availableProcessors() * 2;
    private static ExecutorService executor;
    private static ScriptEngine engine;

    public static void main(String[] args) throws Exception {
        File tempDir = new File(TEMP_DIR);
        if (!tempDir.exists()) tempDir.mkdir();

        engine = new ScriptEngineManager().getEngineByName("nashorn");
        executor = Executors.newFixedThreadPool(MAX_THREADS);

        String inputFilePath = args[0];
        String scriptFilePath = args[1];
        String outputFilePath = args[2];

        processDataFile(inputFilePath, scriptFilePath, outputFilePath);
    }

    private static void processDataFile(String inputFilePath, String scriptFilePath, String outputFilePath) throws ScriptException, FileNotFoundException, InterruptedException {
        File tempInputFile = File.createTempFile("input", null, new File(TEMP_DIR));
        try (InputStream is = new FileInputStream(inputFilePath)) {
            Files.copy(is, tempInputFile.toPath());
        }

        String scriptCode = new String(Files.readAllBytes(new File(scriptFilePath).toPath()));
        ScriptContext context = engine.create();
        context.setBindings(engine.get bindings (), ScriptContext.ENGINE_SCOPE);

        BoundScriptContext boundContext = (BoundScriptContext) context;
        boundContext.withLocalVariable("inputFile", tempInputFile, ScriptContext.FILE_SCOPE);

        engine.eval(new StringReader(scriptCode), context);

        Object outputObject = context.get("output");
        if (outputObject instanceof File) {
            Files.copy((((File) outputObject)).toPath(), new File(outputFilePath).toPath());
        }

        tempInputFile.deleteOnExit();
    }

    private static Callable<Void> createCommandCallable(String command) {
        return () -> {
            ProcessBuilder builder = new ProcessBuilder(command);
            builder.redirectErrorStream(true);

            try (Process process = builder.start()) {
                int exitCode = process.waitFor();
                if (exitCode != 0) {
                    throw new RuntimeException("Command execution failed: " + command);
                }
            } catch (InterruptedException | IOException e) {
                throw new RuntimeException(e);
            }

            return null;
        } ;
    }

    public static void executeCommands(List<String> commands, String tempDir, Consumer<Long> onProgress) throws InterruptedException, ExecutionException {
        List<Future<Void>> futures = executor.invokeAll(commands.stream()
                .map(command -> CompletableFuture.runAsync(() -> createCommandCallable(command).call(), executor))
                .peek(futures::add)
                .collect(Collectors.toList()));

        futures.forEach(future -> {
            try {
                future.get();
                onProgress.accept(100L); // 100% for simplicity, adjust as needed
            } catch (ExecutionException e) {
                Throwable cause = e.getCause();
                if (cause instanceof InterruptedException) {
                    throw new RuntimeException(cause);
                } else if (cause instanceof Error || cause instanceof RuntimeException) {
                    throw (RuntimeException) cause;
                } else {
                    System.err.println("Command execution failed: " + command);
                }
            }
        });

        executor.shutdownNow();

        try {
            FileUtils.cleanDirectory(new File(tempDir));
        } catch (IOException e) {
            System.err.println("Failed to clean temp directory: " + tempDir);
        }
    }
}
```

The code above provides a skeleton for the Java application. It reads an input file, applies user-specified scripts on it using Nashorn JS engine, and writes the output to another file. The temporary files are stored in a dedicated directory `temp`.

The `executeCommands()` method can be used to run concurrent system commands based on user-specified lists of commands. It also handles exceptions gracefully by retrying transient errors, logging execution metrics, and cleaning up the temp directory upon completion or shutdown.']

