int executeModuleTests(const char* moduleLabel, int* keyArray, record* recordArray, void (*testFunction)(const char*, int*, record*), size_t numKeys) {
    void* handle;
    record* alignedRecordArray = NULL;
    long* offsetArray = NULL;
    int* resetStateFuncAddress = NULL;
    functionPointer resetStateFunc;

    // Step 1,2: Allocate memory for arrays and initialize them
    offsetArray = malloc((numKeys+1)*sizeof(long));
    for (size_t i = 0; i < numKeys+1; ++i) {
        offsetArray[i] = i*sizeof(record);
    }

    alignedRecordArray = calloc(numKeys, sizeof(record));
    if (!alignedRecordArray) {
        goto cleanup;
    }

    // Step 3: Load the shared library using dlopen
    handle = dlopen(moduleLabel, RTLD_LAZY | RTLD_GLOBAL);
    if (!handle) {
        printf("Error: Cannot load module %s\n", moduleLabel);
        goto cleanup;
    }

    // Step 4: Find the test function and resetState function in the shared library
    void* testFunctionAddress = dlsym(handle, "testFunction");
    if (!testFunctionAddress) {
        printf("Error: Cannot find test function in module %s\n", moduleLabel);
        goto cleanup;
    }

    resetStateFuncAddress = dlsym(handle, "blueslip.resetState");
    if (resetStateFuncAddress == NULL) {
        printf("Warning: resetState function not found in module %s\n", moduleLabel);
    }

    // Step 5: Implement a loop to execute each test case
    for (size_t i = 0; i < numKeys; ++i) {
        recordArray[i] = alignedRecordArray[i]; // Reset the record array before each test

        // Set the value of each record's int field to a random value within a specified range
        recordArray[i].value = rand() % 100;

        // Step 4: Call the test function from the loaded shared library
        testFunction(moduleLabel, keyArray, recordArray);

        if (resetStateFuncAddress) {
            resetStateFunc = (functionPointer)resetStateFuncAddress;
            resetStateFunc();
        }
    }

    // Step 8: Return an integer indicating the success or failure of the operation
    int retVal = 0;
    if (handle && testFunctionAddress) {
        retVal = 1;
    } else {
        retVal = -1;
    }

cleanup:
    // Step 9: Free allocated memory
    if (alignedRecordArray) free(alignedRecordArray);
    if (offsetArray) free(offsetArray);
    if (handle) dlclose(handle);

    return retVal;
}
