['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct DataRecord {
    char buffer[32];
    int timestamp;
    double value;
} DataRecord;

struct RecordPool {
    DataRecord* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
};

struct RecordPool* createRecordPool(size_t num_records) {
    struct RecordPool* pool = malloc(sizeof(struct RecordPool));
    if (!pool) return NULL;

    pool->capacity = num_records;
    pool->size = 0;
    pool->records = calloc(num_records, sizeof(DataRecord));
    if (!pool->records) {
        free(pool);
        return NULL;
    }

    pool->lock = PTHREAD_MUTEX_INITIALIZER;

    return pool;
}

DataRecord* getRecord(struct RecordPool* pool, size_t index) {
    pthread_mutex_lock(&pool->lock);

    if (index >= pool->size) {
        if (pool->size == pool->capacity) {
            pool->capacity *= 2;
            pool->records = realloc(pool->records, pool->capacity * sizeof(DataRecord));
        }

        memset(&pool->records[pool->size], 0, sizeof(DataRecord));
        pool->size++;
    }

    snprintf(pool->records[index].buffer, sizeof(pool->records[index].buffer), "prefix_%zu", index);
    pool->records[index].timestamp = time(NULL);
    pool->records[index].value = 0.0;

    pthread_mutex_unlock(&pool->lock);

    return &pool->records[index];
}

void destroyRecordPool(struct RecordPool* pool) {
    if (pool->records) free(pool->records);
    free(pool);
}
```

