#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned short CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // randomly generated CRCFLAG
} NFAPI_CRC_INDICATION_PDU_T;

bool process_data(int *buffer, size_t buffer_len, NFAPI_CRC_INDICATION_PDU_T **pdus, size_t *pdus_count) {
    if (!buffer || !pdus || !pdus_count) return false;

    // Memory for PDUs will be allocated dynamically as needed
    NFAPI_CRC_INDICATION_PDU_T *pdus_tmp = NULL;
    size_t pdus_capacity = 0, pdus_used = 0;

    bool success = true;
    for (size_t i = 0; i < buffer_len && success; ++i) {
        // Validate input and exclude negative numbers/duplicates
        if (buffer[i] <= 0 || (pdus_used > 0 && pdus_tmp[pdus_used - 1].RNTI == buffer[i])) continue;

        // Allocate space for new PDU structure
        if (pdus_used >= pdus_capacity) {
            if (!pdus_capacity) pdus_capacity = 1;
            else pdus_capacity *= 2;

            pdus_tmp = realloc(pdus_tmp, pdus_capacity * sizeof(*pdus_tmp));
            if (!pdus_tmp) {
                success = false;
                break;
            }
        }

        // Initialize new PDU structure
        pdus_tmp[pdus_used].RX_UE_INFORMATION_TAG = (unsigned int)time(NULL);
        pdus_tmp[pdus_used].RNTI = buffer[i];
        pdus_tmp[pdus_used].CRC_INDICATION_REL8_TAG = htons((uint16_t)(rand() % 256)); // randomly generated CRC_INDICATION_REL8_TAG
        pdus_tmp[pdus_used++].CRCFLAG = (unsigned char)rand(); // randomly generated CRCFLAG
    }

    if (!success) {
        free(pdus_tmp);
        return false;
    }

    *pdus = realloc(*pdus, pdus_used * sizeof(**pdus));
    if (*pdus) memcpy(*pdus, pdus_tmp, pdus_used * sizeof(**pdus));
    free(pdus_tmp);

    *pdus_count = pdus_used;
    return true;
}
```
