const int DEFAULT_INITIAL_CAPACITY = 1024;
const float DEFAULT_RESIZE_THRESHOLD = 0.75f;

template<typename T>
using Record = std::unique_ptr<T>;

class ConcurrentHashTable {
public:
    ConcurrentHashTable(size_t initialCapacity, float resizeThreshold)
        : capacity_(initialCapacity), resizeThreshold_(resizeThreshold), table_(), keys_(), offsets_(), lock_() {}

    Record<int> insert(int key);

    void start();
    void stop();

private:
    size_t capacity_;
    float resizeThreshold_;
    std::unordered_map<long, Record<int>> table_;
    std::vector<long> offsets_;
    std::vector<int> keys_;
    std::mutex lock_;
};

template<typename T>
Record<int> ConcurrentHashTable<T>::insert(int key) {
    std::unique_ptr<std::uniform_int_distribution<long>> dist(new std::uniform_int_distribution<long>(0, RAND_MAX));
    std::unique_ptr<std::mt19937> gen(new std::mt19937());
    std::shuffle(offsets_.begin(), offsets_.end(), *gen, *dist);

    long hash = key % capacity_;
    auto it = table_.emplace_hint(table_.begin() + offsets_[hash], key, Record<int>(new int(rand())));
    if (it.second) {
        offsets_[hash]++;
        return it.first->second;
    }

    // Handle collision by rehashing with a different offset index
    for (size_t i = 1; i < offsets_.size(); ++i) {
        hash = (key + i * capacity_) % capacity_;
        it = table_.emplace_hint(table_.begin() + offsets_[hash], key, Record<int>(new int(rand())));
        if (it.second) {
            offsets_[hash]++;
            return it.first->second;
        }
    }

    // Resize the table if necessary
    if (table_.size() / capacity_ > resizeThreshold_) {
        resize(2 * capacity_);
    }

    throw std::runtime_error("Failed to insert key due to hash collisions.");
}

template<typename T>
void ConcurrentHashTable<T>::start() {
    // Implement your thread management here using std::thread and a loop for each worker thread.
}

template<typename T>
void ConcurrentHashTable<T>::stop() {
    // Implement your cleanup and shutdown logic here, such as joining threads, deallocating memory, etc.
}
