#include <stdio.h>
#include <string.h>

typedef struct {
    sockaddr_in addr;
    int fd;
} ConnectedSocket;

struct Timeout {
    time_t start;
    time_t timeout;
};

static sem_t connection_mutex, dns_mutex, slow_client_log_mutex;
static unsigned int max_connections = 100, connections = 0;
static unsigned long long rate_limit = 1000LL * 1000LL * 1000LL, bytes_sent = 0; // 1 GB per second limit

ConnectedSocket* dns_resolve(const char* hostname, time_t timeout) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4 only
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags = AI_NUMERICHOST | AI_NUMERICSERV | AI_ADDRCONFIG;

    int status = getaddrinfo(hostname, "http", &hints, &res);
    if (status != 0) {
        perror("getaddrinfo");
        return NULL;
    }

    struct addrinfo *r = res;
    while (r) {
        sockaddr_in* addr = (sockaddr_in*)(r->ai_addr);
        ConnectedSocket* socket = malloc(sizeof(ConnectedSocket));
        if (!socket) {
            perror("malloc");
            continue;
        }

        socket->addr = *addr;
        socket->fd = socket(AF_INET, SOCK_STREAM, 0);
        if (socket->fd == -1) {
            perror("socket");
            free(socket);
            r = r->ai_next;
            continue;
        }

        struct Timeout timeout = {.start = time(NULL), .timeout = timeout};
        sem_wait(&dns_mutex);
        if (connections >= max_connections) {
            sem_post(&dns_mutex);
            close(socket->fd);
            free(socket);
            r = r->ai_next;
            continue;
        }
        connections++;
        sem_post(&dns_mutex);

        if (connect(socket->fd, (struct sockaddr*)&socket->addr, sizeof(socket->addr)) == 0) {
            return socket;
        }

        // Connection failed or timeout. Clean up and move to the next address.
        close(socket->fd);
        free(socket);
        r = r->ai_next;
    }

    freeaddrinfo(res);
    return NULL;
}

ConnectedSocket* connect_to(const char* hostname, const char* port) {
    ConnectedSocket* socket = dns_resolve(hostname, 5);
    if (!socket) {
        return NULL;
    }

    struct Timeout timeout = {.start = time(NULL), .timeout = 10};
    sem_timedwait(&timeout.timeout, &dns_mutex);
    if (time(NULL) - timeout.start > timeout.timeout) {
        perror("Timed out waiting for connection");
        free(socket);
        return NULL;
    }

    if (connections >= max_connections) {
        sem_wait(&slow_client_log_mutex);
        // Log slow client behavior and enforce a delay before retrying.
        sem_post(&slow_client_log_mutex);
        sleep(1);
        return NULL;
    }

    if (socket->fd >= 0) {
        connections++;
    } else {
        // Unable to allocate socket or failed DNS resolution. Try again later.
        sem_wait(&slow_client_log_mutex);
        // Log slow client behavior and enforce a delay before retrying.
        sem_post(&slow_client_log_mutex);
        sleep(1);
    }

    if (connect(socket->fd, (struct sockaddr*)&socket->addr, sizeof(socket->addr)) == 0) {
        return socket;
    }

    close(socket->fd);
    free(socket);
    return NULL;
}
```

