#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <malloc.h>
#include <stdlib.h>
#define BUFFER_PREFIX "RECORD"
#define MAX_RECORDS 1000000
#define THREAD_SAFE_OFFSET 64
#define CACHE_ALIGNMENT 64

typedef struct Record {
    char buffer[256]; // Max string length
    int timestamp;
    double value;
    pthread_mutex_t lock;
} Record;

typedef struct MemoryBlock {
    size_t size;
    void* data;
    struct MemoryBlock* next;
} MemoryBlock;

struct MemoryPool {
    MemoryBlock* free_list;
    size_t records_allocated;
    size_t records_used;
};

Record* create_record(size_t index) {
    Record* record = malloc(sizeof(Record));
    sprintf(record->buffer, "%s%lu", BUFFER_PREFIX, index);
    record->timestamp = time(NULL);
    record->value = 0.0;
    pthread_mutex_init(&record->lock, NULL);
    return record;
}

MemoryBlock* allocate_memory_block(struct MemoryPool* pool, size_t record_size) {
    if (pool->free_list) {
        MemoryBlock* free_block = pool->free_list;
        pool->free_list = free_block->next;
        free_block->next = NULL;
        free_block->size = record_size;
        return free_block;
    } else {
        void* new_data = malloc(record_size);
        MemoryBlock* new_block = (MemoryBlock*)((uintptr_t)new_data + THREAD_SAFE_OFFSET & ~(CACHE_ALIGNMENT - 1));
        new_block->size = record_size;
        new_block->next = NULL;
        return new_block;
    }
}

void free_memory_block(struct MemoryPool* pool, void* data) {
    MemoryBlock* memory_block = (MemoryBlock*)((uintptr_t)data - THREAD_SAFE_OFFSET);
    memory_block->next = pool->free_list;
    pool->free_list = memory_block;
}

struct MemoryPool* create_memory_pool(size_t initial_size) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    pool->records_allocated = initial_size;
    pool->records_used = 0;
    pool->free_list = NULL;
    return pool;
}

Record* memory_pool_allocate(struct MemoryPool* pool) {
    if (pool->records_used < pool->records_allocated) {
        Record* record = allocate_memory_block(pool, sizeof(Record));
        memcpy(record, create_record(pool->records_used), sizeof(Record));
        pool->records_used++;
        return record;
    } else {
        size_t new_size = pool->records_allocated * 2;
        struct MemoryPool* new_pool = realloc(pool, sizeof(struct MemoryPool) + new_size * sizeof(Record));
        if (!new_pool) {
            // Handle out of memory error
        }
        pool = new_pool;
        pool->records_allocated = new_size;
        return memory_pool_allocate(pool);
    }
}

void clear_memory_pool(struct MemoryPool* pool) {
    for (size_t i = 0; i < pool->records_used; i++) {
        free(pool->free_list);
        pool->free_list = NULL;
    }
    pool->records_used = 0;
}

void report_memory_usage(struct MemoryPool* pool) {
    // Implement a method to calculate and report memory usage and fragmentation within the pool
}
