    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} node_t;

static node_t *head = NULL;
static size_t total_memory_usage = 0;
static size_t max_memory_usage = 0;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file;

void log(const char *message) {
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fflush(log_file);
    }
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list_mutex);

    node_t **current = &head;
    node_t *new_node = malloc(sizeof(node_t));
    if (!new_node) {
        log("Allocation failure");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    new_node->data = *pdu;
    new_node->next = NULL;

    while (*current != NULL && ((*current)->rnti < new_node->data.rnti)) {
        current = &(*current)->next;
    }

    if (*current == NULL) {
        *current = new_node;
    } else {
        new_node->next = *current;
        *current = new_node;
    }

    total_memory_usage += sizeof(node_t);
    if (total_memory_usage > max_memory_usage) {
        max_memory_usage = total_memory_usage;
        log(fmt("Max memory usage: %zu", max_memory_usage));
    }

    pthread_mutex_unlock(&list_mutex);
}

void garbage_collection() {
    // Implement a simple garbage collection algorithm here
    // Release nodes that are no longer needed based on your chosen strategy
    node_t *current = head, *temp;

    while (current != NULL) {
        temp = current->next;

        if (current->next == NULL) {
            free(current);
            total_memory_usage -= sizeof(node_t);
            current = temp;
            continue;
        }

        current = temp;
    }
}

void init() {
    log_file = fopen("crc_indication_log.txt", "w+");
    if (!log_file) {
        perror("Unable to open/create log file");
    } else {
        fprintf(log_file, "Successful allocations: 0\nFailed allocations: 0\nMax memory usage: 0\n");
    }
}
