['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <float.h>
#include <limits.h>

typedef struct Number {
    float value;
    struct Number *next;
} Number;

size_t unique_numbers(FILE *stream, size_t *count, float *avg) {
    Number *head = NULL, *current, *temp;
    float max_values = 1000.0f;
    bool end_of_file = false;
    size_t unique_count = 0;

    while (!end_of_file) {
        current = (Number *)malloc(sizeof(Number));
        if (!current) {
            fprintf(stderr, "Error: Memory allocation failure.\n");
            return 1;
        }

        if (fscanf(stream, "%f", &current->value) != 1) {
            free(current);
            if (feof(stream)) {
                end_of_file = true;
            } else {
                fprintf(stderr, "Error: Invalid number format.\n");
                return 2;
            }
        }

        current->next = head;
        head = current;

        if (unique_count < max_values) {
            unique_count++;
            continue;
        }

        temp = head;
        for (size_t i = 0; i < unique_count - 1; ++i) {
            temp = temp->next;
        }

        if (temp->value == current->value) {
            free(current);
            continue;
        }

        while (unique_count > max_values) {
            temp = head;
            for (size_t i = 0; i < unique_count - 1; ++i) {
                temp = temp->next;
            }
            free(temp->next);
            unique_count--;
        }

        unique_count++;
        (*avg) = ((*avg) * (unique_count - 1) + current->value) / unique_count;
    }

    if (unique_count == 0) {
        printf("No numbers provided\n");
        return 0;
    }

    (*count) = unique_count;
    return 0;
}
```

This function reads floating-point numbers from the given stream, stores unique values in a linked list, and dynamically adjusts the size of the internal storage array based on the number of unique values. It handles potential input issues such as memory allocation failures, invalid number formats, and end-of-file conditions. The average and count of unique numbers are calculated and returned, along with error messages if necessary.']

