    unsigned int key_range;
    unsigned int crypt_ops;
    AES_KEY *aes_ctx;
    Camellia_ctx *camellia_ctx;
    EVP_MD_CTX *md5_ctx;
    EVP_MD_CTX *sha1_ctx;
    RSA *rsa;
} Config;

void initializeDataAndAddCryptographicPrimitives(Config* config) {
    // Seed pseudo-random number generator
    srand(time(NULL));

    // Allocate memory for long values and keys
    long *long_values = malloc(config->max_value * sizeof(long));
    int *keys = malloc((config->crypt_ops + 1) * sizeof(int));
    Record *records = malloc(config->crypt_ops * sizeof(Record));

    // Initialize long values and keys
    for (size_t i = 0; i < config->max_value; ++i) {
        long_values[i] = (long)pow((double)2, config->max_value - i) % config->max_value;
    }
    for (size_t i = 0; i < config->crypt_ops; ++i) {
        keys[i] = rand() % config->key_range;
    }
    keys[config->crypt_ops] = -1; // Mark the last key as invalid to denote end of list

    // Initialize cryptographic contexts
    EVP_MD_init(&config->md5_ctx, EVP_md5());
    EVP_MD_init(&config->sha1_ctx, EVP_sha1());
    if (config->aes_ctx == NULL) {
        AES_set_encrypt_key(config->max_value, AES_MODE_CBC, config->aes_ctx);
    }
    if (config->camellia_ctx == NULL) {
        Camellia_setup((unsigned char*)config->max_value, config->camellia_ctx);
    }
    if (config->rsa == NULL) {
        RSA* tempRSA = RSA_new();
        int keySize = RSA_size(tempRSA);
        config->rsa = RSA_generate_key(keySize, RSA_F4, NULL, NULL);
        RSA_free(tempRSA);
    }

    // Initialize records with unique random values
    for (size_t i = 0; i < config->crypt_ops; ++i) {
        size_t j;
        do {
            j = keys[i];
        } while (j >= config->crypt_ops);

        records[j].key = keys[i];
        records[j].recordValue = rand() % config->key_range;
        keys[i] = -1; // Mark the key as used to avoid reuse
    }
}

