struct NetworkTrafficStat {
    std::atomic<uint64_t> packetCount;
    std::atomic<uint64_t> byteCount;
    std::vector<std::pair<time_t, int>> eventRecords; // event records with timestamp and data
    mutex mtx;
};

typedef boost::intrusive_ptr<NetworkTrafficStat> NetworkTrafficStatPtr;

boost::lockfree::hash_map<std::string, NetworkTrafficStatPtr> hashTable;
std::queue<std::pair<std::string, NetworkTrafficUpdate>> updateQueue;
std::thread updateThread;

struct NetworkTrafficUpdate {
    std::string key;
    NetworkTrafficStat newData;
};

void periodicUpdates() {
    while(true) {
        // acquire lock and dequeue an update
        std::unique_lock<std::mutex> lk(mtx);
        updateQueue.wait(lk, [this](){ return !updateQueue.empty(); });
        auto update = updateQueue.front();
        updateQueue.pop();
        lk.unlock();

        // update the entry in the hash table with new data
        NetworkTrafficStatPtr stat = hashTable.load(key);
        if (stat) {
            auto oldData = *stat;
            // ... merge oldData and newData, update eventRecords, etc.
            // ... then store the updated data back to the hash table
            stat->packetCount = oldData.packetCount + newData.packetCount;
            stat->byteCount += newData.byteCount;
            // ... update other fields as needed
        }
    }
}

void insert(const std::string& key, NetworkTrafficStatPtr value) {
    if (value) {
        auto success = hashTable.compare_and_swap_strong(key, nullptr, value);
        if (!success) {
            // handle collision or existing entry
        }
    }
}

NetworkTrafficStatPtr lookup(const std::string& key) {
    return hashTable.load(key);
}

void deleteEntry(const std::string& key) {
    NetworkTrafficStatPtr stat = hashTable.extract(key);
    // free or recycle the deleted data structure as needed
}

void enqueueUpdate(const std::string& key, const NetworkTrafficStat& newData) {
    updateQueue.emplace(std::make_pair(key, newData));
    // wake up the periodic updates thread if it's waiting for an update
    std::unique_lock<std::mutex> lk(mtx);
    updateQueue.notify_all();
}
