        if (!is_cached || sb.st_size != tiffgetsamplesize(tif_cached)) {
            tif = TIFFOpen(file_path, "r");
            if (tif == NULL) {
                perror("Error opening file");
                goto cleanup;
            }

            bits_per_sample = TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL);
            sample_per_pixel = (bits_per_sample + 7) / 8;
            num_samples = (bits_per_sample > 8) ? 8 : ((bits_per_sample & 3) != 0) ? 4 : 1;
            memset(extra_samples, 0, sizeof(int8_t) * 8);

            if (num_samples > 1) {
                extra_samples[num_samples - 1] = TIFFGetField(tif, TIFFTAG_EXTRASAMPLES);
                for (size_t j = 0; j < num_samples - 2; ++j) {
                    extra_samples[j] = TIFFGetField(tif, TIFFTAG_EXTRASAMPLEBITS + j);
                }
            }

            is_cached = true;
        } else {
            tif = tif_cached;
        }
    } else if (strstr(file_path, ".png")) {
        png_ptr = png_create_read_struct(PNG_LIBPNG_VER_PTR, NULL, NULL, NULL);
        if (!png_ptr) {
            perror("Error initializing PNG reader");
            goto cleanup;
        }

        if (setjmp(png_jmpbuf(png_ptr))) {
            png_destroy_read_struct(&png_ptr, NULL);
            goto cleanup;
        }

        png_init_io(png_ptr, file_path);
        png_read_info(png_ptr, (png_infop*)NULL);

        bits_per_sample = png_get_bit_depth(png_ptr, 0);
        sample_per_pixel = 8 * ((bits_per_sample + 7) / 8);
        num_samples = png_get_channels(png_ptr, (png_infop*)NULL);
        memset(extra_samples, 0, sizeof(int8_t) * 8);

        if (num_samples > 1) {
            for (size_t j = 0; j < num_samples - 1; ++j) {
                extra_samples[j] = png_get_channum(png_ptr, 0, j);
            }
        }
    } else if (strstr(file_path, ".jpg") || strstr(file_path, ".jpeg")) {
        cinfo.err = jpeg_stdio_init(&cinfo, fopen(file_path, "r"));
        if (cinfo.err != JPEG_NO_ERROR) {
            perror("Error initializing JPEG reader");
            goto cleanup;
        }

        cinfo.read_scanlines = jpeg_read_scanlines;
        cinfo.term_source = jpeg_destroy_decompress;

        jpeg_get_table_hints(&cinfo);
        jpeg_create_decompress(&cinfo);
        jpeg_read_header(&cinfo, TRUE);

        bits_per_sample = cinfo.output_components;
        sample_per_pixel = 8 * ((bits_per_sample + 7) / 8);
        num_samples = (bits_per_sample > 8) ? 8 : ((bits_per_sample & 3) != 0) ? 4 : 1;
        memset(extra_samples, 0, sizeof(int8_t) * 8);

