                extra_samples[j] = cinfo.comp_info[j].h_samp_factor;
            }
        }
    } else {
        perror("Unsupported file format");
        goto cleanup;
    }

    target_count = (sb.st_size - sample_per_pixel) / (sizeof(LTE_PHY_RX_TARGET) + sizeof(LTE_RX_SUBFRAME_INFO));
    targets = calloc(target_count, sizeof(LTE_PHY_RX_TARGET));
    if (!targets) {
        perror("Error allocating memory");
        goto cleanup;
    }

    map = mmap(NULL, sb.st_size, PROT_READ, MAP_PRIVATE, fileno(tif ? tif : png_ptr->io), 0);
    if (map == MAP_FAILED) {
        perror("Error mapping file");
        goto cleanup;
    }

    for (i = 0; i < target_count; ++i) {
