#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct memory_block {
    size_t allocated_size;
    size_t used_size;
    NFAPI_CRC_INDICATION_PDU_T *data;
    pthread_mutex_t mutex;
};

static struct memory_block *memory_block = NULL;
static const size_t MAX_MEMORY = 1024 * 1024; // 1 MB max memory
static const size_t STRUCTURE_SIZE = sizeof(NFAPI_CRC_INDICATION_PDU_T);
static size_t num_structures = 0;

void init_memory() {
    if (!memory_block) {
        memory_block = calloc(1, sizeof(*memory_block));
        if (!memory_block) {
            // Handle error: out of memory
            return;
        }
        pthread_mutex_init(&memory_block->mutex, NULL);
    }
}

void cleanup_memory() {
    if (memory_block && memory_block->data) {
        free(memory_block->data);
        memory_block->used_size = 0;
    }
    pthread_mutex_destroy(&memory_block->mutex);
    free(memory_block);
    memory_block = NULL;
}

void *allocate_structures(size_t num) {
    size_t needed_size = num * STRUCTURE_SIZE;

    pthread_mutex_lock(&memory_block->mutex);

    if (needed_size > MAX_MEMORY - memory_block->allocated_size) {
        // Handle error: not enough available memory
        pthread_mutex_unlock(&memory_block->mutex);
        return NULL;
    }

    void *new_data = realloc(memory_block->data + memory_block->used_size, needed_size);
    if (!new_data) {
        // Handle error: out of memory
        pthread_mutex_unlock(&memory_block->mutex);
        return NULL;
    }

    memory_block->allocated_size += needed_size;
    memory_block->used_size += num * STRUCTURE_SIZE;

    NFAPI_CRC_INDICATION_PDU_T *new_data_ptr = (NFAPI_CRC_INDICATION_PDU_T *) new_data;
    for (size_t i = 0; i < num; ++i) {
        // Set fields as needed
        new_data_ptr[i].RX_UE_INFORMATION_TAG = i + 1;
        new_data_ptr[i].RNTI = rand() % 65536;
        memset(new_data_ptr[i].CRC_INDICATION_REL8_TAG, rand() % 256, sizeof(new_data_ptr[i].CRC_INDICATION_REL8_TAG));
        new_data_ptr[i].CRCFLAG = rand() % 2;
    }

    pthread_mutex_unlock(&memory_block->mutex);

    return new_data_ptr;
