typedef struct hashmap {
    unsigned long capacity;
    unsigned long size;
    NFAPI_CRC_INDICATION_PDU_T **entries;
    pthread_mutex_t map_lock;
} Hashmap;

Hashmap* create_hashmap(unsigned long capacity) {
    Hashmap* h = (Hashmap*) malloc(sizeof(Hashmap));
    h->capacity = capacity;
    h->size = 0;
    h->entries = calloc(h->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    pthread_mutex_init(&h->map_lock, NULL);
    return h;
}

unsigned long hash(unsigned long key) {
    unsigned long hash = 5381;
    int c;

    while (key) {
        c = (int)(key & 0xFF);
        key >>= 8;
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }

    return hash % h->capacity;
}

void insert(Hashmap* h, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&h->map_lock);
    unsigned long index = hash(data->RNTI);
