    NFAPI_CRC_INDICATION_PDU_T* data = h->entries[index];
    if (data == NULL) data = NULL;
    else if (data->RNTI != RNTI) data = NULL;
    pthread_mutex_unlock(&h->map_lock);
    return data;
}

void remove(Hashmap* h, uint32_t RNTI) {
    pthread_mutex_lock(&h->map_lock);
    unsigned long index = hash(RNTI);
    if (h->entries[index] == NULL) {
        pthread_mutex_unlock(&h->map_lock);
        return;
    }
    if (h->entries[index]->RNTI != RNTI) {
        pthread_mutex_unlock(&h->map_lock);
        return;
    }
    memmove(h->entries + index, h->entries + index + 1, --h->size - index);
    free(h->entries[index]);
    h->entries[h->size] = NULL;
    pthread_mutex_unlock(&h->map_lock);
}

