void insertStringAfterMatch(const std::string& idToFind, const std::string& newDetail) {
    std::unique_lock<std::mutex> inventoryLock(g_inventoryMutex);

    // Check if the list is empty or null pointer
    if (!g_inventoryList || g_inventoryList->empty()) {
        // Initialize the list if it's empty
        g_inventoryList = std::make_unique<std::forward_list<std::string>>();
    }

    auto iter = g_inventoryList->begin();
    auto end = g_inventoryList->end();

    // Find the first occurrence of idToFind and insert newDetail after it, or append to the end if not found
    while (iter != end) {
        if (*iter == idToFind) {
            iter = g_inventoryList->insert_after(iter, newDetail);
            break;
        }
        ++iter;
    }

    // If the list iterator reached the end without finding a match, append the newDetail to the end of the list
    if (iter == end) {
        g_inventoryList->push_back(newDetail);
    }

    // Handle memory allocation failures gracefully
    inventoryLock.unlock();
}
