NFAPI_CRC_INDICATION_PDU_T* generateAndSortNfapiPduList(int N, bool enableLogging) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;
    NFAPI_CRC_INDICATION_PDU_T *currentNode;
    uint32_t uniqueRTNIs[N]; // Store RNTI values for duplicate check
