        // Keep generating RNTI until a unique one is found
        do {
            rnti = rand();
        } while (findInArray(rnti, uniqueRTNIs, i));

        uniqueRTNIs[i] = rnti;

        pthread_mutex_lock(&mutex);
        currentNode = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!currentNode) {
            perror("Failed to allocate memory");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        currentNode->RNTI = rnti;
        currentNode->RX_UE_INFORMATION_TAG = rand(); // Assuming shared data source for RX_UE_INFORMATION_TAG is available
        currentNode->CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Randomly setting CRCFLAG with a 50% chance of true value
        if (enableLogging) {
