                   currentNode->RNTI, currentNode->RX_UE_INFORMATION_TAG, currentNode->CRC_INDICATION_REL8_TAG);
        }

        if (!head) {
            head = tail = currentNode;
        } else {
            tail->next = currentNode;
            tail = currentNode;
        }
        pthread_mutex_unlock(&mutex);
    }

    // Sort the linked list based on RNTI values
    NFAPI_CRC_INDICATION_PDU_T *tempNode;
    for (i = 0; i < N - 1; ++i) {
        pthread_mutex_lock(&mutex);
        if (head->RNTI > head->next->RNTI) {
            tempNode = head->next;
            head->next = tempNode->next;
            tempNode->next = head;
            head = tempNode;
        }
        pthread_mutex_unlock(&mutex);
    }

    return head;
}

