typedef struct Record {
    int value;
} Record;

// Global variables for maximum size limits and random number range
size_t maxRecords = 1000;
size_t maxRecordSize = 1024 * sizeof(int);
int minValue = 0, maxValue = 100;

// Mutex to ensure thread safety
pthread_mutex_t mutex;

// Function to initialize and manage dynamic memory for multiple arrays and structures
void* initDataStructures() {
    Record *records = NULL;
    int *keys = malloc(maxRecords * sizeof(int));
    long *offsets = malloc(maxRecords * sizeof(long));

    if (!keys || !offsets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&mutex, NULL);

    records = malloc(maxRecordSize * maxRecords);

    if (!records) {
        fprintf(stderr, "Memory allocation for records failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize record values with random numbers within the specified range
    for (size_t i = 0; i < maxRecords; ++i) {
        pthread_mutex_lock(&mutex);
        records[i * maxRecordSize + sizeof(int)] = rand() % (maxValue - minValue + 1) + minValue;
        pthread_mutex_unlock(&mutex);
    }

    // Initialize offsets and keys arrays
    long currentOffset = 0;
    for (size_t i = 0; i < maxRecords; ++i) {
        keys[i] = i;
        offsets[i] = currentOffset;
        currentOffset += sizeof(Record);
    }

    return records;
}

// Function to free allocated memory when done with the data structures
void freeDataStructures(void *data) {
    free((char *)data + maxRecordSize * maxRecords - maxRecords * sizeof(long)); // Free keys array
    free((char *)data + maxRecordSize * maxRecords - maxRecords * sizeof(long) - maxRecords * sizeof(int)); // Free offsets array
    free(data); // Free records array
    pthread_mutex_destroy(&mutex);
}
