typedef struct {
    unsigned long RNTI;
    unsigned char RX_UE_INFORMATION_TAG;
    unsigned char CRC_INDICATION_REL8_TAG;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *prev, *next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void insert_sorted(Node** head_ref, Node* new_node) {
    Node *current = *head_ref;
    while (current != NULL && current->data.RNTI < new_node->data.RNTI) {
        current = current->next;
    }
    if (*head_ref == NULL) {
        *head_ref = new_node;
    } else if (current == *head_ref) {
        new_node->next = *head_ref;
        (*head_ref)->prev = new_node;
        *head_ref = new_node;
    } else {
        new_node->next = current;
        new_node->prev = current->prev;
        if (current->prev != NULL)
            current->prev->next = new_node;
        else
            *head_ref = new_node;
        current->prev = new_node;
    }
}

