struct LTE_PHY_TX_FRAME_INFO {
    // ...
};

class LteFrameManager {
private:
    std::vector<std::unique_ptr<LTE_PHY_TX_FRAME_INFO>> frames;
    mutex dataMutex;
    atomic_int readIndex;
    atomic_int writeIndex;

public:
    void addFrame(const LTE_PHY_TX_FRAME_INFO& frame) {
        std::unique_ptr<LTE_PHY_TX_FRAME_INFO> newFrame = std::make_unique<LTE_PHY_TX_FRAME_INFO>(frame);
        unique_lock<mutex> lock(dataMutex);
        if (writeIndex == frames.size()) {
            frames.push_back(std::move(newFrame));
        } else {
            frames[writeIndex] = std::move(newFrame);
        }
        writeIndex++;
    }

    const LTE_PHY_TX_FRAME_INFO& getNextFrame() {
        unique_lock<mutex> lock(dataMutex);
        if (readIndex == writeIndex) {
            throw std::runtime_error("No more frames available");
        }
        auto frame = frames[readIndex];
        readIndex++;
        return *frame;
    }
};
```

