    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_FILE_SIZE (1024 * 1024 * 16) // 16MB max file size
#define ALIGNMENT 64 // Cache line alignment for performance

int loadNfareBundle(const char* filename, size_t* numItems, NFAPI_CRC_INDICATION_PDU_T*** bundle) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("fopen");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    size_t fileSize = ftell(file);
    if (fileSize > MAX_FILE_SIZE) {
        fprintf(stderr, "File too large: %zu bytes\n", fileSize);
        return -2;
    }
    rewind(file);

    size_t numAttempts = 3;
    bool success = false;
    for (size_t i = 0; i < numAttempts && !success; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* items = malloc((fileSize + ALIGNMENT - 1) & ~(ALIGNMENT - 1));
        if (!items) {
            perror("malloc");
            continue;
        }

        size_t readBytes = fread(items, 1, fileSize, file);
        if (readBytes != fileSize) {
            free(items);
            if (feof(file)) {
                success = true;
            } else {
                perror("fread");
            }
        } else {
            success = true;
        }
    }

    if (!success) {
        fprintf(stderr, "Failed to read file after %zu attempts\n", numAttempts);
        return -3;
    }

    *numItems = fileSize / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *bundle = items;
    srand(time(NULL));
    for (size_t i = 0; i < *numItems; ++i) {
        ((NFAPI_CRC_INDICATION_PDU_T*)items)[i].CRCFLAG = rand() % 2;
    }

    return 0;
}
