typedef struct {
    LTE_TARGET_RB rb;
    uint32_t time_instance;
    size_t num_subframes;
    LTE_RX_SUBFRAME_INFO *subframe_info;
} LTE_PHY_RX_TARGET;

typedef struct cache_node {
    LTE_PHY_RX_TARGET target;
    struct cache_node *next;
} CACHE_NODE;

struct lte_phy_rx_targets {
    size_t capacity;
    size_t count;
    LTE_PHY_RX_TARGET *array;
    pthread_mutex_t mutex;
    CACHE_NODE *cache_head;
    CACHE_NODE *cache_tail;
};

LTE_PHY_RX_TARGETS* lte_phy_rx_targets_init(size_t initial_capacity) {
    LTE_PHY_RX_TARGETS *targets = mmap(NULL, sizeof(LTE_PHY_RX_TARGETS), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (targets == MAP_FAILED) {
        perror("mmap failed");
        return NULL;
    }

    memset(targets, 0, sizeof(LTE_PHY_RX_TARGETS));

    targets->capacity = initial_capacity;
    targets->count = 0;
    pthread_mutex_init(&(targets->mutex), NULL);
    targets->array = calloc(initial_capacity, sizeof(LTE_PHY_RX_TARGET));

    if (!targets->array) {
        perror("calloc failed");
        munmap(targets, sizeof(LTE_PHY_RX_TARGETS));
        return NULL;
    }

    targets->cache_head = NULL;
    targets->cache_tail = NULL;

    return targets;
}

void lte_phy_rx_targets_destroy(LTE_PHY_RX_TARGETS *targets) {
    if (!targets) return;

    pthread_mutex_destroy(&(targets->mutex));

    munmap((void*) targets, sizeof(LTE_PHY_RX_TARGETS));
}

size_t lte_phy_rx_targets_get_capacity(const LTE_PHY_RX_TARGETS *targets) {
    return targets->capacity;
}

size_t lte_phy_rx_targets_get_count(const LTE_PHY_RX_TARGETS *targets) {
    return targets->count;
}

LTE_PHY_RX_TARGET* lte_phy_rx_targets_get(LTE_PHY_RX_TARGETS *targets, uint32_t time_instance, LTE_TARGET_RB rb) {
    pthread_mutex_lock(&(targets->mutex));

    size_t i;
    for (i = 0; i < targets->count; ++i) {
        if (targets->array[i].time_instance == time_instance && targets->array[i].rb == rb) {
            pthread_mutex_unlock(&(targets->mutex));
            return &(targets->array[i]);
        }
    }

    for (i = 0; i < targets->cache_head; ++i) {
        if (targets->cache_head->target.time_instance == time_instance && targets->cache_head->target.rb == rb) {
            LTE_PHY_RX_TARGET *tmp = targets->cache_head;
            targets->cache_head = tmp->next;
            if (targets->cache_head == NULL) targets->cache_tail = NULL;
            pthread_mutex_unlock(&(targets->mutex));
            return tmp;
        }
    }

    pthread_mutex_unlock(&(targets->mutex));

    // If not found in the array or cache, add a new element.
    if (targets->count == targets->capacity) {
        size_t new_capacity = (targets->capacity * 2 > MAX_ELEMENTS) ? MAX_ELEMENTS : (targets->capacity * 2);
        LTE_PHY_RX_TARGET *new_array = realloc(targets->array, new_capacity * sizeof(LTE_PHY_RX_TARGET));
        if (!new_array) {
            perror("realloc failed");
            return NULL;
        }
        targets->array = new_array;
        targets->capacity = new_capacity;
    }

    LTE_PHY_RX_TARGET *element = &(targets->array[targets->count]);
    element->rb = rb;
    element->time_instance = time_instance;
    // Initialize variable-length array of LTE_RX_SUBFRAME_INFO here.

    pthread_mutex_lock(&(targets->mutex));
    ++(targets->count);
    pthread_mutex_unlock(&(targets->mutex));

    return element;
}
