    pthread_mutex_lock(&mutex);
        strcpy(update_html_section_id, section_id);
        strcpy(update_html_element_id, element_id);
    pthread_mutex_unlock(&mutex);
}

void* background_service() {
    while (1) {
        pthread_mutex_lock(&mutex);
            if (!strcmp(update_html_section_id, "")) break; // Exit loop if no update is needed
            char* section = document.getById(update_html_section_id);
            char* element = section->getById(update_html_element_id);
            refreshElement(element);
        pthread_mutex_unlock(&mutex);
    }
    return 0;
}

void InitializeRxTargetsAndSubframes(size_t num_targets, size_t* subframe_info_len_arr) {
    LTE_PHY_RX_TARGET* targets = malloc(num_targets * sizeof(LTE_PHY_RX_TARGET));

    for (size_t i = 0; i < num_targets; ++i) {
        init_target(&targets[i], subframe_info_len_arr[i]);
    }

    // Start background service thread
    pthread_t background_service_thread;
    pthread_create(&background_service_thread, NULL, background_service, NULL);
}
