typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

struct mem_manager {
    size_t capacity; // maximum number of structures that can be allocated
    size_t count; // current number of structures in use
    size_t size; // size of each structure in bytes
    NFAPI_CRC_INDICATION_PDU_T *data; // pointer to the dynamically allocated array
    pthread_mutex_t lock; // mutex for thread safety
};

void init_mem_manager(struct mem_manager *mm, size_t capacity, size_t size) {
    mm->capacity = capacity;
    mm->count = 0;
    mm->size = size;
    mm->data = mmap(NULL, capacity * size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mm->data == MAP_FAILED) {
        fprintf(stderr, "Error: Failed to allocate memory for the data structures\n");
        exit(EXIT_FAILURE);
    }
    mm->lock = PTHREAD_MUTEX_INITIALIZER;
}

NFAPI_CRC_INDICATION_PDU_T* alloc_structure(struct mem_manager *mm) {
    pthread_mutex_lock(&mm->lock);
    if (mm->count >= mm->capacity) {
        fprintf(stderr, "Error: The maximum number of structures has been reached\n");
        pthread_mutex_unlock(&mm->lock);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *pdu = mm->data + mm->count;
    mm->count++;
    pthread_mutex_unlock(&mm->lock);
    pdu->crc_indication.crcflag = (unsigned char)rand() % 2; // set CRCFLAG randomly
    return pdu;
}

void free_mem_manager(struct mem_manager *mm) {
    munmap(mm->data, mm->capacity * mm->size);
}

