#include "PH_STATS_REPORT_T.h" // Custom data structure definition
#include "AnalyticsEngine.h"   // External analytics engine interface

class PHMetricsCollector {
public:
    explicit PHMetricsCollector(std::unique_ptr<AnalyticsEngine> analytics)
        : analytics_(std::move(analytics)) {}

    void addReport(const PH_STATS_REPORT_T& report);

private:
    void validateAndTransmitReports();
    std::unique_ptr<AnalyticsEngine> analytics_;
    std::mutex reports_mutex;
    std::deque<PH_STATS_REPORT_T> reports_queue;
    std::queue<PH_STATS_REPORT_T> local_storage;
    const int maxConcurrentReports = 10000;
    std::thread validationThread_;
};

void PHMetricsCollector::addReport(const PH_STATS_REPORT_T& report) {
    std::unique_lock<std::mutex> lock(reports_mutex);

    // Implement signal data format parsing and compatibility checks here.

    if (reports_queue.size() < maxConcurrentReports) {
        reports_queue.push_back(report);
    } else {
        local_storage.push_back(report);
    }

    lock.unlock();
}

void PHMetricsCollector::validateAndTransmitReports() {
    while (true) {
        std::unique_lock<std::mutex> reportsLock(reports_mutex);

        if (reports_queue.empty() && local_storage.empty()) {
            reportsLock.unlock();
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            continue;
        }

        auto reportsToProcess = reportsQueue_.load() + localStorage_.load();
        auto reportsToSend = std::min(reportsToProcess, maxConcurrentReports);

        if (analytics_ != nullptr) {
            // Forward reports to the analytics engine for processing.
            analytics_->processBatch(reportsToSend);
        } else {
            localStorage_.swap(reportsToSend);
            // Store reports locally when analytics engine is unavailable.
        }

        reportsLock.unlock();
    }
}

void PHMetricsCollector::start() {
    validationThread_ = std::thread(&PHMetricsCollector::validateAndTransmitReports, this);
}
