    LTE_TARGET_TIME_INSTANCE time_instance;
    size_t subframe_info_len;
    LTE_RX_SUBFRAME_INFO *subframe_info;
} LTE_PHY_RX_TARGET;

// Shared memory region for metadata cache
void *metadata_cache;
size_t metadata_cache_size;
sem_t metadata_cache_mutex;

// Global variables for logging and monitoring
FILE *log_file;
size_t total_allocated = 0;
size_t max_allocated = 0;

// Function to parse TIFF image file and extract metadata
int tiff_parse(TIFF *, int *, int *, int *, int *);

LTE_PHY_RX_TARGET* lte_phy_rx_target_alloc(size_t num_structures) {
    LTE_PHY_RX_TARGET *targets;
    size_t metadata_cache_offset = 0;

    // Check if metadata cache has sufficient space for requested structures
    while (metadata_cache_offset + sizeof(LTE_PHY_RX_TARGET) * num_structures > metadata_cache_size) {
        // If not, extend the shared memory region
        void *extended_cache = realloc(metadata_cache, metadata_cache_size + PAGE_SIZE);
        if (!extended_cache) {
            fprintf(log_file, "Failed to allocate more memory for metadata cache\n");
            return NULL;
        }
        metadata_cache = extended_cache;
        metadata_cache_size += PAGE_SIZE;
    }

    // Lock the metadata cache mutex before accessing it
    sem_wait(&metadata_cache_mutex);

    targets = (LTE_PHY_RX_TARGET*)(metadata_cache + metadata_cache_offset);
    metadata_cache_offset += sizeof(LTE_PHY_RX_TARGET) * num_structures;
    sem_post(&metadata_cache_mutex);

    // Allocate memory for subframe_info arrays and initialize random lengths
    TIFF *tiff_file = NULL;
    int bits_per_sample, sample_per_pixel, extra_samples;
    if (tiff_open("image.tiff", "r", &tiff_file) != 0) {
        fprintf(log_file, "Failed to open image file\n");
        return NULL;
    }

    if (!tiff_parse(tiff_file, &bits_per_sample, &sample_per_pixel, &extra_samples, NULL)) {
        tiff_close(tiff_file);
        fprintf(log_file, "Failed to parse image metadata\n");
        return NULL;
    }

    targets = calloc(num_structures, sizeof(LTE_PHY_RX_TARGET));
    if (!targets) {
        tiff_close(tiff_file);
        fprintf(log_file, "Failed to allocate memory for structures\n");
        return NULL;
    }

    // Parse each structure's TIFF metadata and subframe information
    for (size_t i = 0; i < num_structures; ++i) {
        LTE_PHY_RX_TARGET *target = targets + i;

        if (tiff_seek(tiff_file, -1, SEEK_END)) {
            tiff_close(tiff_file);
            free(targets);
            fprintf(log_file, "Failed to seek in image file\n");
            return NULL;
        }

        if (tiff_parse(tiff_file, &bits_per_sample, &sample_per_pixel, &extra_samples, target->subframe_info)) {
            tiff_close(tiff_file);
            fprintf(log_file, "Failed to parse structure metadata and subframe information\n");
            free(targets);
            return NULL;
        }

        if (bits_per_sample != 1 && bits_per_sample != 2 && bits_per_sample != 4 && bits_per_sample != 8 && bits_per_sample != 16) {
            tiff_close(tiff_file);
            free(targets);
            fprintf(log_file, "Unsupported number of bits per sample\n");
            return NULL;
        }

        target->subframe_info_len = rand() % (extra_samples + 1) + 1;
        target->subframe_info = calloc(target->subframe_info_len, sizeof(LTE_RX_SUBFRAME_INFO));
        if (!target->subframe_info) {
            tiff_close(tiff_file);
            free(targets);
            fprintf(log_file, "Failed to allocate memory for subframe info array\n");
            return NULL;
        }
    }

    tiff_close(tiff_file);

    // Calculate and store the MD5 hash of the subframe information in each structure
    unsigned char md5[MD5_DIGEST_LENGTH];
    for (size_t i = 0; i < num_structures; ++i) {
        LTE_PHY_RX_TARGET *target = targets + i;

        SHA1_CTX ctx;
        SHA1_Init(&ctx);
        for (size_t j = 0; j < target->subframe_info_len; ++j) {
            SHA1_Update(&ctx, &(target->subframe_info[j]), sizeof(LTE_RX_SUBFRAME_INFO));
        }
        SHA1_Final(md5, &ctx);

        memcpy(target->rb.md5_hash, md5, MD5_DIGEST_LENGTH);
    }

    return targets;
}

