```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <type_info>

typedef struct Record {
    int value;
} Record;

struct MoSTState {
    long *offsets;
    int *keys;
    Record *records;
};

void* initializeSystemState() {
    int offsetSize = 8; // long size
    int keySize = sizeof(int);
    int recordSize = sizeof(Record);

    long *offsets = (long *)mmap(NULL, offsetSize * MAX_OFFSETS, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
    if (offsets == MAP_FAILED) {
        perror("mmap: offsets");
        return NULL;
    }

    int *keys = (int *)calloc(MAX_KEYS, keySize);
    if (!keys) {
        perror("calloc: keys");
        munmap(offsets, offsetSize * MAX_OFFSETS);
        return NULL;
    }

    Record *records = (Record *)calloc(MAX_RECORDS, recordSize);
    if (!records) {
        free(keys);
        munmap(offsets, offsetSize * MAX_OFFSETS);
        perror("calloc: records");
        return NULL;
    }

    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        records[i].value = rand() % MAX_VALUE;
    }

    // Load from file and verify the object is an instance of MoSTState
    int fd = open("state.bin", O_RDONLY);
    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        perror("fstat: state.bin");
        free(keys);
        munmap(offsets, offsetSize * MAX_OFFSETS);
        free(records);
        close(fd);
        return NULL;
    }

    void *obj = mmap(NULL, sb.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (obj == MAP_FAILED) {
        perror("mmap: state object");
        free(keys);
        munmap(offsets, offsetSize * MAX_OFFSETS);
        free(records);
        close(fd);
        return NULL;
    }

    if (typeid(*obj) != typeid(MoSTState)) {
        perror("Invalid object type");
        munmap(obj, sb.st_size);
        free(keys);
        munmap(offsets, offsetSize * MAX_OFFSETS);
        free(records);
        close(fd);
        return NULL;
    }

    close(fd);
    munmap(obj, sb.st_size); // Unmap and return the loaded state object
    return (MoSTState *) records;
}
```

