namespace fs = std::filesystem;

constexpr size_t MAX_FILE_SIZE = 1000 * 1024 * 1024; // 1GB max file size

int convertJPEGtoPDF(const std::string& inputPath, const std::string& outputPath) {
    if (!fs::exists(inputPath) || !fs::is_regular_file(inputPath)) {
        std::cerr << "Error: Invalid JPEG file path." << std::endl;
        return 1;
    }

    if (fs::exists(outputPath) && fs::is_regular_file(outputPath)) {
        std::remove(outputPath.c_str());
    }

    const auto inputFileSize = fs::file_size(inputPath);
    if (inputFileSize > MAX_FILE_SIZE) {
        std::cout << "Warning: File size exceeds the maximum allowed limit of " << MAX_FILE_SIZE / (1024 * 1024) << "MB." << std::endl;
    }

    std::string command = "mupdf --pdf-compress --output \"";
    command += outputPath + "\" ";
    command += inputPath + " ";

    int status = system(command.c_str());
    if (status != 0) {
        std::cerr << "Error: Command execution failed with status code " << status << ". Please ensure you have the required tools installed." << std::endl;
        return status;
    }

    // PDF validation using Poppler
    std::ifstream ifs(outputPath, std::ios::binary);
    if (!ifs.is_open()) {
        std::cerr << "Error: Unable to open output file for validation." << std::endl;
        return 1;
    }

    try {
        poppler::pdf_document doc(ifs);
        // Perform additional validations or operations on the PDF document as needed...
    } catch (const std::exception& e) {
        std::cerr << "Error: Invalid PDF structure detected during validation. Detailed error: " << e.what() << std::endl;
        return 1;
    }

    ifs.close();

    return 0;
}
