std::vector<NFAPI_CRC_INDICATION_PDU_T> generateStructures(int N) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> structures;
    std::mt19937 generator;
    std::uniform_int_distribution<> distribution(0, 65535);

    for (size_t i = 0; i < N; ++i) {
        structures.emplace_back();
        structures[i].RX_UE_INFORMATION_TAG = i;
        structures[i].RNTI = distribution(generator);
        while (std::find_if(structures.begin(), structures.end(),
            [&](const NFAPI_CRC_INDICATION_PDU_T &other) { return other.RNTI == structures[i].RNTI; }) != structures.end()) {
            structures[i].RNTI = distribution(generator);
        }
        structures[i].CRC_INDICATION_REL8_TAG = i % 256;
        structures[i].CRCFLAG = (distribution(generator) & 1) == 0;
    }

    return structures;
}

class SQLExecutor {
private:
    std::shared_ptr<sqlpp::connection> connection_;
    boost::asio::steady_timer timer_;

public:
    explicit SQLExecutor(std::shared_ptr<sqlpp::connection> connection) : connection_(connection), timer_(*connection->getIOContext()) {}

    sqlpp::result execute(const std::string& sql, const std::vector<NFAPI_CRC_INDICATION_PDU_T>& structures) {
