        sqlpp::result result;

        try {
            auto start = std::chrono::steady_clock::now();
            auto query = connection_->prepare(stmt);
            auto params = query->bind(structures.begin(), structures.end());
            result = query->execute(params);

            if (std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - start).count() > timeout_) {
                std::cerr << "Query execution timed out." << std::endl;
            }
        } catch (const std::exception& e) {
            std::cerr << "Error executing SQL command: " << e.what() << std::endl;
        }

        return result;
    }
};

sqlpp::result executeSQL(std::shared_ptr<sqlpp::connection> connection, const std::string& sqlCommandString, const std::vector<NFAPI_CRC_INDICATION_PDU_T>& structures) {
