using System.Collections.Generic;

public IDbDataParameter[] CreateParameters(List<NFAPI_CRC_INDICATION_PDU_T> list) {
    var parameters = new List<IDbDataParameter>();

    foreach (var pdu in list) {
        parameters.Add(new SqlParameter("RX_UE_INFORMATION_TAG", pdu.RX_UE_INFORMATION_TAG));
        parameters.Add(new SqlParameter("RNTI", pdu.RNTI));
        parameters.Add(new SqlParameter("CRC_INDICATION_REL8_TAG", pdu.CRC_INDICATION_REL8_TAG));
        parameters.Add(new SqlParameter("CRCFLAG", pdu.CRCFLAG));
    }

    return parameters.ToArray();
}

public IDataReader PersistCrcIndications(List<NFAPI_CRC_INDICATION_PDU_T> list, string connectionString, string sqlCommand) {
    using (var conn = new SqlConnection(connectionString)) {
        try {
            conn.Open();

            using (var transaction = conn.BeginTransaction()) {
                using (var cmd = new SqlCommand(sqlCommand, conn, transaction)) {
                    cmd.Parameters.AddRange(CreateParameters(list));
                    cmd.ExecuteNonQuery();
                    transaction.Commit();
                }

                return cmd.Connection.CreateCommand().ExecuteReader();
            }
        } catch (Exception ex) {
            Console.WriteLine($"Error persisting crc indications: {ex}");
            throw;
        }
    }
}
