#include <NFAPI_CRC_INDICATION_PDU.h>

// External data source API URL
#define RNT_API_URL "https://api.example.com/rnti"

typedef struct {
    sem_t lock;
    size_t max_list_size;
    pthread_mutex_t mtx;
    CURL *curl;
} Context;

Context *ctx = NULL;

void init(size_t max_list_size) {
    ctx = malloc(sizeof(Context));
    ctx->max_list_size = max_list_size;
    sem_init(&ctx->lock, 0, 1);
    pthread_mutex_init(&ctx->mtx, NULL);
    ctx->curl = curl_easy_init();
}

void cleanup() {
    if (ctx) {
        curl_easy_cleanup(ctx->curl);
        free(ctx);
    }
}

NFAPI_CRC_INDICATION_PDU_T *generate_pdu(size_t n) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (size_t i = 0; i < n; ++i) {
        // Generate RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
        pdus[i].rx_ue_information_tag.length = rand() % 16 + 2;
        pdus[i].rx_ue_information_tag.value = malloc(pdus[i].rx_ue_information_tag.length);
        for (size_t j = 0; j < pdus[i].rx_ue_information_tag.length; ++j) {
            pdus[i].rx_ue_information_tag.value[j] = rand() % 256;
        }

        sem_wait(&ctx->lock);
        // Get unique RNTI from external data source
        char *rnti = curl_easy_perform(ctx->curl, RNT_API_URL);
        if (!rnti) {
            perror("Curl request failed.");
            free(pdus);
            return NULL;
        }
        sem_post(&ctx->lock);

        pdus[i].rnti.length = strlen(rnti);
        pdus[i].rnti.value = strdup(rnti);

        pdus[i].crc_indication_rel8_tag.crcflag = rand() % 2;
    }
    return pdus;
}

