#include <functional>
#include <memory>
#include <unordered_map>

// Custom Memory Pool class for efficient allocation and deallocation
class MemoryPool {
public:
    void* Allocate(size_t size) {
        if (freeList_.empty()) {
            void* newMemory = malloc(size + alignment_);
            if (!newMemory) {
                throw std::bad_alloc();
            }
            char* current = static_cast<char*>(newMemory) + alignment_;
            for (size_t i = size; i > alignment_; i -= alignment_) {
                freeList_.push_back(current);
                current += alignment_;
            }
        }
        void* result = freeList_.front();
        freeList_.pop_front();
        return result;
    }

    void Deallocate(void* pointer) {
        if (pointer) {
            char* alignedPointer = static_cast<char*>(pointer) - alignment_;
            freeList_.push_back(alignedPointer);
        }
    }

private:
    std::list<char*> freeList_;
    size_t alignment_ = 8; // Align allocations to 8 bytes for cache locality
};

