    contextArray = static_cast<UEContext*>(contextPool_.Allocate(capacity * sizeof(UEContext)));
    if (!contextArray) {
        throw std::bad_alloc();
    }

    // Load initial data from external sources, handling potential delays or failures gracefully
    std::unique_lock<std::mutex> lock(initDataMutex);
    for (size_t i = 0; i < capacity; ++i) {
