            contextArray[i].crcIndication.crc = 0;
        } else {
            lock.unlock(); // Release the lock to avoid deadlocks when external data is loaded asynchronously
            std::this_thread::sleep_for(std::chrono::milliseconds(50)); // Yield CPU to allow other threads to run
            lock.lock();
