#include <semaphore.h>
#include <stdbool.h>

typedef struct {
    char* name;
    int urgency;
    struct project* dependency;
} project;

struct list_node {
    project* data;
    struct list_node* next;
};

static sem_t lock;
static struct list_node* head = NULL;

void parse_project(const char* str) {
    char token[256], *token_ptr = strtok(str, ";");
    project* new_project = malloc(sizeof(project));

    // Parse project name
    strcpy(token, token_ptr);
    if (strlen(token) == 0) {
        free(new_project);
        return;
    }
    new_project->name = strdup(token);

    // Parse urgency level
    token_ptr = strtok(NULL, "=");
    if (!token_ptr || strlen(token) == 0) {
        free(new_project->name);
        free(new_project);
        return;
    }
    sscanf(token, "%d", &new_project->urgency);

    // Parse dependency (optional)
    token_ptr = strtok(NULL, ";");
    if (token_ptr && strlen(token)) {
        strcpy(token, token_ptr);
        new_project->dependency = find_or_create_project(token);
    } else {
        new_project->dependency = NULL;
    }

    sem_wait(&lock);
    add_to_list(new_project);
    sem_post(&lock);
}

project* find_or_create_project(const char* name) {
    project* current = head;
    while (current != NULL) {
        if (strcmp(current->name, name) == 0) {
            return current;
        }
        current = current->next;
    }

    project* new_project = malloc(sizeof(project));
    strcpy(new_project->name, name);
    new_project->urgency = 0;
    new_project->dependency = NULL;

    sem_wait(&lock);
    if (head == NULL) {
        head = new_project;
    } else {
        struct list_node* current_node = head;
        while (current_node->next != NULL) {
            current_node = current_node->next;
        }
        current_node->next = malloc(sizeof(struct list_node));
        current_node->next->data = new_project;
        current_node->next->next = NULL;
    }
    sem_post(&lock);

    return new_project;
}

void add_to_list(project* project) {
    if (head == NULL || strcmp(project->name, head->data->name) < 0) {
        struct list_node* new_node = malloc(sizeof(struct list_node));
        new_node->data = project;
        new_node->next = head;
        head = new_node;
    } else {
        sem_wait(&lock);
        struct list_node* current_node = head;
        while (current_node->next != NULL && strcmp(project->name, current_node->next->data->name) > 0) {
            current_node = current_node->next;
        }
        project->next = current_node->next;
        current_node->next = project;
        sem_post(&lock);
    }
}

