#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>

typedef struct {
    int *key;
    int value;
} Record;

void initialize_records(int n, int m, int k, Record* records, int* keys, long* offsets) {
    if (n <= 0 || m <= 0 || k <= 0) return;

    records = realloc(records, k * sizeof(Record));
    keys = realloc(keys, m * sizeof(int));
    offsets = calloc(n + 1, sizeof(long));

    for (int i = 0; i < k; ++i) {
        records[i].key = &keys[(i * (m - 1)) % m];
        records[i].value = 0;
    }

    offsets[0] = 0;
}

int custom_hash(int key, int index, int min_value, int max_value) {
    double factor = (double)(max_value - min_value + 1) / ((double)RAND_MAX + 1);
    int hash = abs((key * index + rand()) % (max_value - min_value + 1)) + min_value;
    return hash < max_value ? hash : max_value - 1;
}

void update_records(Record* records, int min_value, int max_value) {
    if (!records || !min_value || !max_value) return;

    for (int i = 0; i < records->k; ++i) {
        int hash = custom_hash(*records[i].key, i, min_value, max_value);
        if (hash >= min_value && hash <= max_value)
            *records[i].value++ = hash;
    }
}

void free_memory(Record* records, int* keys, long* offsets) {
    if (!records || !keys || !offsets) return;

    free(records);
    free(keys);
    free(offsets);
}
