    LTE_TARGET_TIME_INSTANCE time_instance;
    size_t subframe_info_len;
    LTE_RX_SUBFRAME_INFO* subframe_info;
} LTE_PHY_RX_TARGET;

const int LTE_PHY_RX_TARGET_ARRAY_SIZE = 1024;

// Custom memory pool allocator
typedef struct MEM_POOL {
    void* start;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
} MEM_POOL;

void mem_pool_init(MEM_POOL* pool, size_t initial_size) {
    pool->start = malloc(initial_size);
    if (!pool->start) {
        // Handle memory allocation failure and integrate with external logging library
        printf("Failed to allocate memory for custom memory pool!\n");
        exit(1);
    }
    pool->size = initial_size;
    pool->used = 0;
    pool->lock = PTHREAD_MUTEX_INITIALIZER;
}

void* mem_pool_alloc(MEM_POOL* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    void* result = NULL;
    if (size <= pool->size - pool->used) {
        result = (char*)pool->start + pool->used;
        pool->used += size;
    }
    pthread_mutex_unlock(&pool->lock);
    return result;
}

void mem_pool_free(MEM_POOL* pool, void* ptr) {
    pthread_mutex_lock(&pool->lock);
    if (ptr && pool->used > 0) {
        pool->used -= ((char*)ptr - (char*)pool->start);
    }
    pthread_mutex_unlock(&pool->lock);
}

// Function to initialize dynamic array of LTE_PHY_RX_TARGET structures
void init_lte_phy_rx_target_array(LTE_PHY_RX_TARGET** targets, MEM_POOL* mem_pool) {
