        (*targets)[i].subframe_info = (LTE_RX_SUBFRAME_INFO*)mem_pool_alloc(mem_pool, sizeof(LTE_RX_SUBFRAME_INFO) * (*targets)[i].subframe_info_len);
        if (!(*targets)[i].subframe_info) {
            // Handle memory allocation failure and integrate with external logging library
            printf("Failed to allocate memory for LTE_RX_SUBFRAME_INFO array in LTE_PHY_RX_TARGET structure!\n");
            exit(1);
        }
    }
