#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/types.h>
#include <netinet/in.h>

typedef struct Packet {
    sockaddr_in source;
    sockaddr_in destination;
    uint16_t protocol;
    uint16_t checksum;
} Packet;

typedef struct DynamicList {
    Packet* data;
    size_t capacity;
    size_t size;
    clock_t last_insert;
    clock_t last_delete;
    double insert_avg_time;
    double delete_avg_time;
    FILE* log_file;
} DynamicList;

DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) {
        fprintf(stderr, "Error: Failed to allocate memory for the dynamic list.\n");
        return NULL;
    }

    list->data = (Packet*)calloc(initial_capacity, sizeof(Packet));
    if (!list->data) {
        fprintf(stderr, "Error: Failed to allocate memory for the packet array.\n");
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    list->last_insert = clock();
    list->last_delete = clock();
    list->insert_avg_time = 0.0;
    list->delete_avg_time = 0.0;
    list->log_file = stdout; // Default to standard output for logging

    return list;
}

void resize_dynamic_list(DynamicList* list, size_t new_capacity) {
    Packet* temp_data = (Packet*)realloc(list->data, new_capacity * sizeof(Packet));
    if (!temp_data) {
        fprintf(stderr, "Error: Failed to reallocate memory for the packet array.\n");
        return;
    }

    list->data = temp_data;
    list->capacity = new_capacity;
}

void log_packet_operation(DynamicList* list, const char* operation) {
    time_t now = time(NULL);
    struct tm* local = localtime(&now);
    fprintf(list->log_file, "%s: %d-%02d-%02d %02d:%02d:%02d - Operation: %s\n", asctime(local), (int)ntohl(list->data[list->size - 1].source.sin_addr.s_addr),
                                                                                (int)ntohs(list->data[list->size - 1].source.sin_port),
                                                                                (int)ntohl(list->data[list->size - 1].destination.sin_addr.s_addr),
                                                                                (int)ntohs(list->data[list->size - 1].destination.sin_port),
                                                                                operation);
}

void insert_packet(DynamicList* list, const sockaddr_in* source, const sockaddr_in* destination, uint16_t protocol, uint16_t checksum) {
    if (list->size >= list->capacity) {
        resize_dynamic_list(list, list->capacity * 2);
    }

    Packet* packet = &list->data[list->size];
    memcpy(&packet->source, source, sizeof(sockaddr_in));
    memcpy(&packet->destination, destination, sizeof(sockaddr_in));
    packet->protocol = protocol;
    packet->checksum = checksum;

    clock_t now = clock();
    list->last_insert = now;
    list->size++;
    double current_avg_time = (now - list->last_insert) / CLOCKS_PER_SEC;
    list->insert_avg_time = (list->size > 1) ? (list->insert_avg_time * (list->size - 1) + current_avg_time) / list->size : current_avg_time;

    log_packet_operation(list, "Insert");
}

void delete_packet(DynamicList* list, size_t index) {
    if (index >= list->size || index < 0) {
        fprintf(stderr, "Error: Invalid packet index for deletion.\n");
        return;
    }

    clock_t now = clock();
    list->last_delete = now;
    list->size--;
    double current_avg_time = (now - list->last_delete) / CLOCKS_PER_SEC;
    list->delete_avg_time = (list->size > 1) ? (list->delete_avg_time * (list->size - 1) + current_avg_time) / list->size : current_avg_time;
}
```

