    fread(size, sizeof(int), 1, file);
    fread(size, sizeof(long), 1, file);
    fread(size, sizeof(record*), 1, file);

    // Allocate memory for the arrays and records based on the read size
    *offsets = (long *)malloc(*size * sizeof(long));
    *keys = (int *)malloc(*size * sizeof(int));
    **records = (record**)malloc(*size * sizeof(record*));
    for (int i = 0; i < *size; ++i) {
        (*records)[i] = malloc(sizeof(record));
