    for (int i = 0; i < *size; ++i) {
        fread(&(*offsets)[i], sizeof(long), 1, file);
        fread(&(*keys)[i], sizeof(int), 1, file);
        fread(&((*records)[i]->value), sizeof(int), 1, file);
