class Player {
public:
    enum Attack { ATTACK_1, ATTACK_2 };
    std::atomic<Attack> currentAttack{ATTACK_1};
    std::chrono::steady_clock::time_point lastAttackTime{std::chrono::steady_clock::now()};
    std::chrono::seconds cooldownDuration{9};

    Attack selectAttack() {
        auto now = std::chrono::steady_clock::now();
        if (now - lastAttackTime < cooldownDuration) return currentAttack;
        std::uniform_int_distribution<> dist(0, 1);
        currentAttack = static_cast<Attack>(dist(std::random_device{}));
        lastAttackTime = now;
        return currentAttack;
    }
};

class GameSession {
public:
    void processGameSession() {
        std::vector<Player> players;
        // Initialize players with specified number of players

        std::mutex roundsMutex;
        std::atomic<int> roundsCompleted{0};

        auto roundDuration = std::chrono::seconds(5);
        auto attackFeedUpdateInterval = std::chrono::milliseconds(500); // 0.5 seconds

        std::thread dataFeedThread([&]() {
            while (true) {
                std::this_thread::sleep_for(attackFeedUpdateInterval);
                // Update player statistics based on external data feeds
            }
        });

        std::vector<std::thread> threads;
        for (auto& player : players) {
            threads.emplace_back([&, &player]() {
                while (true) {
                    std::this_thread::sleep_for(roundDuration);

                    std::unique_lock<std::mutex> lock(roundsMutex);
                    if (!roundsCompleted.load() % players.size()) break; // Exit after each round for all players

                    auto attack = player.selectAttack();
                    // Apply the selected attack on game environment

                    lock.unlock();

                    std::this_thread::sleep_for(std::chrono::seconds(1)); // Simulate attack processing time
                }
            });
        }

        dataFeedThread.detach();
        for (auto& thread : threads) thread.join();

        std::cout << "Number of successful attacks: " << /*Count successful attacks here*/ << std::endl;
        std::cout << "Number of failed attacks due to cooldown: " << /*Count failed attacks due to cooldown here*/ << std::endl;
        std::cout << "Total number of rounds completed: " << roundsCompleted.load() << std::endl;
    }
};
