                token = strtok(NULL, ",");
                if (!token) break;
                data[index].nestedData.arr[i] = atoi(token);
            }
        }

        fclose(fp);
    } else {
        // Fetch data from an external source.
        // ...
    }

    return 0;
}

void deallocateDataArray(dataEntry* array, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        free(array[i].str);
    }
    free(array);
}
