struct TrafficFlow *traffic_array;
size_t array_size = ARRAY_INITIAL_SIZE;
pthread_mutex_t array_mutex = PTHREAD_MUTEX_INITIALIZER;

void resize_array() {
    size_t new_capacity = (array_size >= MAX_ARRAY_SIZE) ? array_size * 2 : array_size + 10;
    struct TrafficFlow *new_traffic_array = realloc(traffic_array, new_capacity * sizeof(struct TrafficFlow));
    if (!new_traffic_array) {
        fprintf(stderr, "Error: Failed to allocate memory for array expansion.\n");
        return;
    }
    traffic_array = new_traffic_array;
    array_size = new_capacity;
}

void serialize(FILE *file) {
    if (!traffic_array || !file) {
        fprintf(stderr, "Error: Cannot serialize null pointers.\n");
        return;
    }
    if (fwrite(traffic_array, sizeof(struct TrafficFlow), array_size, file) != array_size) {
        fprintf(stderr, "Error: Failed to write data to file.\n");
    }
}

void deserialize(FILE *file) {
    if (!file || !traffic_array) {
        fprintf(stderr, "Error: Cannot deserialize null pointers.\n");
        return;
    }
    fseek(file, 0, SEEK_SET);
    if (fread(traffic_array, sizeof(struct TrafficFlow), array_size, file) != array_size) {
        fprintf(stderr, "Error: Failed to read data from file.\n");
    }
}
