#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
    unsigned char flag; // 0: inactive, 1: active
} Record;

struct Segment {
    size_t capacity;
    size_t used;
    Record* records;
};

struct System {
    struct Segment* segments;
    size_t num_segments;
    size_t max_records;
    size_t threshold;
    pthread_mutex_t lock;
};

void init_system(struct System* sys, size_t num_segments, size_t max_records, size_t threshold) {
    sys->num_segments = num_segments;
    sys->max_records = max_records;
    sys->threshold = threshold;
    sys->segments = malloc(sizeof(struct Segment) * num_segments);

    for (size_t i = 0; i < num_segments; ++i) {
        sys->segments[i].capacity = MAX_SEGMENT_SIZE;
        sys->segments[i].used = 0;
        sys->segments[i].records = malloc(MAX_SEGMENT_SIZE * sizeof(Record));
    }

    pthread_mutex_init(&sys->lock, NULL);
}

void destroy_system(struct System* sys) {
    for (size_t i = 0; i < sys->num_segments; ++i)
        free(sys->segments[i].records);
    free(sys->segments);
    pthread_mutex_destroy(&sys->lock);
}

void* get_random_value(void* arg) {
    return rand() % 100 + 1;
}

void add_record(struct System* sys, size_t segment_id, int key) {
    pthread_mutex_lock(&sys->lock);

    while (sys->segments[segment_id].used >= sys->segments[segment_id].capacity &&
           sys->max_records > 0) {
        struct Segment* next_segment = (segment_id + 1 < sys->num_segments) ? &(sys->segments[segment_id + 1]) : sys->segments;
        if (next_segment->used + 1 <= next_segment->capacity &&
            sys->max_records - sys->threshold >= next_segment->capacity) {
            segment_id = next_segment - sys->segments;
        } else {
            pthread_mutex_unlock(&sys->lock);
            sleep(1); // Simulate memory pressure signals, adjust time as needed
            pthread_mutex_lock(&sys->lock);
        }
    }

    Record* record = &(sys->segments[segment_id]->records[sys->segments[segment_id]->used]);
    record->value = key;
    record->flag = 1; // active
    ++sys->segments[segment_id]->used;

    pthread_mutex_unlock(&sys->lock);
}

int main() {
    struct System sys;
    init_system(&sys, 4, 1000, 5000);

    // Simulate concurrent access from multiple threads
    pthread_t threads[NUM_THREADS];
    for (size_t i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, add_record_wrapper, &sys)) {
            perror("pthread_create");
            exit(EXIT_FAILURE);
        }
    }

    // Wait for all threads to finish
    for (size_t i = 0; i < NUM_THREADS; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("pthread_join");
            exit(EXIT_FAILURE);
        }
    }

    destroy_system(&sys);
    return 0;
}
