#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>
#include <sys/time.h>

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU;

typedef struct _NODE {
    NFAPI_CRC_INDICATION_PDU data;
    struct _NODE* next;
} NODE;

struct _LIST {
    int capacity;
    int size;
    NODE* head;
    NODE* tail;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
    time_t last_cleanup;
};

void log(const char* format, ...) {
    // Implement your logging module here
}

void cleanup(struct _LIST* list) {
    NODE *current = list->head, *next;
    struct timeval tv;

    gettimeofday(&tv, NULL);

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    list->size = 0;
    list->head = NULL;
    list->tail = NULL;

    log("%s: Cleanup started at %ld.%06ld", __func__, (long int)tv.tv_sec, (int)tv.tv_usec);
}

void resize(struct _LIST* list) {
    // Implement your dynamic resizing mechanism here
}

bool enqueue(struct _LIST* list, NFAPI_CRC_INDICATION_PDU data) {
    NODE *new_node = (NODE*)malloc(sizeof(NODE));
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->capacity) {
        resize(list);
    }

    if (list->head == NULL) {
        log("%s: Queue empty, enqueuing first element.", __func__);
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    list->size++;
    pthread_cond_signal(&list->not_full);

    pthread_mutex_unlock(&list->mutex);

    return true;
}

NFAPI_CRC_INDICATION_PDU dequeue(struct _LIST* list) {
    NFAPI_CRC_INDICATION_PDU data;
    NODE *node = NULL;

    pthread_mutex_lock(&list->mutex);

    if (list->size == 0) {
        log("%s: Queue empty, returning NULL.", __func__);
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }

    node = list->head;
    data = list->head->data;
    list->head = list->head->next;

    if (list->size == 1) {
        free(node);
        list->tail = NULL;
    }

    list->size--;
    pthread_cond_signal(&list->not_empty);

    pthread_mutex_unlock(&list->mutex);

    return data;
}

void init_list(struct _LIST* list, int capacity) {
    list->capacity = capacity;
    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
    list->last_cleanup = time(NULL);

    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->not_full, NULL);
    pthread_cond_init(&list->not_empty, NULL);
}

void* cleanup_thread(void *arg) {
    struct _LIST *list = (struct _LIST *)arg;
    struct timeval tv;

    while (true) {
        gettimeofday(&tv, NULL);

        if ((tv.tv_sec - list->last_cleanup) > 60) {
            cleanup(list);
            list->last_cleanup = tv.tv_sec;
        }

        pthread_cond_wait(&list->not_empty, &list->mutex);
    }

    return NULL;
}
```

