use std::collections::{HashMap, HashSet};
use std::mem;
use rand::Rng;
use reqwest::Client;
use log::{info, error, trace};
use serde_json::{Map, Value};
use serde::{Deserialize, Serialize};

type Offset = u64;
type Key = i32;
type Record = (Key, bool);

const THRESHOLD: i32 = 1000;
const CONFIG_URL: &str = "https://config.api/getConfig";

#[derive(Debug, Serialize, Deserialize)]
struct Config {
    active_records_limit: i32,
    record_range_max: i32,
}

fn create_http_client_with_dynamic_data_management() -> Client {
    let mut config = load_config().unwrap_or_default();
    let offset = Offset::MAX;
    let keys: HashSet<Key> = HashSet::new();
    let records: HashMap<Key, Record> = HashMap::with_capacity(config.active_records_limit as usize);

    let mut rng = rand::thread_rng();

    let client = Client::builder()
        .max_connections(10) // Adjust as needed for concurrent requests
        .build().unwrap();

    let load_config = move || {
        match client.get(CONFIG_URL).send() {
            Ok(response) => response.json::<Config>().expect("Failed to parse config"),
            Err(_) => Config::default(),
        }
    };

    let reinitialize_data = || {
        let new_config = load_config();
        config = new_config;
        keys.clear();
        records.clear();
        generate_records(&mut rng, &config);
    };

    let generate_records = |rng: &mut rand::Rng, config: &Config| {
        for _ in 0..config.active_records_limit {
            let key = rng.gen_range(1..=config.record_range_max);
            let is_active = if keys.len() >= THRESHOLD as usize { false } else { true };
            let record: Record = (key, is_active);

            if is_active && records.insert(key, record).is_err() {
                error!("Data inconsistency detected.");
                reinitialize_data();
                return;
            }

            keys.insert(key);
        }
    };

    let update_records = |new_record: (Key, Record)| {
        if let Some((_, old_record)) = records.insert(new_record.0, new_record) {
            if old_record.1 && new_record.1 && (old_record.1 || !new_record.1) {
                error!("Data inconsistency detected.");
                reinitialize_data();
                return;
            }
        }
    };

    let logger = log4rs::init_file_appender_full("debug.log", LevelFilter::Debug).unwrap();

    struct DataManager {
        keys: HashSet<Key>,
        records: HashMap<Key, Record>,
    }

    impl Drop for DataManager {
        fn drop(&mut self) {
            reinitialize_data();
        }
    }

    let data_manager = DataManager {};

    struct LoggingMiddleware {
        inner: Box<dyn reqwest::blocking::RequestBuilder + Send + Sync>,
    }

    impl reqwest::Client for LoggingMiddleware {
        type Builder = reqwest::blocking::RequestBuilder;
        type Response = reqwest::Response;
        type Error = reqwest::Error;

        fn build_request(&self) -> Self::Builder {
            let request = self.inner.build();
            LoggingMiddleware { inner: Box::new(request) }
        }

        fn send(&self) -> Result<Self::Response, Self::Error> {
            trace!("Sending request: {:?}", self.inner.url());
            let result = self.inner.send()?;
            info!("Received response from {}: {}", result.url(), result);
            Ok(result)
        }
    }

    let client = Client::builder()
        .request_builder(|b| LoggingMiddleware { inner: b })
        .redact_response(|r| r.json::<Map<Value>>())
        .build().unwrap();

    (client, data_manager)
}
```

