    int TX_POWER;
    int ANTENNA_PORT;
};

typedef struct {
    void *data;
    size_t size;
    size_t capacity;
    sem_t mutex;
} RingBuffer;

RingBuffer *ring_buffer_create(size_t size) {
    RingBuffer *rb = malloc(sizeof(RingBuffer));
    rb->data = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    rb->size = size;
    rb->capacity = size;
    sem_init(&rb->mutex, 0, 1);
    return rb;
}

void ring_buffer_push(RingBuffer *rb, void *data) {
    sem_wait(&rb->mutex);

    // Calculate high-resolution timestamp and initialize SEQ_NUM field in data
    uint64_t current_timestamp = get_high_resolution_timestamp();
    memcpy(((char *)data + offsetof(TX_PACKET_INFO_T, SEQ_NUM)), &current_timestamp, sizeof(uint64_t));

    // Map antenna ports to power levels based on external configuration file
    int antenna_port = get_antenna_port((char *)data);
    set_tx_power(antenna_port, ((TX_PACKET_INFO_T*)data)->TX_POWER);

    sem_post(&rb->mutex);
}

// Implement thread-safe methods for querying statistics here

void ring_buffer_destroy(RingBuffer *rb) {
    munmap(rb->data, rb->size);
    free(rb);
}
