#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    LTE_EUTRAN_CELLOP_RELAY_T cell;
    LTE_UL_CCCH_MESSAGE_T msg;
} LTE_ENB_CONFIGURATION_T;

typedef struct ArrayNode {
    LTE_ENB_CONFIGURATION_T *data;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
    sem_t semaphore;
} ArrayNode;

ArrayNode *create_array(size_t initial_capacity) {
    ArrayNode *arr = malloc(sizeof(ArrayNode));
    arr->data = calloc(initial_capacity, sizeof(LTE_ENB_CONFIGURATION_T));
    arr->capacity = initial_capacity;
    arr->length = 0;
    pthread_mutex_init(&arr->mutex, NULL);
    sem_init(&arr->semaphore, 0, arr->capacity);
    return arr;
}

LTE_ENB_CONFIGURATION_T *get_config(ArrayNode *arr) {
    LTE_ENB_CONFIGURATION_T *data = NULL;
    sem_wait(&arr->semaphore);
    pthread_mutex_lock(&arr->mutex);
    if (arr->length < arr->capacity) {
        data = &arr->data[arr->length];
        memset(data, 0, sizeof(LTE_ENB_CONFIGURATION_T));
        arr->length++;
    }
    pthread_mutex_unlock(&arr->mutex);
    sem_post(&arr->semaphore);
    return data;
}

void resize_array(ArrayNode **arr, size_t new_capacity) {
    if (new_capacity <= (*arr)->capacity) return;

    ArrayNode *temp = malloc(sizeof(ArrayNode));
    temp->data = calloc(new_capacity, sizeof(LTE_ENB_CONFIGURATION_T));
    temp->capacity = new_capacity;
    temp->length = (*arr)->length;
    pthread_mutex_init(&temp->mutex, NULL);
    sem_init(&temp->semaphore, 0, temp->capacity);

    int i;
    for (i = 0; i < (*arr)->length; ++i) {
        sem_wait((*arr)->semaphore);
        pthread_mutex_lock(&(*arr)->mutex);
        LTE_ENB_CONFIGURATION_T *current = &(*arr)->data[i];
        memcpy(&temp->data[i], current, sizeof(LTE_ENB_CONFIGURATION_T));
        pthread_mutex_unlock(&(*arr)->mutex);
        sem_post((*arr)->semaphore);
    }

    free(*arr);
    *arr = temp;
}

void safe_iterate(ArrayNode *arr, void (*func)(LTE_ENB_CONFIGURATION_T *)) {
    if (arr == NULL || func == NULL) return;

    sem_wait(&arr->semaphore);
    pthread_mutex_lock(&arr->mutex);

    size_t start = arr->length - 1, end = arr->length;
    while (start != 0) {
        start--;
        if (start >= arr->capacity - arr->length) end = start + 1;
    }

    for (size_t i = end; i < arr->length; ++i) {
        LTE_ENB_CONFIGURATION_T *current = &arr->data[i];
        func(current);
    }

    pthread_mutex_unlock(&arr->mutex);
    sem_post(&arr->semaphore);
