struct Record {
    long offset;
    int key;
    int value;
};

std::vector<Record> manageRecords(size_t size, bool log, int minKey, int maxKey, int minValue, int maxValue) {
    std::vector<Record> records;
    std::unordered_map<int, size_t> keysMap;
    std::mt19937 rng(time(0)); // random number generator with current time seed
    std::uniform_int_distribution<> distrKey(minKey, maxKey), distrValue(minValue, maxValue);

    for (size_t i = 0; i < size; ++i) {
        int key = distrKey(rng);
        while (keysMap.count(key)) key = distrKey(rng);
        records.emplace_back(Record{0, key, distrValue(rng)});
        keysMap[key] = i;
    }

    std::sort(records.begin(), records.end(), [](const Record& a, const Record& b) { return a.key < b.key; });
    if (log) logRecords(records); // optional logging function not provided here
    return records;
}
