        target->rx_subframe_info[i] = data[i];
    }

    target->rx_subframe_info_len = data_len;

    pthread_mutex_unlock(&target->mutex);
}

size_t delete_rx_subframe_info(LTE_PHY_RX_TARGET *target, size_t start_index, size_t num_elements) {
    pthread_mutex_lock(&target->mutex);

    if (start_index >= target->rx_subframe_info_len || num_elements > target->rx_subframe_info_len - start_index) {
        pthread_mutex_unlock(&target->mutex);
        return 0;
    }

    memmove(target->rx_subframe_info + start_index, target->rx_subframe_info + start_index + num_elements, (target->rx_subframe_info_len - start_index - num_elements) * sizeof(int));
    target->rx_subframe_info_len -= num_elements;

    pthread_mutex_unlock(&target->mutex);
    return num_elements;
}
