uint32_t count_vowels(const char *str) {
    uint32_t count = 0;
    while (*str != '\0') {
        if (strchr("aeiouAEIOU", *str))
            ++count;
        ++str;
    }
    return count;
}

char* rename_file(const char *path) {
    size_t len = strlen(path);
    size_t ext_len = 4; // default extension length
    char *new_name = malloc(len + ext_len + 1);
    if (!new_name) return NULL;
    memcpy(new_name, path, len);

    const char *ext_start = path + len;
    for (const char *ext_end = ext_start + ext_len; ext_start < ext_end; ++ext_start) {
        if (*ext_start == '.') {
            break;
        }
    }
    size_t ext_len2 = ext_end - ext_start;

    if (ext_len2 + count_vowels(path) > 5) {
        memcpy(new_name + len, "_V", 3);
        ext_len = 3;
    } else {
        memcpy(new_name + len, "_C", 2);
        ext_len = 2;
    }

    memmove(new_name + len + ext_len, ext_start, ext_len2);
    new_name[len + ext_len + ext_len2] = '\0';

    if (strlen(new_name) > 256) {
        free(new_name);
        return NULL;
    }

    return new_name;
}

NFAPI_CRC_INDICATION_PDU_T* gen_pdu(size_t n) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return NULL;

    for (size_t i = 0; i < n; ++i) {
        pdus[i].Rx_ue_information_tag.Value = i;
        pdus[i].Rnti = i + 123456789;
        pdus[i].Crc_indication_rel8_tag.Crcflag = (i % 2) ? 0 : 1;
    }

    return pdus;
}

char* modify_and_generate(const char *path, size_t n, FILE **file) {
    char *new_name = rename_file(path);
    if (!new_name) return NULL;

    FILE *new_fp = fopen(new_name, "w+");
    if (!new_fp) {
        free(new_name);
        return NULL;
    }

    fseek(*file, 0, SEEK_SET); // reset the file pointer to the start of the file
    size_t buf_size = 1024;
    char *buf = malloc(buf_size);
    if (!buf) {
        fclose(new_fp);
        free(new_name);
        return NULL;
    }

    while (fgets(buf, buf_size, *file)) {
        size_t read = strlen(buf);
        char *new_buf = realloc(buf, read + 1 + strlen(new_name));
        if (!new_buf) {
            free(buf);
            fclose(new_fp);
            free(new_name);
            return NULL;
        }
        memcpy(new_buf + read, new_name, strlen(new_name) + 1);
        fputs(new_buf, new_fp);
        free(buf);
        buf = new_buf;
    }
    free(buf);

    fclose(new_fp);

    NFAPI_CRC_INDICATION_PDU_T *pdus = gen_pdu(n);
    if (!pdus) {
        free(new_name);
        return NULL;
    }

    *file = fopen(new_name, "r"); // open the file for reading
    return new_name;
}
