#define MEMORY_POOL_SIZE 1024
#define MEMORY_THRESHOLD 90

NFAPI_CRC_INDICATION_PDU_T* memory_pool;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
size_t used_memory = 0;
size_t max_memory = 0;
bool filter_crcflag = false;
pthread_cond_t free_condition = PTHREAD_COND_INITIALIZER;

void* memory_pool_init(size_t num_ue_instances) {
    if (num_ue_instances > MEMORY_POOL_SIZE) {
        printf("Error: Number of UE instances exceeds the memory pool size.\n");
        return NULL;
    }

    memory_pool = malloc(num_ue_instances * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!memory_pool) {
        printf("Error: Failed to allocate memory for the memory pool.\n");
        return NULL;
    }

    max_memory = num_ue_instances;
    used_memory = 0;

    return memory_pool;
}

NFAPI_CRC_INDICATION_PDU_T* get_next_free() {
    pthread_mutex_lock(&pool_mutex);

    if (used_memory < max_memory) {
        NFAPI_CRC_INDICATION_PDU_T* next = memory_pool + used_memory;
        ++used_memory;
        pthread_mutex_unlock(&pool_mutex);
        return next;
    } else {
        pthread_cond_wait(&free_condition, &pool_mutex);
        pthread_mutex_unlock(&pool_mutex);
        return get_next_free();
    }
}

void put_back(NFAPI_CRC_INDICATION_PDU_T* element) {
    if (element->rnti >= max_memory) {
        printf("Error: Invalid RNTI value.\n");
        return;
    }

    pthread_mutex_lock(&pool_mutex);

    if (used_memory > 0 && element->rnti < used_memory) {
        memory_copy(memory_pool + element->rnti, element);
        --used_memory;
        pthread_cond_signal(&free_condition);
        pthread_mutex_unlock(&pool_mutex);
    } else {
        printf("Error: Trying to put back an element outside the current memory usage.\n");
        pthread_mutex_unlock(&pool_mutex);
    }
