// Custom memory management functions
typedef struct MemBlock {
    void *data;
    size_t size;
    struct MemBlock *next;
} MemBlock;

void* mem_malloc(size_t size) {
    MemBlock *mem = (MemBlock*) malloc(sizeof(MemBlock));
    if (!mem) return NULL;

    mem->data = malloc(size);
    if (!mem->data) {
        free(mem);
        return NULL;
    }

    mem->size = size;
    mem->next = NULL;
    return mem->data;
}

void mem_free(void *ptr) {
    MemBlock *mem = (MemBlock*) ptr;
    free(mem->data);
    free(mem);
}

// Custom resizable array structure
typedef struct ResizableArray {
    void **data;
    size_t capacity;
    size_t length;
    size_t item_size;
} ResizableArray;

ResizableArray* resizable_array_create(size_t initial_capacity, size_t item_size) {
    ResizableArray *arr = (ResizableArray*) malloc(sizeof(ResizableArray));
    if (!arr) return NULL;

    arr->data = mem_malloc(initial_capacity * item_size);
    if (!arr->data) {
        free(arr);
        return NULL;
    }

    arr->capacity = initial_capacity;
    arr->length = 0;
    arr->item_size = item_size;
    return arr;
}

void resizable_array_resize(ResizableArray *arr, size_t new_capacity) {
    void *new_data = mem_malloc(new_capacity * arr->item_size);
    if (!new_data) return;

    for (size_t i = 0; i < arr->length; ++i) {
        memcpy(new_data + (i * arr->item_size), arr->data + (i * arr->item_size), arr->item_size);
    }

    mem_free(arr->data);

    arr->data = new_data;
    arr->capacity = new_capacity;
}

