typedef struct _hash_table {
    record* records;
    unsigned int size;
    pthread_mutex_t mutex;
} hash_table;

hash_table* create_hash_table(unsigned int size) {
    hash_table* ht = malloc(sizeof(hash_table));
    ht->records = calloc(size, sizeof(record));
    ht->size = size;
    ht->mutex = PTHREAD_MUTEX_INITIALIZER;
    return ht;
}

void hash_insert(hash_table* ht, record r) {
    unsigned long key = r.key % ht->size;
    pthread_mutex_lock(&ht->mutex);
    int i = key;
    for ( ; i < ht->size; ++i ) {
        if (!ht->records[i].key) {
            ht->records[i] = r;
            break;
        }
        if (ht->records[i].key == r.key) {
            pthread_mutex_unlock(&ht->mutex);
            return;
        }
    }
    i %= ht->size;
    for ( ; i > 0; --i ) {
        if (!ht->records[i - 1].key) {
            ht->records[i - 1] = r;
            break;
        }
    }
    pthread_mutex_unlock(&ht->mutex);
}

record* hash_lookup(hash_table* ht, unsigned long key) {
    record* record = &ht->records[(unsigned int)key % ht->size];
    for ( ; record->key == key; ++record ) {
        if (!record->key) return NULL;
