    while (*numBuffers < NUM_BUFFERS) {
        if (!tempBuffers) {
            tempBuffers = (AUDIO_STREAM_BUFFER*)malloc(capacity * sizeof(AUDIO_STREAM_BUFFER));
            if (!tempBuffers) {
                break; // Handle error
            }
