        // Initialize each buffer with default values
        for (int i = 0; i < capacity; ++i) {
            tempBuffers[i].header.isInitialized = false;
            tempBuffers[i].sampleData = NULL;
            tempBuffers[i].timestamp = 0;
        }

        // Check for overflow and reallocate if needed
        if (*numBuffers + capacity >= NUM_BUFFERS) {
            capacity *= GROWTH_FACTOR;
            AUDIO_STREAM_BUFFER* newTempBuffers = (AUDIO_STREAM_BUFFER*)realloc(tempBuffers, capacity * sizeof(AUDIO_STREAM_BUFFER));
