#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct Record {
    long offset;
    int key;
    int value;
} Record;

struct DynamicCollection {
    Record* records;
    long* offsets;
    int* keys;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
};

void init_record(Record* record, long offset) {
    record->offset = offset;
    record->key = 0;
    record->value = rand() % MAX_VALUE_RANGE;
}

int create_dynamic_collection(struct DynamicCollection** dynamic_collection, size_t max_records, size_t threshold) {
    *dynamic_collection = malloc(sizeof(struct DynamicCollection));
    if (!*dynamic_collection) {
        return MEMORY_ERROR;
    }

    (*dynamic_collection)->capacity = max_records;
    (*dynamic_collection)->length = 0;
    (*dynamic_collection)->offsets = calloc(max_records, sizeof(long));
    if (!(*dynamic_collection)->offsets) {
        free(*dynamic_collection);
        return MEMORY_ERROR;
    }

    (*dynamic_collection)->keys = calloc(max_records, sizeof(int));
    if (!(*dynamic_collection)->keys) {
        free((*dynamic_collection)->offsets);
        free(*dynamic_collection);
        return MEMORY_ERROR;
    }

    (*dynamic_collection)->records = malloc(max_records * sizeof(Record));
    if (!(*dynamic_collection)->records) {
        free((*dynamic_collection)->offsets);
        free((*dynamic_collection)->keys);
        free(*dynamic_collection);
        return MEMORY_ERROR;
    }

    for (size_t i = 0; i < max_records; ++i) {
        init_record(&(*dynamic_collection)->records[i], i);
    }

    (*dynamic_collection)->mutex = PTHREAD_MUTEX_INITIALIZER;

    return SUCCESS;
}

int insert(struct DynamicCollection* dynamic_collection, long offset, int key) {
    if (dynamic_collection->length >= dynamic_collection->capacity) {
        return MAX_CAPACITY_ERROR;
    }

    pthread_mutex_lock(&dynamic_collection->mutex);

    while (dynamic_collection->offsets[dynamic_collection->length] <= offset) {
        ++dynamic_collection->length;
    }

    dynamic_collection->keys[dynamic_collection->length - 1] = key;
    dynamic_collection->records[dynamic_collection->length - 1].key = key;
    dynamic_collection->offsets[dynamic_collection->length] = offset;
    dynamic_collection->records[dynamic_collection->length - 1].offset = offset;

    pthread_mutex_unlock(&dynamic_collection->mutex);

    return SUCCESS;
}

int delete(struct DynamicCollection* dynamic_collection, long offset) {
    if (dynamic_collection->length == 0) {
        return NO_ELEMENTS_ERROR;
    }

    pthread_mutex_lock(&dynamic_collection->mutex);

    size_t index = 0;
    for (; index < dynamic_collection->length && dynamic_collection->offsets[index] <= offset; ++index) {}

    if (index == dynamic_collection->length || dynamic_collection->offsets[index] != offset) {
        pthread_mutex_unlock(&dynamic_collection->mutex);
        return NO_ELEMENTS_ERROR;
    }

    for (size_t i = index + 1; i < dynamic_collection->length; ++i) {
        dynamic_collection->offsets[i - 1] = dynamic_collection->offsets[i];
        dynamic_collection->keys[i - 1] = dynamic_collection->keys[i];
    }

    --dynamic_collection->length;

    pthread_mutex_unlock(&dynamic_collection->mutex);

    return SUCCESS;
}

void destroy(struct DynamicCollection* dynamic_collection) {
    if (!dynamic_collection) {
        return;
    }

    free(dynamic_collection->records);
    free(dynamic_collection->keys);
    free(dynamic_collection->offsets);
    free(dynamic_collection);
}
```

The code above defines a custom data structure called `DynamicCollection`, which manages an array of 'record' structures, each containing a long offset, an int key, and an int value. It handles the maximum number of records specified by a parameter, dynamically resizes its underlying arrays when needed, and ensures that all allocated memory is correctly initialized and deallocated upon completion. The data structure provides functions for creating, inserting, deleting elements, as well as destroying it. The implementation uses pthreads mutex to protect the critical sections of code while accessing and modifying the underlying arrays. The code also considers memory usage efficiency, minimizing fragmentation, and latency during frequent insertions and deletions of records."]

