typedef struct {
    long offset;
    int key;
    float data_value;
} data_point;

void read_csv(const char *filename, long *offsets, int *keys, float *data_values, data_point **data_points, size_t *num_points) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    char line[256];
    int offset_idx = 0, key_idx = 0, data_idx = 0, point_idx = 0;
    size_t capacity = 1024;
    *num_points = capacity;
    data_point *data_points_arr = malloc(capacity * sizeof(data_point));
    if (!data_points_arr) {
        perror("Error allocating memory for data points");
        fclose(file);
        return;
    }

    while (fgets(line, sizeof(line), file)) {
        if (point_idx >= *num_points) {
            capacity *= 2;
            data_points_arr = realloc(data_points_arr, capacity * sizeof(data_point));
            if (!data_points_arr) {
                perror("Error reallocating memory for data points");
                fclose(file);
                free(data_points_arr);
                return;
            }
            *num_points = capacity;
        }

        char *token = strtok(line, ",");
        if (!token) {
            continue; // Skip empty lines
        }

        long offset = strtol(token, NULL, 10);
        if (offset < 0 || offset > LLONG_MAX - (*num_points * sizeof(data_point))) {
            fprintf(stderr, "Invalid offset: %ld\n", offset);
            continue;
        }

        token = strtok(NULL, ",");
        int key = atoi(token);
        if (key < 0 || key > INT_MAX) {
            fprintf(stderr, "Invalid key: %d\n", key);
            continue;
        }

        token = strtok(NULL, ",");
        float data_value = strtof(token, NULL);
        if (data_value < FLT_MIN || data_value > FLT_MAX) {
            fprintf(stderr, "Invalid data value: %f\n", data_value);
            continue;
        }

        data_points_arr[point_idx].offset = offset;
        data_points_arr[point_idx].key = key;
        data_points_arr[point_idx].data_value = data_value;
        point_idx++;
    }

    fclose(file);
    *num_points = point_idx;
    *data_points = data_points_arr;
}
