void lte_phy_manager_add_config(struct lte_phy_manager *manager, const lte_phy_config *config) {
    pthread_mutex_lock(&manager->lock);

    if (phy_config_validate(config)) {
        if (manager->num_elements == manager->capacity) {
            void *new_array;
            size_t new_capacity = 2 * manager->capacity;
            lte_phy_config *old_array = manager->array;

            new_array = mmap(NULL, new_capacity * sizeof(lte_phy_config), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
            if (new_array == MAP_FAILED) {
                perror("mmap failed");
                pthread_mutex_unlock(&manager->lock);
                return;
            }

            memcpy(new_array, old_array, manager->num_elements * sizeof(lte_phy_config));
            free(old_array);
            manager->array = new_array;
            manager->capacity = new_capacity;
        }

        manager->array[manager->num_elements] = *config;
        ++manager->num_elements;
    }

    pthread_mutex_unlock(&manager->lock);
}

void lte_phy_manager_update_config(struct lte_phy_manager *manager, unsigned int index, const lte_phy_config *new_config) {
    pthread_mutex_lock(&manager->lock);

    if (index < manager->num_elements && phy_config_validate(new_config)) {
        manager->array[index] = *new_config;
    }

    pthread_mutex_unlock(&manager->lock);
