void lte_phy_manager_remove_config(struct lte_phy_manager *manager, unsigned int index) {
    pthread_mutex_lock(&manager->lock);

    if (index < manager->num_elements) {
        size_t i;
        lte_phy_config last = manager->array[manager->num_elements - 1];

        for (i = index; i < manager->num_elements - 1; ++i) {
            manager->array[i] = manager->array[i + 1];
        }
        --manager->num_elements;

        if ((manager->num_elements > 0 && (manager->num_elements % 2)) || manager->num_elements == manager->capacity / 4) {
            void *tmp_array;
            size_t new_capacity = manager->capacity / 2;
            lte_phy_config *old_array = manager->array;

            tmp_array = mmap(NULL, new_capacity * sizeof(lte_phy_config), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
            if (tmp_array == MAP_FAILED) {
                perror("mmap failed");
                pthread_mutex_unlock(&manager->lock);
                return;
            }

            memcpy(tmp_array, old_array, (manager->num_elements * sizeof(lte_phy_config)));
            free(old_array);
            manager->array = tmp_array;
            manager->capacity = new_capacity;
        }
    }

    pthread_mutex_unlock(&manager->lock);
