typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void add_to_list(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (!new_node) return;

    if (*head == NULL) {
        *head = new_node;
        return;
    }

    Node* current = *head;
    while (current->next != NULL)
        current = current->next;
    current->next = new_node;
}

void fetch_and_process(NFAPI_CRC_INDICATION_PDU_T* data, uint32_t* rnti, bool* is_valid_rnti) {
    // Integrate with external data source to fetch UE information and RNTI values
    *rnti = fetch_UE_RNTI();
    *is_valid_rnti = validate_RNTI(*rnti);
    if (!*is_valid_rnti) return;
    *data = prepare_CRC_indication(*rnti);
}

void resize_list(Node** head, size_t new_size) {
    Node** new_head = (Node**)malloc((new_size + 1) * sizeof(Node*));
    if (!new_head) return;

    Node* current = *head;
    size_t i = 0;
    while (current != NULL) {
        new_head[i] = current;
        current = current->next;
        ++i;
    }
    free(*head);
    *head = new_head;
    (*head)[new_size] = NULL;
}

void process_collection(Node* head) {
    Node* current = head;
    size_t num_elements = 0;
    while (current != NULL) {
        ++num_elements;
        current = current->next;
    }

    if (num_elements > MAX_ELEMENTS)
        resize_list(&head, num_elements * 2);

    current = head;
    while (current != NULL) {
        fetch_and_process(&(current->data.crc_indication), &(current->data.rnti), &(current->data.is_valid_rnti));
        if (!current->data.is_valid_rnti) {
            Node* temp = current;
            current = current->next;
            free(temp);
        } else {
            // Perform further processing on valid elements within the specified latency bounds
            process_valid_element(&(current->data));
            current = current->next;
        }
    }
}
