pthread_mutex_t logEntriesMutex = PTHREAD_MUTEX_INITIALIZER;

void validateAndProcessFile(const char *path, int rootDirIndex) {
    DIR *dir = opendir(path);
    if (!dir) return; // invalid path or inaccessible directory

    struct dirent *entry;
    while ((entry = readdir(dir))) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        char fullPath[512];
        snprintf(fullPath, sizeof(fullPath), "%s/%s", path, entry->d_name);
        validateAndProcessFile(fullPath, rootDirIndex + 1);

        if (rootDirIndex > rootDirIndex) continue; // not within the desired directory hierarchy

        FILE *file = fopen(fullPath, "r");
        if (!file) continue; // unable to open the file

        char line[4096];
        int lineNumber = 0;
        while (fgets(line, sizeof(line), file)) {
            ++lineNumber;

            regmatch_t match;
            if (!regexec(&emailRegex, line, 1, &match, REG_NOTEOL)) {
                EmailLogEntry entry = {};
                snprintf(entry.fileName, sizeof(entry.fileName), fullPath);
                entry.lineNumber = lineNumber;
                strncpy(entry.email, line + match.rm_so, match.rm_eo - match.rm_so);
                entry.email[match.rm_eo] = '\0';

                pthread_mutex_lock(&logEntriesMutex);
                // Add your existing logging framework integration here
                // ...
                pthread_mutex_unlock(&logEntriesMutex);
            }
        }

        fclose(file);
    }

    closedir(dir);
}

void initRegex() {
    regcompile(&validPathRegex, "[/][^/]+", REG_EXTENDED|REG_NEWLINE); // Adjust the regular expression according to your directory policy
    regcompile(&emailRegex, "\\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\\b", REG_EXTENDED);
}

void processFilesInDirectoryHierarchy(const char *rootDir, void (*logEntryCallback)(EmailLogEntry *)) {
    validateAndProcessFile(rootDir, 0);
    // Call the logEntryCallback function for each EmailLogEntry created during processing
    pthread_mutex_lock(&logEntriesMutex);
    // Iterate through the logEntries array and call the logEntryCallback function for each entry
    // ...
    pthread_mutex_unlock(&logEntriesMutex);
}
