typedef struct Record {
    int key;
    float offset;
} Record;

Record* InitializeRecords(int count, int minKey, int maxKey, float minOffset, float maxOffset) {
    Record *records = (Record*)calloc(count, sizeof(Record));
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand((unsigned int)time(NULL));

    for (int i = 0; i < count; ++i) {
        records[i].key = minKey + rand() % ((maxKey - minKey) + 1);
        records[i].offset = minOffset + ((rand() / (float)RAND_MAX) * ((maxOffset - minOffset) + 1));
    }

    return records;
}

void InitializeRecords_CleanUp(Record **records, int count) {
    if (*records) {
        free(*records);
        *records = NULL;
    }
}

inline void swap(Record* a, Record* b) {
    Record temp = *a;
    *a = *b;
    *b = temp;
}

void SortRecords(Record *records, int count) {
    for (int i = 0; i < count - 1; ++i) {
        for (int j = i + 1; j < count; ++j) {
            if (records[i].key > records[j].key) {
                swap(&records[i], &records[j]);
            }
        }
    }
}

#define TO_STRING(x) #x
#define STRINGIFY(x) TO_STRING(x)

static inline char* RecordToString(const Record *record) {
    return STRINGIFY(int)(record->key) ":" STRINGIFY(float)(record->offset);
}

inline void PrintRecords(const Record *records, int count) {
    for (int i = 0; i < count; ++i) {
        printf("%s\n", RecordToString(&records[i]));
    }
}
