typedef struct {
    time_t timestamp;
    double temperature;
    int humidity;
    float pressure;
    char *metadata;
} sensor_reading;

void sensor_readings_init(sensor_reading **readings, size_t capacity) {
    // Allocate memory for the array of pointers to sensor_reading structures
    *readings = malloc(capacity * sizeof(sensor_reading*));
    if (*readings == NULL) {
        fprintf(stderr, "Failed to allocate memory for sensor_readings array\n");
        exit(EXIT_FAILURE);
    }

    // Iterate through the allocated array and initialize each element with a null pointer
    for (size_t i = 0; i < capacity; ++i) {
        (*readings)[i] = NULL;
    }
}

void add_sensor_reading(sensor_reading **readings, size_t *length, sensor_reading *new_reading) {
    // Allocate memory for the new sensor reading structure
    if (new_reading == NULL || new_reading->metadata == NULL) {
        fprintf(stderr, "Invalid sensor reading provided\n");
        return;
    }

    // Reallocate memory for the array of sensor_reading structures, including one additional element to accommodate the new reading
    *readings = realloc(*readings, (*length + 1) * sizeof(sensor_reading));
    if (*readings == NULL) {
        fprintf(stderr, "Failed to allocate memory for additional sensor reading\n");
        exit(EXIT_FAILURE);
    }

    // Set the new sensor reading in the allocated position and increment the length of the array
    (*(*readings + (*length)) = new_reading;
    ++(*length);
}

void sort_sensor_readings(sensor_reading *readings, size_t length) {
    qsort(readings, length, sizeof(sensor_reading), compare_timestamps);
    // Sort by temperature within each timestamp-equal group (stable sort)
    stable_qsort(readings, length, sizeof(sensor_reading), compare_temperatures);
}

int compare_timestamps(const void *a, const void *b) {
    return (*(time_t*)a - *(time_t*)b);
}

int compare_temperatures(const void *a, const void *b) {
    double temp_a = ((sensor_reading*)a)->temperature;
    double temp_b = ((sensor_reading*)b)->temperature;

    if (temp_a < temp_b) return -1;
    else if (temp_a > temp_b) return 1;
    else return 0;
}
