use reqwest::Client;
use std::collections::{HashMap, Vec};
use std::sync::Mutex;
use rand::Rng;
use sha2::Sha256;

type NFAPI_CRC_INDICATION_PDU_T = (u16, u32, [u8; 4]); // Assuming RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG are tuples of appropriate types

struct NFAPIContext {
    pdu_list: Vec<NFAPI_CRC_INDICATION_PDU_T>,
    http_client: Client,
    log: Option<Box<dyn Fn(&String)>>,
}

impl NFAPIContext {
    fn new(log: Option<Box<dyn Fn(&String)>>) -> Self {
        let client = Client::new();
        Self { pdu_list: Vec::new(), http_client: client, log }
    }

    async fn initialize_pdu(&mut self) {
        let mut rng = rand::thread_rng();
        let mut pdu_list = self.pdu_list.drain(..).collect::<Vec<&NFAPI_CRC_INDICATION_PDU_T>>();

        let mut crc_map = Mutex::new(HashMap::new());

        // Concurrently initialize PDUs with CRC values using rayon for efficient parallelization
        pdu_list.par_iter_mut().enumerate()
            .for_each(|(i, pdu)| {
                let crc_map = &mut *crc_map.lock().unwrap();
                if !crc_map.contains_key(&pdu.1) {
                    let crcflag = rng.gen();
                    let mut data = Vec::with_capacity(pdu.2.len());
                    for b in &pdu.2 {
                        data.push(*b);
                    }
                    let hash = Sha256::digest(&data).into_bytes();
                    let crc_val = u16::from_ne_bytes(hash);

                    if self.log.is_some() {
                        self.log.as_ref().unwrap(&format!("Initializing CRC for PDU {}...", i));
                    }

                    crc_map.insert(pdu.1, (pdu.2, crc_val, crcflag));
                }
            });

        let mut updated_pdus = Vec::new();
        for (i, pdu) in pdu_list {
            if let Some((data, crc_val, crcflag)) = crc_map.get(&pdu.1) {
                updated_pdus.push((i, pdu.0, *data, crc_val, crcflag));
            } else {
                if self.log.is_some() {
                    self.log.as_ref().unwrap(&format!("Failed to initialize CRC for PDU {}", i));
                }
                updated_pdus.push((i, pdu.0, [0u8; 4], pdu.2.3, false)); // Set default CRC value and flag
            }
        }

        self.pdu_list = updated_pdus;
    }

    async fn send_http_requests(&mut self) {
        let url = "https://example.com"; // Replace with actual URL

        for pdu in &self.pdu_list {
            let (_, _, data, crc_val, _) = pdu;

            let request_builder = self.http_client
                .post(url)
                .header("Content-Type", "application/octet-stream")
                .body(data);

            if self.log.is_some() {
                let message = format!("Sending HTTP request for PDU {}", pdu.0);
                self.log.as_ref().unwrap(&message);
            }

            match request_builder.send().await {
                Ok(response) => {
                    if response.status().is_success() && crc_val == calc_crc32checksum(&data) {
                        if self.log.is_some() {
                            let message = format!("Successfully sent and received HTTP request for PDU {}", pdu.0);
                            self.log.as_ref().unwrap(&message);
                        }
                    } else {
                        if self.log.is_some() {
                            let message = format!("HTTP request for PDU {} failed or incorrect CRC received", pdu.0);
                            self.log.as_ref().unwrap(&message);
                        }
                    }
                }
                Err(e) => {
                    if self.log.is_some() {
                        let message = format!("Failed to send HTTP request for PDU {}: {}", pdu.0, e);
                        self.log.as_ref().unwrap(&message);
                    }
                }
            }
        }
    }
}

fn calc_crc32checksum(data: &[u8]) -> u32 {
    let mut crc = !0u32;
    for byte in data {
        const TABLE: [u32; 256] = [
            0x00000000, 0x77073096, 0xee0e612c, 0x990951ba, 0x076dc419, 0x706af48f,
            0xe963a535, 0x9e6495a3, 0x0edb8832, 0x79dcb8a4, 0xe0d5e119, 0x97d2d988,
            0x09b64c2b, 0x7eb17cbd, 0xe7b82d07, 0x90bf1d91, 0x1db71064, 0x6ab027cd,
            0xf3b97148, 0x84be41de, 0x1adad47d, 0x6ddde4eb, 0xf4d4b551, 0x83d385c7,
            0x136c9ce4, 0x646ba8c0, 0xfd62f97a, 0x8a65c9ec, 0x14015c4f, 0x63066cd9,
            0xfa0f3d63, 0x8d080df5, 0x3b6e20c8, 0x4c69105e, 0xd56041e4, 0xa2677172,
            0x3c03e4d1, 0x4b04d447, 0xd20decfb, 0x2f0fda83, 0x5e0abc08, 0x286f6fc1,
            0xde026bf1, 0x296f3d3c, 0x4ac52b87, 0x53c8d78a, 0xa5c4cca3, 0xb6939fe7,
            0xfc19dc63, 0x2b6ffda8, 0x56f8e8bc, 0x2f17db13, 0x4ac745c6, 0x5338d8d1,
            0xaa63b30e, 0x6bdea3cf, 0xb160897a, 0x2f6fbe4c, 0x4ae527b0, 0xa2e18a61,
            0xab1c5ed5, 0xfc53f0a5, 0x6d703ef3, 0xd16adaba3, 0x2e6d7a2e, 0x4ac17b66,
            0xa830461d, 0xf271dfee, 0x6afa69ab, 0xaa65f30c, 0xa52ab561, 0xfc2fabec,
            0x6dbdea01, 0x8bdea5dd, 0xfcb9887c, 0x6dbe4bca, 0xf97376f0, 0x8e609bf5,
            0xfc5267f1, 0x6dc11b35, 0xea63a2c1, 0xbb629dbb, 0xfc4ee116, 0x6da4fb98,
            0xf6dbec9b, 0xbe4bcb6e, 0xfc3af0eb, 0x6d7a895f, 0xea81c2f7, 0xb7dbcf7c,
            0xfe04be09, 0xae04be0e, 0xfa04bee1, 0xcb0ebb34, 0xfc53f0a5, 0x6d703ef3,
        ];

        let index = ((crc >> 24) ^ *byte) & 255;
        crc = table[index] ^ (crc << 8);
        crc = crc ^ (table[(crc >> 16) & 255] ^ (crc << 16));
        crc = crc ^ (table[(crc >> 23) & 255] ^ (crc << 32));
        crc = crc ^ table[((crc >> 18) & 255)];
        crc = crc ^ table[((crc >> 12) & 255)] ^ table[(crc >> 12)];
        crc = crc ^ table[(crc >>  7) & 255] ^ table[(crc >>  4)];
        crc = crc ^ table[(crc >>  3) & 255] ^ table[crc >> 10];
        crc = crc ^ table[(crc >>   8) & 255] ^ table[(crc >> 14)];
        crc = crc ^ table[(crc >>  3) & 255] ^ table[((crc >> 10) & 255)];
    }
    crc
}

async fn run(log: Option<Box<dyn Fn(&String)>>) {
    let mut context = NFAPIContext::new(log);
    // Add your PDUs to the context here
    context.initialize_pdu().await;
    context.send_http_requests().await;
}
```

