class CRCList {
private:
    std::list<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> entries_;
    std::map<std::uint16_t, bool> rnti_map_;
    size_t max_entries_ = 10000;
    size_t current_entries_ = 0;
