    std::mt19937 rand_;

public:
    CRCList() : rand_(rand_dev_) {}

    void add(const NFAPI_CRC_INDICATION_PDU_T& data) {
        if (current_entries_ >= max_entries_) {
            std::cout << "Memory constraint reached, queueing entry.\n";
            // Queue the entry or adopt a more aggressive garbage collection strategy here.
            return;
        }

        if (rnti_map_.find(data.rnti) != rnti_map_.end()) {
            std::cout << "Duplicate RNTI found, rejecting entry.\n";
            return;
