    return entry;
}

void destroy_entry(hash_entry_t* entry) {
    free(entry);
}

struct list* create_list(size_t initial_capacity) {
    struct list* list = (struct list*)malloc(sizeof(struct list));
    if (!list) return NULL;
    list->count = 0;
    list->capacity = initial_capacity;
    list->entries = calloc(initial_capacity, sizeof(hash_entry_t*));
    if (!list->entries) {
        free(list);
        return NULL;
    }
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void grow_list(struct list* list) {
    size_t new_capacity = list->capacity * 2;
    hash_entry_t** new_entries = realloc(list->entries, new_capacity * sizeof(hash_entry_t*));
    if (!new_entries) return; // Handle memory allocation failure gracefully
    list->entries = new_entries;
    list->capacity = new_capacity;
}

bool add_to_list(struct list* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) grow_list(list);

    uint16_t rnti = data->RNTI;
    size_t hash = rnti % list->capacity;
    for (hash_entry_t** entry = &list->entries[hash]; *entry != NULL; entry = &(*entry)->next) {
        if ((*entry)->data.RNTI == rnti) {
            pthread_mutex_unlock(&list->lock);
            free(data); // Return the data since it's a duplicate
            return false;
        }
    }

    hash_entry_t* new_entry = create_entry(data);
    if (!new_entry) {
        pthread_mutex_unlock(&list->lock);
        return false; // Handle memory allocation failure gracefully
    }

    *entry = new_entry;
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return true;
}

void cleanup(struct list* list) {
    pthread_mutex_lock(&list->lock);
    hash_entry_t** entry = list->entries;
    for (size_t i = 0; i < list->capacity; ++i, ++entry) {
        while (*entry) {
            hash_entry_t* next = (*entry)->next;
            destroy_entry(*entry);
            *entry = next;
        }
    }
    free(list->entries);
    free(list);
    pthread_mutex_unlock(&list->lock);
}
```

