    public static UserSession initializeSession(String configFile) {
        try (Reader reader = new FileReader(configFile)) {
            JsonReader jsonReader = Json.createReader(reader);
            JsonObject jsonConfig = jsonReader.readObject();

            JsonObject sessionObj = jsonConfig.getJsonObject("session");
            String sessionId = sessionObj.getString("id");
            long timeoutInMillis = jsonConfig.getInt("timeout") * 60 * 1000; // Convert seconds to milliseconds

            UserSession userSession = new UserSession(sessionId, Instant.now());
            userSession.setTimeout(timeoutInMillis);

            for (Map.Entry<String, JsonValue> entry : sessionObj.getJsonObject("parameters").entrySet()) {
                userSession.putParameter(entry.getKey(), entry.getValue().toString());
            }

            sessions.putIfAbsent(sessionId, userSession);

            handleActivities(userSession);

            return userSession;
        } catch (IOException | JsonReaderException e) {
            System.err.println("Error initializing session: " + e.getMessage());
            return null;
        }
    }

    private static void handleActivities(UserSession userSession) {
        // Implement the logic to store and manage activities, ensuring efficient resource management and correct handling of network failures.
        // ...

        if (userActivities.size() > MAX_ACTIVITIES) {
            userActivities.poll();
        }
        userActivities.add(new UserActivity(userSession));
    }

    public static void clearExpiredSessions() {
        Instant now = Instant.now();
        sessions.removeIf(session -> session.isExpired(now));
    }
}
