```javascript
const fs = require('fs-extra');
const path = require('path');
const { promisify } = require('util');

const readFile = promisify(fs.readFile);
const readdir = promisify(fs.readdir);
const stat = promisify(fs.stat);

async function processFiles(directoryPath, fileExtensions) {
    let processedContents = '';
    const successfulFiles = [];
    const failedFiles = [];

    try {
        // Check if the directory exists
        await fs.access(directoryPath);
    } catch (error) {
        return Promise.reject(`Directory does not exist: ${error}`);
    }

    const files = await readdir(directoryPath);

    for (const file of files) {
        const filePath = path.join(directoryPath, file);

        try {
            // Check if the file is a directory
            const stats = await stat(filePath);
            if (stats.isDirectory()) continue;
        } catch (error) {
            failedFiles.push(`File does not exist or is inaccessible: ${error}`);
            continue;
        }

        // Check file size and handle empty files
        try {
            const stats = await stat(filePath);
            if (stats.size === 0) {
                failedFiles.push(`File is empty: ${file}`);
                continue;
            }
        } catch (error) {
            failedFiles.push(`Unable to determine file size: ${error}`);
            continue;
        }

        // Check file type and handle unsupported extensions
        const ext = path.extname(filePath).toLowerCase();
        if (!fileExtensions.includes(ext)) {
            failedFiles.push(`Unsupported file type (expected: [${fileExtensions}], found: ${ext}): ${file}`);
            continue;
        }

        try {
            // Read the file and handle transient network failures
            let content;
            const retries = 3;
            for (let i = 0; i < retries; i++) {
                try {
                    content = await readFile(filePath, 'utf8');
                    break;
                } catch (error) {
                    if (i === retries - 1) {
                        failedFiles.push(`Failed to read file due to permanent error: ${error}`);
                        continue;
                    }
                }
            }

            // Process the content and update the result
            processedContents += content.toUpperCase();
            successfulFiles.push(file);
        } catch (error) {
            failedFiles.push(`Error processing file: ${error}`);
        }
    }

    return Promise.resolve({
        processedContents,
        successfulFiles
    });
}
```

This code handles the following edge cases:
- Directory does not exist.
- File does not exist or is inaccessible.
- File is empty.
- Unsupported file type.
- Metadata files are missing or contain invalid data (assuming no metadata files are used here)."]

