```java
public class RetryManager {
    private int maxRetries;
    private long backoff;

    public RetryManager(int maxRetries, long backoff) {
        this.maxRetries = maxRetries;
        this.backoff = backoff;
    }

    public void retry(Runnable task) {
        int retriesLeft = maxRetries;
        boolean success = false;

        while (!success && retriesLeft > 0) {
            try {
                task.run();
                success = true;
            } catch (Exception e) {
                System.out.println("Failed to execute the task, retrying in " + backoff + " milliseconds...");
                retriesLeft--;
                try {
                    Thread.sleep(backoff);
                } catch (InterruptedException ex) {}
            }
        }

        if (!success) {
            System.out.println("Maximum retries reached, giving up.");
        }
    }
}
```

