      this._profilePictureUrl = response.data.profilePictureUrl;
      this._lastLoginTimestamp = response.data.lastLoginTimestamp;

      // Cache data with dynamic TTL based on current load and system resource utilization
      cache.put(this.cacheKey(), { ...this }, MAX_AGE_MS);

      // Send notifications when user details change
      if (response.data.hasChanged) NotificationService.sendUpdate();
