    if (IS_ERR(root)) {
        // Error handling for invalid file formats or missing required fields
        goto cleanup;
    }

    *cfg = malloc(sizeof(struct Config));
    if (!*cfg) {
        // Error handling for memory allocation failure
        goto cleanup;
    }
    (*cfg)->root = root;

    ret = 0;
cleanup:
    if (fp) gzclose(fp);
    if (buf) free(buf);

    return ret;
}

