#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Transaction {
    double amount;
    char status;
    struct Transaction *next;
} Transaction;

struct DataSet {
    long offset;
    int size, capacity;
    Transaction **records;
};

DataSet* create_dataset() {
    DataSet* set = malloc(sizeof(DataSet));
    set->offset = 0;
    set->size = 0;
    set->capacity = 1000;
    set->records = calloc(set->capacity, sizeof(Transaction*));
    return set;
}

void append_transaction(DataSet *set, double amount, char status) {
    if (set->size == set->capacity) {
        set->capacity *= 2;
        set->records = realloc(set->records, sizeof(Transaction*) * set->capacity);
    }

    Transaction* transaction = malloc(sizeof(Transaction));
    transaction->amount = amount;
    transaction->status = status;
    transaction->next = NULL;

    set->records[set->offset] = transaction;
    set->offset++;
}

void deallocate_dataset(DataSet *set) {
    for (long i = 0; i < set->offset; ++i) {
        Transaction* transaction = set->records[i];
        free(transaction);
    }
    free(set->records);
    free(set);
}

Transaction* generate_transaction() {
    static long seed = time(NULL);
    static unsigned short status;
    double amount = (double)rand_r(&seed) / RAND_MAX * 10000.0 + 0.01;
    status = (unsigned short)(rand_r(&seed) < (RAND_MAX / 4));
    return malloc(sizeof(Transaction));
}

int main() {
    DataSet* set = create_dataset();

    srand(time(NULL));
    for (long i = 0; i < 10000; ++i) {
        Transaction* transaction = generate_transaction();
        append_transaction(set, transaction->amount, transaction->status);
        free(transaction);
    }

    // Do something with the dataset here...

    deallocate_dataset(set);

    return 0;
}
```

This code creates a dynamically-sized dataset structure `DataSet`, which holds an array of pointers to transaction records (`Transaction*`) and maintains information about its current size, capacity, and offset. Each transaction record has a double value for the amount, a char for the status, and a pointer to the next transaction in the list (if applicable).

The `create_dataset()` function initializes the DataSet structure with a small fixed-size buffer for transaction records. When adding transactions, we check if the current capacity has been exceeded, and if so, double the size of the capacity and reallocate memory.

The `append_transaction()` function adds a new transaction to the dataset by allocating space for the transaction structure and updating the appropriate offset and size variables. It also handles increasing the capacity when needed.

The `deallocate_dataset()` function frees all allocated memory associated with the dataset, including both transaction records and the DataSet structure itself.

Finally, the `main()` function creates a new dataset, generates 10,000 transactions, appends them to the dataset, performs any required data processing, deallocates the dataset, and terminates the program.']

