        struct RX_UE_INFORMATION_TAG rx_ue_information_tag;
        hash(&tag_counter, &rx_ue_information_tag.tag); // Use a hash function to generate unique tags
        tag_counter++;

        pdu->rnti = rnti;
        pdu->crc_indication = crc_indication;
        pdu->rx_ue_information_tag = rx_ue_information_tag;

        if (log_level >= DEBUG) {
            time_t current_time;
            struct tm *time_info;
            char time_buffer[80];

            time(&current_time);
            time_info = localtime(&current_time);
            strftime(time_buffer, sizeof(time_buffer), "%Y-%m-%d %H:%M:%S", time_info);

            printf("[%s] PDU created at 0x%p with RNTI=%llu, TAG=%u, CRCFLAG=%d\n", time_buffer, pdu, pdu->rnti.value, pdu->rx_ue_information_tag.tag, pdu->crc_indication.crcflag);
        }
    }

    FILE *output_file = fopen(output_path, "wb");
    if (!output_file) {
        perror("Failed to open output file");
        goto cleanup;
    }

    for (size_t i = 0; i < num_pdus; ++i) {
        size_t written = fwrite(pdus[i], sizeof(struct NFAPI_CRC_INDICATION_PDU_T), 1, output_file);
        if (written != 1) {
            perror("Failed to write PDU");
            goto cleanup;
        }
    }

cleanup:
    for (size_t i = 0; i < num_pdus; ++i) {
        if (pdus[i])
            return_pdu_to_pool(&pdu_pool, pdus[i]);
    }
    free(pdus);
    pthread_mutex_destroy(&pdu_pool.mutex);
}
```

