fun initializeDefaultThemeDirectory() {
    if (!Files.exists(Paths.get(THEME_CACHE_DIR))) {
        Files.createDirectories(Paths.get(THEME_CACHE_DIR))
    }
}

fun loadThemeFromCache(key: Int): Bitmap? {
    return themeCache[key]
