fun recycleUnusedThemes() {
    val currentTime = System.currentTimeMillis()
    themeCache.forEach { entry ->
        if (entry.value == null || (currentTime - entry.key) > THEME_CACHE_TIMEOUT ) {
            entry.value = null
        }
    }
}

