    executor = Executors.newSingleThreadExecutor()
    initializeDefaultThemeDirectory()
    executor.execute { loadThemesFromCache() }
}

private fun loadThemesFromCache() {
    val themeDir = Paths.get(THEME_CACHE_DIR)
    Files.walkFileTree(themeDir, object : FileVisitor<Path>(){
        override fun visitFileFailed(file: Path?, exc: IOException?): FileVisitResult {
            return FileVisitResult.CONTINUE
        }

        override fun postVisitDirectory(dir: Path?, exc: IOException?): FileVisitResult {
            if (!Files.isRegularFile(dir)) return FileVisitResult.CONTINUE

            val themeFile = dir.resolve(file.fileName)
            val theme = parseThemeFromFile(themeFile.toFile())
            if (theme != null) {
                themeCache.put(theme.hashCode(), theme)
            }
            return FileVisitResult.CONTINUE
        }

        override fun visitFile(file: Path, attrs: BasicFileAttributes?): FileVisitResult {
            return FileVisitResult.SKIP_SUBTREE
        }
    })
}
