        free(record_pool);
        record_pool = new_record_pool;
        record = &record_pool[record_used++];
    }
    pthread_mutex_unlock(&lock);
    return record;
}

void increment_key_refcount(Key *key) {
    if (key && key->offset) {
        key->offset->ref_count++;
    }
}

void decrement_key_refcount(Key *key) {
    if (key && key->offset) {
        if (--key->offset->ref_count == 0) {
            free(key->offset);
            key->offset = NULL;
            free(key);
            key = NULL;
        }
    }
}

