    MEMORY_POOL *pool = &ue_context_pool;
    void *ptr = NULL;

    pthread_mutex_lock(&pool->lock);
    if (pool->used < pool->size) {
        ptr = pool->pool + pool->used++;
    } else {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&pool->lock);

    return ptr;
}

