```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <cstdlib>
#include <ctime>

#include <boost/circular_buffer.hpp>

#pragma once
struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRCFLAG;
};

class DynamicList {
public:
    explicit DynamicList(size_t maxSize = 10000) : maxSize_(maxSize), cleanInterval_(30 * 60), nextClean_(std::chrono::system_clock::now()) {}

    void AddEntry(const NFAPI_CRC_INDICATION_PDU_T& entry);
    bool RemoveEntry(uint16_t rnti);
    const NFAPI_CRC_INDICATION_PDU_T* GetEntryByRNTI(uint16_t rnti) const;
    void UpdateEntryCRCFLAG(uint16_t rnti, bool newValue);

private:
    friend class ListUpdaterThread;

    std::mutex dataMutex_;
    std::unordered_map<uint16_t, NFAPI_CRC_INDICATION_PDU_T> data_;
    boost::circular_buffer<std::time_t> times_;
    size_t maxSize_;
    std::chrono::system_clock::time_point nextClean_;
    std::condition_variable cv_;
    std::atomic<bool> running_;

    class ListUpdaterThread {
    public:
        ListUpdaterThread(DynamicList& list);
        void operator()();

    private:
        DynamicList& list_;
    };
};

void DynamicList::AddEntry(const NFAPI_CRC_INDICATION_PDU_T& entry) {
    dataMutex_.lock();
    if (data_.size() >= maxSize_) {
        auto it = data_.begin();
        std::advance(it, static_cast<ptrdiff_t>(std::chrono::system_clock::now().time_since_epoch().count()) % data_.size());
        times_.pop_back();
        data_.erase(it);
    }
    data_[entry.RNTI] = entry;
    dataMutex_.unlock();
}

bool DynamicList::RemoveEntry(uint16_t rnti) {
    std::unique_lock<std::mutex> lock(dataMutex_);
    auto it = data_.find(rnti);
    if (it == data_.end()) return false;

    times_.push_back(std::time(nullptr));
    data_.erase(it);

    lock.unlock();
    cv_.notify_one();

    return true;
}

const NFAPI_CRC_INDICATION_PDU_T* DynamicList::GetEntryByRNTI(uint16_t rnti) const {
    auto it = data_.find(rnti);
    if (it != data_.end()) return &it->second;
    return nullptr;
}

void DynamicList::UpdateEntryCRCFLAG(uint16_t rnti, bool newValue) {
    dataMutex_.lock();
    auto it = data_.find(rnti);
    if (it == data_.end()) {
        std::cout << "Invalid RNTI" << std::endl;
        dataMutex_.unlock();
        return;
    }
    it->second.CRCFLAG = newValue;
    dataMutex_.unlock();
}
```

