// Configuration structure
typedef struct {
    size_t chunk_size; // Chunk size for memory pool
    int log_level;     // Logging level (0: error, 1: warning, 2: info)
    enum strategy { BEST_FIT, FIRST_FIT } allocation_strategy; // Allocation strategy
} config_t;

// External configuration module interface
config_t* get_config();
void free_config(config_t *cfg);

// CRC flag generation function
unsigned char generate_crcflag() {
    return (rand() % 2) ? 1 : 0;
}

// RX_UE_INFORMATION_TAG structure
typedef struct {
    unsigned short rnti; // RNTI
    unsigned short id;   // ID
} tag_t;

// CRC_INDICATION_REL8_TAG structure
typedef struct {
    unsigned char crcflag; // CRC flag
    unsigned short cic;     // CIC
} tag2_t;

// NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    tag_t rx_ue_information_tag;
    tag2_t crc_indication_rel8_tag;
} pdu_t;

// Memory pool cache for pdu_t structures
struct slab_cache {
    void *pool; // Pool of uninitialized memory blocks
    size_t block_size; // Size of each memory block
    size_t used;       // Number of currently allocated blocks
};

// Initialize and allocate a slab cache for pdu_t structures
void init_slab(struct slab_cache *cache, size_t chunk_size, size_t block_size) {
    cache->block_size = block_size;
    cache->used = 0;
    cache->pool = malloc(chunk_size * block_size);
    if (!cache->pool) {
        fprintf(stderr, "Failed to initialize slab cache\n");
        exit(EXIT_FAILURE);
    }
}

// Allocate a pdu_t structure from the slab cache
pdu_t* allocate_slab(struct slab_cache *cache) {
    if (cache->used >= cache->block_size) {
        fprintf(stderr, "Slab cache is full\n");
        exit(EXIT_FAILURE);
    }

    pdu_t *pdu = ((pdu_t*) cache->pool) + cache->used++;
    memset(pdu, 0, cache->block_size);
    return pdu;
}

// Function to dynamically allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
void* allocate_pdus(config_t *cfg) {
    struct slab_cache cache;
    size_t n = cfg->chunk_size, i;
    pdu_t **pdus;

    init_slab(&cache, sizeof(pdu_t) * n, sizeof(pdu_t));

    pdus = malloc(n * sizeof(pdu_t*));
    if (!pdus) {
        fprintf(stderr, "Failed to allocate memory for pdu pointers\n");
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < n; ++i) {
        pdus[i] = allocate_slab(&cache);
        if (!pdus[i]) {
            fprintf(stderr, "Failed to allocate memory for pdu structures\n");
            exit(EXIT_FAILURE);
        }
    }

    // Fill the array with valid RX_UE_INFORMATION_TAG and RNTI, and a randomly set CRC_INDICATION_REL8_TAG.
    for (i = 0; i < n; ++i) {
        pdus[i]->rx_ue_information_tag.rnti = rand() % UINT16_MAX;
        pdus[i]->rx_ue_information_tag.id = rand() % UINT16_MAX;
        pdus[i]->crc_indication_rel8_tag.cic = rand() % UINT16_MAX;
        pdus[i]->crc_indication_rel8_tag.crcflag = generate_crcflag();
    }

    // Logging mechanism to track allocation and failure events
    if (cfg->log_level >= 2) {
        printf("Successfully allocated and initialized %zu pdu structures\n", n);
    }

    return pdus;
}
