    char name[MAX_NAME_LENGTH];
    char ip[MAX_IP_LENGTH][INET6_ADDRSTRLEN];
    bool status;
    pthread_mutex_t lock;
} NICB;

typedef struct {
    char ip[INET6_ADDRSTRLEN];
    char domain[MAX_DOMAIN_LENGTH];
    time_t timestamp;
} DNSCache;

struct dns_cache_node {
    DNSCache cache;
    struct dns_cache_node *next;
};

struct dns_cache {
    struct dns_cache_node *head;
    int capacity;
    int size;
};

struct dns_service {
    void* handle;
    int (*resolve)(void*, const char*, char[]);
    void (*cleanup)(void*);
};

void init_nicb(NICB* nicb, uint32_t id, bool status) {
    nicb->id = id;
    nicb->status = status;
    memset(nicb->name, 0, sizeof(nicb->name));
    memset(nicb->ip, 0, sizeof(nicb->ip));
    pthread_mutex_init(&nicb->lock, NULL);
}

void add_ip(NICB* nicb, const char* ip) {
    bool unique = true;
    for (int i = 0; i < ARRAY_SIZE(nicb->ip); ++i) {
        if (!strcmp(nicb->ip[i], ip)) {
            unique = false;
            break;
        }
    }

    if (unique) {
        strcpy(nicb->ip[ARRAY_SIZE(nicb->ip) - 1], ip);
    }
}

DNSCache* find_in_cache(struct dns_cache* cache, const char* ip) {
    struct dns_cache_node* current = cache->head;
    while (current != NULL) {
        if (!strcmp(current->cache.ip, ip)) {
            return &current->cache;
        }
        current = current->next;
    }
    return NULL;
}

DNSCache* get_dns_result(struct dns_service* service, const char* ip) {
    DNSCache result;
    strcpy(result.ip, ip);

    if (service->resolve(service->handle, ip, result.domain)) {
        time_t current_time = time(NULL);
        if (current_time - result.timestamp < 600) { // Cache for up to 10 minutes
            return &result;
        }
    }

    DNSCache* cache_entry = find_in_cache(cache, ip);
    if (cache_entry != NULL && current_time - cache_entry->timestamp < 600) { // Use cached result if not expired
        return cache_entry;
    }

    // Make DNS call and populate the result.domain with the IP's domain name.
    service->resolve(service->handle, ip, result.domain);
    result.timestamp = current_time;

    struct dns_cache_node* new_entry = malloc(sizeof(struct dns_cache_node));
    if (new_entry == NULL) { // Handle memory allocation errors gracefully
        return &result;
    }

    memcpy(&new_entry->cache, &result, sizeof(DNSCache));
    new_entry->next = cache->head;
    cache->head = new_entry;
    if (cache->size >= cache->capacity) { // Efficiently manage cache to avoid excessive memory usage
        cache->capacity *= 2;
        struct dns_cache_node** current = &cache->head;
        while (*current != NULL && (current->next != NULL)) {
            struct dns_cache_node* next = current->next;
            if (current_time - current->cache.timestamp >= 600) { // Evict expired cache entries
                *current = next->next ? next->next : *current;
                free(next);
            } else {
                current = &next->next;
            }
        }
    }

    return &result;
}

void nicb_list_init(NICB** list, int capacity) {
    *list = malloc(capacity * sizeof(NICB));
    if (*list == NULL) { // Handle memory allocation errors gracefully
        fprintf(stderr, "Failed to allocate memory for NICB list\n");
        exit(1);
    }

    for (int i = 0; i < capacity; ++i) {
        init_nicb(*list + i, i, false);
    }
}

void nicb_add(NICB** list, uint32_t id, const char* name, bool status) {
    for (int i = 0; i < capacity; ++i) {
        if ((*list + i)->id == id) {
            pthread_mutex_lock(&((*list + i)->lock));
            strcpy((*list + i)->name, name);
            (*list + i)->status = status;
            pthread_mutex_unlock(&((*list + i)->lock));
            return;
        }
    }
}

void nicb_ip_add(NICB** list, uint32_t id, const char* ip) {
    for (int i = 0; i < capacity; ++i) {
        if ((*list + i)->id == id) {
            pthread_mutex_lock(&((*list + i)->lock));
            add_ip(*list + i, ip);
            pthread_mutex_unlock(&((*list + i)->lock));
            return;
        }
    }
}

void nicb_dns(NICB** list, uint32_t id, const char* ip) {
    for (int i = 0; i < capacity; ++i) {
        if ((*list + i)->id == id) {
            pthread_mutex_lock(&((*list + i)->lock);
            DNSCache* dns_result = get_dns_result(&nicb_dns_service, ip);
            strcpy((*list + i)->name, dns_result->domain);
            pthread_mutex_unlock(&((*list + i)->lock));
            return;
        }
    }
}
