// Validate IP address and return a validated in_addr structure or NULL on failure
struct in_addr validate_ip(const char* ip_str) {
    struct in_addr ip;
    if (inet_pton(AF_INET, ip_str, &ip) <= 0) {
        return NULL;
    }
    return ip;
}

// Function to initialize and populate the doubly-linked list with NICB structures
void init_nicb_list(NICB** head, uint32_t num_nicbs, void (*error_callback)(const char* msg)) {
    pthread_mutexattr_t attr;
    NICB *current = NULL, *new_node;

    // Initialize mutex attributes for thread safety
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);

    for (uint32_t i = 0; i < num_nicbs; ++i) {
        // Allocate memory for new NICB node
        new_node = malloc(sizeof(NICB));
        if (!new_node) {
            perror("Memory allocation failed");
            error_callback("Memory allocation failure");
            continue;
        }

        // Initialize NICB node and its mutex
        memset(new_node, 0, sizeof(NICB));
        pthread_mutex_init(&new_node->mutex, &attr);

        // Set network interface ID and configure IP validation function
        new_node->id = i;
        new_node->validate_ip = validate_ip;

        // Populate with valid IP addresses (assuming IP addresses are provided)
        // ...

        // Add the new NICB node to the list, ensuring thread safety
        pthread_mutex_lock(&current->mutex);
        if (!current) {
            current = new_node;
            current->prev = current->next = NULL;
        } else {
            current->next = new_node;
            new_node->prev = current;
            current = new_node;
        }
        pthread_mutex_unlock(&current->mutex);
    }

    // Set the head of the doubly-linked list
    *head = current;
}

