static int retry_delay = 100000; // in microseconds

void *my_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        pthread_mutex_lock(&mutex);
        num_attempts--;
        pthread_mutex_unlock(&mutex);
        if (num_attempts == 0) {
            fprintf(stderr, "Out of memory! Failed after %d attempts.\n", num_attempts);
            exit(1);
        }
        usleep(retry_delay);
    }
    return ptr;
}

void initialize_crc_indications(NFAPI_CRC_INDICATION_PDU_T** array, size_t capacity) {
