    size_t payload_len = g_byte_array_get_size(pdu->payload);
    g_serial_tee_write(serializer, &payload_len, sizeof(payload_len));
    g_serial_tee_write(serializer, g_byte_array_freeze_to_data(pdu->payload, NULL), payload_len);
}

void dynamic_list_deserialize(DynamicList* list, GFile* file) {
    if (!g_file_open(file, 0, 0644, NULL)) {
        printf("Failed to open file for reading: %s\n", g_strerror(g_file_error_from_errno(g_io_error_from_info(g_file_get_error(file)))));
        return;
    }
    GSerialTee deserializer = { 0 };
    g_serial_tee_init(&deserializer, NULL, file, NULL);
    while (TRUE) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(NFAPI_CRC_INDICATION_PDU_T_SIZE);
        RX_UE_INFORMATION_TAG tag;
        size_t payload_len;
        gsize len = sizeof(tag) + 16 + sizeof(CRC_INDICATION_REL8_TAG) + sizeof(payload_len);
        if (g_serial_tee_read(&deserializer, &tag, len) != len || tag >= get_dynamic_quark()) {
            break;
        }
        g_serial_tee_read(&deserializer, pdu->rnti, 16);
        g_serial_tee_read(&deserializer, &pdu->crc_indication_rel8_tag, sizeof(CRC_INDICATION_REL8_TAG));
        g_serial_tee_read(&deserializer, &payload_len, sizeof(payload_len));
        if (payload_len > 0) {
            pdu->payload = g_byte_array_new();
            g_byte_array_set_size(pdu->payload, payload_len);
            g_serial_tee_read(&deserializer, g_byte_array_get_data(pdu->payload), payload_len);
        }
        dynamic_list_add(list, pdu);
    }
    g_object_unref(file);
}
