ProcessedNumber *read_numbers(const char *filename, size_t *count) {
    int fd = open(filename, O_RDONLY | O_BINARY);
    if (fd == -1) {
        log_error("Failed to open file");
        return NULL;
    }

    struct stat st;
    fstat(fd, &st);
    size_t file_size = st.st_size;
    char *map = mmap(NULL, file_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (map == MAP_FAILED) {
        log_error("Failed to map memory");
        close(fd);
        return NULL;
    }

    size_t current_pos = 0;
    size_t processed_count = 0;
    ProcessedNumber *processed_numbers = malloc(file_size / (sizeof(ProcessedNumber) + sizeof(uintmax_t)));
    if (!processed_numbers) {
        log_error("Failed to allocate memory for processed numbers");
        munmap(map, file_size);
        close(fd);
        return NULL;
    }

    while (current_pos < file_size) {
        size_t number_length = 0;
        char *number = memchr(map + current_pos, '\n', file_size - current_pos);
        if (!number) {
            number = memchr(map + current_pos, 0, file_size - current_pos);
            if (!number) break; // Reached EOF without finding a newline or null character
        }
        number_length = (uintptr_t)number - (uintptr_t)(map + current_pos);

        if (is_valid_number(map + current_pos, number_length)) {
            ProcessedNumber *pn = processed_numbers + processed_count++;
            pn->type = is_integer(map + current_pos, number_length) ? 0 : 1;
            pn->value = strtoumax(map + current_pos, NULL, 10);
        }

        current_pos += number_length + 1; // Advance by newline or null character
    }

    if (close(fd) == -1) {
        log_error("Failed to close file");
    }

    *count = processed_count;
    return processed_numbers;
}

int main() {
    const char *filename = "input.txt";
    size_t count;
    ProcessedNumber *processed_numbers = read_numbers(filename, &count);
    if (!processed_numbers) return 1;

    // Process the numbers and find maximums here
    int64_t max_int = -9223372036854775807;
    double max_float = -DBL_MAX;
    for (size_t i = 0; i < count; ++i) {
        if (processed_numbers[i].type == 0) {
            max_int = fmax(max_int, processed_numbers[i].value);
        } else {
            max_float = fmax(max_float, processed_numbers[i].value);
        }
    }

    printf("Maximum absolute integer: %" PRId64 "\n", max_int);
    printf("Maximum absolute floating-point number: %.17g\n", max_float);

    free(processed_numbers);
    return 0;
}
