LTEPHYCONTEXT_LIST* init_ltephycontext_list(unsigned int initial_capacity) {
    LTEPHYCONTEXT_LIST *list = mmap(NULL, sizeof(LTEPHYCONTEXT_LIST), MMAP_PROT_PRIVATE, MAP_ANONYMOUS | MAP_SHARED, -1, 0);
    if (list == MAP_FAILED) {
        perror("mmap failed");
        return NULL;
    }

    pthread_mutex_init(&((LTEPHYCONTEXT_LIST*) list)->mutex, NULL);
    ((LTEPHYCONTEXT_LIST*) list)->capacity = initial_capacity;
    ((LTEPHYCONTEXT_LIST*) list)->size = 0;
    ((LTEPHYCONTEXT_LIST*) list)->head = NULL;

    return list;
}

void destroy_ltephycontext_list(LTEPHYCONTEXT_LIST *list) {
    pthread_mutex_destroy(&list->mutex);
    munmap(list, sizeof(LTEPHYCONTEXT_LIST));
}

LTEPHYCONTEXT_NODE* create_ltephycontext_node() {
    LTEPHYCONTEXT_NODE *node = malloc(sizeof(LTEPHYCONTEXT_NODE));
    if (!node) {
        perror("malloc failed");
        return NULL;
    }

    node->next = NULL;
    return node;
}

void free_ltephycontext_node(LTEPHYCONTEXT_NODE *node) {
    if (node) {
        free(node);
    }
}

LTEPHYCONTEXT_NODE* append_ltephycontext(LTEPHYCONTEXT_LIST *list, const void *srs_config, const float *metrics) {
    pthread_mutex_lock(&list->mutex);

    LTEPHYCONTEXT_NODE *new_node = create_ltephycontext_node();
    if (!new_node) {
        perror("Out of memory during append.");
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }

    memcpy(new_node->srs_config, srs_config, sizeof(srs_config));
    memcpy(new_node->measurement_metrics, metrics, sizeof(metrics));

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        LTEPHYCONTEXT_NODE *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    list->size++;
    if (list->size >= list->capacity && list->capacity > 0) {
        list->capacity *= 2;
    }

    pthread_mutex_unlock(&list->mutex);
    return new_node;
}

void log_ltephycontext_init(const char *message, LTEPHYCONTEXT_LIST *list) {
    if (log_level >= LOG_DEBUG) {
        printf("%s: initialized LTEPH context list with capacity %u, size %u\n", message, list->capacity, list->size);
    }
}

void log_ltephycontext_append(const char *message, const void *srs_config, const float *metrics) {
    if (log_level >= LOG_DEBUG) {
        printf("%s: appended LTEPH context with config %p, metrics %p\n", message, srs_config, metrics);
    }
}
```

