typedef struct MemPool {
    void** pool;
    size_t capacity;
    size_t count;
} MemPool;

void initMemPool(MemPool* mp, size_t capacity) {
    // Initialize the memory pool with 'capacity' elements
    mp->pool = mmap(NULL, capacity * sizeof(void*), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mp->pool == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    mp->capacity = capacity;
    mp->count = 0;
}

void* getFromMemPool(MemPool* mp) {
    if (mp->count >= mp->capacity) return NULL;
    void* result = mp->pool[mp->count];
    mp->count++;
    return result;
}

void putBackToMemPool(MemPool* mp, void* data) {
    if (mp->count == 0) return;
    mp->pool[--mp->count] = data;
}

