#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>

#define MAX_PAYLOAD_SIZE 1024 // Maximum payload size constraint
#define NUM_PACKETS 1000 // Number of packets to be initialized and populated

struct DataPacket {
    int id;
    struct timeval timestamp;
    unsigned short payload_len;
    char payload[MAX_PAYLOAD_SIZE];
};

// External synchronized time source function
extern void get_synchronized_time(struct timeval *tv);

// Synchronization mechanism for handling high-throughput scenarios
pthread_mutex_t packets_mutex = PTHREAD_MUTEX_INITIALIZER;
sem_t buffer_semaphore = SEM_INITIALIZE(NUM_PACKETS); // Semaphore to limit concurrent access to the buffer

void init_packets() {
    struct DataPacket packets[NUM_PACKETS];
    gettimeofday(&(packets[0].timestamp), NULL); // Initialize timestamp for first packet

    int id = 1; // Unique packet identifier starting from 1

    for (int i = 1; i < NUM_PACKETS; ++i) {
        get_synchronized_time(&(packets[i].timestamp)); // Synchronize timestamp for subsequent packets

        packets[i].id = id++;
        packets[i].payload_len = rand() % MAX_PAYLOAD_SIZE + 1; // Generate random payload length within the constraints

        // Truncate payload if it exceeds the maximum size
        if (packets[i].payload_len > MAX_PAYLOAD_SIZE) {
            packets[i].payload_len = MAX_PAYLOAD_SIZE;
        }

        // Fill payload with random data
        for (int j = 0; j < packets[i].payload_len; ++j) {
            packets[i].payload[j] = rand() % 256;
        }
    }

    // Populate the array with the initialized packets while ensuring data integrity and resource usage efficiency
    pthread_mutex_lock(&packets_mutex);
    sem_wait(&buffer_semaphore);

    for (int i = 0; i < NUM_PACKETS; ++i) {
        // Validate payload length to prevent buffer overflow and truncate if necessary
        if (packets[i].payload_len > MAX_PAYLOAD_SIZE) {
            packets[i].payload_len = MAX_PAYLOAD_SIZE;
        }

        // Write the packet to a buffer for further processing or network transmission
        // ...

        // Release the semaphore to allow concurrent access to the buffer
        sem_post(&buffer_semaphore);
    }

    pthread_mutex_unlock(&packets_mutex);
}
```

