    queue->length = 0;
    memset(queue->data, 0, initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&queue->queue_lock, NULL);
}

void enqueue(NIC_QUEUE_T *queue, NFAPI_CRC_INDICATION_PDU_T data) {
