    if (queue->length == 0) return (NFAPI_CRC_INDICATION_PDU_T){};

    pthread_mutex_lock(&queue->queue_lock);

    NFAPI_CRC_INDICATION_PDU_T data = queue->data[0];
    memmove(queue->data, queue->data + 1, (queue->length - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    queue->length--;
    pthread_mutex_unlock(&queue->queue_lock);

    return data;
}

void prune_inactive(NIC_QUEUE_T* queue, time_t timeout) {
