            memmove(queue->data + i, queue->data + i + 1, (queue->length - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
    }
    queue->length--;

    pthread_mutex_unlock(&queue->queue_lock);
