struct nfapi_crc_indication_pdu {
    time_t timestamp;
    RX_UE_INFORMATION_TAG rxtag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcflag;
};

typedef struct nfapi_crc_indication_pdu_manager {
    struct nfapi_crc_indication_pdu *data;
    size_t capacity;
    size_t count;
    time_t timeout_threshold;
    sem_t mutex;
    sem_t log_mutex;
} manager_t;

manager_t *init_manager(size_t capacity, const char *env_name) {
    manager_t *manager = malloc(sizeof(manager_t));
    if (!manager) {
        syslog(LOG_ERR, "Failed to allocate memory for manager");
        return NULL;
    }

    manager->data = calloc(capacity, sizeof(struct nfapi_crc_indication_pdu));
    if (!manager->data) {
        free(manager);
        syslog(LOG_ERR, "Failed to allocate memory for data array");
        return NULL;
    }

    manager->capacity = capacity;
    manager->count = 0;
    manager->timeout_threshold = atoi(getenv(env_name)) * 60; // Convert timeout threshold from seconds to time_t units

    sem_init(&manager->mutex, 0, 1);
    sem_init(&manager->log_mutex, 0, 1);

    return manager;
}

void log_event(const char *message) {
    if (sem_trywait(&manager->log_mutex) == 0) {
        openlog("nfapi-crc-indicator", LOG_PID | LOG_PERROR, LOG_DEBUG);
        syslog(LOG_INFO, "%s", message);
        closelog();
        sem_post(&manager->log_mutex);
    }
}

void add_entry(manager_t *manager, const struct nfapi_crc_indication_pdu *entry) {
    if (sem_trywait(&manager->mutex) == 0) {
        if (manager->count >= manager->capacity) {
            log_event("Reached capacity limit, discarding entry");
        } else {
            memcpy(&manager->data[manager->count], entry, sizeof(struct nfapi_crc_indication_pdu));
            manager->count++;
            log_event("Added entry successfully");
        }
        sem_post(&manager->mutex);
    }
}

void prune_inactive(manager_t *manager) {
    if (sem_trywait(&manager->mutex) == 0) {
        time_t current = time(NULL);
        size_t i;
        for (i = 0; i < manager->count; ++i) {
            if (current - manager->data[i].timestamp > manager->timeout_threshold) {
                manager->count--;
                memmove(&manager->data[i], &manager->data[i + 1], (manager->count - i) * sizeof(struct nfapi_crc_indication_pdu));
                log_event("Pruned inactive entry");
            }
        }
        sem_post(&manager->mutex);
    }
}

void cleanup(manager_t *manager) {
    if (manager->data) free(manager->data);
    free(manager);
}
