#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_POOL_SIZE 1000
#define RNTI_SIZE sizeof(RX_UE_INFORMATION_TAG) + sizeof(RNTI) + sizeof(CRC_INDICATION_REL8_TAG)

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    int crcflag;
    struct Node *next;
} NFAPI_CRC_INDICATION_PDU_T;

struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
};

void log_error(const char *message) {
    // Implement your logging mechanism here.
}

struct Node* create_node(NFAPI_CRC_INDICATION_PDU_T *data) {
    struct Node *new_node = (struct Node*) malloc(sizeof(struct Node));
    if (!new_node) {
        log_error("Out of memory");
        return NULL;
    }
    memcpy(&new_node->data, data, RNTI_SIZE);
    new_node->next = NULL;
    return new_node;
}

struct Node** create_pool(size_t size) {
    struct Node **pool = (struct Node**) malloc(size * sizeof(struct Node*));
    if (!pool) {
        log_error("Out of memory");
        return NULL;
    }
    for (size_t i = 0; i < size; ++i) {
        pool[i] = NULL;
    }
    return pool;
}

void free_pool(struct Node **pool, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (pool[i]) {
            struct Node *temp = pool[i];
            pool[i] = NULL;
            free(temp);
        }
    }
    free(pool);
}

struct Node* get_node_from_pool(struct Node** pool) {
    for (size_t i = 0; i < MAX_POOL_SIZE; ++i) {
        if (!pool[i]) {
            pool[i] = create_node(&pool[i % MAX_POOL_SIZE]->data);
            return pool[i];
        }
    }
    log_error("Pool overflow");
    return NULL;
}

void update_list(NFAPI_CRC_INDICATION_PDU_T *new_data, struct Node **head) {
    if (get_rnti(new_data) == get_rnti(*head->next)) {
        log_error("Duplicate RNTI detected");
        return;
    }

    struct Node* new_node = get_node_from_pool(pool);
    if (!new_node) {
        log_error("Failed to obtain a node from the pool");
        return;
    }

    memcpy(&new_node->data, new_data, RNTI_SIZE);
    new_node->next = *head->next;
    *head->next = new_node;
}

void init_list(struct Node **head) {
    *head = (struct Node*) malloc(sizeof(struct Node));
    if (!*head) {
        log_error("Out of memory");
        return;
    }
    (*head)->next = NULL;
}

void free_list(struct Node **head) {
    struct Node *current = *head->next, *temp;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }
    free(*head);
}
```

