void validate(long offset, long valid_range_start, long valid_range_end) {
    if (offset < valid_range_start || offset >= valid_range_end) {
        fprintf(stderr, "Invalid offset: %ld\n", offset);
        exit(1);
    }
}

void* fetch_dependency(ExternalDependency* dep) {
    CURL *curl;
    CURLcode res;

    curl = curl_easy_init();
    if(!curl) {
        fprintf(stderr, "Error initializing cURL\n");
        exit(1);
    }

    curl_easy_setopt(curl, CURLOPT_URL, dep->url);
    res = curl_easy_perform(curl);

    if(res != CURLE_OK) {
        fprintf(stderr, "Error fetching dependency URL: %s\n", dep->url);
        exit(1);
    }

    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &dep->status_code);
    curl_easy_cleanup(curl);
}

void check_dependencies() {
    pthread_t thread_id[num_dependencies];

    for (size_t i = 0; i < num_dependencies; ++i) {
        pthread_create(&thread_id[i], NULL, fetch_dependency, &(dependencies[i]));
    }

    for (size_t i = 0; i < num_dependencies; ++i) {
        pthread_join(thread_id[i], NULL);
    }
}

