    if(!file) {
        fprintf(stderr, "Error opening input file\n");
        exit(1);
    }

    while((read = getline(&line, &len, file)) != -1) {
        char* token = strtok(line, ",");

        if(!token || in_record) {
            continue;
        }

        key = atoi(token);

        offset = num_records;

        // Check valid range for offset
        validate(offset, 0, 10000000 - 1);

        Record* record = &records[num_records++];

        token = strtok(NULL, ",");
        record->key = key;
        record->offset = offset;
        record->value = rand() % 100 + 1; // Random value within [1, 100] range

        in_record = true;
    }

    fclose(file);
}

void exec_command(const char* command) {
    pid_t pid;
    int status;
    FILE *fp;

    pid = fork();

    if (pid < 0) {
        fprintf(stderr, "Error forking child process\n");
        exit(1);
    } else if (pid == 0) {
        fp = popen(command, "r");

        char buffer[256];
        while (fgets(buffer, sizeof(buffer), fp)) {
            fputs(buffer, stdout);
        }

        pclose(fp);
        exit(0);
    } else {
        waitpid(pid, &status, 0);
    }
}

