#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>

#define MAX_RECORDS 1000000
#define ALIGNMENT 64

typedef struct Record {
    int key;
    long offset;
} Record;

typedef struct Slab {
    void* data;
    size_t used;
    size_t capacity;
} Slab;

Slab slabs[MAX_RECORDS / ALIGNMENT + 1]; // Slabs for efficient memory management
pthread_mutex_t slabs_mutex = PTHREAD_MUTEX_INITIALIZER; // For synchronization during reclamation

Record* get_record(void) {
    for (size_t i = 0; i < sizeof(slabs) / sizeof(Slab); ++i) {
        if (slabs[i].used < slabs[i].capacity) {
            size_t index = slabs[i].used++;
            return (Record*)((char*)slabs[i].data + index * sizeof(Record));
        }
    }

    // Allocate a new slab when all current ones are full
    Slab* new_slab = (Slab*)mmap(0, sizeof(Record) * ALIGNMENT, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!new_slab) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    new_slab->data = (void*)(((long)new_slab & ~(ALIGNMENT - 1)) + ALIGNMENT); // Ensure alignment for optimal cache usage
    new_slab->used = 0;
    new_slab->capacity = ALIGNMENT;

    pthread_mutex_lock(&slabs_mutex);
    int index = sizeof(slabs) / sizeof(Slab);
    slabs[index] = *new_slab;
    pthread_mutex_unlock(&slabs_mutex);

    return (Record*)((char*)new_slab->data + new_slab->used++ * sizeof(Record));
}

void free_record(Record* record) {
    pthread_mutex_lock(&slabs_mutex);
    for (size_t i = 0; i < sizeof(slabs) / sizeof(Slab); ++i) {
        if ((char*)record - sizeof(Record) >= (char*)slabs[i].data &&
            (char*)record - sizeof(Record) <= (char*)slabs[i].data + slabs[i].capacity * sizeof(Record)) {
            slabs[i].used--;
            break;
        }
    }
    pthread_mutex_unlock(&slabs_mutex);
}

// Implement your system-specific concurrent access management and processing logic here.
```

