static pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t queue_cond = PTHREAD_COND_INITIALIZER;

LTE_PHY_RX_TARGET* init_targets(size_t num_targets) {
    LTE_PHY_RX_TARGET *current, *new_target;
    Request *request;
    pthread_t thread_id;

    for (int i = 0; i < num_targets; ++i) {
        new_target = malloc(sizeof(LTE_PHY_RX_TARGET));
        if (!new_target) continue;

        new_target->rb.some_field = SOME_INITIAL_VALUE;
        new_target->time_instance.some_field = SOME_INITIAL_VALUE;
        new_target->num_subframes = random() % 100 + 1;
        new_target->subframe_info = malloc(new_target->num_subframes * sizeof(LTE_RX_SUBFRAME_INFO));
        if (!new_target->subframe_info) {
            free(new_target);
            continue;
        }

        new_target->next = head;
        head = new_target;

        request = malloc(sizeof(Request));
        if (!request) continue;
        request->target = new_target;
        request->completed = false;
        request->next = NULL;

        pthread_create(&thread_id, NULL, process_request, (void*)request);
    }

    return head;
}

void* process_request(void *arg) {
    Request *request = arg;
    LTE_PHY_RX_TARGET *target = request->target;

    pthread_mutex_lock(&queue_lock);
    request->completed = true;
    if (request_queue == NULL || request->next == NULL) {
        request_queue = request;
    } else {
        Request *current = request_queue;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = request;
    }
    pthread_mutex_unlock(&queue_lock);
    pthread_cond_signal(&queue_cond);

    // Process the target here, handling external data source and logging
    // ...

    free(request);
    return NULL;
}

void handle_requests() {
    Request *current, *next;
    int num_processed = 0;

    while (true) {
        pthread_mutex_lock(&queue_lock);
        while (num_processed < MAX_REQUESTS && request_queue == NULL || request_queue->completed) {
            pthread_cond_wait(&queue_cond, &queue_lock);
        }

        if (num_processed >= MAX_REQUESTS) break;

        current = request_queue;
        request_queue = request_queue->next;
        num_processed++;
        pthread_mutex_unlock(&queue_lock);
    }
}
