void reset_testing_environment(entry* entries, int num_entries) {
    for (int i = 0; i < num_entries; ++i) {
        entries[i].value = 0.0;
        if (entries[i].function) {
            void (*cleanup)(void) = dlsym(entries[i].function, "__dl_fini");
            cleanup();
            entries[i].function = NULL;
        }
    }
