void test_module(const char* moduleLabel, int* keyArray, const struct { double min, max; } valueRange, void (*testFunction)(void*, const char*, int, double*), entry* entries, int num_entries) {
    void* handle = dlopen(moduleLabel, RTLD_NOW | RTLD_LOCAL);
    if (!handle) {
        fprintf(stderr, "Error: Unable to load module %s\n", moduleLabel);
        return;
    }

    reset_testing_environment(entries, num_entries);

    void* function = dlsym(handle, "initialize");
    if (function) {
        (*function)();
    }

    for (int i = 0; i < num_entries; ++i) {
        entries[i].value = valueRange.min + rand() / (RAND_MAX / (valueRange.max - valueRange.min)) + 0.5;
        entries[i].function = dlsym(handle, keyArray[i] == -1 ? "test" : charArray[keyArray[i]]);
    }

    for (int i = 0; i < num_entries; ++i) {
        printf("Testing module %s: test case %d\n", moduleLabel, i);
        (*testFunction)(entries[i].function, moduleLabel, keyArray[i], entries[i].value);
    }

    void (*cleanup)(void) = dlsym(handle, "__dl_fini");
    cleanup();
    dlclose(handle);
}
