    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crcIndicator;
    bool crcFlag;
};

class DynamicCRCArray {
private:
    std::unordered_map<uint32_t, std::shared_ptr<NFAPI_CRC_INDICATION_PDU_T>> data;
    mutex mtx;
    function<void(const uint32_t&, const CRC_INDICATION_REL8_TAG&)> updateCallback;

public:
    void setUpdateCallback(function<void(const uint32_t&, const CRC_INDICATION_REL8_TAG&)> cb) {
        updateCallback = cb;
    }

    auto find(const uint32_t& rnti) {
        std::shared_ptr<NFAPI_CRC_INDICATION_PDU_T> ret;
        unique_lock<mutex> lock(mtx);
        if (auto iter = data.find(rnti); iter != data.end()) {
            ret = iter->second;
        }
        return ret;
    }

    void addOrUpdate(const uint32_t& rnti, const RX_UE_INFORMATION_TAG& rxTag, const CRC_INDICATION_REL8_TAG& crcIndicator) {
        unique_lock<mutex> lock(mtx);
        if (auto iter = data.find(rnti); iter == data.end()) {
            auto newElement = make_shared<NFAPI_CRC_INDICATION_PDU_T>();
            newElement->rnti = rnti;
            newElement->rxTag = rxTag;
            newElement->crcIndicator = crcIndicator;
            newElement->crcFlag = (bool)(std::rand() % 2);
            data[rnti] = newElement;
        } else {
            iter->second->crcIndicator = crcIndicator;
        }
        if(updateCallback) {
            updateCallback(rnti, crcIndicator);
        }
    }

    void remove(const uint32_t& rnti) {
        unique_lock<mutex> lock(mtx);
        data.erase(rnti);
    }
};
