['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int key;
    long offset;
} Record;

struct MemoryPool {
    Record* data;
    size_t capacity;
    size_t used;
    size_t max_size;
    size_t resizes;
    size_t initializations;
    double avg_time;
    pthread_mutex_t mutex;
};

struct MemoryPool* create_memory_pool(size_t initial_capacity, size_t max_size, double growth_factor) {
    struct MemoryPool *pool = malloc(sizeof(struct MemoryPool));
    pool->data = malloc(initial_capacity * sizeof(Record));
    pool->capacity = initial_capacity;
    pool->used = 0;
    pool->max_size = max_size;
    pool->resizes = 0;
    pool->initializations = 1;
    pool->avg_time = 0.0;
    pool->mutex = PTHREAD_MUTEX_INITIALIZER;

    return pool;
}

void push(struct MemoryPool *pool, const Record *record) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->used >= pool->capacity) {
        size_t new_capacity = pool->capacity * growth_factor;
        if (new_capacity > pool->max_size) {
            fprintf(stderr, "Error: Maximum array size exceeded.\n");
            pthread_mutex_unlock(&pool->mutex);
            return;
        }

        Record* temp = realloc(pool->data, new_capacity * sizeof(Record));
        if (!temp) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            pthread_mutex_unlock(&pool->mutex);
            return;
        }

        pool->data = temp;
        pool->capacity = new_capacity;
        pool->resizes++;
    }

    pool->data[pool->used] = *record;
    pool->used++;

    clock_t start = clock();
    if (pool->avg_time == 0.0) {
        pool->avg_time = (double)(CLOCKS_PER_SEC / pool->initializations);
    }
    pool->avg_time += (clock() - start) / ((double)pool->initializations);

    pthread_mutex_unlock(&pool->mutex);
}

void destroy_memory_pool(struct MemoryPool *pool) {
    free(pool->data);
    free(pool);
}
```

