#include <stdbool.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct union_find {
    int parent;
    int rank;
} UF;

UF* make_set(int n) {
    UF* set = malloc(n * sizeof(UF));
    for (int i = 0; i < n; i++) {
        set[i].parent = i;
        set[i].rank = 0;
    }
    return set;
}

int find_set(UF* uf, int x) {
    if (uf[x].parent != x)
        uf[x].parent = find_set(uf, uf[x].parent);
    return uf[x].parent;
}

void union_sets(UF* uf, int x, int y) {
    int rootx = find_set(uf, x);
    int rooty = find_set(uf, y);

    if (rootx == rooty) return;

    if (uf[rootx].rank < uf[rooty].rank) {
        uf[rootx].parent = rooty;
        uf[rooty].rank += 1;
    } else if (uf[rootx].rank > uf[rooty].rank) {
        uf[rooty].parent = rootx;
        uf[rootx].rank += 1;
    } else {
        uf[rootx].parent = rooty;
        uf[rooty].rank += 1;
    }
}
