#include <pthread.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    LTE_TARGET_RB rb;
    LTE_TARGET_TIME_INSTANCE time_instance;
    uint16_t subframe_info_len;
    uint8_t subframe_info[MAX_SUBFRAME_INFO_LENGTH];
} LTE_PHY_RX_TARGET;

struct slab {
    size_t used;
    size_t total;
    LTE_PHY_RX_TARGET *slab;
    struct slab *next;
};

struct slab_pool {
    struct slab *head;
    pthread_mutex_t lock;
};

void lte_phy_rx_target_init(struct slab_pool *pool, size_t initial_size) {
    pool->head = malloc(initial_size * sizeof(LTE_PHY_RX_TARGET));
    if (!pool->head) return;
    pool->head->total = initial_size;
    pool->head->used = 0;
    pool->head->next = NULL;

    pthread_mutex_init(&pool->lock, NULL);
}

LTE_PHY_RX_TARGET *lte_phy_rx_target_alloc(struct slab_pool *pool) {
    struct slab *current = pool->head;
    pthread_mutex_lock(&pool->lock);
    if (current->used < current->total) {
        LTE_PHY_RX_TARGET *target = &(current->slab[current->used]);
        current->used++;
        pthread_mutex_unlock(&pool->lock);
        return target;
    }
    pthread_mutex_unlock(&pool->lock);

    struct slab *new_slab = malloc(SLAB_SIZE * sizeof(LTE_PHY_RX_TARGET));
    if (!new_slab) return NULL;
    new_slab->total = SLAB_SIZE;
    new_slab->used = 0;
    new_slab->next = pool->head;
    pool->head = new_slab;

    LTE_PHY_RX_TARGET *target = &(pool->head->slab[pool->head->used - 1]);
    return target;
}

void lte_phy_rx_target_free(LTE_PHY_RX_TARGET *target) {
    pthread_mutex_lock(&(target->pool->lock));
    target->pool->slab[--(target->pool->used)] = *target;
    pthread_mutex_unlock(&(target->pool->lock));
}

void lte_phy_rx_target_cleanup(struct slab_pool *pool) {
    struct slab *current = pool->head, *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    pool->head = NULL;
    pthread_mutex_destroy(&pool->lock);
}

void lte_phy_rx_target_randomize(LTE_PHY_RX_TARGET *target, uint16_t max_subframe_info_len) {
    target->subframe_info_len = rand() % (MAX_SUBFRAME_INFO_LENGTH - max_subframe_info_len + 1) + max_subframe_info_len;
}
