    pthread_mutex_init(&nic->mutex, NULL);
}

void* get_available_port() {
    static int next_port = 0;
    int port = next_port++;
    if (port <= 1024) return NULL;
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    if (getsockname(socket(AF_INET, SOCK_STREAM, IPPROTO_TCP), (struct sockaddr*)&addr, NULL) == -1) {
        return NULL;
    }
    return &port;
}

void add_port(NicConfig* nic, int port) {
    pthread_mutex_lock(&nic->mutex);
    for (int i = 0; nic->ports[i] != -1; ++i) {} // Find the first empty port index
    nic->ports[i] = port;
    pthread_mutex_unlock(&nic->mutex);
}

void delete_port(NicConfig* nic, int port) {
    pthread_mutex_lock(&nic->mutex);
    for (int i = 0; nic->ports[i] != -1; ++i) {
        if (nic->ports[i] == port) {
            nic->ports[i] = -1;
            break;
        }
    }
    pthread_mutex_unlock(&nic->mutex);
}

void nic_config_validate(NicConfig* nic) {
    struct in6_addr ip, subnet_mask, gateway;
    if (inet_pton(AF_INET6, nic->ip, &ip) <= 0 ||
        inet_pton(AF_INET6, nic->subnet_mask, &subnet_mask) <= 0 ||
        inet_pton(AF_INET6, nic->gateway, &gateway) <= 0 ||
        !memcmp(&ip_v4mapped(&ip), &ip_v4mapped(&subnet_mask), sizeof(struct in_addr))) {
        return;
    }

    struct in6_addr net, broadcast, mask;
    inet_pton(AF_INET6, nic->ip, &net);
    inet_pton(AF_INET6, inet_network(nic->ip), &broadcast);
    inet_pton(AF_INET6, inet_direct(nic->subnet_mask), &mask);
    if (memcmp(&broadcast, &inet_makeaddr(AF_INET6, 0xFFFF, ~mask.s6_addr32[3]), sizeof(struct in6_addr)) != 0 ||
        memcmp(&gateway, &net, sizeof(struct in6_addr)) > sizeof(struct in6_addr)) {
        return;
    }
}
