LTE_PHY_RX_TARGET* initialize_target(size_t num_records, size_t threshold) {
    LTE_PHY_RX_TARGET* target = malloc(sizeof(LTE_PHY_RX_TARGET));
    target->num_records = num_records;
    target->active_count = 0;
    target->records = malloc(num_records * sizeof(LTE_RX_SUBFRAME_INFO));
