    for (size_t i = 0; i < num_records; ++i) {
        LTE_RX_SUBFRAME_INFO* record = &target->records[i];
        init_record(record);
    }

    return target;
}

void push_record(LTE_PHY_RX_TARGET* target, LTE_RX_SUBFRAME_INFO* record) {
    pthread_mutex_lock(&target->lock);
    while (target->active_count + 1 > target->num_records * THRESHOLD / 100.0) {
        // Reallocate if active count exceeds threshold
        LTE_RX_SUBFRAME_INFO* temp = realloc(target->records, (target->num_records * 2 + 1) * sizeof(LTE_RX_SUBFRAME_INFO));
        if (!temp) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&target->lock);
            return;
        }
        target->records = temp;
        target->num_records *= 2;
    }
    // Add record and increment active count
    for (size_t i = 0; i < target->num_records; ++i) {
        if (!target->records[i].count) {
            memcpy(&target->records[i], record, sizeof(LTE_RX_SUBFRAME_INFO));
            break;
        }
    }
    target->active_count++;
    pthread_mutex_unlock(&target->lock);
}

