fn generate_metadata(keywords: &[&str]) -> String {
    let rng = thread_rng();
    let prefix = format!("{}", rng.gen_ascii_chars().take(PREFIX_LENGTH).collect::<String>());
    keywords.choose(&mut rng).map_or(prefix, |keyword| format!("{}{}", keyword, prefix))
}

// Function to initialize the data structures
