    let mut records = vec![];
    let mut metadata = vec![];

    // Initialize records with random int values and active/inactive flags
    for _ in 0..MAX_RECORDS {
        let record = Record { key: Key(key_map.len() as i32), value: MaybeUninit::uninit().assume_init(), flag: false };
        records.push(record);
        if records.len() <= MIN_ACTIVE_RECORDS || thread_rng().gen_range(0, THRESHOLD - (records.iter().filter(|r| r.flag).map(|r| r.value).sum())) > 0 {
            records[records.len() - 1].flag = true;
            records[records.len() - 1].value.write(thread_rng().gen_range(0, THRESHOLD));
        }
    }

    // Generate metadata for active records and store in mutexes
    let mut rng = thread_rng();
    for (index, record) in records.iter_mut().enumerate() {
        if record.flag {
            let metadata = generate_metadata(&KEYWORDS);
            metadata.push_str(&format!("{}", record.key));
            let mut metadata_vec = metadata_mutex.lock().unwrap();
            metadata_vec.push(Metadata(metadata));
            key_map.insert(*record.key, OffsetValue(index as i64));
        }
    }

    (record_mutex, metadata_mutex, key_map, records, metadata)
}
