// Callback function for 'get_cell_config' to populate the data cache
void on_cell_config_fetched(NFAPI_UL_CCCH_INDICATION_PDU_T* config) {
    pthread_mutex_lock(&data_lock);
    if (!data_cache || data_cache_size < config->UE_ID) { // Reallocate if necessary
