    get_cell_config();

    // Wait for data to be fetched and ready
    pthread_mutex_lock(&data_lock);
    while (data_cache_size < num_cells) {
        sem_wait(&data_ready_semaphore);
    }
    pthread_mutex_unlock(&data_lock);

