#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
    char *str;
} Record;

// Synchronization mechanism: a read-write lock for efficient concurrent access
pthread_rwlock_t rwlock;

// Function to initialize the memory allocations
void init_mem(size_t num_offsets, size_t num_keys, size_t num_records, size_t initial_size) {
    long *offsets = malloc(num_offsets * sizeof(long));
    int *keys = malloc(num_keys * sizeof(int));
    Record *records = malloc(num_records * sizeof(Record));

    // Dynamic resizing strategy: power of 2 growth factor
    size_t growth_factor = 4;

    // Initialize the read-write lock
    pthread_rwlock_init(&rwlock, NULL);
}

// Function to fill each record with a random value within a specified range
void fill_records(size_t num_records, int min, int max) {
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % (max - min + 1) + min;
        // Generate a random string of fixed length
        char str[32];
        snprintf(str, sizeof(str), "%d", records[i].value);
        records[i].str = strdup(str);
    }
}

// Thread-safe function to get the next available offset
long get_next_offset() {
    pthread_rwlock_rdlock(&rwlock);
    long offset = *offsets++;
    pthread_rwlock_unlock(&rwlock);
    return offset;
}

// Thread-safe function to add a new key and record, resizing arrays if necessary
void add_key_and_record(int key, const char *str) {
    size_t num_records_before = 0;
    pthread_rwlock_wrlock(&rwlock);
    // Count the number of records before acquiring the write lock to determine if resizing is needed
    for (size_t i = 0; i < num_records; ++i) {
        if (!records[i].str) {
            num_records_before++;
        } else {
            break;
        }
    }

    // Dynamic resizing strategy: reallocate the arrays and records, doubling in size if necessary
    if (num_records < num_records_before * growth_factor) {
        size_t new_size = num_records ? (num_records * 2) : initial_size;
        long *new_offsets = realloc(offsets, new_size * sizeof(long));
        int *new_keys = realloc(keys, new_size * sizeof(int));
        Record *new_records = realloc(records, new_size * sizeof(Record));

        if (new_offsets && new_keys && new_records) {
            offsets = new_offsets;
            keys = new_keys;
            records = new_records;
            num_records *= 2;
        } else {
            pthread_rwlock_unlock(&rwlock);
            return;
        }
    }

    // Assign the key, record, and next available offset
    long next_offset = get_next_offset();
    keys[key] = next_offset;
    records[next_offset].value = rand() % (max - min + 1) + min;
    records[next_offset].str = strdup(str);

    pthread_rwlock_unlock(&rwlock);
}

// Example usage in a thread function
void *thread_func(void *arg) {
    int id = *(int *) arg;

    // Get the next available key and record
    long offset = get_next_offset();
    int key = keys[id];
    Record *record = &records[offset];

    // Access the record value and string without holding the lock (assuming read-only access)
    printf("Thread %d: value=%d, str=\"%s\"\n", id, record->value, record->str);

    return NULL;
}
