    std::string gateway;
    std::vector<uint16_t> ports;
};

class NetworkConfig {
public:
    void loadFromXml(const std::string& xml);
    NicConfig* getNic(const std::string& nicName);
    void configure();
private:
    std::unordered_map<std::string, NicConfig> _nicMap;
    boost::circular_buffer<NicConfig> _cache;
    uint32_t _cacheSize = 1000; // Adjust cache size as needed
    boost::optional<boost::asio::io_service> _loadBalancerService;
};

void NetworkConfig::loadFromXml(const std::string& xml) {
    pugi::xml_document doc;
    pugi::xml_parse_result result = doc.load_string(xml.c_str());
    if (result == false) {
        std::cerr << "Failed to parse XML: " << result.description() << std::endl;
        return;
    }

    pugi::xml_node nicNode = doc.child("network").child("nic");
    while (nicNode) {
        NicConfig nicConfig;
        nicConfig.role = nicNode.attribute("role").value();
        nicConfig.ip = nicNode.attribute("ip").value();
        nicConfig.subnetMask = nicNode.attribute("subnet_mask").value();
        nicConfig.gateway = nicNode.attribute("gateway").value();
        pugi::xml_node portNodes = nicNode.child("ports");
        while (portNodes && portNodes.child("port")) {
            nicConfig.ports.push_back(std::stoi(portNodes.child("port").text().get()));
            portNodes = portNodes.next_sibling();
        }
        _nicMap[nicNode.attribute("name").value()] = nicConfig;
        nicNode = nicNode.next_sibling();
    }
}

NicConfig* NetworkConfig::getNic(const std::string& nicName) {
    auto it = _nicMap.find(nicName);
    if (it == _nicMap.end()) return nullptr;
    boost::circular_buffer<NicConfig>::iterator cacheIt = std::find(_cache.begin(), _cache.end(), it->second);
    if (cacheIt != _cache.end()) return &*cacheIt;
    return &it->second;
}

void NetworkConfig::configure() {
    for (auto& nic : _nicMap) {
        validateIp(nic.second.ip, nic.second.subnetMask, nic.second.gateway);
        configurePorts(nic.second.ports);
        // Integrate with load balancer service here
        // Apply network topology updates and handle errors gracefully
    }
}
