#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct _bucket {
    struct _record* head;
    pthread_mutex_t mutex;
} bucket;

typedef struct _record {
    int id;
    double amount;
    struct _record *next;
} record;

typedef struct _hash_table {
    bucket* buckets;
    size_t capacity;
    size_t size;
} hash_table;

void init_bucket(bucket* bucket) {
    bucket->head = NULL;
    pthread_mutex_init(&bucket->mutex, NULL);
}

hash_table* create_hash_table(size_t capacity) {
    if (capacity < 16) capacity = 16;

    hash_table* table = malloc(sizeof(hash_table));
    if (!table) return NULL;

    table->capacity = capacity;
    table->size = 0;
    table->buckets = calloc(capacity, sizeof(bucket));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    for (size_t i = 0; i < capacity; ++i) init_bucket(&table->buckets[i]);

    return table;
}

size_t hash(int id, size_t capacity) {
    return id % capacity;
}

record* create_record(int id, double amount) {
    record* new_record = malloc(sizeof(record));
    if (!new_record) return NULL;

    new_record->id = id;
    new_record->amount = amount;
    new_record->next = NULL;

    return new_record;
}

bool insert(hash_table* table, int id, double amount) {
    if (!table || !create_record(id, amount)) return false;

    bucket* bucket = &table->buckets[hash(id, table->capacity)];
    pthread_mutex_lock(&bucket->mutex);

    record* new_record = create_record(id, amount);
    if (!new_record) {
        free(new_record);
        pthread_mutex_unlock(&bucket->mutex);
        return false;
    }

    new_record->next = bucket->head;
    bucket->head = new_record;

    pthread_mutex_unlock(&bucket->mutex);
    ++table->size;

    return true;
}

record* find(hash_table* table, int id) {
    if (!table || id < 0) return NULL;

    bucket* bucket = &table->buckets[hash(id, table->capacity)];
    pthread_mutex_lock(&bucket->mutex);

    record* current = bucket->head;
    while (current != NULL) {
        if (current->id == id) {
            pthread_mutex_unlock(&bucket->mutex);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&bucket->mutex);
    return NULL;
}

bool delete(hash_table* table, int id) {
    if (!table || id < 0) return false;

    bucket* bucket = &table->buckets[hash(id, table->capacity)];
    pthread_mutex_lock(&bucket->mutex);

    record* previous = NULL;
    record* current = bucket->head;
    while (current != NULL) {
        if (current->id == id) {
            if (previous) previous->next = current->next;
            else bucket->head = current->next;

            free(current);
            --table->size;

            pthread_mutex_unlock(&bucket->mutex);
            return true;
        }
        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&bucket->mutex);
    return false;
}
