typedef struct MemRegion {
    void *ptr;
    size_t length;
    posix_mlock_t lock;
} MemRegion;

void init_memregion(MemRegion *mr, size_t bytes) {
    mr->ptr = mmap(NULL, bytes, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mr->ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    mr->length = bytes;
    pthread_mutex_init(&mr->lock, NULL);
}

void *get_memregion(MemRegion *mr, size_t offset, size_t length) {
    void *result = (char *)mr->ptr + offset;
    posix_mlock(&mr->lock, (size_t)(length));
    return result;
}

void free_memregion(MemRegion *mr) {
    munmap((char *)mr->ptr, mr->length);
    pthread_mutex_destroy(&mr->lock);
}

