    size_t entry_count;
    pthread_mutex_t mutex;
    DependencyManager dependency_manager;
    void** dependencies;
};

void initialize_test_environment(struct TestEnvironment** env, const char* moduleLabel, int* keyArray, const struct { double lower, upper; } valueRange, TestFunc testFunction, DependencyManager dependency_manager) {
    // Allocate and align memory for offsets, keys, entries, and dependencies
    size_t entry_size = sizeof(struct Entry) + (sizeof(void*) - 1) & ~(sizeof(void*) - 1);
    size_t alignment = sizeof(void*);

    *env = malloc(sizeof(struct TestEnvironment));
    (*env)->offsets = (long*)aligned_alloc(alignment, keyArraySize * sizeof(long));
    (*env)->keys = (int*)aligned_alloc(alignment, keyArraySize * sizeof(int));
    (*env)->entries = (struct Entry*)aligned_alloc(alignment, keyArraySize * entry_size);
    (*env)->dependencies = malloc(sizeof(void*));

    // Initialize mutex and dependency manager
    pthread_mutex_init(&(*env)->mutex, NULL);
    (*env)->dependency_manager = dependency_manager;

    // Fill entries with random values and initialize dependencies
    for (size_t i = 0; i < keyArraySize; ++i) {
        (*env)->offsets[i] = (long)aligned_alloc(alignment, sizeof(double));
        (*env)->keys[i] = keyArray[i];
        struct Entry* entry = &(*env)->entries[i * entry_size / sizeof(struct Entry)];
        entry->value = rand() * (1.0 / RAND_MAX) * (valueRange.upper - valueRange.lower) + valueRange.lower;
        entry->function_ptr = NULL;
        if ((*env)->dependency_manager) {
            void** dependency_handle = &(*env)->dependencies[i];
            (*env)->dependency_manager(moduleLabel, dependency_handle);
        }
    }

    // Load module and set function pointers for each test case
    // ... (Module loading code not included here)

    // Register test function for each test case
    // ... (Test registration code not included here)
}

void run_tests(struct TestEnvironment* env, void(*log_function)(const char*, const char*)) {
    pthread_t threads[env->entry_count];
    struct Entry** entries = env->entries;

    for (size_t i = 0; i < env->entry_count; ++i) {
        void* args[] = { entries[i], &log_function };
        pthread_create(&threads[i], NULL, execute_test, args);
    }

    // Wait for all threads to finish
    for (size_t i = 0; i < env->entry_count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void reset_test_environment(struct TestEnvironment* env) {
    // Free allocated memory and reset mutex
    for (size_t i = 0; i < env->entry_count; ++i) {
        free((void*)env->offsets[i]);
    }
    free(env->offsets);
    free(env->keys);
    for (size_t i = 0; i < env->entry_count * (entry_size / sizeof(struct Entry)); ++i) {
        struct Entry* entry = &env->entries[i];
        entry->value = 0.0;
        entry->function_ptr = NULL;
    }
    pthread_mutex_destroy(&env->mutex);
}

void* execute_test(void* args) {
    struct Entry* entry = (struct Entry*)args[0];
    void(*log_function)(const char*, const char*) = args[1];

    // Call test function and log results
    // ... (Test execution code not included here)
}
