typedef struct _list_node {
    NFAPI_CRC_INDICATION_PDU *data;
    struct _list_node *next;
    pthread_mutex_t mutex;
} list_node;

static list_node *head = NULL;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void add_to_list(NFAPI_CRC_INDICATION_PDU *pdu) {
    if (head == NULL) {
        head = malloc(sizeof(list_node));
        if (!head) return;
        head->data = pdu;
        head->next = NULL;
        pthread_mutex_init(&head->mutex, NULL);
    } else {
        pthread_mutex_lock(&list_mutex);
        list_node *current = head;
        while (current->next) current = current->next;
        current->next = malloc(sizeof(list_node));
        if (!current->next) goto cleanup;
        current->next->data = pdu;
        current->next->next = NULL;
        pthread_mutex_init(&current->next->mutex, NULL);
    cleanup:
        pthread_mutex_unlock(&list_mutex);
    }
    pthread_mutex_lock(&pdu->mutex);
    pdu->rnti += 1; // Ensure uniqueness of RNTI values within the list
    if (pdu->crc_indication.CRCFLAG == ALREADY_PROCESSED) {
        pthread_mutex_unlock(&pdu->mutex);
        return;
    }
    pthread_mutex_unlock(&pdu->mutex);
}

NFAPI_CRC_INDICATION_PDU* remove_from_list(uint32_t rnti) {
    if (head == NULL) return NULL;
    pthread_mutex_lock(&list_mutex);
    list_node *current = head, *prev = NULL;
    while (current != NULL) {
        pthread_mutex_lock(&current->data->mutex);
        if (current->data->rnti == rnti && current->data->crc_indication.CRCFLAG != ALREADY_PROCESSED) {
