            NFAPI_CRC_INDICATION_PDU *temp = current->data;
            pthread_mutex_unlock(&current->data->mutex);
            free(current);
            return temp;
        }
        prev = current;
        current = current->next;
        pthread_mutex_unlock(&current->data->mutex);
    }
    pthread_mutex_unlock(&list_mutex);
    return NULL;
}

