pthread_cond_t list_not_full = PTHREAD_COND_INITIALIZER;

bool is_unique(Node* node) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.rnti == node->data.rnti) return false;
        current = current->next;
    }
    return true;
}

void enqueue(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = *pdu;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->mutex, NULL);

    pthread_mutex_lock(&list_mutex);
    while (is_full() && !is_unique(new_node)) {
        pthread_cond_wait(&list_not_full, &list_mutex);
    }

    if (!head) {
        head = new_node;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&list_mutex);
}

Node* dequeue() {
    Node* temp_head = head;
    if (temp_head == NULL) return NULL;

    pthread_mutex_lock(&temp_head->mutex);
    Node* data = temp_head;
    head = temp_head->next;
    pthread_mutex_unlock(&temp_head->mutex);

    return data;
}

size_t size() {
    size_t count = 0;
    Node* current = head;
    while (current != NULL) {
        ++count;
        current = current->next;
    }
    return count;
}

bool is_full() {
    return size() >= max_list_size;
}

