#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

#define MAX_RECORDS 100000
#define LOG_FILE "system.log"
#define MEMORY_LIMIT (MAX_RECORDS * sizeof(struct record) + MAX_RECORDS * PAGE_SIZE)

typedef struct {
    long value;
    char* message;
} record;

int log_rotated = 0;
int log_fd = -1;
off_t log_offset = 0;

record* records;
size_t num_records = 0;
size_t max_records = 0;

void init() {
    max_records = (MEMORY_LIMIT / sizeof(record)) - MAX_RECORDS;
    if (max_records < 1) {
        fprintf(stderr, "Insufficient memory for required operations.\n");
        exit(EXIT_FAILURE);
    }
    records = malloc(max_records * sizeof(record));
}

void free_resources() {
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].message);
    }
    free(records);
    records = NULL;
}

int open_log() {
    if (log_rotated) {
        log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
        log_offset = 0;
        log_rotated = 0;
    } else {
        log_fd = open(LOG_FILE, O_WRONLY | O_APPEND, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
        if (log_fd == -1) {
            perror("Error opening log file");
            return 1;
        }
    }
    return 0;
}

void log_state() {
    if (open_log()) {
        return;
    }

    struct flock lock;
    lock.l_type = F_WRLCK;
    lock.l_whence = SEEK_SET;
    lock.l_start = log_offset;
    lock.l_len = 0;
    fcntl(log_fd, F_SETLKW, &lock);

    fprintf(fdopen(log_fd, "a"), "State:\n");
    fprintf(fdopen(log_fd, "a"), "\tNumber of records: %zu\n", num_records);
    fprintf(fdopen(log_fd, "a"), "\tMaximum allowed records: %zu\n", max_records);
    fprintf(fdopen(log_fd, "a"), "\tMemory usage (bytes): %ld\n", MEMORY_LIMIT);
    fflush(fdopen(log_fd, "a"));

    lock.l_type = F_UNLCK;
    fcntl(log_fd, F_SETLKW, &lock);
}

void add_record(long value, const char* message) {
    if (num_records == max_records) {
        log_state();
        log_rotated = 1;
        init();
    }

    records[num_records].value = value;
    records[num_records].message = strdup(message);
    ++num_records;
}

record* get_record(size_t index) {
    if (index >= num_records || index >= max_records) {
        return NULL;
    }
    return &records[index];
}
```

