int createPDUs(NFAPI_CRC_INDICATION_PDU_T** pds, size_t n) {
    int retries = config.maxRetries;
    size_t bufferSize = config.bufferSize;
    long timeout = config.timeout;

    *pds = (NFAPI_CRC_INDICATION_PDU_T*)calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pds) {
        perror("Memory allocation failed");
        return -1;
    }

    while (retries > 0) {
        CURL* curl;
        CURLcode res;
        char* response = NULL;
        FILE* fptr = tmpfile();

        curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, "https://your-data-api.com/api/v1/pdus");
            curl_easy_setopt(curl, CURLOPT_TIMEOUT, timeout);

            res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                fprintf(stderr, "Failed to retrieve PDUs: %s\n", curl_easy_strerror(res));
                curl_easy_cleanup(curl);
                fclose(fptr);
                retries--;
                continue;
            }

            res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE);
            if (res != 200) {
                fprintf(stderr, "Data API returned non-200 status code: %d\n", res);
                curl_easy_cleanup(curl);
                fclose(fptr);
                retries--;
                continue;
            }

            curl_easy_getinfo(curl, CURLINFO_RESPONSE_LENGTH_TOTAL, &len);
            if (len > bufferSize) {
                fprintf(stderr, "Data response too large for buffer\n");
                curl_easy_cleanup(curl);
                fclose(fptr);
                retries--;
                continue;
            }

            cur_off_t pos = 0;
            cur_off_t read = 0;
            char* buffer = malloc(len + 1);
            if (!buffer) {
                fprintf(stderr, "Memory allocation failed\n");
                curl_easy_cleanup(curl);
                fclose(fptr);
                retries--;
                continue;
            }

            while (read < len) {
                size_t nread = fread(&buffer[read], 1, len - read, fptr);
                if (nread == 0) break;
                read += nread;
            }
            buffer[len] = '\0';

            int i;
            for (i = 0; i < n && read < len; i++) {
                json_object *obj = json_tokener_parse(buffer);
                if (!obj) continue;

                json_object* tag_obj = json_object_object_get(obj, "tag");
                RX_UE_INFORMATION_TAG tag = json_object_get_int(tag_obj);

                json_object* rnti_obj = json_object_object_get(obj, "rnti");
                RNTI rnti = json_object_get_int(rnti_obj);

                json_object* crcflag_obj = json_object_object_get(obj, "crcflag");
                int crcflag = json_object_get_int(crcflag_obj);

                CRC_INDICATION_REL8_TAG crc_indication = (CRC_INDICATION_REL8_TAG){ .crcflag = (uint8_t)crcflag };

                (*pds)[i] = (NFAPI_CRC_INDICATION_PDU_T){ .tag = tag, .rnti = rnti, .crc_indication = crc_indication };

                read += json_object_get_int(json_object_object_get(obj, "length")) + 1; // skip comma and length field
            }

            free(buffer);
            curl_easy_cleanup(curl);
            fclose(fptr);

            if (read == len) {
                retries = 0;
            }
        }
    }

    if (retries == 0) {
        free(*pds);
        *pds = NULL;
        return -1;
    }

    return 0;
}

