std::forward_list<std::unique_ptr<std::string>> insertStringAfterMatch(const std::forward_list<std::unique_ptr<std::string>>& data, const std::string& target, const std::string& replacement) {
    std::forward_list<std::unique_ptr<std::string>> result;
    std::unique_ptr<std::string> current(new std::string(*data.begin())); // Copy the first element and create a unique_ptr to manage its memory.
    auto it = data.begin();
    ++it;

    while (it != data.end()) {
        if (current->compare(*it) == 0 && target.compare(*it) == 0) { // Check if the current string matches the target string and is unique.
            result.push_front(std::move(current)); // If a match is found, move the current string to the output list and insert the replacement string after it.
            result.emplace_after(result.begin(), std::make_unique<std::string>(replacement));
            current = std::move(it->clone()); // Clone the next string to manage its memory with a unique_ptr.
        } else if (current->compare(*it) == 0) { // Check for duplicates and handle potential inconsistencies gracefully.
            ++it;
            continue;
        } else {
            result.push_back(std::move(current)); // If there's no match, append the current string to the output list and move to the next string in the input list.
            if (it != data.end()) {
                current = std::move(it->clone()); // Clone the next string to manage its memory with a unique_ptr.
            }
        }
        it = it == data.end() ? data.begin() : std::next(it); // Iterate through the input list in a cyclic manner.
    }

    if (current != nullptr) {
        result.push_back(std::move(current)); // Append any remaining strings to the output list.
    }

    if (!result.empty() && result.front()->compare(target) == 0) { // Check if the first string in the output list matches the target string and handle potential inconsistencies gracefully.
        auto it = std::find_if(result.begin(), result.end(), [&](const std::unique_ptr<std::string>& str) { return str->compare(replacement) == 0; }); // Find the position of the replacement string in the output list.
        if (it != result.end()) { // If the replacement string is found, remove it to avoid duplicate replacements.
            result.erase(it);
        } else { // If the replacement string is not found, append it to the end of the output list.
            result.emplace_back(std::make_unique<std::string>(replacement));
        }
    }

    return result;
}
