// Function for reading and serializing CRCTIndications
NFAPI_CRC_INDICATION_PDU_T* readAndSerializeCrcIndications(const char* dir) {
    int fd = open((const char*)dir, O_RDONLY);
    if (fd < 0) {
        perror("Error opening file");
        return NULL;
    }

    size_t fileSize = lseek(fd, 0, SEEK_END);
    if (fileSize > MAX_MEMORY) {
        printf("File size exceeds the maximum allowed memory\n");
        close(fd);
        return NULL;
    }

    void* buf = mmap(NULL, fileSize + sizeof(size_t), PROT_READ, MAP_PRIVATE, fd, 0);
    if (buf == MAP_FAILED) {
        perror("Error mapping memory");
        close(fd);
        return NULL;
    }

    size_t* dataSize = (size_t*)buf;
    *dataSize = fileSize - sizeof(size_t);

    close(fd);

    NFAPI_CRC_INDICATION_PDU_T* data = (NFAPI_CRC_INDICATION_PDU_T*)((char*)buf + sizeof(size_t));
    uint64_t allocated = 0;
    for (int i = 0; i < *dataSize / sizeof(NFAPI_CRC_INDICATION_PDU_T); ++i) {
        data[i].RX_UE_INFORMATION_TAG = htons(rand() % 65535);
        data[i].RNTI = htonl(rand());
        data[i].CRC_INDICATION_REL8_TAG = rand();
        data[i].CRCFLAG = rand() % 2;

        allocated++;
    }

    munmap(buf, fileSize + sizeof(size_t));

    if (allocated != *dataSize / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        perror("Error allocating memory");
        return NULL;
    }

    return data;
}

// Deserialize function for NFAPI_CRC_INDICATION_PDU_T structures
