#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    char session_id[32];
    time_t login_timestamp;
    time_t last_activity_timestamp;
    time_t expiration_time;
} Session;

struct list {
    size_t capacity;
    size_t count;
    Session *sessions;
    pthread_mutex_t mutex;
    pthread_cond_t not_full; // Condition variable to signal when there is available space.
};

void session_list_init(struct list *list, size_t initial_capacity) {
    list->capacity = initial_capacity;
    list->count = 0;
    list->sessions = malloc(initial_capacity * sizeof(Session));
    if (!list->sessions) {
        fprintf(stderr, "Memory allocation failure.\n");
        return;
    }
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->not_full, NULL);
}

void session_list_destroy(struct list *list) {
    free(list->sessions);
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->not_full);
}

int session_list_add(struct list *list, const char *session_id, time_t login_timestamp, time_t last_activity_timestamp, time_t expiration_time) {
    if (list->count >= list->capacity) return 0; // List is full.

    pthread_mutex_lock(&list->mutex);
    while (list->count >= list->capacity) {
        pthread_cond_wait(&list->not_full, &list->mutex);
    }

    Session *session = &list->sessions[list->count];
    strcpy(session->session_id, session_id);
    session->login_timestamp = login_timestamp;
    session->last_activity_timestamp = last_activity_timestamp;
    session->expiration_time = expiration_time;

    list->count++;
    pthread_cond_signal(&list->not_full); // Signal that there is available space.
    pthread_mutex_unlock(&list->mutex);

    return 1; // Successfully added session.
}

int session_list_remove(struct list *list, const char *session_id) {
    if (list->count == 0) return 0; // List is empty.

    pthread_mutex_lock(&list->mutex);
    size_t i;
    for (i = 0; i < list->count; ++i) {
        if (!strcmp(list->sessions[i].session_id, session_id)) break;
    }

    if (i >= list->count) { // Session not found.
        pthread_mutex_unlock(&list->mutex);
        return 0;
    }

    memmove(&list->sessions[i], &list->sessions[i+1], (list->count-i-1)*sizeof(Session));
    --list->count;
    pthread_cond_signal(&list->not_full); // Signal that there is available space.
    pthread_mutex_unlock(&list->mutex);

    return 1; // Successfully removed session.
}

void performance_monitor(struct list *list) {
    static time_t last_activation = 0;
    static time_t last_deactivation = 0;
    static size_t activation_count = 0;
    static size_t deactivation_count = 0;
    static double average_time = 0.0;
    static const double threshold = 100.0; // Adjust dynamically based on current load.

    time_t now = time(NULL);
    double elapsed;

    if (now - last_activation > threshold) {
        elapsed = (now - last_activation) / activation_count;
        average_time = 0.9 * average_time + 0.1 * elapsed;
        last_activation = now;
        activation_count = 0;
    }

    if (now - last_deactivation > threshold) {
        elapsed = (now - last_deactivation) / deactivation_count;
        average_time = 0.9 * average_time + 0.1 * elapsed;
        last_deactivation = now;
        deactivation_count = 0;
    }

    ++activation_count;
