// Define a mutex to protect the list
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Dynamic list structure (using a linked list)
typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

Node* head = NULL;  // Head of the list

void create_node(NFAPI_CRC_INDICATION_PDU_T* new_data) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = *new_data;
    new_node->next = NULL;
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) goto unlock_and_return;

    while (current && current->data.rnti == data->rnti) {
        // If the list already contains an element with the same RNTI, skip it.
        current = current->next;
    }

    if (!current) {  // Add at the head if the list is empty
        new_node->data = *data;
        new_node->next = head;
        head = new_node;
    } else {
        // Find the appropriate position in the list to insert the new node.
        while (current && current->next && current->next->data.rnti == data->rnti) {
            current = current->next;
        }

        if (!current->next) {  // Insert at the end of the list
            current->next = new_node;
            new_node->data = *data;
            new_node->next = NULL;
        } else {  // Insert in the middle of the list
            new_node->data = *data;
            new_node->next = current->next;
            current->next = new_node;
        }
    }

unlock_and_return:
    pthread_mutex_unlock(&list_mutex);
}

