#include <iostream>
#include <vector>
#include <list>
#include <map>
#include <boost/multi_index_container.hpp>
#include <boost/serialization/access.hpp>
#include <boost/serialization/vector.hpp>
#include <boost/serialization/list.hpp>
#include <boost/serialization/map.hpp>
#include <boost/serialization/utility.hpp>
#include <boost/archive/text_oarchive.hpp>
#include <boost/archive/text_iarchive.hpp>
#include <boost/thread/mutex.hpp>
#include <boost/thread/locks.hpp>
#include <boost/atomic.hpp>
#include <system_error>
#include <fstream>
#include <cstdint>
#include <ctime>

namespace my {
    struct Message {
        std::uint64_t message_id;
        std::uint64_t timestamp;
        int priority;

        friend class boost::serialization::access;

        template<class Archive>
        void serialize(Archive & ar, const unsigned int version) {
            ar & message_id & timestamp & priority;
        }
    };

    typedef boost::multi_index::multimap<Message::message_id, Message> MessageIndex;
    typedef std::vector<Message> MessageList;

    class MessageManager {
    public:
        explicit MessageManager(const std::string& filename) : m_data(), m_mutex(), m_file(filename, std::ios::out | std::ios::binary), m_iarchive(&m_file) {
            load();
        }

        ~MessageManager() {
            save();
        }

        void insert(const Message& message) {
            boost::lock_guard<boost::mutex> lock(m_mutex);
            m_data.insert(message);
        }

        bool remove(std::uint64_t id) {
            boost::lock_guard<boost::mutex> lock(m_mutex);
            MessageIndex::nth_iterator it = m_data.get_by_id(id).first;
            if (it != m_data.end()) {
                m_data.erase(it);
                return true;
            }
            return false;
        }

        const Message& get(std::uint64_t id) const {
            auto it = m_data.get_by_id(id).first;
            if (it != m_data.end())
                return *it;
            throw std::runtime_error("Message not found");
        }

        void serialize(boost::archive::text_oarchive& ar) const {
            ar & boost::serialization::make_nvp("messages", m_data);
        }

        void deserialize(boost::archive::text_iarchive& ar) {
            ar & boost::serialization::make_nvp("messages", m_data);
        }

    private:
        void load() {
            if (m_file.is_open())
                m_file.close();
            m_file.open(std::ios::in | std::ios::binary);
            if (m_file.is_open()) {
                boost::archive::text_iarchive iar(m_file);
                iar >> boost::serialization::base_object<MessageManager>(*this);
                m_file.close();
            }
        }

        void save() const {
            if (!m_file.is_open())
                m_file.open(std::ios::out | std::ios::binary | std::ios::trunc);
            boost::archive::text_oarchive oar(m_file);
            oar << boost::serialization::base_object<MessageManager>(*this);
            m_file.close();
        }

        MessageList m_data;
        boost::mutex m_mutex;
        std::ifstream m_file;
        boost::archive::text_iarchive m_iarchive;
    };
}
```

