```cpp
#include <iostream>
#include <vector>
#include <string>
#include <time.h>
#include <cstdlib>
#include <mutex>
#include <atomic>
#include <thread>
#include <condition_variable>
#include <memory>

struct Record {
    std::atomic<int> value;
    std::unique_ptr<char[]> identifier;
};

class DataStructures {
private:
    std::vector<long> offsets;
    std::vector<int> keys;
    std::vector<Record> records;
    mutex mtx;
    atomic<size_t> nextKeyIndex;
    condition_variable cv;

public:
    DataStructures(size_t size) {
        resizeVectors(size);
    }

    void resizeVectors(size_t size) {
        if (size > offsets.size()) {
            offsets.resize(size);
            keys.resize(size);
            records.reserve(size);
            for (size_t i = offsets.size(); i < size; ++i) {
                records.emplace_back();
            }
        }
    }

    Record& getRecordByKey(int key) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this, key] { return keys[key] != 0; });
        auto index = keys[key];
        keys[key] = 0; // Prevent reuse of the key during the lock duration
        return records[index];
    }

    void putRecord(const Record& record) {
        std::unique_lock<std::mutex> lock(mtx);
        auto key = nextKeyIndex++;
        keys[key] = 1;
        auto index = records.size();
        records.emplace_back(record);
        offsets.push_back(index);
        cv.notify_one(); // Allow another thread to use the key if available
    }

    void initializeRecords() {
        for (auto& record : records) {
            record.value = std::rand() % 100;
            auto timestamp = static_cast<int>(std::time(nullptr));
            record.identifier = std::make_unique<char[]>(std::to_string(key).length() + 16); // Adjust size based on platform and architecture
            std::sprintf(record.identifier.get(), "%d-%lu", key, timestamp);
        }
    }
};
```

This code creates a `DataStructures` class that manages the three data structures you specified. The class uses atomic variables to ensure thread safety and synchronization mechanisms like mutexes and condition variables for concurrent access from multiple threads. The `resizeVectors()` function allows for dynamic resizing of the arrays and records, while the `getRecordByKey()` and `putRecord()` functions provide the primary interfaces for interacting with the data structures.

The `initializeRecords()` function initializes each record with a random value and a unique identifier based on the key and a timestamp. The identifier size can be adjusted according to your platform's requirements.']

