```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <cstdlib>
#include <ctime>
#include <nlohmann/json.hpp>
using json = nlohmann::json;

class TransactionRecord {
public:
    double amount;
    char status;

    TransactionRecord() : amount(0), status(' ') {}
};

class TransactionDataSet {
private:
    std::vector<TransactionRecord> records_;
    size_t capacity_;

public:
    TransactionDataSet() : capacity_(1000) {
        records_.resize(capacity_);
    }

    void append(const TransactionRecord& record) {
        if (records_.size() == capacity_) {
            capacity_ += 1000;
            records_.resize(capacity_);
        }
        records_[records_.size() - 1] = record;
    }

    void save(const std::string& filename) const {
        json j;
        for (const auto& record : records_) {
            json r;
            r["amount"] = record.amount;
            r["status"] = record.status;
            j.push_back(r);
        }

        std::ofstream outputFile(filename);
        if (outputFile.is_open()) {
            outputFile << j.dump();
        } else {
            std::cerr << "Error: Unable to open file for writing." << std::endl;
        }
    }

    void load(const std::string& filename) {
        json j;
        std::ifstream inputFile(filename);
        if (inputFile.is_open()) {
            inputFile >> j;
            for (auto i = 0u; i < j.size(); ++i) {
                const auto& record = j[i];
                TransactionRecord tr;
                tr.amount = record["amount"];
                tr.status = record["status"];
                append(tr);
            }
        } else {
            std::cerr << "Error: Unable to open file for reading." << std::endl;
        }
    }
};

TransactionDataSet createTransactions() {
    TransactionDataSet transactions;
    std::mt19937 generator(time(0));
    std::uniform_real_distribution<> distribution(0.01, 10000.0);

    for (size_t i = 0; i < transactions.capacity_; ++i) {
        TransactionRecord record;
        record.amount = distribution(generator);
        record.status = (generator % 2 == 0) ? 'Y' : 'N';
        transactions.append(record);
    }

    return transactions;
}
```

