['```rust
use std::collections::VecDeque;
use reqwest::{Client, Response};
use serde_json::Value;
use rand::Rng;
use tokio::sync::mpsc::{channel, Receiver};
use tokio::task::spawn;

struct Config {
    min: f64,
    max: f64,
    range_precision: u8,
    num_concurrent_tasks: usize,
    validate_certificate: bool,
    url: String,
}

struct NFAPI_CRC_INDICATION_PDU_T {
    rx_ue_information_tag: u32,
    rnti: u16,
    crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG,
}

struct CRC_INDICATION_REL8_TAG {
    crcflag: bool,
}

async fn process_number(num: f64, config: &Config, tx: &Receiver<NFAPI_CRC_INDICATION_PDU_T>) {
    if num < config.min || num > config.max {
        return;
    }

    let mut rng = rand::thread_rng();
    let crcflag = rng.bool(0.5); // 50% chance of setting CRC flag

    let pdu = NFAPI_CRC_INDICATION_PDU_T {
        rx_ue_information_tag: 123,
        rnti: 456,
        crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG { crcflag },
    };

    tx.send(pdu).unwrap();
}

fn read_and_process(config: Config) -> Result<(), Box<dyn std::error::Error> {
    let (tx, rx) = channel::<NFAPI_CRC_INDICATION_PDU_T>(config.num_concurrent_tasks);

    let mut valid_numbers = VecDeque::new();

    let mut line = String::new();
    loop {
        let mut stdin = tokio::io::stdin();
        match stdin.read_line(&mut line).await {
            Ok(_) => {
                if let Ok(num) = line.trim().parse::<f64>() {
                    valid_numbers.push_back(num);
                }
                line.clear();
            }
            Err(e) => {
                eprintln!("Error reading input: {}", e);
                return Err(Box::new(e));
            }
        }
    }

    let mut concurrent_tasks = Vec::with_capacity(config.num_concurrent_tasks);

    for _ in 0..config.num_concurrent_tasks {
        let valid_numbers_clone = valid_numbers.clone();
        let config_clone = config;
        let tx_clone = tx.clone();
        let task = spawn(async move { process_number(valid_numbers_clone.pop_front(), &config_clone, &tx_clone) });
        concurrent_tasks.push(task);
    }

    for task in concurrent_tasks {
        task.await;
    }

    let mut sum = 0.0;
    let mut count = 0;

    for number in valid_numbers {
        sum += number;
        count += 1;
    }

    let mean = sum / count as f64;
    let standard_deviation = (count * sum * sum - sum.pow(2) * count as f64) / ((count - 1) * count as f64).sqrt();

    println!("Mean: {}", mean);
    println!("Standard Deviation: {}", standard_deviation);

    let client = Client::new();

    let req = client.post(config.url)
        .json(&json!({ "mean": mean, "std_dev": standard_deviation }))
        .cert(if config.validate_certificate { true } else { None })
