// Define the structure
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[3];
} NFAPI_CRC_INDICATION_PDU;

// Define the linked list node
typedef struct NODE {
    NFAPI_CRC_INDICATION_PDU data;
    struct NODE* next;
} Node;

// Function prototype for the callback function
typedef void (*ResourceExhaustionCallback)(const char* message);

// Custom dynamic list implementation
Node* create_list(int N, ResourceExhaustionCallback cb, unsigned int seed) {
    srand(seed);
    Node *head = NULL, *current = NULL, *new_node;

    if (N <= 0) return head; // Handle edge case: N must be a positive value

    for (int i = 0; i < N; ++i) {
        new_node = malloc(sizeof(Node));
        if (!new_node) {
            cb("Memory allocation error");
            return head; // Resource exhaustion: clean up and exit
        }
        new_node->data.CRC_INDICATION_REL8_TAG[2] = (new_node->data.RNTI + seed) % 256;
        new_node->next = NULL;

        if (!head) {
            head = current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    return head;
}

void iterate(Node *head, void (*function)(NFAPI_CRC_INDICATION_PDU*)) {
    for (Node *current = head; current != NULL; current = current->next) {
        function(&(current->data));
    }
}

// Cleanup routine
void cleanup(Node **head_ptr) {
    Node *current, *temp;

    current = *head_ptr;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }
    *head_ptr = NULL;
}
```

