use rayon::prelude::*;
use crossbeam_channel::{Sender, Receiver, unbounded};
use std::thread;
use std::ops::Deref;

#[derive(Serialize, Deserialize)]
struct Task {
    id: String,
    params: Vec<u8>,
    status: Status,
    result: Option<Vec<u8>>,
}

#[derive(Clone)]
enum Status {
    Pending,
    Running,
    Completed,
    Cancelled,
    Error,
}

struct BackgroundTaskQueue {
    task_id_map: Arc<Mutex<HashMap<String, usize>>>,
    status_vec: Arc<Mutex<VecDeque<Task>>>,
    results_vec: Arc<Mutex<VecDeque<Vec<u8>>>,
    sender: Sender<Task>,
}

impl BackgroundTaskQueue {
    fn new() -> Self {
        let (sender, receiver) = unbounded();
        let task_id_map = Arc::new(Mutex::new(HashMap::new()));
        let status_vec = Arc::new(Mutex::new(VecDeque::new()));
        let results_vec = Arc::new(Mutex::new(VecDeque::new()));
        BackgroundTaskQueue { task_id_map, status_vec, results_vec, sender }
    }

    fn submit(&self, task: Task) {
        self.task_id_map.lock().unwrap().insert(task.id.clone(), self.status_vec.lock().unwrap().len());
        let idx = self.status_vec.lock().unwrap().len();
        self.status_vec.lock().unwrap().push_back(task);

        let task_clone = task.clone();
        thread::spawn(move || {
            // Process the task and update its status and result in-place.
            let idx = task_clone.id.as_str();
            self.process_task(idx);
        });

        self.sender.send(task).unwrap();
    }

    fn process_task(&self, id: &str) {
        // Implement task processing here. This method should be updated to work with the external data source for periodic updates of task parameters.
    }

    fn get_status(&self, id: &str) -> Option<Status> {
        let lock = self.status_vec.lock().unwrap();
        let idx = *self.task_id_map.lock().unwrap().get(id)?;
        Some(lock[idx].status)
    }

    fn cancel(&self, id: &str) {
        let mut lock = self.status_vec.lock().unwrap();
        if let Some(idx) = self.task_id_map.lock().unwrap().get(id) {
            *idx = lock.len();
            for task in lock.drain(*idx..) {
                if task.id == id {
                    task.status = Status::Cancelled;
                    break;
                }
            }
        }
    }

    fn get_result(&self, id: &str) -> Option<Vec<u8>> {
        let lock = self.results_vec.lock().unwrap();
        let idx = *self.task_id_map.lock().unwrap().get(id)?;
        Some(lock[idx].clone())
    }
}
