import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.zip.CharArrayEncoder;

public class HashCombiner {
    private final List<String> strings = new ArrayList<>();

    public void add(String input) {
        if (input == null || input.length() > 1024) {
            throw new IllegalArgumentException("Input string must not be null or longer than 1024 characters.");
        }

        strings.add(input);
    }

    public BigInteger combine() throws NoSuchAlgorithmException {
        byte[] digest = MessageDigest.getInstance("MD5").digest(getCombinedString().getBytes());
        return new BigInteger(1, digest);
    }

    private String getCombinedString() {
        StringBuilder combined = new StringBuilder();
        for (String string : strings) {
            if (combined.length() > 0) {
                combined.append(" ");
            }
            combined.append(string);
        }
        return combined.toString();
    }
}
