    while (atomic_load(static_cast<volatile void**>(list->lock)) != 0) {
        sched_yield();
    }
    atomic_store(static_cast<volatile void**>(list->lock), 1);
#endif

    tail->data = data;
    tail->next = malloc(sizeof(node_t));
    if (!tail->next) {
