struct Pool {
    NetworkStat* network_stats;
    sem_t update_sem;
    size_t count;
};

void init_pool(struct Pool* pool) {
    pool->network_stats = mmap(NULL, sizeof(NetworkStat) * MAX_INTERFACES, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_SHARED, -1, 0);

    if (pool->network_stats == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&pool->update_sem, NULL);
}

void destroy_pool(struct Pool* pool) {
    munmap(pool->network_stats, sizeof(NetworkStat) * MAX_INTERFACES);
    pthread_mutex_destroy(&pool->update_sem);
}

NetworkStat* get_network_stat(struct Pool* pool, const char* ifname) {
    for (size_t i = 0; i < pool->count; ++i) {
        if (strcmp(pool->network_stats[i].ifname, ifname) == 0)
            return &pool->network_stats[i];
    }

    return NULL;
}

void update_network_stat(struct Pool* pool, const char* ifname, double packet_loss, double jitter, double latency, double bandwidth) {
    NetworkStat* stat = get_network_stat(pool, ifname);

    if (!stat) {
        stat = &pool->network_stats[pool->count];
        strcpy(stat->ifname, ifname);
        pthread_mutex_init(&stat->lock, NULL);
        pool->count++;
    }

    pthread_mutex_lock(&stat->lock);

    stat->packet_loss = packet_loss;
    stat->jitter = jitter;
    stat->latency = latency;
    stat->bandwidth = bandwidth;

    pthread_mutex_unlock(&stat->lock);
}

