} NFAPI_CRC_INDICATION_PDU_T;

typedef struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node *next;
} list_node_t;

struct signal_pipeline {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    list_node_t **elements;
    time_t threshold;
    void (*callback)(NFAPI_CRC_INDICATION_PDU_T*);
};

void init_list(struct signal_pipeline *pipe, size_t capacity, time_t threshold, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pipe->lock = PTHREAD_MUTEX_INITIALIZER;
    pipe->capacity = capacity;
    pipe->count = 0;
    pipe->threshold = threshold;
    pipe->callback = callback;

    pipe->elements = calloc(capacity, sizeof(list_node_t*));
}

void push(struct signal_pipeline *pipe, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&pipe->lock);

    if (pipe->count >= pipe->capacity) {
        // Handle resizing here
    }

    list_node_t *new_node = malloc(sizeof(list_node_t));
    new_node->data = data;
    new_node->next = NULL;

    if (pipe->elements[pipe->count] == NULL) {
        pipe->elements[pipe->count] = new_node;
    } else {
        list_node_t *last_node = pipe->elements[pipe->count];
        while (last_node->next != NULL) {
            last_node = last_node->next;
        }
        last_node->next = new_node;
    }

    data.crc_indication.crcflag = rand() % 2;
    pipe->count++;

    if (pipe->callback != NULL) {
        pipe->callback(&data);
    }

    pthread_mutex_unlock(&pipe->lock);
}

void remove_expired(struct signal_pipeline *pipe) {
    pthread_mutex_lock(&pipe->lock);

    for (size_t i = 0; i < pipe->count; ++i) {
        if (time(NULL) - pipe->elements[i]->data.creation_time > pipe->threshold) {
            list_node_t *temp = pipe->elements[i];
            pipe->elements[i] = pipe->elements[i + 1];
            free(temp);
        }
    }

    pthread_mutex_unlock(&pipe->lock);
}
