#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
    unsigned char flag;
    time_t timestamp;
    long offset;
    int key;
} Record;

typedef struct Node {
    Record data;
    struct Node* left;
    struct Node* right;
    pthread_mutex_t lock;
} Node;

struct Repository {
    Node* root;
    int threshold;
    time_t expiration;
};

// Helper function for in-order traversal with pruning
void prune(Node* node, time_t current_time) {
    if (!node) return;

    prune(node->left, current_time);

    if (node->data.flag == 0 && (current_time - node->data.timestamp) > expiration) {
        free(node);
    }

    prune(node->right, current_time);
}

void initialize_record(Record* record, long offset, int key, int threshold) {
    record->offset = offset;
    record->key = key;
    record->value = rand() % threshold;
    record->flag = 1;
    record->timestamp = time(NULL);
}

Repository* repository_init(long offset, int key, int threshold, time_t expiration) {
    Repository* repo = malloc(sizeof(Repository));
    repo->root = NULL;
    repo->threshold = threshold;
    repo->expiration = expiration;

    pthread_mutex_init(&repo->lock, NULL);
    return repo;
}

void repository_deinit(Repository* repo) {
    prune(repo->root, time(NULL));
    free(repo);
}

Node* find_node(Node* node, long offset, int key) {
    if (!node) return NULL;

    if (node->data.offset == offset && node->data.key == key) {
        return node;
    }

    pthread_mutex_lock(&node->lock);

    Node* result = find_node(node->left, offset, key);
    if (!result) {
        result = find_node(node->right, offset, key);
    }

    pthread_mutex_unlock(&node->lock);
    return result;
}

void insert(Repository* repo, Node* node, long offset, int key) {
    Node* new_node = malloc(sizeof(Node));
    initialize_record(&new_node->data, offset, key, repo->threshold);
    new_node->left = NULL;
    new_node->right = NULL;
    pthread_mutex_init(&new_node->lock, NULL);

    int compare = cmp(node, offset, key);
    if (compare < 0) {
        pthread_mutex_lock(&node->lock);
        node->left = new_node;
        pthread_mutex_unlock(&node->lock);
    } else if (compare > 0) {
        pthread_mutex_lock(&node->lock);
        node->right = new_node;
        pthread_mutex_unlock(&node->lock);
    }
}

void update(Repository* repo, Node* node, long offset, int key) {
    if (!node) return;

    if (node->data.offset == offset && node->data.key == key) {
        node->data.value = rand() % repo->threshold;
        node->data.timestamp = time(NULL);
        node->data.flag = 1;

        // Check and adjust sum of active values if necessary
        int active_sum = 0;
        Node* current = node;
        while (current) {
            if (current->data.flag == 1) {
                active_sum += current->data.value;
            }
            current = current->left;
        }

        if (active_sum > repo->threshold) {
            // Reallocate memory and update pointers
            int new_threshold = (int)(repo->threshold * 0.9);
            while (active_sum > new_threshold) {
                // Find least active node and remove it from the tree
                Node* least_active = NULL;
                int least_value = INT_MAX;
                Node* current = node;
                while (current) {
                    if (current->data.flag == 1) {
                        if (current->data.value < least_value && current->data.timestamp + current->data.value <= time(NULL)) {
                            least_active = current;
                            least_value = current->data.value;
                        }
                    }
                    current = current->left;
                }

                if (least_active) {
                    // Remove the least active node from its parent's subtree
                    Node* parent = least_active->parent;
                    int compare = cmp(parent, least_active->data.offset, least_active->data.key);
                    if (compare < 0) {
                        parent->left = least_active->right;
                    } else {
                        parent->right = least_active->left;
                    }

                    free(least_active);
                }
            }
        }
    } else {
        pthread_mutex_lock(&node->lock);
        insert(repo, node, offset, key);
        pthread_mutex_unlock(&node->lock);
    }
}

int cmp(Node* node, long offset, int key) {
    if (node->data.offset < offset || node->data.key < key) {
        return -1;
    } else if (node->data.offset > offset || node->data.key > key) {
        return 1;
    } else {
        return 0;
    }
}

int repository_active_count(Repository* repo) {
    int count = 0;
    Node* current = repo->root;
    while (current) {
        if (current->data.flag == 1) {
            count++;
        }
        current = current->left;
    }
    return count;
}

void repository_prune(Repository* repo) {
    prune(repo->root, time(NULL));
}
```

This code provides a basic implementation of the requested task, using a binary search tree for storage. It employs pthread mutexes to ensure thread safety and handles memory allocation failures gracefully. The `Repository` struct stores the root node, threshold, expiration time, and a lock for protecting the repository from concurrent modifications.

The function `initialize_record()` initializes record structures with random values within a specified range. The `repository_init()` function initializes the repository struct and creates an empty binary search tree. The `repository_deinit()` function deallocates all memory allocated by the repository upon exit.

The function `find_node()` searches for a specific node in the tree, while the functions `insert()` and `update()` add or modify records in the tree, respecting the specified threshold and handling potential data races with locks. The function `cmp()` compares a given offset and key with the current node's values to determine its position in the tree.

The function `repository_active_count()` queries the number of active records at any point, ensuring accurate counts despite concurrent modifications. The `repository_prune()` function triggers periodic pruning of inactive records, reducing memory usage over time."]

