        (*arr)[i].max_symbols = (*arr)[i].symbol_count;
        (*arr)[i].current_index = 0;
        (*arr)[i].symbols = malloc((*arr)[i].max_symbols * sizeof(void*));

        if (!(*arr)[i].symbols) {
            fprintf(stderr, "Error: Out of memory.\n");
            exit(1);
        }
    }
}

void lte_packet_array_destroy(LTE_Packet** arr) {
    for (size_t i = 0; i < *arr ? *arr : 0; ++i) {
        free((*arr)[i].symbols);
    }
    free(*arr);
    *arr = NULL;
}

void lte_packet_array_iterate(const LTE_Packet* arr, size_t len, packet_process_func proc, void* userdata) {
    for (size_t i = 0; i < len; ++i) {
        if (arr[i].current_index >= arr[i].max_symbols) continue; // Skip empty packets

        proc(&arr[i].symbols[arr[i].current_index], &arr[i].dci, &arr[i].report, userdata);
        ++arr[i].current_index;
    }
}

