```csharp
public class NFAPI_CRC_INDICATION_PDU_T
{
    public RX_UE_INFORMATION_TAG RxUeInformationTag { get; set; }
    public uint RNTI { get; set; }
    public CRC_INDICATION_REL8_TAG CrCIndicationRel8Tag { get; set; }
}

public class CRC_INDICATION_REL8_TAG
{
    public bool CRCTagFlag { get; set; }
}

public class Node<T> where T : new() // Generic linked list node type, using inheritance for specific structure type
{
    public T Data { get; set; } = new T();
    public Node<T> Next { get; set; }
}

public class LinkedListManager<T> where T : new() // Main dynamic linked list manager class
{
    private Node<T> head;
    private int count;

    public void Add(T data)
    {
        if (head == null)
            head = new Node<T> { Data = data };
        else
        {
            var current = head;
            while (current.Next != null)
                current = current.Next;
            current.Next = new Node<T> { Data = data };
        }
        count++;
    }

    public void RemoveByRNTI(uint rnti)
    {
        if (head == null) return;
        var current = head;
        if (current.Data.RNTI == rnti)
        {
            head = current.Next;
            count--;
            return;
        }
        while (current.Next != null && current.Next.Data.RNTI != rnti)
            current = current.Next;
        if (current.Next == null) return; // Element not found
        current.Next = current.Next.Next;
        count--;
    }

    public T GetByRNTI(uint rnti)
    {
        var current = head;
        while (current != null && current.Data.RNTI != rnti)
            current = current.Next;
        if (current == null) throw new Exception("Element not found"); // Element not found
        return current.Data;
    }

    public void UpdateCRCFlagByRNTI(uint rnti, bool crcFlag)
    {
        var current = head;
        while (current != null && current.Data.RNTI != rnti)
            current = current.Next;
        if (current == null) throw new Exception("Element not found"); // Element not found
        current.Data.CrCIndicationRel8Tag.CRCTagFlag = crcFlag;
    }
}
