using System;
using System.Data;
using System.Data.SqlClient;
using System.Collections.Generic;
using System.Linq;

public IDataReader ExecuteDynamicQuery(Dictionary<string, object> filters, string connectionString, string baseCommand)
{
    using (SqlConnection connection = new SqlConnection(connectionString))
    {
        SqlCommand command = new SqlCommand();
        command.Connection = connection;
        command.CommandType = CommandType.Text;

        // Initialize the command with the base SQL command
        command.CommandText = baseCommand;

        // Build the WHERE clause based on user-provided filters
        StringBuilder whereClause = new StringBuilder("WHERE ");
        bool firstFilter = true;

        foreach (KeyValuePair<string, object> filter in filters)
        {
            string column = filter.Key;
            object value = filter.Value;

            // Handle partial matches
            if (value is string partialMatch && partialMatch.Length > 0)
            {
                whereClause.Append($"{column} LIKE '@Partial{column}'");
                command.Parameters.Add($"@Partial{column}", SqlDbType.NVarChar);
            }
            // Handle date ranges
            else if (value is DateTime dateRange && dateRange != DateTime.MinValue)
            {
                DateTime startDate = dateRange.StartOfDay();
                DateTime endDate = dateRange.EndOfDay();

                whereClause.Append($"{column} >= '@From{column}' AND {column} <= '@To{column}'");
                command.Parameters.Add($"@From{column}", SqlDbType.DateTime);
                command.Parameters.Add($"@To{column}", SqlDbType.DateTime);
            }
            // Handle nested conditions (AND, OR)
            else if (value is IDictionary<string, object> nestedFilters)
            {
                // Nested filters require special handling for WHERE clause construction
                BuildNestedWhereClause(nestedFilters, whereClause);
            }
            // Handle simple equality checks
            else
            {
                whereClause.Append($"{column} = @{column}");
                command.Parameters.Add($"@{column}", SqlDbType.GetSqlType(value));
            }

            if (!firstFilter)
            {
                whereClause.Append(" AND ");
            }
            firstFilter = false;
        }

        // Add ORDER BY clause if required
        if (filters.Any(f => f.Key.StartsWith("orderBy")))
        {
            string orderColumn = filters.First(f => f.Key.StartsWith("orderBy")).Value.ToString();
            whereClause.Append($" ORDER BY {orderColumn}");
        }

        // Add OFFSET and LIMIT clauses for pagination
        if (filters.Any(f => f.Key == "offset"))
        {
            int offset = Convert.ToInt32(filters["offset"]);
            whereClause.Append($" OFFSET {offset}");

            // If a limit is also provided, add it as well
            if (filters.Any(f => f.Key == "limit"))
            {
                int limit = Convert.ToInt32(filters["limit"]);
                whereClause.Append($" LIMIT {limit}");
            }
        }

        command.CommandText += whereClause.ToString();

        connection.Open();
        return command.ExecuteReader();
    }

    void BuildNestedWhereClause(IDictionary<string, object> nestedFilters, StringBuilder whereClause)
    {
        bool firstNestedFilter = true;
        foreach (KeyValuePair<string, object> nestedFilter in nestedFilters)
        {
            string column = nestedFilter.Key;
            object value = nestedFilter.Value;

            // Handle simple equality checks within nested filters
            if (value is string equality && equality == "=")
            {
                whereClause.Append($" ({column} = @{column})");
                command.Parameters.Add($"@{column}", SqlDbType.GetSqlType(filters[column]));
            }
            // Recursively handle nested conditions within nested filters
            else if (value is IDictionary<string, object> subNestedFilters)
            {
                BuildNestedWhereClause(subNestedFilters, whereClause);
            }

            if (!firstNestedFilter)
            {
                whereClause.Append(" OR ");
            }
            firstNestedFilter = false;
        }
    }
}
