        fflush(log_file);
        pthread_mutex_unlock(&log_mutex);
    }

    return records;
}

void free_record_array(Record *records, int N) {
    if (!records || N <= 0) {
        return;
    }

    pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
    FILE *log_file = fopen("memory_log.txt", "a");

    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&log_mutex);
        fprintf(log_file, "Deallocated memory for record %d\n", i);
