void* process_input(void* arg) {
    Config* config = arg;
    struct buffer input_buf = {NULL, 0, 0};
    char c;

    // Buffer input efficiently using a ring buffer or similar
    while ((c = fgetc(stdin)) != EOF) {
        if (input_buf.pos == input_buf.cap) {
            if (realloc(&input_buf.buffer, input_buf.cap + BUFFER_SIZE) == NULL) break;
            input_buf.cap += BUFFER_SIZE;
        }

        input_buf.buffer[input_buf.pos++] = c;
    }

    int* valid_data = mmap(NULL, config->max_count * sizeof(int), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    size_t data_len = 0;

    for (size_t i = 0; i < input_buf.pos; ++i) {
        if (isdigit(input_buf.buffer[i])) {
            int num = 0, base = 1;
            for (int j = i + 1; j <= i + 9 && j < input_buf.pos; ++j) {
                if (!isdigit(input_buf.buffer[j])) break;
                num += (input_buf.buffer[j] - '0') * base;
                base *= 10;
            }

            if (config->validate(num)) {
                valid_data[(data_len)++] = num;
            }
        }
    }

    munmap(input_buf.buffer, input_buf.cap);

    // Calculate the specified statistic and log any errors
    double result = config->calc_statistic(valid_data, data_len, config->validate);
    if (data_len == 0) {
        char msg[] = "No valid integers processed.";
        log_error("%s", msg);
        printf("No valid integers processed.\n");
    } else {
        printf("%f\n", result);
    }

    munmap(valid_data, config->max_count * sizeof(int));
    pthread_exit(NULL);
}

int main(int argc, char* argv[]) {
    Config config = {
        .max_count = 100000,
        .validate = validate_even,
        .calc_statistic = avg,
        .log_error = log_error,
    };

    if (argc > 1) {
        if (!strcmp(argv[1], "--odd")) config.validate = validate_odd;
        else if (!strcmp(argv[1], "--median")) config.calc_statistic = median;
        else if (sscanf(argv[1], "%" SCNu64, &config.max_count) != 1 || config.max_count <= 0) {
            log_error("Invalid max count specified: %s", argv[1]);
            return -1;
        }
    }

    pthread_t threads[NUM_THREADS];
    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, process_input, &config)) return -1;
    }

    for (int i = 0; i < NUM_THREADS; ++i) pthread_join(threads[i], NULL);

    return 0;
}
