#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct record {
    long offset;
    int key;
    float value;
} Record;

typedef struct stat {
    int key;
    int count;
} Stat;

static pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;
static Record *records = NULL;
static Stat *stats = NULL;
static size_t capacity = 0;
static size_t num_threads = 0;
static size_t key_range = 0;

void init(size_t thread_count, size_t max_keys) {
    if (records || stats) {
        free_resources();
    }

    capacity = next_power_of_two(thread_count);
    num_threads = thread_count;
    key_range = max_keys;

    records = malloc(capacity * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        exit(1);
    }

    stats = calloc(key_range, sizeof(Stat));
    if (!stats) {
        fprintf(stderr, "Failed to allocate memory for stats\n");
        free(records);
        exit(1);
    }
}

void free_resources() {
    free(records);
    free(stats);

    records = NULL;
    stats = NULL;
    capacity = 0;
}

void *thread_func(void *arg) {
    long i = (long) arg;

    for (size_t j = i * num_threads / capacity; j < (i + 1) * num_threads / capacity; ++j) {
        pthread_rwlock_wrlock(&rwlock);
        records[j].key = rand() % key_range;
        pthread_rwlock_unlock(&rwlock);

        // Update stats in a thread-safe manner
        update_stat(records[j].key);
    }

    return NULL;
}

void update_stat(int key) {
    pthread_rwlock_rdlock(&rwlock);

    Stat *stat = &stats[key];
    ++stat->count;

    pthread_rwlock_unlock(&rwlock);
}

void run(size_t thread_count, size_t max_keys) {
    init(thread_count, max_keys);

    pthread_t threads[num_threads];

    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, thread_func, (void *) i)) {
            fprintf(stderr, "Failed to create thread\n");
            free_resources();
            exit(1);
        }
    }

    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Failed to join thread\n");
            free_resources();
            exit(1);
        }
    }

    free_resources();
}

// Helper function for finding the next power of two
size_t next_power_of_two(size_t value) {
    if (value == 0) return 1;
    size_t result = 1;
    while (result < value) result <<= 1;
    return result;
}
```

This code defines a `run()` function that initializes resources, creates threads, and handles the synchronization between them using a read-write lock. The `init()`, `free_resources()`, `thread_func()`, `update_stat()`, and helper functions like `next_power_of_two()` provide additional functionality for managing the shared data structures efficiently in a multi-threaded environment.

To handle large datasets, the code ensures that resources are allocated in a power of two fashion and optimizes memory access patterns through the use of read-write locks, which minimize lock contention. Additionally, the function gracefully degrades by properly freeing allocated resources upon completion and exiting the application when necessary.']

