typedef struct {
    int key;
    size_t offset;
} record;

void free_arrays(long* offsets, int* keys, record* records, size_t num_elements) {
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);
    if (records != NULL) free(records);
}

record* create_records(size_t num_records, size_t offset_num, size_t key_num, int min, int max) {
    long* offsets = malloc(offset_num * sizeof(long));
    int* keys = malloc((key_num + 1) * sizeof(int));
    record* records = malloc(num_records * sizeof(record));
    if (offsets == NULL || keys == NULL || records == NULL) {
        free_arrays(offsets, keys, records, 0);
        perror("Memory allocation failed\n");
        return NULL;
    }

    // Initialize offsets to zero and keys to invalid values
    memset(offsets, 0, offset_num * sizeof(long));
    memset(keys, 0xff, (key_num + 1) * sizeof(int));

    // Find distinct keys in ascending order
    size_t unique_keys = 0;
    for (size_t i = 0; i < key_num; ++i) {
        if (keys[i] != 0xff) {
            bool is_unique = true;
            for (size_t j = 0; j < unique_keys; ++j) {
                if (keys[i] == keys[unique_keys]) {
                    is_unique = false;
                    break;
                }
            }
            if (is_unique) {
                keys[unique_keys] = keys[i];
                ++unique_keys;
            }
        }
    }

    // Fill records with unique integers
    size_t key_index = 0;
    for (size_t i = 0; i < unique_keys; ++key_index) {
        keys[key_index] = min + key_index * ((max - min + 1) / unique_keys);
    }

    size_t offset_index = 0;
    for (size_t i = 0; i < num_records; ++i) {
        records[i].key = keys[offset_index];
        records[i].offset = offsets[offset_index++];
        ++offsets[key_index];
    }

    return records;
}

