// ConnectionRecordProto defines the protocol buffer for connection records

struct connection {
    google::protobuf::Message* record;
    pthread_mutex_t lock;
};

typedef struct connection connection_t;
typedef struct connection_list connection_list_t;

struct connection_list {
    gsl_list* list;
    size_t max_size;
    time_t last_save;
    pthread_mutex_t lock;
    void (*callback)(connection_record_pb*, int); // External API callback
};

// Helper functions for connection_list operations
void init_connection(connection_t* conn, const char* session_id, const char* client_ip,
                     const char* server_ip, bool status) {
    conn->record = connection_record_pb_create();
    connection_record_pb_set_session_id(conn->record, session_id);
    connection_record_pb_set_client_ip(conn->record, client_ip);
    connection_record_pb_set_server_ip(conn->record, server_ip);
    connection_record_pb_set_status(conn->record, status);
}

connection_t* get_connection_by_id(const char* session_id, const connection_list_t* list) {
    gsl_list_foreach (connection_t*, conn, list->list) {
        if (strcmp(conn->record->session_id(), session_id) == 0)
            return *conn;
    }
    return NULL;
}

void update_connection_status(const char* session_id, connection_t* conn, bool status) {
    pthread_mutex_lock(&conn->lock);
        connection_record_pb_set_status(conn->record, status);
    pthread_mutex_unlock(&conn->lock);
}

void remove_connection_by_id(const char* session_id, connection_list_t* list) {
    gsl_list* temp = NULL;
    gsl_list_foreach (connection_t*, conn, list->list) {
        if (strcmp(conn->record->session_id(), session_id) == 0) {
            if (temp)
                gsl_list_remove(list->list, temp);
            else
                temp = gsl_list_remove(list->list, *conn);
            free(conn->record);
            free(conn);
        }
    }
}

// Other functions for concurrency management, external API callback, persistence, etc.

int main() {
    // Initialize connection list with predefined records
