    list->list = gsl_list_create(_gsl_list_free);
    list->max_size = 1000000;
    list->last_save = time(NULL);
    pthread_mutex_init(&list->lock, NULL);

    // Initialize connections and start threads as needed
    ...

    return 0;
}
