bool add_to_list(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return false;

    new_node->data = data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);

    sem_wait(&list_mutex);

    // Validate frame number and timestamp
    if (data.frame_number > UINT16_MAX || data.timestamp > UINT32_MAX) {
        free(new_node);
        sem_post(&list_mutex);
        return false;
    }

    if (list_len + 1 > MAX_LIST_SIZE) {
        free(new_node);
        sem_post(&list_mutex);
        return false;
    }

    // Calculate unique ID for the structure
    data.id = ((data.ue_id << 32) | (data.frame_number << 16) | data.timestamp);

    new_node->data = data;
    new_node->next = head;
    head = new_node;
    list_len++;
    sem_post(&list_mutex);

    return true;
}

