#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

typedef struct NetworkEvent {
    time_t timestamp;
    enum EventType { EVT_TYPE_DATA, EVT_TYPE_ERROR } type;
    unsigned long id;
} NetworkEvent;

typedef struct LoggingService {
    void (*send_update)(const NetworkEvent*);
    NetworkEvent* (*get_history)(unsigned int limit);
} LoggingService;

struct DynamicArray {
    NetworkEvent** data;
    unsigned int capacity;
    unsigned int size;
};

void da_init(struct DynamicArray* array, unsigned int initial_capacity) {
    array->data = calloc(initial_capacity, sizeof(NetworkEvent*));
    array->capacity = initial_capacity;
    array->size = 0;
}

void da_add(struct DynamicArray* array, const NetworkEvent* event) {
    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->data = realloc(array->data, array->capacity * sizeof(NetworkEvent*));
    }
    array->data[array->size++] = malloc(sizeof(NetworkEvent));
    memcpy(array->data[array->size - 1], event, sizeof(NetworkEvent));
}

void da_remove_old(struct DynamicArray* array, time_t threshold) {
    for (unsigned int i = 0; i < array->size; ) {
        if (array->data[i]->timestamp <= threshold) {
            free(array->data[i]);
            memmove(&array->data[i], &array->data[i + 1], --array->size - i);
        } else {
            ++i;
        }
    }
}

void da_iterate(const struct DynamicArray* array, void (*func)(const NetworkEvent*)) {
    for (unsigned int i = array->size - 1; i != UINT_MAX; --i) {
        func(array->data[i]);
    }
}

void integrate_logging_service(struct DynamicArray* array, const LoggingService* service) {
    void send_update(const NetworkEvent* event) {
        service->send_update(event);
    }

    NetworkEvent* get_history(unsigned int limit) {
        NetworkEvent* events = calloc(limit, sizeof(NetworkEvent));
        unsigned int index = 0;
        da_iterate(array, (const NetworkEvent* event) {
            if (index < limit) {
                memcpy(&events[index++], event, sizeof(NetworkEvent));
            } else {
                break;
            }
        });
        return events;
    }

    // Replace the existing add function with the optimized version that handles logging.
    void da_add(struct DynamicArray* array, const NetworkEvent* event) {
        service->send_update(event);
        da_optimized_add(array, event);
    }

    void da_optimized_add(struct DynamicArray* array, const NetworkEvent* event) {
        if (array->size == array->capacity) {
            array->capacity *= 2;
            array->data = realloc(array->data, array->capacity * sizeof(NetworkEvent*));
        }
        array->data[array->size++] = malloc(sizeof(NetworkEvent));
        memcpy(array->data[array->size - 1], event, sizeof(NetworkEvent));
    }
}
```

