#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000

typedef struct {
    long offset;
    int key;
    int value;
} Record;

typedef struct Node {
    Record record;
    struct Node *next;
} Node;

typedef struct {
    Node **nodes;
    int capacity;
    int size;
    pthread_mutex_t mutex;
} RecordCollection;

RecordCollection* createRecordCollection(int capacity) {
    if (capacity <= 0 || capacity > MAX_RECORDS) {
        return NULL;
    }

    RecordCollection *collection = malloc(sizeof(RecordCollection));
    collection->nodes = calloc(capacity, sizeof(Node*));
    collection->capacity = capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

int addRecord(RecordCollection *collection, int key, int value, long offset) {
    if (collection == NULL || collection->size >= collection->capacity) {
        return -1; // Error: Collection is full or invalid.
    }

    pthread_mutex_lock(&collection->mutex);

    int index = offset % collection->capacity;
    Node *node = malloc(sizeof(Node));
    node->record.key = key;
    node->record.value = value;
    node->record.offset = offset;
    node->next = collection->nodes[index];
    collection->nodes[index] = node;
    ++collection->size;

    pthread_mutex_unlock(&collection->mutex);

    return 0; // Success
}

void fillRecordWithRandomValue(int *value, int min, int max, unsigned long seed) {
    *value = (rand_r(&seed) % (max - min + 1)) + min;
}

NFAPI_CRCI_INDICATION_PDU_T createNFCICRCIndicationPdu() {
    // Implementation of NFAPI_CRCI_INDICATION_PDU_T structure goes here.
}

int initializeCollection(RecordCollection *collection, unsigned long seed) {
    if (collection == NULL) {
        return -1; // Error: Invalid collection.
    }

    pthread_mutex_lock(&collection->mutex);

    for (int i = 0; i < collection->capacity; ++i) {
        Record record;
        fillRecordWithRandomValue(&record.value, 0, INT_MAX - 1, seed++);
        RecordCollectionNode *node = malloc(sizeof(RecordCollectionNode));
        node->record = record;
        node->next = collection->nodes[i];
        collection->nodes[i] = node;
    }

    pthread_mutex_unlock(&collection->mutex);

    return 0; // Success
}
