// Maximum list size
#define MAX_LIST_SIZE 10000
// Batch processing size
#define BATCH_PROCESSING_SIZE 500

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data;
    uint64_t unique_id; // Combination of UE ID, frame number, and subframe number
} list_item_t;

// Thread-safe queue
typedef struct __queue {
    list_item_t* head;
    list_item_t* tail;
    size_t length;
    sem_t sem;
} queue_t;

void init_queue(queue_t* q) {
    q->head = NULL;
    q->tail = NULL;
    q->length = 0;
    sem_init(&q->sem, 0, BATCH_PROCESSING_SIZE);
}

// Function to add an item to the queue
void enqueue(queue_t* q, list_item_t item) {
    pthread_mutex_lock(&q->head->data.crc_indication.rnti_lock); // Lock RNTI for uniqueness check
    if (validate_RNTI(item.data.rx_ue_information_tag, item.data.crc_indication.rnti)) {
        item.unique_id = get_unique_id();
        list_item_t* new_node = malloc(sizeof(list_item_t));
        new_node->data = item.data;
        new_node->unique_id = item.unique_id;

        if (q->tail == NULL) {
            q->head = new_node;
            q->tail = new_node;
        } else {
            q->tail->next = new_node;
            q->tail = new_node;
        }

        ++(q->length);
    }
    pthread_mutex_unlock(&q->head->data.crc_indication.rnti_lock);
}

list_item_t* dequeue(queue_t* q) {
    if (isEmptyQueue(q)) {
        return NULL;
    }

    list_item_t* ret = q->head;
    pthread_mutex_lock(&ret->data.crc_indication.rnti_lock); // Lock RNTI for removal
    if (ret == q->tail) {
        q->head = NULL;
        q->tail = NULL;
    } else {
        q->head = ret->next;
    }
    --(q->length);
    pthread_mutex_unlock(&ret->data.crc_indication.rnti_lock);
    return ret;
}

// Function to manage the dynamic list in a multi-threaded environment
NFAPI_CRC_INDICATION_PDU_T* manage_list(size_t* error) {
    queue_t q;
    init_queue(&q);

    // Start batch processing thread
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, batch_processor, &q) != 0) {
        *error = 1;
        return NULL;
    }

    // Process incoming structures here
    // ...

    pthread_join(thread_id, NULL);

    NFAPI_CRC_INDICATION_PDU_T* list = malloc((q.length + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (size_t i = 0; i < q.length; ++i) {
        list[i] = q.head->data;
        q.head = dequeue(&q);
    }
    free(list + q.length);

    return list;
}

void* batch_processor(void* arg) {
    queue_t* q = (queue_t*)arg;
    sem_t* sem = &q->sem;

    while (true) {
        sem_wait(sem); // Wait for new items to add to the queue

        size_t batch_size = MIN(BATCH_PROCESSING_SIZE, q->length);
        list_item_t* batch[batch_size];
        size_t i;
        for (i = 0; i < batch_size; ++i) {
            batch[i] = dequeue(q);
            if (!batch[i]) { // Processed all the items in this batch
                break;
            }
        }

        // Process the batch here, considering the high-latency, low-bandwidth network environment constraints
        // ...

        sem_post(sem); // Signal that we processed a batch of items
    }
}
```

