class WifiManager {
private:
    std::mutex mtx;
    std::vector<WIFI_PHY_RX_TARGET> targets;
    boost::circular_buffer<WIFI_RX_PACKET_INFO> packetBuffer;

public:
    void addTarget(const WIFI_TARGET_CHANNEL& channel, const WIFI_TARGET_TIMESTAMP& timestamp) {
        // Create a new target with dynamically sized WIFI_RX_PACKET_INFO array
        WIFI_PHY_RX_TARGET target = {channel, timestamp};
