    void processPackets() {
        std::unique_lock<std::mutex> lock(mtx);
        while (!packetBuffer.empty()) {
            // Process a packet and push it to the corresponding target's WIFI_RX_PACKET_INFO array
            WIFI_RX_PACKET_INFO packet = packetBuffer.front();
            for (auto& target : targets) {
                if (target.timestamp == packet.timestamp && target.channel == packet.channel) {
                    // Ensure concurrent access is safe by locking the target's WIFI_RX_PACKET_INFO array
                    std::unique_lock<std::mutex> targetLock(target.packetInfoMutex);
                    target.packetInfo.push_back(packet);
                    break;
                }
            }
            packetBuffer.pop_front();
        }
    }

    void flush() {
        std::unique_lock<std::mutex> lock(mtx);
        // Flush the packet information arrays, freeing up resources and resetting them
        for (auto& target : targets) {
            target.packetInfo.clear();
        }
    }
};
