class RateLimiter {
public:
    explicit RateLimiter(size_t threshold) : m_threshold(threshold), m_lastRequestTime() {}

    bool allowRequest(const string& ip) {
        auto now = chrono::system_clock::now();
        auto elapsed = now - m_lastRequestTime;

        if (elapsed > chrono::seconds(60)) {
            m_requestsCount.clear();
            m_lastRequestTime = now;
        }

        if (m_requestsCount.count(ip) >= m_threshold)
            return false;

        m_requestsCount[ip]++;
        m_lastRequestTime = now;
        return true;
    }
private:
    size_t m_threshold;
    time_point<system_clock> m_lastRequestTime;
    unordered_map<string, size_t> m_requestsCount;
};

