        ip_service.post([this, url, ip, cb]() {
            io_service.post([this, url, ip, cb]() mutable {
                http::async_get(http::socket(ip_service), url, transfer_all(), bind(&HttpClient::onGetCompleted, shared_from_this(), placeholders::_1, url, ip, cb));
            });
        });
    }

private:
