            var filePathWithExtension = Path.Combine(directory, fileName + ".dat");

            using (var writer = new BinaryWriter(File.OpenWrite(filePathWithExtension))) {
                writer.Write(BitConverter.GetBytes(record.isActive));
                writer.Write(BitConverter.GetBytes(record.value));
            }
        }
    }

    private string GenerateFilename(int value) {
        var baseFileName = Path.GetFileNameWithoutExtension(FilePath);
        var extension = GetFileExtension(baseFileName);
        var formattedValue = String.Format("{0:D" + minDigits + "}", value).PadLeft(maxDigits, '0');
        return string.Concat(formattedValue, extension);
