        [HttpPost]
        public async Task<IActionResult> UpdateContent([FromQuery] string sectionId, [FromQuery] string elementId, [FromBody] string content) {
            if (!ValidatesSectionAndElementIds(sectionId, elementId)) return BadRequest();

            TaskCompletionSource<bool> tcs;
            if (_cache.TryGetValue((sectionId, elementId), out tcs)) await tcs.Task;
            else {
                var result = await _contentService.UpdateContentAsync(sectionId, elementId, content);
                _cache[(sectionId, elementId)] = new TaskCompletionSource<bool>();
                _cache[(sectionId, elementId)].SetResult(result.Success);
            }

            return Ok();
