void execute_command(char command[]) {
    pid_t pid = fork();

    if (pid < 0) {
        perror("fork");
        return;
    } else if (pid == 0) {
        // Child process executes the command
        execvp(command, (char*[]) { command, NULL });
        perror("execvp");
        exit(1);
    } else {
        // Parent process adds command to list and manages it
        struct command *new_cmd = malloc(sizeof(struct command));
        strcpy(new_cmd->command, command);
        new_cmd->pid = pid;
        new_cmd->status = 0;
        new_cmd->next = command_head;
        command_head = new_cmd;
    }
}

// Logging function
void log(char message[]) {
    openlog("CDS", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "%s", message);
    closelog();
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <username>\n", argv[0]);
        return 1;
    }

    char username[256];
    strcpy(username, argv[1]);

    uid_t uid;
    gid_t gid;

    authenticate(username, &uid, &gid);

    setgid(gid);
    setuid(uid);

    char directory[256];
    sprintf(directory, "/path/to/working/directory");

    // Main loop for managing command execution, backup, and user interaction
    while (1) {
        char command[256];
        fgets(command, sizeof(command), stdin);

        if (strchr(command, '\n') == NULL) continue;

        backup(directory);
        execute_command(command);
        log(command);
    }

    return 0;
}
