            if (inputArray[i] == inputArray[j]) {
                foundDuplicate = 1;
                break;
            }
        }
        if (foundDuplicate) {
            printf("Error: Duplicate value found in the input list\n");
            free(inputArray);
            return;
        }
        ++i;
    }

    // Find and print the largest integer in the array
    unsigned int maxValue = findMax(inputArray, N);
