    // Create a linked list of NFAPI_CRC_INDICATION_PDU_T structures based on the input array
    NFAPI_CRC_INDICATION_PDU_T** pduList = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pduList) {
        perror("Memory allocation failure");
        free(inputArray);
        return;
    }

    // Allocate memory for each NFAPI_CRC_INDICATION_PDU_T structure and initialize its fields based on the input array values
    for (size_t j = 0; j < N; ++j) {
        pduList[j] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pduList[j]) {
            perror("Memory allocation failure");
            // Free previously allocated memory and exit the function
            for (size_t k = 0; k < j; ++k) {
                free(pduList[k]);
            }
            free(inputArray);
            free(pduList);
            return;
        }

        pthread_mutex_lock(dataLock);
        // Access the shared data source for generating RX_UE_INFORMATION_TAG values
        unsigned int tagValue = 0;
        if (getDataSource(&tagValue)) {
            pduList[j]->RX_UE_INFORMATION_TAG = tagValue;
        } else {
