            pduList[j]->RX_UE_INFORMATION_TAG = DEFAULT_TAG_VALUE;
        }
        pthread_mutex_unlock(dataLock);

        pduList[j]->RNTI = inputArray[j];
        pduList[j]->CRC_INDICATION_REL8_TAG = generateCRCFlag();
    }

    // Sort the linked list based on RNTI values and return it
    qsort(pduList, N, sizeof(NFAPI_CRC_INDICATION_PDU_T*), compareRNTI);

    // Transmit the processed data securely and reliably using an external network interface API
    transmitData(pduList, N);

    // Clean up dynamically allocated memory
    for (size_t k = 0; k < N; ++k) {
        free(pduList[k]);
    }
    free(pduList);
    free(inputArray);
}

// Helper function to compare two NFAPI_CRC_INDICATION_PDU_T structures based on their RNTI values for sorting purposes
int compareRNTI(const void* a, const void* b) {
    return (*(NFAPI_CRC_INDICATION_PDU_T*)a)->RNTI - (*(NFAPI_CRC_INDICATION_PDU_T*)b)->RNTI;
}
