#define RECORD_SIZE sizeof(Record)
#define CHUNK_SIZE (1024 * 1024) // 1MB chunk size for optimization

pthread_mutex_t load_mutex = PTHREAD_MUTEX_INITIALIZER;
size_t processed_records = 0, missing_entries = 0, duplicate_entries = 0, total_chunks = 0;
Record *chunks;

void *load_record(void *arg) {
    long file_pos = *(long *)arg;
    Record *current_chunk = chunks + (file_pos / CHUNK_SIZE) * CHUNK_SIZE;
    Record *curr = &current_chunk[file_pos % CHUNK_SIZE];

    if (fseek(data_file, file_pos * RECORD_SIZE, SEEK_SET)) {
        fprintf(stderr, "Error seeking file position: %ld\n", file_pos);
        return NULL;
    }

    if (fread(curr, RECORD_SIZE, 1, data_file)) {
        return curr;
    } else {
        missing_entries++;
        return NULL;
    }
}

Record *find_unique_key(int key) {
    Record *iter = chunks;
    while (iter < chunks + total_chunks * CHUNK_SIZE) {
        if (!iter->key || iter->key == key) {
            return iter;
        }
        iter++;
    }
    return NULL;
}

int main() {
    // Open the binary file and get its size
    FILE *data_file = fopen("large_file.bin", "r");
    if (!data_file) {
        perror("Error opening file");
        return 1;
    }

    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    total_chunks = (file_size / CHUNK_SIZE) + ((file_size % CHUNK_SIZE) ? 1 : 0);
    chunks = mmap(NULL, total_chunks * CHUNK_SIZE * RECORD_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    pthread_t threads[total_chunks];
    long file_pos = 0;

    for (size_t i = 0; i < total_chunks; ++i) {
        if (pthread_create(&threads[i], NULL, load_record, &file_pos)) {
            perror("Error creating thread");
            return 1;
        }
        file_pos += CHUNK_SIZE;
    }

    for (size_t i = 0; i < total_chunks; ++i) {
        void *tmp;
        pthread_join(threads[i], &tmp);

        if (!tmp) continue; // Skip missing entries

        Record *new_rec = find_unique_key(tmp->key);
        if (new_rec) { // Merge duplicate entries into existing records
            new_rec->offset = tmp->offset;
        } else { // Add unique record to the first available chunk
            new_rec = chunks;
            new_rec->key = tmp->key;
            new_rec->offset = tmp->offset;
            processed_records++;
        }
    }

    // Generate random keys for any remaining empty records
    for (Record *iter = chunks; iter < chunks + total_chunks * CHUNK_SIZE; ++iter) {
        if (!iter->key) {
            int key = rand() % MAX_KEY_VALUE;
            Record *unique = find_unique_key(key);
            while (unique) {
                key = (key + 1) % MAX_KEY_VALUE;
                unique = find_unique_key(key);
            }
            iter->key = key;
            iter->offset = rand() % MEMORY_USAGE_LIMIT;
            processed_records++;
        }
    }

    printf("Processed records: %zu\n", processed_records);
    printf("Missing entries: %zu\n", missing_entries);
    printf("Duplicate entries: %zu\n", duplicate_entries);

    // Unmap and free the memory chunks
    munmap(chunks, total_chunks * CHUNK_SIZE * RECORD_SIZE);

    return 0;
}
