```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_MEMORY_LIMIT (1024 * 1024) // Set your desired maximum memory limit here

typedef struct record {
    long offset;
    int key;
    double data;
    struct record* next;
} Record;

Record* head = NULL;
size_t current_memory_usage = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void validate() {
    Record *current = head, *temp;
    while (current != NULL) {
        temp = current->next;
        if (current->next && current_memory_usage + sizeof(Record) > MAX_MEMORY_LIMIT) {
            fprintf(stderr, "Memory error: Exceeded maximum limit.\n");
            exit(EXIT_FAILURE);
        }
        current = temp;
    }
}

void add_record(long offset, int key, double data) {
    pthread_mutex_lock(&mutex);
    validate();
    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Memory error: Failed to allocate memory.\n");
        return;
    }
    new_record->offset = offset;
    new_record->key = key;
    new_record->data = data;
    new_record->next = head;
    head = new_record;
    current_memory_usage += sizeof(Record);
    pthread_mutex_unlock(&mutex);
}

Record* find_record(int key) {
    Record *current = head;
    while (current != NULL) {
        if (current->key == key) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void modify_record(int key, double new_data) {
    Record *record = find_record(key);
    if (record != NULL) {
        record->data = new_data;
    } else {
        fprintf(stderr, "Error: Key not found.\n");
    }
}

void free_memory() {
    Record *current, *next;
    pthread_mutex_lock(&mutex);
    current = head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
    current_memory_usage = 0;
    pthread_mutex_unlock(&mutex);
}
```

