    if (!pool) return NULL;

    pool->maxMemory = maxMemory;
    pool->totalAllocated = 0;
    pool->slabs = NULL;
    pthread_mutex_init(&pool->lock, NULL);

    // Initialize slab array and allocate first slab
    size_t numSlabs = (maxMemory / sizeof(MY_SLAB_ITEM)) + 1;
    pool->slabs = calloc(numSlabs, sizeof(MY_SLAB_ITEM*));
    if (!pool->slabs) {
        free(pool);
        return NULL;
    }

    pool->slabs[0] = (MY_SLAB_ITEM*)mySlabNew(pool, maxMemory / numSlabs);
    if (!pool->slabs[0]) {
        free(pool->slabs);
        free(pool);
        return NULL;
    }

    return pool;
}
