    if (bytesRead != ciphertext_len) {
        fprintf(stderr, "Error reading file: only %lu bytes read\n", bytesRead);
        freeChunked(ciphertext, sizeof(unsigned char));
        fclose(file);
        return;
    }

    // Decrypt the ciphertext and load the records
    AES_KEY aesKey;
    AES_set_encrypt_key((const unsigned char *)key, 128, &aesKey);
    record records[MAX_RECORDS];
    int numRecords = 0;
    for (int i = 0; i < ciphertext_len - AES_BLOCK_SIZE;) {
        unsigned char iv[AES_BLOCK_SIZE];
        memcpy(iv, &ciphertext[i], AES_BLOCK_SIZE);
        i += AES_BLOCK_SIZE;

        unsigned char plaintext[AES_BLOCK_SIZE];
        aesDecrypt((unsigned char *)(&ciphertext[i]), ciphertext_len - i, (const unsigned char *)key, iv, (unsigned char *)plaintext);
        i += AES_BLOCK_SIZE;

        record* r = &records[numRecords++];
        getRecordData(r, file); // Load the offset and key fields from the binary data

        if (!validateRecord(r)) {
            continue;
        }

        r->record_value = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
        int duplicate = 0;
        for (int j = 0; j < numRecords && !duplicate; ++j) {
            if (r->key == records[j].key) {
                r->key = findUniqueKey(records, r->key, numRecords);
                duplicate = 1;
            }
        }
    }

    // Process and report on the results
    // ...

    fclose(file);
    freeChunked(ciphertext, sizeof(unsigned char));
}
