    return (rnti >= 0 && rnti <= RNTI_MAX);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(uint32_t *unique_rnti) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (pdu == NULL) {
        return NULL;
    }

    pdu->RNTI = *unique_rnti;
    srand(time(NULL));
    pdu->crc_indication.crcflag = rand() % 2; // Randomly set CRCFLAG value

    *unique_rnti += 1; // Increment the RNTI for uniqueness

    return pdu;
}

NFAPI_CRC_INDICATION_PDU_T** allocate_pdus(int N, pthread_rwlock_t *rwlock) {
    NFAPI_CRC_INDICATION_PDU_T **pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (pdus == NULL) {
        perror("Failed to allocate memory for pdus array");
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        pthread_mutex_t mutex;
        init_mutex(&mutex);
        pdus[i] = create_pdu(&pdus[i][0]);

        if (pdus[i] == NULL) {
            perror("Failed to allocate memory for pdu");
            return NULL;
        }

        pthread_rwlock_wrlock(rwlock);
        // Implement a mechanism to handle uniqueness of RNTI values within the array.
        int j = i - 1;
        while (j >= 0 && pdus[j] != NULL) {
            if (pdus[i]->RNTI == pdus[j]->RNTI) {
                free(pdus[i]);
                pdus[i] = NULL;
                break;
            }
            --j;
        }
        pthread_rwlock_unlock(rwlock);
    }

    return pdus;
}

void deallocate_pdus(NFAPI_CRC_INDICATION_PDU_T **pdus, int N) {
    for (int i = 0; i < N; ++i) {
        if (pdus[i] != NULL) {
            free(pdus[i]);
            pdus[i] = NULL;
        }
    }

    free(pdus);
}

