#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    PDU_DATA_REL8_TAG pdu_data;
} NFAPI_RX_PDU_T;

typedef struct AllocPool {
    size_t chunk_size;
    NFAPI_RX_PDU_T* pool;
    size_t used;
    pthread_mutex_t lock;
} AllocPool;

AllocPool* create_pool(size_t chunk_size) {
    AllocPool *pool = malloc(sizeof(AllocPool));
    if (!pool) return NULL;

    pool->chunk_size = chunk_size;
    pool->used = 0;
    pool->lock = PTHREAD_MUTEX_INITIALIZER;

    pool->pool = calloc(chunk_size, sizeof(NFAPI_RX_PDU_T));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    return pool;
}

NFAPI_RX_PDU_T* alloc_from_pool(AllocPool *pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used < pool->chunk_size) {
        NFAPI_RX_PDU_T *pdu = &pool->pool[pool->used];
        ++pool->used;
        pthread_mutex_unlock(&pool->lock);
        return pdu;
    }

    pthread_mutex_unlock(&pool->lock);

    NFAPI_RX_PDU_T *new_pool = realloc(pool->pool, sizeof(NFAPI_RX_PDU_T) * (2 * pool->chunk_size));
    if (!new_pool) return NULL;

    memmove(&pool->pool[pool->used], &pool->pool[0], pool->used * sizeof(NFAPI_RX_PDU_T));

    AllocPool* new_pool_ptr = realloc(pool, sizeof(AllocPool) + (sizeof(NFAPI_RX_PDU_T) * (2 * pool->chunk_size)));
    if (!new_pool_ptr) {
        free(new_pool);
        return NULL;
    }

    pool = new_pool_ptr;
    pool->chunk_size *= 2;
    pool->pool = new_pool;

    NFAPI_RX_PDU_T *pdu = &pool->pool[pool->used];
    ++pool->used;

    return pdu;
}

void free_pool(AllocPool *pool) {
    free(pool->pool);
    free(pool);
}

// External configuration module interface
extern size_t get_N();
extern int get_min_payload_len();
extern int get_max_payload_len();

NFAPI_RX_PDU_T* create_array(size_t N) {
    AllocPool *pool = create_pool(16); // Initial chunk size
    if (!pool) return NULL;

    NFAPI_RX_PDU_T *array = malloc(N * sizeof(NFAPI_RX_PDU_T));
    if (!array) {
        free_pool(pool);
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        array[i] = *(alloc_from_pool(pool));
    }

    // Initialize RX_UE_INFORMATION_TAG, RNTI, and payload with random values within specified ranges
    for (size_t i = 0; i < N; ++i) {
        array[i].rx_ue_info.tag = rand() % MAX_RX_UE_INFO_TAGS;
        array[i].rnti.rnti = rand() % MAX_RNTIs;
        array[i].pdu_data.length = rand() % (get_max_payload_len() - get_min_payload_len()) + get_min_payload_len();
    }

    return array;
}

// Free the allocated memory when no longer needed
void free_array(NFAPI_RX_PDU_T *array, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        // Clean up the pool allocator
        if (&array[i] == *(alloc_from_pool(NULL))) {
            free_from_pool((NFAPI_RX_PDU_T*)&array[i]);
        }
    }

    free(array);
}

// Free a single PDUs from the pool allocator
void free_from_pool(NFAPI_RX_PDU_T *pdu) {
    pthread_mutex_lock(&pool->lock);

    if (pdu >= pool->pool && pdu < pool->pool + pool->used) {
        memmove(pdu, pdu + 1, (pool->used - (pdu - pool->pool)) * sizeof(NFAPI_RX_PDU_T));
        --pool->used;
    }

    pthread_mutex_unlock(&pool->lock);
}
```
This code provides a C function for dynamically allocating an array of `N` `NFAPI_RX_PDU_T` structures, each containing a valid `RX_UE_INFORMATION_TAG`, `RNTI`, and a corresponding `PDU_DATA_REL8_TAG` with a payload length randomly set within the specified range. The function utilizes a pool allocator to manage memory efficiently and minimize fragmentation while handling potential allocation failures gracefully. The implementation supports integration with an external configuration module for runtime parameterization, and proper cleanup of resources is ensured when no longer needed.']

