use chrono::Utc;
use reqwest::Client;
use serde::{Deserialize, Serialize};
use std::collections::{HashMap, HashSet};
use redis::{ConnectionPool, FromRedisValue};
use parking_lot::{Mutex, RwLock};

type Config = NetworkConfig { mac_addr: String, ip_addr: String, vlan_tags: HashSet<u16> };
type ConfigMap = HashMap<String, Config>;

#[derive(Serialize, Deserialize)]
struct ApiResponse {
    mac_addr: String,
    ip_addr: String,
    vlan_tags: Vec<u16>,
}

async fn validate_config(config: &Config, api_client: &Client) -> Result<(), ()> {
    let response = api_client.get(&format!("http://api/validate/{}&{}", config.mac_addr, config.ip_addr))
        .send()
        .await?
        .json::<ApiResponse>()
        .await?;

    if config == &response {
        Ok(())
    } else {
        Err(())
    }
}

struct NetworkConfigManager {
    cache: RwLock<ConfigMap>,
    api_client: Client,
    redis_pool: ConnectionPool,
}

impl NetworkConfigManager {
    async fn new(api_url: &str) -> Self {
        let client = reqwest::Client::new();
        let pool = redis::ConnectionPool::new(redis::Url::parse_from_uri("redis://localhost").unwrap()).unwrap();
        NetworkConfigManager {
            cache: RwLock::new(HashMap::new()),
            api_client: client,
            redis_pool,
        }
    }

    async fn insert(&self, config: Config) -> Result<(), ()> {
        let mut cache = self.cache.write();

        // Validate the configuration with the external API and log the result if successful.
        if validate_config(&config, &self.api_client).await?.is_ok() {
            log::info!("Inserted configuration: {} {}", config.mac_addr, config.ip_addr);
        } else {
            log::error!("Failed to insert configuration: {} {}", config.mac_addr, config.ip_addr);
            return Err(());
        }

        // Save the configuration in Redis for persistence and caching.
        let key = config.mac_addr.clone();
        if let Ok(mut redis_client) = self.redis_pool.get().await {
            redis_client.set(&key, &serde_json::to_string(&config).unwrap()).await?;
        }

        cache.insert(key, config);
        Ok(())
    }
}
