#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 1000

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    struct _NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU;

typedef struct {
    NFAPI_CRC_INDICATION_PDU **list;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} ListManager;

void init_list(ListManager *manager) {
    manager->count = 0;
    manager->capacity = MAX_ENTRIES;
    manager->list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU *) * manager->capacity);
    memset(manager->list, 0, sizeof(NFAPI_CRC_INDICATION_PDU *) * manager->capacity);
    pthread_mutex_init(&manager->mutex, NULL);
}

void push(ListManager *manager, NFAPI_CRC_INDICATION_PDU *pdu) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count == manager->capacity) {
        printf("List is full, discarding entry.\n");
        free(pdu);
    } else {
        size_t index = manager->count % manager->capacity;
        pdu->crc_indication.crcflag = rand();
        manager->list[index] = pdu;
        manager->count++;
    }
    pthread_mutex_unlock(&manager->mutex);
}

void clear(ListManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->capacity; ++i) {
        NFAPI_CRC_INDICATION_PDU *temp = manager->list[i];
        while (temp != NULL) {
            NFAPI_CRC_INDICATION_PDU *next = temp->next;
            free(temp);
            temp = next;
        }
    }
    memset(manager->list, 0, sizeof(NFAPI_CRC_INDICATION_PDU *) * manager->capacity);
    manager->count = 0;
    pthread_mutex_unlock(&manager->mutex);
}
