class Page {
private:
    std::list<std::string> sections;
    std::mutex sectionsMutex;
    Service* service;

public:
    Page(Service* s) : service(s) {}

    void updatePageElement(const std::string& sectionID, const std::string& elementID, const std::string& content) {
        std::unique_lock<std::mutex> lock(sectionsMutex);
        auto it = sections.begin();
        bool foundSection = false;
        while (it != sections.end() && !foundSection) {
            if ((*it) == sectionID) {
                foundSection = true;
                it = sections.begin(); // Reset iterator to find the element within the current section

                auto elmIt = std::find_if(it, sections.end(), [&](const std::string& s) { return s == (sectionID + ":" + elementID); });
                if (elmIt != sections.end()) {
                    *elmIt = content;
                } else {
                    it = sections.insert(it, sectionID + ":" + elementID + "=" + content);
                }
            }
            ++it;
        }

        if (!foundSection) {
            sections.push_back(sectionID + ":" + elementID + "=" + content);
        }

        std::future<void> updateResult = service->asyncUpdate(sectionID, elementID, content);
        if (updateResult.wait_until(std::chrono::system_clock::now() + std::chrono::seconds(5)) == std::future_status::timeout) {
            // Handle timeout gracefully...
        } else {
            updateResult.get();
        }
    }
};
