#define MAX_LIST_SIZE (1024)
#define ENTRY_SIZE (sizeof(NFAPI_CRC_INDICATION_PDU_T))

static NFAPI_CRC_INDICATION_PDU_T list[MAX_LIST_SIZE];
static size_t head = 0;
static size_t tail = 0;
static size_t count = 0;
static uint32_t rolling_average = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_entry(NFAPI_CRC_INDICATION_PDU_T *entry) {
    if (count >= MAX_LIST_SIZE) {
        return; // List is full, do not add entry
    }
    pthread_mutex_lock(&mutex);
    if (++tail == MAX_LIST_SIZE) {
        tail = 0;
    }
    list[tail] = *entry;
    list[tail].CRCFLAG = rand() % 2; // Set CRCFLAG to random value
    rolling_average = ((rolling_average * count + list[tail].CRCFLAG) / (count + 1));
    count++;
    pthread_mutex_unlock(&mutex);
}

void remove_oldest() {
    pthread_mutex_lock(&mutex);
    if (count > 0 && head != tail) { // Check if list is not empty and not circular
        head++;
        if (head == MAX_LIST_SIZE) {
            head = 0;
        }
        count--;
    }
    pthread_mutex_unlock(&mutex);
}
