class FileLoader {
  constructor(directory, maxConcurrentOperations = 5000) {
    this.directory = directory;
    this.maxConcurrentOperations = maxConcurrentOperations;
    this.queue = async.queue((file, callback) => {
      const fullPath = path.join(this.directory, file);
      fs.readFile(fullPath, 'utf8')
        .then(content => {
          // Handle external data sources here
          content = resolveExternalResources(content);
          callback(null, content);
        })
        .catch(error => {
          logError(`Failed to read file: ${file}: ${error.message}`);
          callback(error);
        });
    }, { concurrencyLimit: this.maxConcurrentOperations });
  }

  loadFiles() {
    const self = this;
    return new Promise((resolve, reject) => {
      chokidar.watch(this.directory, { persistent: true }).on('add', file => {
        self.queue.push(file);
      });

      let result = [];
      self.queue.drain(() => {
        result = result.concat(self.queue.length === 0 ? result : [...result, ...self.queue]);
        if (result.length === chokidar.getWatcher().getWatchingFiles().length) {
          resolve(result);
        }
      });
    });
  }
}

