#include <pthread.h>
#include <semaphore.h>

typedef struct {
    int offset;
    char key[64];
    char metadata[64];
} Record;

struct Buffer {
    Record* buffer;
    size_t capacity;
    size_t count;
    sem_t full, empty;
};

void init_buffer(struct Buffer* buffer, size_t size) {
    buffer->capacity = size;
    buffer->count = 0;
    buffer->buffer = malloc(sizeof(Record) * size);
    sem_init(&buffer->empty, 0, buffer->capacity);
    sem_init(&buffer->full, 0, 0);
}

void push_buffer(struct Buffer* buffer, Record record) {
    sem_wait(&buffer->empty);
    memcpy(&buffer->buffer[buffer->count], &record, sizeof(Record));
    ++buffer->count;
    sem_post(&buffer->full);
}

Record pop_buffer(struct Buffer* buffer) {
    Record record;
    sem_wait(&buffer->full);
    memcpy(&record, &buffer->buffer[--buffer->count], sizeof(Record));
    sem_post(&buffer->empty);
    return record;
}

void worker(void* arg, struct Buffer* buffer) {
    while (1) {
        // Receive external data and process it here
        Record record = process_data();
        push_buffer(buffer, record);
    }
}

int main() {
    size_t num_records = 10000;
    struct Buffer buffer;
    pthread_t* threads = malloc(sizeof(pthread_t) * num_threads);

    init_buffer(&buffer, num_records);

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_create(threads + i, NULL, worker, &buffer);
    }

    // Process the filled records in parallel

    return 0;
}
