} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRCI_INDICATION_PDU_T* data;
    struct Node* next;
} Node;

struct ThreadSafeQueue {
    Node* head;
    Node* tail;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t not_empty;
};

ThreadSafeQueue* create_threadsafe_queue(size_t initial_capacity) {
    ThreadSafeQueue* queue = malloc(sizeof(ThreadSafeQueue));
    if (!queue) return nullptr;

    queue->head = queue->tail = nullptr;
    queue->capacity = initial_capacity;
    queue->size = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->not_empty, NULL);

    return queue;
}

bool is_full(const ThreadSafeQueue* queue) {
    return queue->size == queue->capacity;
}

void enqueue(ThreadSafeQueue* queue, NFAPI_CRCI_INDICATION_PDU_T* data) {
    Node* newNode = malloc(sizeof(Node));
    if (!newNode) return;

    newNode->data = data;
    newNode->next = nullptr;

    pthread_mutex_lock(&queue->mutex);

    if (is_full(queue)) {
        free(newNode);
        pthread_mutex_unlock(&queue->mutex);
        return;
    }

    if (!queue->head) {
        queue->head = newNode;
        queue->tail = queue->head;
    } else {
        queue->tail->next = newNode;
        queue->tail = newNode;
    }

    ++(queue->size);
    pthread_mutex_unlock(&queue->mutex);

    // Wake up a waiting thread (if any) since there is data available now.
    pthread_cond_signal(&queue->not_empty);
}

NFAPI_CRCI_INDICATION_PDU_T* dequeue(ThreadSafeQueue* queue) {
    Node* temp;
    NFAPI_CRCI_INDICATION_PDU_T* data = nullptr;

    pthread_mutex_lock(&queue->mutex);

    if (isEmpty(queue)) {
        pthread_mutex_unlock(&queue->mutex);
        return nullptr;
    }

    data = queue->head->data;
    temp = queue->head;
    queue->head = queue->head->next;

    if (!queue->head) {
        queue->tail = nullptr;
    }

    free(temp);
    --(queue->size);
    pthread_mutex_unlock(&queue->mutex);

    return data;
}

bool isEmpty(const ThreadSafeQueue* queue) {
    return !queue || !queue->head;
}

// Function to populate a dynamic list of NFAPI_CRCI_INDICATION_PDU_T structures.
void populate_list(ThreadSafeQueue* queue, size_t num_elements) {
    for (size_t i = 0; i < num_elements; ++i) {
        NFAPI_CRCI_INDICATION_PDU_T* data = malloc(sizeof(NFAPI_CRCI_INDICATION_PDU_T));
        if (!data) continue; // handle error gracefully, e.g., by logging or notifying an error handler

        // Initialize the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG fields here

        enqueue(queue, data);
    }
}
