#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    double data;
} Record;

struct MemoryManager {
    Record *data;
    size_t capacity;
    size_t size;
    size_t chunk_size;
    size_t num_reallocations;
    pthread_mutex_t mutex;
    FILE *log_file;
};

void log_event(struct MemoryManager *mm, const char *message) {
    time_t now = time(NULL);
    char log_entry[50];
    snprintf(log_entry, sizeof(log_entry), "%s\n", message);
    fprintf(mm->log_file, "%s%lu", ctime(&now), (long)mm->num_reallocations++);
    fwrite(log_entry, 1, strlen(log_entry), mm->log_file);
}

struct MemoryManager *create_memory_manager(size_t initial_chunk_size) {
    struct MemoryManager *mm = malloc(sizeof(*mm));
    mm->data = NULL;
    mm->capacity = 0;
    mm->size = 0;
    mm->chunk_size = initial_chunk_size;
    mm->num_reallocations = 0;
    pthread_mutex_init(&mm->mutex, NULL);
    FILE *log_file = fopen("memory_manager.log", "w");
    if (log_file == NULL) {
        perror("failed to open log file");
        exit(EXIT_FAILURE);
    }
    mm->log_file = log_file;
    return mm;
}

void destroy_memory_manager(struct MemoryManager *mm) {
    if (mm == NULL) return;
    free(mm->data);
    fclose(mm->log_file);
    pthread_mutex_destroy(&mm->mutex);
    free(mm);
}

Record* allocate_data(struct MemoryManager *mm, size_t size) {
    void *ptr = mmap(NULL, size * sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_data(struct MemoryManager *mm, void *ptr) {
    if (munmap(ptr, mm->chunk_size * sizeof(Record)) == -1) {
        perror("failed to free memory");
        exit(EXIT_FAILURE);
    }
}

void validate_memory(struct MemoryManager *mm) {
    void *base = mm->data;
    size_t n = mm->size / sizeof(Record);
    for (size_t i = 0; i < n; ++i) {
        Record *r = base + i;
        if ((long)r & 1 || r->offset % sizeof(Record) != 0) {
            fprintf(stderr, "memory corruption detected\n");
            exit(EXIT_FAILURE);
        }
    }
}

int insert_record(struct MemoryManager *mm, const Record *new_rec) {
    pthread_mutex_lock(&mm->mutex);
    if (mm->size + sizeof(Record) > mm->capacity) {
        size_t new_capacity = mm->capacity ? mm->capacity * 2 : mm->chunk_size;
        Record *new_data = allocate_data(mm, new_capacity);
        memcpy(new_data, mm->data, mm->size);
        free_data(mm, mm->data);
        mm->data = new_data;
        mm->capacity = new_capacity;
    }
    Record *r = mm->data + mm->size / sizeof(Record);
    memcpy(r, new_rec, sizeof(*new_rec));
    r->offset = mm->size;
    mm->size += sizeof(Record);
    log_event(mm, "inserted record with key:");
    printf("%d\n", r->key);
    validate_memory(mm);
    pthread_mutex_unlock(&mm->mutex);
    return 0;
}

int delete_record(struct MemoryManager *mm, long offset) {
    pthread_mutex_lock(&mm->mutex);
    if (offset >= mm->size || (long)(mm->data + offset / sizeof(Record)) != offset) {
        fprintf(stderr, "deleting non-existent record\n");
        exit(EXIT_FAILURE);
    }
    size_t n = mm->size / sizeof(Record);
    Record *r = mm->data + (offset / sizeof(Record));
    memcpy(r, r + 1, (n - offset / sizeof(Record)) * sizeof(Record));
    memset(r + (n - offset / sizeof(Record)), 0, sizeof(Record));
    mm->size -= sizeof(Record);
    log_event(mm, "deleted record with offset:");
    printf("%ld\n", r->offset);
    validate_memory(mm);
    pthread_mutex_unlock(&mm->mutex);
    return 0;
}
```

