function manageUserRequest() {
    header('Content-Type: application/json');

    $data = json_decode(file_get_contents('php://input'), true);

    if (!isset($data['name'], $data['email'], $data['password'], $data['sub_action']) || !is_numeric($data['id'])) {
        echo json_encode(['message' => 'error', 'error_message' => 'Invalid request data']);
        exit;
    }

    $userData = [
        'name' => filter_var($data['name'], FILTER_SANITIZE_STRING),
        'email' => filter_var($data['email'], FILTER_VALIDATE_EMAIL),
        'password' => password_hash($data['password'], PASSWORD_DEFAULT)
    ];

    $db = new mysqli('host', 'username', 'password', 'database');
    $cache = new Redis();

    if ($db->connect_error) {
        echo json_encode(['message' => 'error', 'error_message' => $db->connect_error]);
        exit;
    }

    $cacheKey = 'user:' . $data['email'];
    $cachedUserData = $cache->get($cacheKey);

    if ($cachedUserData) {
        $userData = json_decode($cachedUserData, true);
    } else {
        $db->begin_transaction();
        try {
            $query = $db->prepare("SELECT * FROM users WHERE email=? LIMIT 1");
            $query->bind_param('s', $data['email']);
            $query->execute();
            $result = $query->get_result();

            if ($result->num_rows > 0) {
                $userData = $result->fetch_assoc();
            } else {
                $query = $db->prepare("INSERT INTO users (name, email, password) VALUES (?, ?, ?)");
                $query->bind_param('sss', $userData['name'], $userData['email'], $userData['password']);
                $query->execute();
                $userId = $db->insert_id;
                $userData['id'] = $userId;
            }

            if (empty($data['id'])) {
                $cache->setex($cacheKey, 60, json_encode($userData)); // Cache user data for 1 minute
            }

            $db->commit();
        } catch (Exception $e) {
            $db->rollback();
            echo json_encode(['message' => 'error', 'error_message' => $e->getMessage()]);
            exit;
        }
    }

    if (isset($data['id'])) { // Update user account
        $query = $db->prepare("UPDATE users SET name=?, email=?, password=? WHERE id=?");
        $query->bind_param('sssi', $userData['name'], $userData['email'], $userData['password'], $data['id']);
        $query->execute();
    } elseif ($data['sub_action'] === 'delete') { // Delete user account
        $query = $db->prepare("DELETE FROM users WHERE id=?");
        $query->bind_param('i', $data['id']);
        $query->execute();
        echo json_encode(['message' => 'success']);
        exit;
    } else { // Create new user account
        echo json_encode($userData);
    }
}
