                SoftReference<Config> ref = new SoftReference<>(config);
                configCache.putIfAbsent(url, ref);
                return ref.get();
            } catch (IOException e) {
                retries--;
                if (retries == 0) {
                    System.err.println("Failed to load configuration after all retries");
                    e.printStackTrace();
                } else {
                    long backoff = Math.min((long) Math.pow(2, retries), 1000);
                    try {
