angular.module('dialogService', []).factory('DialogService', function ($timeout, $q) {
    var cache = {},
        timeoutID;

    function DialogField(fieldName, fieldType, currentValue) {
        this.name = fieldName;
        this.type = fieldType;
        this.value = currentValue;
    }

    function refreshFields(resourceId, url, fieldNames, successCallback, failureCallback) {
        var deferred = $q.defer();

        // Cache the request for a short duration to prevent redundant calls
        if (cache[resourceId]) {
            setTimeout(function () {
                cache[resourceId] = undefined;
                refreshFields(resourceId, url, fieldNames, successCallback, failureCallback);
            }, 1000);
            return deferred.promise;
        }

        // Find all matching dialog fields and construct messages for processing
        var messages = [];
        angular.element(document.querySelectorAll('dialogField')).each(function () {
            if (fieldNames.indexOf(this.name) > -1) {
                messages.push({
                    name: this.name,
                    type: this.type,
                    value: this.value
                });
            }
        });

        // Send the messages to the parent window for processing
        window.parent.postMessage({ resourceId: resourceId, messages: messages }, url);

        timeoutID = $timeout(function () {
            deferred.reject('Refresh timed out');
        }, 5000);

        return deferred.promise
            .then(function (result) {
                angular.element(document.querySelectorAll('dialogField')).each(function () {
                    if (result[this.name] !== undefined) {
                        this.value = result[this.name];
                    }
                });
                successCallback && successCallback();
            })
            .catch(function (error) {
                console.error('Error refreshing fields:', error);
                failureCallback && failureCallback(error);
                clearTimeout(timeoutID);
            });
    }

    return {
