    root.asyncData = mockAsyncData;
    const mockCallback = sinon.spy((node, type, key) => {
      if (type === 'asyncData' && key === undefined) return true;
    });

    await traverseDom('.div', mockCallback);
    expect(mockCallback.callCount).to.equal(1);
    expect(mockCallback.args[0][0]).to.equal(root);
  });

  it('should work alongside third-party libraries and avoid side effects', () => {
