    const mockCallback = sinon.spy(() => {
      // Trigger a side effect in the third-party library
      MockLibrary.selectElements.apply(null, ['[data-test]']);
    });

    traverseDom('.div', mockCallback);
    expect(mockCallback.calledOnce).to.be.true;
    expect(MockLibrary.initialize.callCount).to.equal(1); // Ensure the library was only initialized once
  });
});
