char* processString(const char* input, size_t maxLength, bool truncate, char (*truncationFunc)(const char*, size_t)) {
    if (!input) return NULL;

    size_t inputLen = strlen(input);
    if (inputLen <= maxLength && !truncate) {
        char* result = malloc(inputLen + 1);
        strcpy(result, input);
        result[inputLen] = '/';
        return result;
    } else if (inputLen > maxLength && truncate) {
        size_t truncatedLen = truncationFunc(input, maxLength);
        char* result = malloc(truncatedLen + 1);
        strncpy(result, input, truncatedLen);
        result[truncatedLen] = '\0';
        return result;
    } else {
        return NULL;
    }
}

char* myTruncationFunc(const char* str, size_t maxLength) {
    if (!str || maxLength == 0) return NULL;

    char* truncatedStr = malloc((maxLength - 1) * sizeof(char));
    if (!truncatedStr) return NULL;

    size_t len = strlen(str);
    strncpy(truncatedStr, str, maxLength - 1);
    truncatedStr[maxLength - 1] = '\0';

    return truncatedStr;
}
```

