#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/mman.h>
#include <openssl/aes.h>
#include <stdbool.h>

typedef struct {
    uint32_t rxUeInformationTag;
    uint16_t rnti;
    bool crcFlag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} NFAPI_CRC_QUEUE_T;

void processNfaapiCrcIndications(NFAPI_CRC_QUEUE_T* queue, const char* encKeyFile, const char* ivFile) {
    FILE* keyFile = fopen(encKeyFile, "r");
    FILE* ivFilePtr = fopen(ivFile, "r");
    if (!keyFile || !ivFilePtr) {
        printf("Error loading encryption data\n");
        return;
    }

    unsigned char key[AES_BLOCK_SIZE];
    unsigned char iv[AES_BLOCK_SIZE];
    fread(key, sizeof(key), 1, keyFile);
    fread(iv, sizeof(iv), 1, ivFilePtr);

    AES_KEY aesKey;
    AES_set_encrypt_key(key, 256, &aesKey);

    size_t uniqueKeys[10000] = { 0 }; // Assuming max key count is 10,000
    size_t availableKeysCount = 0;

    while (!feof(keyFile) && !feof(ivFilePtr)) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = mmap(NULL, sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (!pdu) {
            printf("Error allocating memory for PDU\n");
            break;
        }

        pdu->rxUeInformationTag = rand() % 0xFFFFFFFF;
        pdu->rnti = rand() % 0xFFFF;
        pdu->crcFlag = rand() & 1;

        unsigned char ciphertext[AES_BLOCK_SIZE];
        memcpy(ciphertext, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        AES_cbc_encrypt(ciphertext, ciphertext, sizeof(ciphertext), &aesKey, iv, AES_ENCRYPT);

        size_t keyValue;
        bool found = false;
        for (size_t i = 0; i < availableKeysCount; ++i) {
            if (ciphertext[0] == uniqueKeys[i]) {
                keyValue = uniqueKeys[i];
                found = true;
                break;
            }
        }

        if (!found) {
            keyValue = availableKeysCount++;
            uniqueKeys[keyValue] = ciphertext[0];
        }

        pdu->data[(size_t)(ciphertext[1]) & 0xFFFF] = keyValue; // Set the integer value as random number within a specified range, ensuring no two records share the same key value.

        pthread_mutex_lock(&queue->lock);
        if (queue->count < queue->capacity) {
            queue->data[queue->count++] = pdu;
        } else {
            free(pdu); // Free the PDUs that could not be added to the queue due to reaching maximum capacity.
        }
        pthread_mutex_unlock(&queue->lock);
    }

    fclose(keyFile);
    fclose(ivFilePtr);

    munmap(key, sizeof(key));
    munmap(iv, sizeof(iv));
}
```

