            free(newTarget->rxSubframeInfo);
            free(newNode);
            break;
        }

        logMemoryUsage(numSubframesPerTarget);

        pthread_mutex_lock(&listMutex);
        newNode->next = head;
        head = newNode;
        numTargets++;
        pthread_mutex_unlock(&listMutex);
    }
}

LTE_PHY_RX_TARGET* getTarget() {
    LTE_PHY_RX_TARGET_NODE* current = head;
    pthread_mutex_lock(&listMutex);
    if (current == NULL) {
        pthread_mutex_unlock(&listMutex);
        return NULL;
    }
    head = current->next;
    LTE_PHY_RX_TARGET* target = &(current->target);
    numTargets--;
    pthread_mutex_unlock(&listMutex);
    return target;
}

void returnTarget(LTE_PHY_RX_TARGET* target) {
    LTE_PHY_RX_TARGET_NODE* current = head;
    LTE_PHY_RX_TARGET_NODE* prev = NULL;

    pthread_mutex_lock(&listMutex);
    while (current != NULL && current->target.timeInstance < target->timeInstance) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        // Target not found in the list, ignore it.
        pthread_mutex_unlock(&listMutex);
        return;
    }

    if (prev == NULL) {
        head = current->next;
    } else {
        prev->next = current->next;
    }

    numTargets--;

    // Update cache based on the returned target and adjust memory allocation strategies accordingly.
    cacheAdjust(current->dataCache, target->rxSubframeInfo, numSubframesPerTarget);

    pthread_mutex_unlock(&listMutex);
}

void deallocateTargetList() {
    LTE_PHY_RX_TARGET_NODE* current = head;
    while (current != NULL) {
        LTE_PHY_RX_TARGET_NODE* temp = current;
        current = current->next;
        free(temp->target.rxSubframeInfo);
        free(temp->dataCache);
        free(temp);
    }
    head = NULL;
}
