    new_task->TaskID = task_id;
    new_task->TaskName = strdup(task_name);
    pthread_mutex_init(&new_task->task_lock, NULL);
    new_task->resources = NULL;
    new_task->resource_count = 0;
    return new_task;
}

// Function to add a Resource to the given ProjectTask
void add_resource(ProjectTask *task, const char *role, const char *availability, const char *description) {
    Resource *new_resource = malloc(sizeof(Resource));
    new_resource->Role = strdup(role);
    new_resource->Availability = strdup(availability);
    new_resource->ResourceDescription = NULL;
    pthread_mutex_init(&new_resource->resource_lock, NULL);

    // Fetch ResourceDescription asynchronously and store it in the Resource structure
    fetch_resource_description(new_resource);

    pthread_mutex_lock(&task->task_lock);

    new_resource->ResourceDescription = strdup(description);
    if (!task->resources) {
        task->resources = new_resource;
        task->resource_count++;
    } else {
        Resource *last = task->resources;
        while (last->next) last = last->next;
        last->next = new_resource;
        task->resource_count++;
    }

    pthread_mutex_unlock(&task->task_lock);
}

// Cleanup function for a ProjectTask, freeing its resources and self
void destroy_project_task(ProjectTask *task) {
    Resource *current = task->resources;
    Resource *next;

    pthread_mutex_lock(&task->task_lock);
    while (current) {
        next = current->next;
        free(current->Role);
        free(current->Availability);
        free(current->ResourceDescription);
        free(current);
        current = next;
    }
    task->resources = NULL;
    task->resource_count = 0;
    pthread_mutex_destroy(&task->task_lock);
    free(task->TaskName);
    free(task);
}
