typedef struct Record {
    int key;
    int value;
    long offset;
};

typedef struct HashNode {
    struct Record record;
    struct HashNode* next;
} HashNode;

HashNode** createHashTable(unsigned int size) {
    HashNode **table = malloc(sizeof(HashNode*) * size);
    for (unsigned int i = 0; i < size; ++i)
        table[i] = NULL;
    return table;
}

void insertRecord(HashNode** hashTable, unsigned int size, struct Record record) {
    long index = record.key % size;
    HashNode *node = malloc(sizeof(HashNode));
    node->record = record;
    node->next = hashTable[index];
    hashTable[index] = node;
}

struct Record* findRecordByKey(HashNode** hashTable, unsigned int size, int key) {
    long index = key % size;
    HashNode *current = hashTable[index];
    while (current != NULL && current->record.key != key)
        current = current->next;
    return current == NULL ? NULL : &current->record;
}

void sortRecords(struct Record* records, unsigned int size) {
    qsort(records, size, sizeof(struct Record), compareFunc);
}

int compareFunc(const void *a, const void *b) {
    return (*(const struct Record*)a).key - (*(const struct Record*)b).key;
}

void freeMemory(HashNode** hashTable, unsigned int size) {
    for (unsigned int i = 0; i < size; ++i) {
        HashNode *current = hashTable[i];
        while (current != NULL) {
            HashNode *next = current->next;
            free(current);
            current = next;
        }
    }
    free(hashTable);
}

void allocateMemoryAndInitialize(unsigned int offsetSize, unsigned int keySize, unsigned int recordSize, unsigned int numRecords) {
    long *offsets = malloc(offsetSize * numRecords);
    int *keys = malloc(keySize * numRecords);
    struct Record *records = malloc(recordSize * numRecords);

    // Generate unique random values for keys and corresponding records
    srand(time(NULL));
    for (unsigned int i = 0; i < numRecords; ++i) {
        int key = rand() % INT_MAX;
        while (findRecordByKey(records, numRecords, key) != NULL)
            key = rand() % INT_MAX;
        records[i].key = key;
        records[i].value = rand() % INT_MAX;
        records[i].offset = i;
    }

    // Sort the records based on their keys in ascending order
    sortRecords(records, numRecords);

    // Create and populate hash table for efficient retrieval and manipulation of offsets and keys
    unsigned int hashTableSize = numRecords / 2 + 1;
    HashNode **hashTable = createHashTable(hashTableSize);
    for (unsigned int i = 0; i < numRecords; ++i) {
        insertRecord(hashTable, hashTableSize, records[i]);
    }
}

int main() {
    unsigned int offsetSize = 1 * sizeof(long);
    unsigned int keySize = sizeof(int);
    unsigned int recordSize = sizeof(struct Record);
    unsigned int numRecords = 1000000;

    allocateMemoryAndInitialize(offsetSize, keySize, recordSize, numRecords);

    // Implement caching mechanism and external database integration here

    // Handle high-throughput scenarios gracefully

    freeMemory(records, numRecords);
    freeMemory(hashTable, hashTableSize);

    return 0;
}
