typedef struct {
    time_t EventTime;
    enum EventType { NETWORK_EVENT_TYPE_1, NETWORK_EVENT_TYPE_2, NETWORK_EVENT_TYPE_3 } EventType;
    size_t NumParticipants;
    struct Participant* Participants;
} NetworkEvent;

typedef struct Participant {
    enum Role { PARTICIPANT_ROLE_1, PARTICIPANT_ROLE_2, PARTICIPANT_ROLE_3 } Role;
    enum Status { PARTICIPANT_STATUS_ACTIVE, PARTICIPANT_STATUS_INACTIVE } Status;
    char* Description;
} Participant;

#define MAX_MEMORY (100 * 1024 * 1024) // 100MB

static pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t allocated_structures = 0;

NetworkEvent* create_network_event(time_t event_time, enum EventType event_type) {
    if (allocated_structures + 1 >= MAX_MEMORY / sizeof(NetworkEvent)) return NULL;

    NetworkEvent* new_event = malloc(sizeof(NetworkEvent));
    if (!new_event) return NULL;

    pthread_mutex_lock(&memory_lock);
    allocated_structures++;
    pthread_mutex_unlock(&memory_lock);

    new_event->EventTime = event_time;
    new_event->EventType = event_type;
    new_event->NumParticipants = 0;
    new_event->Participants = NULL;

    return new_event;
}

void add_participant(NetworkEvent* network_event, enum Role role, enum Status status, char* description) {
    if (!network_event || !description) return;

    size_t current_size = network_event->NumParticipants;
    Participant** participants = realloc(network_event->Participants, (current_size + 1) * sizeof(Participant*));

    if (!participants) {
        free(network_event->Participants);
        return;
    }

    network_event->Participants = participants;
    network_event->NumParticipants++;

    Participant* new_participant = malloc(sizeof(Participant));
    if (!new_participant) {
        free(network_event->Participants);
        return;
    }

    new_participant->Role = role;
    new_participant->Status = status;
    new_participant->Description = strdup(description);

    network_event->Participants[current_size] = new_participant;
}

void free_network_event(NetworkEvent* network_event) {
    if (!network_event) return;

    pthread_mutex_lock(&memory_lock);
    allocated_structures--;
    pthread_mutex_unlock(&memory_lock);

    free(network_event->Participants);
    free(network_event);
}
```
