    new_item->data = data;
    new_item->next = NULL;

    pthread_mutex_lock(&q_lock);

    sem_wait(&sem_q_notfull);

    if (tail == NULL) {
        head = new_item;
        tail = new_item;
    } else {
        tail->next = new_item;
        tail = tail->next;
    }

    pthread_mutex_unlock(&q_lock);

