    list_node_t* buffer = malloc(size * sizeof(list_node_t));
    if (!buffer) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    for (unsigned int i = 0; i < size; ++i) {
        buffer[i].next = &buffer[(i + 1) % size];
    }
    *head = buffer;

    // Initialize a read/write index and mutex to protect the list access
    unsigned int read_index = 0, write_index = 0;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Function to add an element to the list
    void push(list_node_t** head, const NFAPI_CRC_INDICATION_PDU_T* data) {
        pthread_mutex_lock(&mutex);

        while (is_unique_crcflag(&((*head)->data), data)) {
