            data->CRCFLAG = get_random();
        }

        list_node_t* node = malloc(sizeof(list_node_t));
        if (!node) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&mutex);
            exit(EXIT_FAILURE);
        }
        node->data = *data;
        node->next = (*head)->next;
        (*head)->next = node;

        log_access(ACCESS_WRITE, data);

        pthread_mutex_unlock(&mutex);
    }

    // Function to remove an element from the list (not used in this example)
    void pop(list_node_t** head) {
        pthread_mutex_lock(&mutex);

        list_node_t* temp = (*head);
        (*head) = temp->next;
        free(temp);

        log_access(ACCESS_READ, NULL);

        pthread_mutex_unlock(&mutex);
    }

    // Main thread function to read elements from the list and process them
    void* reader(void* arg) {
        while (true) {
            pthread_mutex_lock(&mutex);

            if ((*head)->next == *head) {  // List is empty, wait for data
                pthread_mutex_unlock(&mutex);
                sched_yield();
                continue;
            }

            list_node_t* temp = *head;
            *head = (*head)->next;
            pthread_mutex_unlock(&mutex);

            log_access(ACCESS_READ, &temp->data);
            // Process the data and free the node when done (not shown in this example)
            free(temp);
        }
        return NULL;
    }
}
