typedef struct {
    time_t timestamp;
    int event_id;
    size_t payload_len;
    char *payload;
    pthread_mutex_t mutex;
} NetworkEventLogEntry;

struct NetworkEventLog {
    size_t capacity;
    size_t count;
    NetworkEventLogEntry *entries;
    size_t archive_capacity;
    NetworkEventLogEntry **archive;
    pthread_mutex_t mutex;
};

NetworkEventLog* network_event_log_create(size_t capacity, size_t archive_capacity) {
    NetworkEventLog *log = malloc(sizeof(NetworkEventLog));
    log->capacity = capacity;
    log->count = 0;
    log->archive_capacity = archive_capacity;
    log->entries = calloc(capacity, sizeof(NetworkEventLogEntry));
    log->archive = calloc(archive_capacity, sizeof(NetworkEventLogEntry*));
    pthread_mutex_init(&log->mutex, NULL);
    return log;
}

void network_event_log_destroy(NetworkEventLog *log) {
    for (size_t i = 0; i < log->count; ++i) {
        free(log->entries[i].payload);
    }
    free(log->entries);
    free(log->archive);
    pthread_mutex_destroy(&log->mutex);
    free(log);
}

NetworkEventLogEntry* network_event_log_get_entry(NetworkEventLog *log, size_t index) {
