void init_dynamic_list(dynamic_list* list, size_t initial_capacity) {
    list->data = mmap(NULL, initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (list->data == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    sem_init(&list->not_full, 0, initial_capacity);
    sem_init(&list->not_empty, 0, 0);
}

void push(dynamic_list* list, const NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&list->mutex);

    while (list->size == list->capacity && sem_trywait(&list->not_full) != 0) {
        // Wait until there's space in the dynamic list, or check if another thread has added an element.
        pthread_cond_t wait_condition;
        bool cond_signaled = false;

        pthread_mutex_unlock(&list->mutex);
        pthread_cond_init(&wait_condition, NULL);

        sem_wait(&list->not_empty);
        if (list->size == list->capacity) {
            // Resize the dynamic list if it's full.
            size_t new_capacity = list->capacity * 2;
            NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (new_data == NULL) {
                perror("realloc failed");
                exit(EXIT_FAILURE);
            }
            list->data = new_data;
            list->capacity = new_capacity;
        }

        pthread_mutex_lock(&list->mutex);
    }

    list->data[list->size] = *item;
    list->size++;

    if (pthread_cond_signal(&wait_condition) != 0) {
        perror("pthread_cond_signal failed");
        exit(EXIT_FAILURE);
    }
    pthread_cond_destroy(&wait_condition);
    pthread_mutex_unlock(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* pop(dynamic_list* list) {
    pthread_mutex_lock(&list->mutex);

    while (list->size == 0 && sem_trywait(&list->not_empty) != 0) {
        // Wait until there's an element in the dynamic list, or check if another thread has removed an element.
        pthread_cond_t wait_condition;
        bool cond_signaled = false;

        pthread_mutex_unlock(&list->mutex);
        pthread_cond_init(&wait_condition, NULL);

        sem_wait(&list->not_full);
        if (list->size == 0) {
            // Resize the dynamic list if it's empty.
            size_t new_capacity = list->capacity / 2;
            NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (new_data == NULL) {
                perror("realloc failed");
                exit(EXIT_FAILURE);
            }
            list->data = new_data;
            list->capacity = new_capacity;
        }

        pthread_mutex_lock(&list->mutex);
    }

    NFAPI_CRC_INDICATION_PDU_T *result = &list->data[list->size - 1];
    list->size--;
    track_success();

    if (pthread_cond_signal(&wait_condition) != 0) {
        perror("pthread_cond_signal failed");
        exit(EXIT_FAILURE);
    }
    pthread_cond_destroy(&wait_condition);
    pthread_mutex_unlock(&list->mutex);

    return result;
}

void destroy_dynamic_list(dynamic_list* list) {
    free(list->data);
