// Prioritized, dynamically resizable list (queue)
struct List {
    Node* head;
    Node* tail;
    unsigned int size;
    pthread_mutex_t queue_mutex;
};

// Initialize the list with given initial capacity
void init_list(struct List* list, unsigned int capacity) {
    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->queue_mutex, NULL);
}

// Push a new element onto the queue, prioritized by RNTI values
void push(struct List* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return;

    node->data = *data;
    node->next = NULL;

    pthread_mutex_lock(&list->queue_mutex);
    if (!list->head) {
        list->head = node;
        list->tail = node;
    } else {
        Node* current = list->head;
        while (current->next && current->next->data.rnti < node->data.rnti)
            current = current->next;

        node->next = current->next;
        current->next = node;
        if (node->next) list->tail = node->next;
    }
    list->size++;
    pthread_mutex_unlock(&list->queue_mutex);
}

// Pop and return the highest priority element from the queue, or NULL if empty
NFAPI_CRC_INDICATION_PDU_T pop(struct List* list) {
    NFAPI_CRC_INDICATION_PDU_T result;
    Node* node;

    pthread_mutex_lock(&list->queue_mutex);
    if (!list->head) {
        pthread_mutex_unlock(&list->queue_mutex);
        return (NFAPI_CRC_INDICATION_PDU_T){0};
    }

    node = list->head;
    result = node->data;
    list->head = node->next;

    if (!list->head) list->tail = NULL;
    free(node);
    list->size--;
    pthread_mutex_unlock(&list->queue_mutex);

    return result;
}

// Periodically check for CRCFLAG sequence inconsistencies and correct them
void verify_crcflag(struct List* list) {
    Node* current = list->head;
    unsigned int last_crcflag = 0;

    pthread_mutex_lock(&list->queue_mutex);
    while (current != NULL) {
        if (!is_unique_crcflag(current->data.crcflag, last_crcflag, current->data.crcflag)) {
            current->data.crcflag = thread_rng();
        }

        last_crcflag = current->data.crcflag;
        current = current->next;
    }
    pthread_mutex_unlock(&list->queue_mutex);
}
