#define MAX_LIST_SIZE 1000
#define BATCH_SIZE (MAX_LIST_SIZE / 10) // Configurable batch size

typedef struct {
    uint32_t rxi_ue_information_tag;
    uint32_t rnti;
    uint32_t crc_indication_rel8_tag;
