typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

struct thread_data {
    pthread_t thread_id;
    Queue* queue;
};

Queue* create_queue() {
    Queue* q = malloc(sizeof(Queue));
    if (!q) return NULL;

    q->front = q->rear = NULL;
    q->size = 0;
    pthread_mutex_init(&q->mutex, NULL);
    return q;
}

void enqueue(Queue* queue, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = malloc(sizeof(Node));
    if (!newNode) return;

    newNode->data = data;
    newNode->next = NULL;

    pthread_mutex_lock(&queue->mutex);
    if (queue->rear) {
        queue->rear->next = newNode;
        queue->rear = newNode;
    } else {
        queue->front = queue->rear = newNode;
    }
    ++queue->size;
    pthread_mutex_unlock(&queue->mutex);
}

void* process_batch(void* arg) {
    ThreadData* data = (ThreadData*)arg;
    Queue* q = data->queue;
    NFAPI_CRC_INDICATION_PDU_T batch[BATCH_SIZE];

    while (true) {
        pthread_mutex_lock(&q->mutex);
        if (q->size < BATCH_SIZE || !q->front) {
            pthread_mutex_unlock(&q->mutex);
            pthread_cond_wait(&data->cond, &q->mutex);
            continue;
        }
        size_t i = 0;
        Node* temp = q->front;
        for (; i < BATCH_SIZE && temp != NULL; ++i) {
            batch[i] = temp->data;
            temp = temp->next;
            if (temp == q->front) // Wrap around
                q->front = NULL;
            free(temp);
        }
        q->size -= i;
        if (q->size == 0)
            q->front = q->rear = NULL;
        pthread_mutex_unlock(&q->mutex);

        // Process batch, including data validation, external data source integration, and network packet loss handling.

    }
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T* list, size_t len) {
    for (size_t i = 0; i < len; ++i) {
        uint32_t id = list[i].rxi_ue_information_tag & 0xFFFFFF;
        uint32_t frame = (id >> 24) % MAX_FRAMES;
        uint32_t subframe = (list[i].crc_indication_rel8_tag >> 16) % MAX_SUBFRAMES;

        list[i].rnti = validate_RNTI(id, frame, subframe); // External data source integration
        list[i].crcflag = (bool)(rand() % 2);
    }
}

void manage_list(NFAPI_CRC_INDICATION_PDU_T* list, size_t len) {
    ThreadData thread_data[NUM_THREADS];
    Queue* queue[NUM_THREADS] = { create_queue(), ... }; // Create NUM_THREADS queues

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        thread_data[i].queue = queue[i];
        pthread_create(&thread_data[i].thread_id, NULL, &process_batch, &thread_data[i]);
    }

    add_to_list(list, len);

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        enqueue(thread_data[i].queue, list[i]); // Enqueue processed structures to their respective queues.
    }

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        pthread_join(thread_data[i].thread_id, NULL);
    }
}
