    ht->size = size;
    ht->records = (Record*)calloc(size, sizeof(Record));
    if (!ht->records) return;
    ht->lock = PTHREAD_MUTEX_INITIALIZER;
}

int find_index(HashTable* ht, int key) {
    size_t index = custom_hash(key);
    size_t i = index;
    while (ht->records[i].value != -1 && ht->records[i].value != key) {
        i = (index + 1) % ht->size;
    }
    return i;
}

void insert(HashTable* ht, int key, Record data) {
    pthread_mutex_lock(&ht->lock);
    size_t index = find_index(ht, key);
    if (ht->records[index].value == -1 || ht->records[index].value == key) {
        ht->records[index] = data;
    } else {
        size_t probe = 1;
        while (ht->records[(index + probe) % ht->size].value != -1 &&
               ht->records[(index + probe) % ht->size].value != key) {
            index = (index + probe + 1) % ht->size;
            probe++;
        }
        if (ht->records[index].value == -1 || ht->records[index].value == key) {
            ht->records[index] = data;
        } else {
            printf("Hash table overflow. Key: %d\n", key);
        }
    }
    pthread_mutex_unlock(&ht->lock);
}

Record* lookup(HashTable* ht, int key) {
