#define MAX_LIST_SIZE 1024
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRHC_INDICATION_PDU_T *list = NULL;
static size_t list_size = 0;
static size_t max_list_size = MAX_LIST_SIZE;

void set_max_list_size(size_t new_size) {
    if (new_size > MAX_LIST_SIZE) {
        max_list_size = MAX_LIST_SIZE;
    } else if (new_size < list_size) {
        list_size = new_size;
    } else {
        max_list_size = new_size;
    }
}

void clear_list() {
    pthread_mutex_lock(&list_mutex);
    if (list) {
        free(list);
        list = NULL;
        list_size = 0;
    }
    pthread_mutex_unlock(&list_mutex);
}

NFAPI_CRHC_INDICATION_PDU_T* create_and_populate_pdu() {
    NFAPI_CRHC_INDICATION_PDU_T *new_pdu;

    new_pdu = malloc(sizeof(NFAPI_CRHC_INDICATION_PDU_T));
    if (!new_pdu) return NULL;

    new_pdu->tag.present = RXUE_INFORMATION_TAG_PRESENT;
    // Set the tag fields according to your specific requirements

    new_pdu->rnti = rand() % 65536;

    new_pdu->crc_indication.present = CRC_INDICATION_REL8_TAG_PRESENT;
    new_pdu->crc_indication.crcFlag = (rand() % 2) == 0 ? 1 : 0;

    return new_pdu;
}

NFAPI_CRHC_INDICATION_PDU_T* get_or_create_pdu() {
    pthread_mutex_lock(&list_mutex);

    if (list_size >= max_list_size) {
        pthread_mutex_unlock(&list_mutex);
        return NULL;
    }

    if (list_size < list_size) {
        NFAPI_CRHC_INDICATION_PDU_T *new_pdu = create_and_populate_pdu();
        if (!new_pdu) {
            pthread_mutex_unlock(&list_mutex);
            return NULL;
        }

        list = realloc(list, (list_size + 1) * sizeof(NFAPI_CRHC_INDICATION_PDU_T));
        if (!list) {
            free(new_pdu);
            pthread_mutex_unlock(&list_mutex);
            return NULL;
        }
        list[list_size++] = new_pdu;
    }

    NFAPI_CRHC_INDICATION_PDU_T *pdu = list[--list_size];

    pthread_mutex_unlock(&list_mutex);
    return pdu;
}
```

