```javascript
async function uploadFileFromURL(url, serverEndpoint, chunkSize = 1048576) { // 10MB chunks
    const fetch = require('node-fetch');
    let activeUploadCount = 0;
    const maxSimultaneousUploads = 10;

    async function uploadChunk(chunkData, fileUrl) {
        try {
            const response = await fetch(serverEndpoint, {
                method: 'POST',
                body: chunkData,
            });

            if (!response.ok) throw new Error(`Server responded with error code ${response.status}`);

            const contentType = response.headers.get('Content-Type');
            if (contentType !== 'application/octet-stream') {
                throw new Error(`Expected octet-stream content type but got: ${contentType}`);
            }

            return response.url; // Return the URL of the uploaded file upon successful completion
        } catch (err) {
            console.error(err);
            throw err;
        }
    }

    async function resumableUpload(fileUrl) {
        let response = await fetch(fileUrl, { method: 'HEAD' });
        const fileSize = response.headers.get('content-length');
        if (!fileSize) throw new Error('Failed to get file size');

        const chunks = Math.ceil(fileSize / chunkSize);
        let currentChunkIndex = 0;
        while (activeUploadCount < maxSimultaneousUploads || currentChunkIndex < chunks) {
            if (currentChunkIndex === chunks) break; // No more chunks to process

            const startIndex = currentChunkIndex * chunkSize;
            const endIndex = Math.min((currentChunkIndex + 1) * chunkSize, fileSize);

            try {
                const response = await fetch(fileUrl.replace('GET', 'RANGE').replace(' ', `-${startIndex}-${endIndex}`));
                if (!response.ok) throw new Error(`Server responded with error code ${response.status}`);

                const contentType = response.headers.get('Content-Type');
                if (contentType !== 'application/octet-stream') {
                    throw new Error(`Expected octet-stream content type but got: ${contentType}`);
                }

                const chunkData = await response.arrayBuffer();
                activeUploadCount++;

                const uploadedUrl = await uploadChunk(new Blob([chunkData]), fileUrl);
                console.log(`Uploaded chunk ${currentChunkIndex}: ${uploadedUrl}`);

                currentChunkIndex++;
            } catch (err) {
                console.error(err);
            } finally {
                activeUploadCount--;
            }
        }
    }

    return resumableUpload(url);
}
