#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <dirent.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    char username[32];
    char activityType[16];
    int duration;
} UserActivityLogEntry;

UserActivityLogEntry* processUserLogs(const char *dir, size_t *entries) {
    DIR *d = opendir(dir);
    if (!d) return NULL;

    struct dirent *entry;
    size_t num_entries = 0;
    FILE *file;
    UserActivityLogEntry *log_entries = calloc(*entries, sizeof(UserActivityLogEntry));

    while ((entry = readdir(d)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        char path[256];
        snprintf(path, sizeof(path), "%s/%s", dir, entry->d_name);
        file = fopen(path, "r");
        if (!file) continue;

        UserActivityLogEntry *current_entry = log_entries + num_entries++;
        char line[1024];
        time_t timestamp;
        while (fgets(line, sizeof(line), file)) {
            sscanf(line, "%*[^,],%ld,%31[^,],%15[^,],%d\n", &timestamp, current_entry->username, current_entry->activityType, &current_entry->duration);
        }
        fclose(file);
    }
    closedir(d);

    *entries = num_entries;
    return log_entries;
}

