// Error codes
enum class ErrorCode { SUCCESS, MEMORY_FAILURE };

// Global variables for random number generation
std::random_device rd;
std::mt19937 gen(rd());
std::uniform_int_distribution<uint16_t> dist_rxTag(0x0001, 0xFFFF); // Modify this to fit your range constraints
std::uniform_int_distribution<uint32_t> dist_rnti(0x0001, 0xFFFFFFFF); // Modify this to fit your range constraints

class DynamicList {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> list;
    const size_t maxSize;
    const size_t stepSize;
    std::atomic<size_t> currentSize{0};
public:
    explicit DynamicList(size_t initialCapacity) : maxSize(1024 * 1024), stepSize(maxSize / 10) {
        if (initialCapacity > maxSize) {
            throw std::runtime_error("Initial capacity exceeds the maximum allowed list size.");
        }
        if (stepSize <= 0 || stepSize >= maxSize) {
            throw std::runtime_error("Invalid step size.");
        }
        reserve(initialCapacity);
    }

    ErrorCode reserve(size_t n) {
        auto newCapacity = currentSize + n;
        if (newCapacity > maxSize) {
            return ErrorCode::MEMORY_FAILURE;
        }
        list.resize(newCapacity, NFAPI_CRC_INDICATION_PDU_T());
        currentSize += n;
        return ErrorCode::SUCCESS;
    }

    void push_back() {
        if (reserve(1) == ErrorCode::MEMORY_FAILURE) {
            throw std::runtime_error("Failed to allocate memory.");
        }

        auto& entry = list[currentSize - 1];
        entry.RX_UE_INFORMATION_TAG = dist_rxTag(gen);
        entry.RNTI = dist_rnti(gen);
        entry.CRCFLAG = (rd() % 2 == 0) ? false : true;
    }

    ~DynamicList() {
        list.resize(currentSize);
    }
};
```

