            } else {
                error->code = EC_STREAM_ERROR;
                strcpy(error->message, "Error reading from data stream.");
            }
        }
    }

    return 0;
}

void process_transaction(char transaction[]) {
    struct tm transaction_time;
    time_t current_time = time(NULL);

    // Parse and validate the transaction, handle null inputs gracefully
    // Calculate the transaction's age based on current time and transaction timestamp
    int transaction_age = get_transaction_age(current_time, localtime_r(&transaction_timestamp, &transaction_time));

    // Filter the transaction based on age, number of transactions in the past 3 seconds, weighted sum
    if (transaction_age <= 3 && num_transactions < 10 && calculate_weighted_sum() < 100.0) {
        strcpy(transaction_weights[num_transactions], transaction);
        num_transactions++;
    }
}

int get_transaction_age(time_t current_time, struct tm transaction_time) {
    return current_time - mktime(&transaction_time);
}

double calculate_weighted_sum() {
    double sum = 0.0;
    int i;

    pthread_mutex_lock(&transactions_lock);
    for (i = 0; i < num_transactions; ++i) {
        sum += transaction_weights[i] * weights[0]; // Weight based on transaction age
        sum += transaction_weights[i] * weights[1]; // Weight based on number of transactions in the past 3 seconds
        sum += transaction_weights[i] * weights[2]; // Weight based on weighted sum
    }
    pthread_mutex_unlock(&transactions_lock);

    return sum;
}

void configure_logging(int level) {
    // Implement logging mechanism here...
}
```

