#define MAX_ELEMENTS 1000
#define MIN_ELEMENTS 100

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
} NFAPI_CRC_INDICATION_PDU;

struct buffer {
    NFAPI_CRC_INDICATION_PDU *data;
    size_t capacity;
    size_t length;
    pthread_mutex_t lock;
};

void initialize_buffer(struct buffer *buf) {
    buf->data = calloc(MIN_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!buf->data) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }

    buf->capacity = MIN_ELEMENTS;
    buf->length = 0;
    pthread_mutex_init(&buf->lock, NULL);
}

void resize_buffer(struct buffer *buf) {
    NFAPI_CRC_INDICATION_PDU *temp_data;
    size_t new_capacity;

    if (buf->length + MIN_ELEMENTS > buf->capacity) {
        new_capacity = ((buf->capacity * 3) / 2) + MIN_ELEMENTS;
        if (new_capacity > MAX_ELEMENTS)
            new_capacity = MAX_ELEMENTS;
    } else {
        new_capacity = buf->capacity;
    }

    temp_data = realloc(buf->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!temp_data) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }

    buf->data = temp_data;
    buf->capacity = new_capacity;
}

void add_pdu(struct buffer *buf, const NFAPI_CRC_INDICATION_PDU *pdu) {
    pthread_mutex_lock(&buf->lock);

    if (buf->length + 1 >= buf->capacity)
        resize_buffer(buf);

    memcpy(&buf->data[buf->length], pdu, sizeof(NFAPI_CRC_INDICATION_PDU));
    ++buf->length;

    pthread_mutex_unlock(&buf->lock);
}

void truncate_pdu(struct buffer *buf, size_t index) {
    if (index >= buf->length)
        return;

    const size_t max_payload = (index + 1) * (MAX_ELEMENTS / buf->length);
    if (sizeof(NFAPI_CRC_INDICATION_PDU[0]) > max_payload) {
        printf("Truncated packet at index %zu due to exceeding payload size limit\n", index);
        memset(&buf->data[index], 0, sizeof(NFAPI_CRC_INDICATION_PDU[0]));
    } else {
        memmove(&buf->data[index], &buf->data[index + 1], buf->length - index - 1);
    }

    --buf->length;
}

void log_stats(const struct buffer *buf) {
    printf("Number of truncated packets: %zu\n", buf->truncated_packets);
    printf("Number of invalid CRC flags: %zu\n", buf->invalid_crc_flags);
}

struct buffer global_buffer;
size_t global_truncated_packets = 0;
size_t global_invalid_crc_flags = 0;
