class EmptyList { /* Implement an empty list class here */ };

template<typename T>
class ForwardList {
private:
    struct Node {
        T data;
        Node* next;
        Node(const T& d, Node* n = nullptr) : data(d), next(n) {}
    };

    Node* head;
    size_t size;

public:
    ForwardList() : head(nullptr), size(0) {}

    void insertAfterOrAppend(const T& target, const T& primary, const T& secondary) {
        if (size == 0) return EmptyList(); // Return an empty list if the original list is empty.

        Node* current = head;
        Node* previous = nullptr;
        bool found = false;

        while (current != nullptr && !found) {
            if (current->data == target) {
                found = true;
                Node* newNode = new Node(primary);
                newNode->next = current->next;
                current->next = newNode;
                ++size;
            } else {
                previous = current;
                current = current->next;
            }
        }

        if (!found) { // If the target is not found, append the secondary string.
            Node* newNode = new Node(secondary);
            newNode->next = head;
            head = newNode;
            ++size;
        }
    }

    // ... Other methods and member variables (size, iterator, etc.) as needed.
};
