#include <boost/optional.hpp>

namespace LoggingSystem {

class LogThread {
public:
    explicit LogThread(const std::string& outputPath) : m_outputFile(outputPath), m_shouldExit(false) {}

    void operator()() {
        while (!m_shouldExit) {
            std::unique_lock<std::mutex> lock(m_queueMutex);
            m_logQueue.wait(lock, [this] { return !m_logQueue.empty(); });

            auto logEntry = m_logQueue.front();
            m_logQueue.pop();
            lock.unlock();

            writeLog(logEntry);
        }
    }

    void enqueueLog(const std::string& logEntry) {
        std::unique_lock<std::mutex> lock(m_queueMutex);
        m_logQueue.push(logEntry);
        lock.notify_one();
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(m_shouldExitLock);
            m_shouldExit = true;
        }
        m_shouldExitCond.notify_one();
    }

private:
    void writeLog(const std::string& logEntry) {
        // Implement external logging service API calls here
        // ...

        std::ofstream file(m_outputFile, std::ios_base::app);
        if (file.is_open()) {
            file << logEntry << '\n';
            file.close();
        }
    }

    std::ofstream m_outputFile;
    std::queue<std::string> m_logQueue;
    std::mutex m_queueMutex;
    std::condition_variable m_logQueueCond;
    std::mutex m_shouldExitLock;
    std::atomic_bool m_shouldExit{false};
    std::condition_variable m_shouldExitCond;
};

class LogManager {
public:
    static LogManager& getInstance() {
        static LogManager instance;
        return instance;
    }

    void initialize(int numThreads, const std::map<std::string, std::string>& outputPaths) {
        for (size_t i = 0; i < numThreads; ++i) {
            threads.emplace_back(LogThread(outputPaths[i]));
        }
    }

    void enqueueLog(const std::string& logEntry, int threadIndex) {
        if (threadIndex >= 0 && threadIndex < static_cast<int>(threads.size())) {
            threads[threadIndex].enqueueLog(logEntry);
        } else {
            throw std::runtime_error("Invalid thread index");
        }
    }

    ~LogManager() {
        for (auto& thread : threads) {
            thread.stop();
            thread.join();
        }
    }

private:
    LogManager() {}
    std::vector<LogThread> threads;
};

}  // namespace LoggingSystem
```

