import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;
import java.util.*;
import org.slf4j.*;
import javax.annotation.*;

public final class AppConfigLoader {
    private static final Logger LOGGER = LogManager.getLogger(AppConfigLoader.class);
    private static volatile AppConfig config;
    private static final ExecutorService CACHE_UPDATE_EXECUTOR = Executors.newSingleThreadExecutor();
    private static final ConcurrentHashMap<String, Supplier<AppConfig>> CONFIG_TYPES = new ConcurrentHashMap<>();

    public static AppConfig getAppConfig(@Nonnull String configType) {
        if (config == null) {
            synchronized (AppConfigLoader.class) {
                if (config == null) {
                    loadConfig(configType);
                }
            }
        }

        return config;
    }

    @Nonnull
    private static AppConfig loadConfig(@Nonnull String configType) {
        Supplier<AppConfig> configSupplier = CONFIG_TYPES.computeIfAbsent(configType, type -> () -> createConfigInstance(type));
        try (InputStream inputStream = AppConfigLoader.class.getResourceAsStream("/" + configType + ".properties")) {
            if (inputStream == null) {
                LOGGER.error("Configuration file '{}' not found.", configType);
                return createDefaultConfig();
            }

            Properties properties = new Properties();
            properties.load(inputStream);

            AppConfig configInstance = configSupplier.get();
            configInstance.loadFromProperties(properties);

            CACHE_UPDATE_EXECUTOR.submit(() -> updateCachedConfig(configInstance));

            return configInstance;
        } catch (IOException e) {
            LOGGER.error("Error while loading configuration file '{}': {}", configType, e.getMessage());
            return createDefaultConfig();
        }
    }

    @Nonnull
    private static AppConfig createConfigInstance(@Nonnull String configType) {
        try {
            Class<?> clazz = Class.forName(configType);
            return (AppConfig) clazz.newInstance();
        } catch (Exception e) {
            LOGGER.error("Error while creating configuration instance of type '{}': {}", configType, e.getMessage());
            return createDefaultConfig();
        }
    }

    @Nonnull
    private static AppConfig createDefaultConfig() {
        // Implement a default configuration object with reasonable defaults
    }

    private static void updateCachedConfig(@Nonnull AppConfig configInstance) {
        synchronized (AppConfigLoader.class) {
            config = configInstance;
        }
    }
}
```

This code provides an example of a Java utility class that loads and caches an `AppConfig` instance from a configuration file. It supports efficient reading, graceful handling of potential file corruption or absence, and ensures the file is read only once per application lifecycle using a single-threaded cache. The utility also provides a fallback mechanism for default values in case the file is unavailable or corrupted. To extend the utility to support other configuration types, simply add more entries to the `CONFIG_TYPES` map with appropriate class names and their corresponding load methods.']

