import java.lang.RuntimeException

class ThemeManager(context: Context) {
    private val context = context.applicationContext
    private val cacheDir = File(context.cacheDir, "themes")
    private var defaultThemeDir = cacheDir.toString()
    private val executorService = Executors.newSingleThreadExecutor()
    private val config = context.getSharedPreferences("config", Context.MODE_PRIVATE)

    init {
        if (!cacheDir.exists()) cacheDir.mkdirs()
        defaultThemeDir = cacheDir.absolutePath
        Log.d("THEME_MANAGER", "Default theme directory set to: $defaultThemeDir")
    }

    fun setConfig(key: String, value: String) {
        config.edit().putString(key, value).apply()
    }

    fun loadTheme(themeName: String): Bitmap? {
        val themeFile = File(getCacheRoot(), themeName)
        if (!themeFile.exists()) return null
        try {
            Glide.with(context).asBitmap().load(themeFile).submit().get()
        } catch (e: Exception) {
            Log.w("THEME_MANAGER", "Failed to load theme: $themeName, exception: ${e.message}")
            return null
        }
    }

    fun applyTransformations(bitmap: Bitmap, options: RequestOptions): Bitmap {
        // Validate transformations and apply them using Glide's RequestOptions
        // ...
        return bitmap // Return the transformed bitmap
    }

    private suspend fun loadCachedThemes() {
        val themeFiles = getThemeFiles()
        for (file in themeFiles) {
            try {
                val futureTarget: FutureTarget<Bitmap> = Glide.with(context).asBitmap().load(file).submit()
                while (!futureTarget.isReady()) {}
                val bitmap = futureTarget.get() // Get the loaded bitmap
                applyTransformations(bitmap, RequestOptions.placeholderOf(R.drawable.theme_placeholder))
                saveTransformedBitmapToCache(file.nameWithoutExtension, bitmap)
            } catch (e: Exception) {
                Log.w("THEME_MANAGER", "Failed to load or transform theme: ${file.name}, exception: ${e.message}")
            }
        }
    }

    private fun getCacheRoot(): File = File(defaultThemeDir)

    private fun getThemeFiles(): Array<File> {
        val files = mutableListOf<File>()
        for (file in cacheDir.listFiles() ?: emptyArray()) {
            if (!file.isDirectory && file.name.endsWith(".png")) {
                files.add(file)
            }
        }
        return files.toTypedArray()
    }

    private fun saveTransformedBitmapToCache(key: String, bitmap: Bitmap) {
        val outputStream = FileOutputStream(getFileFromKey(key))
        bitmap.compress(Bitmap.CompressFormat.PNG, 100, outputStream)
        outputStream.close()
    }

    private fun getFileFromKey(key: String): File {
        return File(getCacheRoot(), key + ".png")
    }

    companion object {
        const val RETRY_DELAY = 500L // milliseconds

        fun startLoadThemes(scope: CoroutineScope) {
            scope.launch(Dispatchers.IO) {
                try {
                    loadCachedThemes()
                } catch (e: Exception) {
                    Log.w("THEME_MANAGER", "Failed to load themes, retrying in ${RETRY_DELAY} ms")
                    Thread.sleep(RETRY_DELAY)
                    startLoadThemes(scope)
                }
            }
        }
    }
}
