```cpp
#include <vector>
#include <cstdlib>
#include <random>
#include <atomic>
#include <boost/circular_buffer.hpp>
#include <functional>

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
    std::atomic<bool> crcflag{false};
};

class PDUManager {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data;
    std::mt19937 rng;
    boost::circular_buffer<std::size_t, 1024> operationLog;
    const std::size_t maxSize = 10000;
    std::mutex mtx;

public:
    PDUManager() : rng(std::random_device{}()) {}

    void addPDU(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::lock_guard<std::mutex> lock(mtx);
        if (data.size() >= maxSize) return; // Reject additions when array is full

        data.push_back(pdu);
        operationLog.push_back(std::bind(&PDUManager::operationType, this));
    }

    const NFAPI_CRC_INDICATION_PDU_T& getPDU(std::size_t index) {
        std::lock_guard<std::mutex> lock(mtx);
        return data[index];
    }

    void resetCRCFlag(std::size_t index) {
        std::lock_guard<std::mutex> lock(mtx);
        if (index >= data.size()) return; // Reject requests when out of bounds
        data[index].crcflag = !data[index].crcflag;
    }

    void iteratePDUs(const std::function<void(const NFAPI_CRC_INDICATION_PDU_T&)>& func) {
        std::lock_guard<std::mutex> lock(mtx);
        for (const auto& pdu : data) func(pdu);
    }

    std::size_t operationCount() const {
        return operationLog.size();
    }

private:
    static std::size_t operationType() { return 1; } // Operation type 1 represents an addition, 2 a get, and 3 a resetCRCFlag
};
```

