#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_CAPACITY 1000
typedef struct {
    int key;
    double data;
    pthread_mutex_t lock;
    struct log_entry *log_head;
} record;

typedef struct log_entry {
    long offset;
    time_t timestamp;
    char message[256];
    struct log_entry *next;
} log_entry;

struct storage {
    record **records;
    size_t num_records;
    size_t capacity;
    pthread_mutex_t lock;
};

void init_record(record **rec, int key, double data) {
    *rec = malloc(sizeof(record));
    if (!*rec) exit(1);
    memset(*rec, 0, sizeof(**rec));
    (*rec)->key = key;
    (*rec)->data = data;
    pthread_mutex_init(&((*rec)->lock), NULL);
}

void init_log_entry(log_entry **entry) {
    *entry = malloc(sizeof(log_entry));
    if (!*entry) exit(1);
    memset(*entry, 0, sizeof(**entry));
}

struct storage *create_storage(size_t capacity) {
    if (capacity > MAX_CAPACITY) return NULL;
    struct storage *store = malloc(sizeof(struct storage));
    store->records = calloc(capacity, sizeof(record*));
    store->num_records = 0;
    store->capacity = capacity;
    pthread_mutex_init(&store->lock, NULL);
    return store;
}

void free_storage(struct storage *store) {
    for (size_t i = 0; i < store->capacity; ++i) {
        if (store->records[i]) {
            free(store->records[i]->log_head);
            free(store->records[i]);
        }
    }
    free(store->records);
    free(store);
}

void add_record(struct storage *store, int key, double data) {
    for (size_t i = 0; i < store->capacity; ++i) {
        if (!store->records[i]) {
            init_record(&store->records[i], key, data);
            store->num_records++;
            break;
        }
    }
}

log_entry* get_log_head(record *rec) {
    pthread_mutex_lock(&rec->lock);
    log_entry *head = rec->log_head;
    pthread_mutex_unlock(&rec->lock);
    return head;
}

void append_log_entry(log_entry **list, long offset, time_t timestamp, char *message) {
    log_entry *entry = malloc(sizeof(log_entry));
    if (!entry) exit(1);
    memset(entry, 0, sizeof(log_entry));
    entry->offset = offset;
    entry->timestamp = timestamp;
    strcpy(entry->message, message);
    entry->next = NULL;

    log_entry *head = *list;
    if (!head) {
        *list = entry;
    } else {
        while (head->next != NULL) head = head->next;
        head->next = entry;
    }
}

void print_record(record *rec) {
    printf("Key: %d, Data: %.2f\n", rec->key, rec->data);
    log_entry *log_head = get_log_head(rec);
    for (log_entry *entry = log_head; entry != NULL; entry = entry->next) {
        printf("  Offset: %ld, Timestamp: %ld, Message: %s\n", entry->offset, entry->timestamp, entry->message);
    }
}

void iterate_records(struct storage *store) {
    pthread_mutex_lock(&store->lock);
    for (size_t i = 0; i < store->num_records; ++i) {
        print_record(store->records[i]);
    }
    pthread_mutex_unlock(&store->lock);
}
```
