// Function to create and configure a network interface
void init_network_interface(NFAPI_INTERFACE *iface, const char *server_ip, int server_port, size_t msg_interval, size_t total_msg_count, size_t max_queue_size) {
    // Initialize iface struct, socket and semaphore
    memset(iface, 0, sizeof(NFAPI_INTERFACE));

    iface->server_addr.sin_family = AF_INET;
    inet_pton(AF_INET, server_ip, &iface->server_addr.sin_addr);
    iface->server_addr.sin_port = htons(server_port);

    iface->msg_interval = msg_interval;
    iface->total_msg_count = total_msg_count;
    iface->max_queue_size = max_queue_size;

    // Initialize socket and connect to server
    iface->socket = socket(AF_INET, SOCK_STREAM, 0);
    connect(iface->socket, (struct sockaddr*)&iface->server_addr, sizeof(iface->server_addr));

    // Create worker thread
    pthread_create(&iface->worker_thread, NULL, worker, iface);
}

// Function to generate and transmit messages in the worker thread
void* worker(void *data) {
    NFAPI_INTERFACE *iface = data;
    sem_t *message_queue = &iface->message_queue;
    struct nfapi_message msg;
    size_t current_msg_index = 0;

    while (true) {
        // Wait for a message to be added to the queue, or exit if necessary
        sem_wait(message_queue);
        if (!current_msg_index < iface->total_msg_count)
            break;

        // Generate message here and handle potential errors as needed
        generate_nfapi_message(&msg);

        // Transmit message and handle potential errors as needed
        transmit_message(iface->socket, &msg);

        if (transmission_succeeded()) {
            ++iface->successful_transmissions;
        } else {
            ++iface->failed_transmissions;
        }

        // Update current message index and queue size
        ++current_msg_index;
        iface->current_queue_size--;

        // Wait for the next message interval or throttle based on system load
        sem_post(message_queue);
        usleep(iface->msg_interval * 1000);
    }

    return NULL;
}

// Implement other necessary functions such as generate_nfapi_message, transmit_message, transmission_succeeded etc.
