#include <stdexcept>

// Define the NFAPI_L1_STATS_PDU structure.
struct NFAPI_L1_STATS_PDU {
    uint64_t ue_id;
    float rssi;
    int mcs;
    float evm;
};

class StatsBuffer {
public:
    void init(size_t min_size, size_t max_size) {
        // Initialize the buffer with minimum size.
        data_.resize(min_size);
        buffer_mutex_.lock();
        current_size_ = min_size;
        buffer_mutex_.unlock();
        max_size_ = max_size;
    }

    void push(const NFAPI_L1_STATS_PDU& pdu) {
        if (current_size_ >= max_size_) {
            throw std::runtime_error("Buffer overflow");
        }

        auto it = data_.end();
        std::unique_lock<std::mutex> lock(buffer_mutex_);
        it = std::prev(data_.end());
        if (it >= data_.begin() + current_size_) {
            // Buffer is full, truncate the payload.
            it->evm = 0.f;
            it->rssi = 0.f;
            it->mcs = 0;
        }

        *it = pdu;
        ++current_size_;
        lock.unlock();
    }

    void log() const {
        std::cout << "Packets truncated: " << truncated_count_.load(std::memory_order_relaxed) << '\n';
        std::cout << "Abnormal EVM values: " << evm_errors_.load(std::memory_order_relaxed) << '\n';
    }

private:
    std::vector<NFAPI_L1_STATS_PDU> data_;
    std::mutex buffer_mutex_;
    size_t current_size_ = 0;
    size_t max_size_ = 0;
    std::atomic<int> truncated_count_{0};
    std::atomic<int> evm_errors_{0};

    // Provide a thread-safe access to the buffer.
    class Accessor {
    public:
        Accessor(const StatsBuffer& buffer) : buffer_(buffer), lock_(buffer.buffer_mutex_) {}

        const NFAPI_L1_STATS_PDU* operator->() const {
            std::unique_lock<std::mutex> lock(lock_);
            return &buffer_.data_[data_it_];
        }

    private:
        const StatsBuffer& buffer_;
        mutable std::unique_lock<std::mutex> lock_;
        decltype(StatsBuffer::data_.begin()) data_it_;
    };

public:
    // Concurrent access to the buffer is allowed through this class.
    Accessor getAccessor() {
        auto it = data_.end();
        std::unique_lock<std::mutex> lock(buffer_mutex_);
        if (data_.empty()) {
            it = data_.begin();
            current_size_ += it - data_.end();
            data_.erase(it, data_.end());
        }
        else {
            it = std::prev(data_.end());
            --current_size_;
        }
        data_it_ = it;
        lock.unlock();
        return Accessor(*this);
    }
};

// Implement the main function to manage the StatsBuffer array.
void processStatsData(int interface_id, std::shared_ptr<StatsBuffer> buffer) {
    // Concurrently initialize multiple buffers from different interfaces.
    Accessor accessor = buffer->getAccessor();
    while (true) {
        auto pdu = *accessor;
        if (pdu.ue_id >= 0 && pdu.evm <= MAX_EVM_VALUE) {
            // Process the valid PDU payload with UE priority levels.
            processPDUPayload(pdu, interface_id);
        }
        else {
            // Log truncated packets and abnormal EVM values for diagnostic purposes.
            if (pdu.ue_id >= 0) {
                ++buffer->truncated_count_;
            }
            if (pdu.evm > MAX_EVM_VALUE) {
                ++buffer->evm_errors_;
            }
        }
    }
}
