typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node *next;
} list_node_t;

static const size_t MAX_SIZE = 10000;
static const size_t BATCH_SIZE = 1000;

list_node_t *head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init() {
    if (head) return;
    head = malloc(sizeof(list_node_t));
    if (!head) return;
    head->next = NULL;
}

void push(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&mutex);
    list_node_t *new_node = malloc(sizeof(list_node_t));
    if (!new_node) goto error;

    new_node->data = data;
    new_node->next = head->next;
    head->next = new_node;

error:
    pthread_mutex_unlock(&mutex);
}

void reset() {
    pthread_mutex_lock(&mutex);
    list_node_t *current = head->next, *temp;
    while (current) {
        temp = current->next;
        current->crc_indication.CRCFLAG = 0;
        current = temp;
    }
    pthread_mutex_unlock(&mutex);
}

void process() {
    if (head->next == NULL) return;

    pthread_mutex_lock(&mutex);
    list_node_t *current = head->next, *temp;
    size_t processed = 0;

    while (current && processed < BATCH_SIZE) {
        temp = current->next;
        // Check for data inconsistencies and handle accordingly
        if (!validate(current->data)) goto error;

        // Process the data here
        process_data(current->data);

        current = temp;
        processed++;
    }

    if (processed < BATCH_SIZE) {
        head->next = head->next->next; // Remove processed elements from the list
    }

    pthread_mutex_unlock(&mutex);
}

void destroy() {
    pthread_mutex_destroy(&mutex);

    list_node_t *current = head, *temp;
    while (current) {
        temp = current->next;
        free(current);
        current = temp;
    }

    free(head);
    head = NULL;
}
