typedef struct DynamicCollection {
    size_t size;
    size_t capacity;
    Record* records;
} DynamicCollection;

DynamicCollection* create_dynamic_collection(size_t initial_size) {
    DynamicCollection* collection = malloc(sizeof(DynamicCollection));
    collection->size = 0;
    collection->capacity = initial_size;
    collection->records = calloc(initial_size, sizeof(Record));
    return collection;
}

void destroy_dynamic_collection(DynamicCollection* collection) {
    free(collection->records);
    free(collection);
}

Record* reallocate_records(DynamicCollection* collection) {
    size_t new_capacity = (collection->capacity * 2 > collection->size) ? collection->capacity * 2 : collection->size * 2;
    Record* new_records = realloc(collection->records, new_capacity * sizeof(Record));

    if (!new_records) {
        fprintf(stderr, "Failed to reallocate memory.\n");
        exit(EXIT_FAILURE);
    }

    collection->records = new_records;
    collection->capacity = new_capacity;
    return collection->records;
