typedef struct {
    char ifname[IF_NAMESIZE];
    char macaddr[ETH_ALEN];
    unsigned int ipv4;
    unsigned short port;
    struct sockaddr_in addr;
} net_interface;

void validate_mac(const char *mac) {
    // Validate MAC address format
    if (sscanf(mac, "%2x:%2x:%2x:%2x:%2x:%2x",
               &((uint8_t*)mac)[0], &((uint8_t*)mac)[1],
               &((uint8_t*)mac)[2], &((uint8_t*)mac)[3],
               &((uint8_t*)mac)[4], &((uint8_t*)mac)[5]) != 6) {
        perror("Invalid MAC address");
        exit(1);
    }
}

void populate_interface_array(net_interface** arr, int* size, char **server_ips) {
    int idx = 0;
    *arr = malloc((*size)*sizeof(net_interface));

    for (int i = 0; i < *size; ++i) {
        net_interface *cur_iface = &((*arr)[idx++]);
        snprintf(cur_iface->ifname, sizeof(cur_iface->ifname), "%s%d", "eth", i);

        char mac[IF_ALEN];
        sprintf(mac, "00:11:22:%d:%d:33", (i/16) % 256, i % 256);
        validate_mac(mac);
        strncpy(cur_iface->macaddr, mac, sizeof(cur_iface->macaddr));

        cur_iface->ipv4 = inet_addr(server_ips[i]);
        cur_iface->port = 80;
        cur_iface->addr.sin_family = AF_INET;
        cur_iface->addr.sin_port = htons(cur_iface->port);
        cur_iface->addr.sin_addr = *(struct in_addr*)&cur_iface->ipv4;
    }
}

void ensure_unique_ip(net_interface *ifaces, int size) {
    // Use a hash set to check for duplicate IPs
    unsigned long ip_hash[size];
    unsigned long *hash = ip_hash;
    memset(hash, 0, sizeof(ip_hash));

    for (int i = 0; i < size; ++i) {
        unsigned long hash_key = ((unsigned long)(ifaces[i].ipv4 & 0xFFFFFFFF)) ^ ((unsigned long)(ifaces[i].port << 32));
        if (hash[hash_key >> 5] & (1 << (hash_key & 31))) {
            fprintf(stderr, "Duplicate IP detected: %s\n", inet_ntoa(ifaces[i].addr.sin_addr));
            exit(1);
        }
        hash[hash_key >> 5] |= (1 << (hash_key & 31));
    }
}
