    size_t buffer_len;
    int buffer_pos;
} CONNECTION_T;

void generate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand() % 0xFFFFFFFF + 1;
    pdu->RNTI = rand() % 0x7FFF + 1;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 0xFFFF + 1;
    pdu->CRCFLAG = (rand() % 2) == 0 ? 1 : 0;
}

void* dns_resolve(void *arg) {
    CONNECTION_T *connection = arg;
    struct hostent *hostinfo;
    struct sockaddr_in serv_addr;
    int port = 53;
    int ret;

    if ((hostinfo = gethostbyname(connection->hostname)) == NULL) {
        perror("gethostbyname");
        return NULL;
    }

    memset((char *) &serv_addr, '\0', sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    bcopy((char *)hostinfo->h_addr, (char *)&serv_addr.sin_addr.s_addr, hostinfo->h_length);
    serv_addr.sin_port = htons(port);

    connection->sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (connection->sockfd < 0) {
        perror("socket");
        return NULL;
    }

    ret = connect(connection->sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr));
    if (ret < 0) {
        perror("connect");
        close(connection->sockfd);
        return NULL;
    }

    pthread_mutex_init(&connection->lock, NULL);
    return connection;
}

void process_data(CONNECTION_T *connection) {
    char delimiter[] = "\n\r";
    char *token;
    int values[4] = {0};
    size_t i = 0;

    while ((token = strtok_r(connection->buffer, delimiter, &connection->buffer_pos)) != NULL) {
        if (i < 3)
            sscanf(token, "%d", &values[i++]);
        else
            values[i++] = (values[i - 1] + atoi(token)) / 2;

        connection->buffer_pos += strlen(token);
        memmove(connection->buffer, connection->buffer + connection->buffer_pos, connection->buffer_len - connection->buffer_pos);
        connection->buffer_len -= connection->buffer_pos;
    }

    free(connection->buffer);
    connection->buffer = malloc(1024);
    memset(connection->buffer, 0, 1024);
    connection->buffer_len = 1024;
    connection->buffer_pos = 0;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T pdus[10];

    for (size_t i = 0; i < 10; ++i)
        generate_pdu(&pdus[i]);

    // Assuming dns_cache is a global cache structure for frequently accessed hostnames.

    CONNECTION_T *connections[10];
    for (size_t i = 0; i < 10; ++i) {
        connections[i] = (CONNECTION_T *)malloc(sizeof(CONNECTION_T));
        connections[i]->hostname = strdup("example.com"); // Replace with the desired hostname.
    }

    pthread_t threads[10];

    for (size_t i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, dns_resolve, connections + i);
    }

    // Wait for all DNS resolution threads to finish.

    for (size_t i = 0; i < 10; ++i) {
        pthread_join(threads[i], (void **)&connections[i]);
    }

    for (size_t i = 0; i < 10; ++i) {
        process_data(connections[i]);
        // Handle connection processing and data parsing here.
    }

    for (size_t i = 0; i < 10; ++i) {
        close(connections[i]->sockfd);
        free(connections[i]->hostname);
        free(connections[i]);
    }

    return 0;
}
