    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Dynamic memory pool structure
struct memory_pool {
    void *memory_start;
    void *memory_end;
    size_t chunk_size;
    size_t num_chunks;
    size_t used_chunks;
    pthread_mutex_t mutex;
    int allocation_strategy; // 0: best-fit, 1: first-fit, 2: next-fit
};

void *memory_pool_alloc(struct memory_pool *pool, size_t size) {
    void *memory = NULL;
    size_t current_chunk = -1;

    pthread_mutex_lock(&pool->mutex);

    if (size <= pool->chunk_size) {
        // Find suitable chunk for allocation
        if (pool->allocation_strategy == 0) {
            // Best-fit strategy
            for (size_t i = 0; i < pool->num_chunks; ++i) {
                if (pool->memory_start[i * pool->chunk_size + sizeof(void*)] >= size) {
                    current_chunk = i;
                    break;
                }
            }
        } else if (pool->allocation_strategy == 1) {
            // First-fit strategy
            for (size_t i = 0; i < pool->num_chunks; ++i) {
                if (pool->memory_start[i * pool->chunk_size + sizeof(void*)] >= size && current_chunk == -1) {
                    current_chunk = i;
                }
            }
        } else { // allocation_strategy == 2
            // Next-fit strategy
            for (size_t i = 0; i < pool->num_chunks; ++i) {
                if (pool->memory_start[(current_chunk + 1) * pool->chunk_size + sizeof(void*)] >= size && current_chunk != -1) {
                    current_chunk++;
                }
                if (pool->memory_start[i * pool->chunk_size + sizeof(void*)] >= size && current_chunk == -1) {
                    current_chunk = i;
                }
            }
        }

        if (current_chunk != -1) {
            memory = pool->memory_start + current_chunk * pool->chunk_size;
            pool->used_chunks++;
        }
    }

    pthread_mutex_unlock(&pool->mutex);
    return memory;
}

void memory_pool_free(struct memory_pool *pool, void *mem) {
    pthread_mutex_lock(&pool->mutex);
    size_t index = (size_t)((uintptr_t)mem - (uintptr_t)pool->memory_start) / pool->chunk_size;
    pool->used_chunks--;
    pthread_mutex_unlock(&pool->mutex);
}

void create_data_structures(int N, struct memory_pool *mem_pool) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)memory_pool_alloc(mem_pool, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    Record *record_array = (Record *)memory_pool_alloc(mem_pool, N * sizeof(Record));

    // Populate PDUs with random data and initialize records
    for (int i = 0; i < N; ++i) {
        pdu_array[i].rx_ue_information_tag = ...;
        pdu_array[i].rnti = ...;
        pdu_array[i].crc_indication_rel8_tag.crcflag = rand() % 2;

        record_array[i].offset = i * sizeof(Record);
        record_array[i].key = i;
        record_array[i].active = 1;
    }
}
