    RX_UE_INFORMATION_TAG rxUEInformationTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
};

class MemoryPool {
public:
    MemoryPool(size_t chunkSize, size_t minChunks, size_t logLevel) : _chunkSize(chunkSize), _minChunks(minChunks), _logLevel(logLevel), _currentChunkIndex(_nextChunkIndex), _initialAllocation(nullptr) {
        _data.reserve(_minChunks * _chunkSize);
    }

    NFAPI_CRC_INDICATION_PDU_T_PTR allocate() {
        if (_currentChunkIndex >= _data.size()) {
            if (_initialAllocation == nullptr) {
                _initialAllocation = std::make_shared<NFAPI_CRC_INDICATION_PDU_T[_chunkSize]>();
                for (auto& pdu : *_initialAllocation) {
                    std::fill(pdu.get(), pdu.get() + _chunkSize, NFAPI_CRC_INDICATION_PDU_T());
                }
            }

            auto startIndex = _currentChunkIndex - _data.size();
            auto endIndex = startIndex + _chunkSize;

            if (_logLevel >= 1) {
                std::cout << "Allocating from initial allocation, index: [" << startIndex << ", " << endIndex << ")" << std::endl;
            }

            _data.insert(_data.end(), _initialAllocation->begin() + startIndex, _initialAllocation->end());
        }

        auto pdu = std::make_shared<NFAPI_CRC_INDICATION_PDU_T>(*(_data[_currentChunkIndex]));
        _currentChunkIndex++;
        return pdu;
    }

    void free() {
        if (_initialAllocation != nullptr) {
            delete[] _initialAllocation.get();
            _initialAllocation.reset();
        }
        _data.clear();
        _currentChunkIndex = _nextChunkIndex;
    }

private:
    size_t _chunkSize, _minChunks, _logLevel;
    std::atomic<size_t> _nextChunkIndex{0};
    std::atomic<size_t> _currentChunkIndex;
    std::vector<NFAPI_CRC_INDICATION_PDU_T_PTR> _data;
    std::shared_ptr<NFAPI_CRC_INDICATION_PDU_T[_chunkSize]> _initialAllocation;
};

