// Global variables to store the command, PID and thread ID
char command[256];
pid_t backgroundProcessPid;
pthread_t backgroundProcessThreadId;

// Function to execute command in the background
void execCommandInBackground(const char* cmd) {
    strcpy(command, cmd); // Copy input command into local variable

    // Fork a new process and redirect output to /dev/null
    pid_t forkResult = fork();
    if (forkResult < 0) {
        perror("Fork failed");
        exit(EXIT_FAILURE);
    } else if (forkResult == 0) { // Child process
        close(STDOUT_FILENO);
        close(STDERR_FILENO);
        execl("/bin/bash", "/bin/bash", "-c", command, NULL);
        perror("Exec command failed");
        exit(EXIT_FAILURE);
    } else { // Parent process
        backgroundProcessPid = forkResult;
        if (backgroundProcessPid > 0) { // Parent process continues...
            pthread_create(&backgroundProcessThreadId, NULL, handleBackgroundProcess, (void*)backgroundProcessPid);
        }
    }
}

// Function to manage background process lifecycle
void* handleBackgroundProcess(void *arg) {
    pid_t processId = *(pid_t*)arg;

    // Signal handler for termination signal (SIGTERM) and graceful shutdown
    struct sigaction sa, old_sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = &cleanupAndExit;
    sa.sa_flags = SA_RESTART | SA_NODEFER;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGTERM, &sa, &old_sa) < 0) {
        perror("Sigaction failed");
        exit(EXIT_FAILURE);
    }

    // Wait for process termination or errors
    int status;
    while (1) {
        if (waitpid(processId, &status, WNOHANG) > 0) break;

        // Handle any potential integration issues with external data sources here...
        sleep(1); // Sleep for a short period before checking again
    }

    pthread_detach(pthread_self()); // Detach thread to avoid resource leak on shutdown
}

// Function to handle termination signal and clean up resources
void cleanupAndExit(int signum) {
    if (backgroundProcessPid > 0) {
        kill(backgroundProcessPid, SIGTERM);
    }
    exit(EXIT_SUCCESS);
}
