import os
import subprocess
import re
import hashlib
from cryptography.fernet import Fernet

def get_env_var(key):
    return os.getenv(key) or ""

def resolve_template(template, env_vars):
    pattern = re.compile("\\$(\\w+)")
    for key, value in env_vars.items():
        template = pattern.sub(value, template)
    return template

def encrypt_credentials(key, iv, plaintext):
    fernet = Fernet(key)
    ciphertext = fernet.encrypt(plaintext, iv).decode()
    return ciphertext

def write_file(path, content):
    with open(path, "w") as f:
        f.write(content)

def read_config_template():
    template_path = "network_service_config_template.txt"
    env_vars = {k: get_env_var(k) for k in [
        "SECRET_KEY", "INITIAL_IV", "CRYPTOGRAPHIC_SIGNATURE"
    ]}
    template = open(template_path, "r").read()
    template = resolve_template(template, env_vars)
    credential_section = """
# Credentials
SECRET_KEY: $(SECRET_KEY)
INITIAL_IV: $(INITIAL_IV)
CRYPTOGRAPHIC_SIGNATURE: $(CRYPTOGRAPHIC_SIGNATURE)
"""
    encrypted_creds = ""
    with open("network_service_encrypted_credentials.txt", "r") as f:
        for line in f:
            if re.search(r"^\$", line):
                continue
            encrypted_creds += line
    credential_section += "\n" + encrypted_creds
    template = template.replace("# Credentials\n", credential_section, 1)
    return template

def main():
    config_template = read_config_template()
    new_config_path = os.path.join(os.getcwd(), "new_network_service_config.txt")
    os.makedirs("encrypted_credentials", exist_ok=True)
    write_file(new_config_path, config_template)
    subprocess.run(["sed", "-i", ",s/SECRET_KEY\s*=\s*/SECRET_KEY=$(cat encrypted_credentials/secret_key)/g", os.getcwd()])

if __name__ == "__main__":
    main()
