static NFAPI_RRC_MSG* rrc_messages = NULL;
static size_t capacity = 0, size = 0;

void init_rrc_messages(size_t n) {
    if (n <= 0 || !((1 << n) - 1)) {
        syscall(SYS_panic, "Invalid N value");
    }
    capacity = (1 << n);
    size = 0;
    rrc_messages = malloc(capacity * sizeof(NFAPI_RRC_MSG));
    if (!rrc_messages) {
        syscall(SYS_panic, "Memory allocation failure");
    }
}

bool add_rrc_message(const NFAPI_RRC_MSG* msg) {
    pthread_mutex_lock(&mutex);
    for (size_t i = size; i-- > 0; ) {
        if (!rrc_messages[i].sequence_number &&
            rrc_messages[i].ue_id == msg->ue_id &&
            VALID_MESSAGE_TYPES[msg->message_type]) {
                rrc_messages[i] = *msg;
                size++;
                pthread_mutex_unlock(&mutex);
                return true;
        }
    }
    pthread_mutex_unlock(&mutex);
    syscall(SYS_panic, "Unable to add RRC message: UE or sequence number already exists");
    return false;
}
