#define CAPACITY_THRESHOLD 1024
#define TIERED_POOL_SIZE 64
#define POLLING_INTERVAL 1000
#define LOGFILE "operations.log"

struct CRCFLAG {
    bool flag;
};

struct UE_INFO {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    struct CRCFLAG crcflag;
};

typedef struct NFAPI_MESSAGE_T {
    struct UE_INFO *ue_infos;
    size_t capacity;
    size_t current_size;
    pthread_mutex_t lock;
    void* tiered_pool[TIERED_POOL_SIZE];
} NFAPI_MESSAGE_T;

void init_tiered_pool(NFAPI_MESSAGE_T *msg) {
    for (size_t i = 0; i < TIERED_POOL_SIZE; ++i)
        msg->tiered_pool[i] = mmap(NULL, sizeof(struct UE_INFO), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
}

NFAPI_MESSAGE_T* create_nfapi_message() {
    NFAPI_MESSAGE_T *msg = malloc(sizeof(NFAPI_MESSAGE_T));
    pthread_mutex_init(&msg->lock, NULL);
    msg->capacity = 0;
    msg->current_size = 0;
    init_tiered_pool(msg);
    return msg;
}

void destroy_nfapi_message(NFAPI_MESSAGE_T *msg) {
    for (size_t i = 0; i < TIERED_POOL_SIZE; ++i)
        munmap(msg->tiered_pool[i], sizeof(struct UE_INFO));
    free(msg);
}

void* get_ue_info(NFAPI_MESSAGE_T *msg, size_t index) {
    if (index >= msg->current_size || index >= msg->capacity)
        return msg->tiered_pool[TIERED_POOL_SIZE - 1];
    return &msg->ue_infos[index];
}

void add_ue_info(NFAPI_MESSAGE_T *msg, const RX_UE_INFORMATION_TAG *ue_info, const RNTI rnti) {
    if (msg->current_size >= msg->capacity) {
        size_t new_capacity = msg->capacity + CAPACITY_THRESHOLD;
        void **new_tiered_pool = realloc(msg->tiered_pool, TIERED_POOL_SIZE * new_capacity * sizeof(void*));
        if (!new_tiered_pool) {
            fprintf(stderr, "Failed to allocate memory\n");
            return;
        }
        memmove(&msg->tiered_pool[TIERED_POOL_SIZE], new_tiered_pool + TIERED_POOL_SIZE, (TIERED_POOL_SIZE * (msg->capacity - TIERED_POOL_SIZE)) * sizeof(void*));
        msg->tiered_pool = new_tiered_pool;
        init_tiered_pool(msg);
    }
    struct UE_INFO *ue = get_ue_info(msg, msg->current_size);
    ue->ue_info = *ue_info;
    ue->rnti = rnti;
    ue->crcflag.flag = rand() % 2;
    ++msg->current_size;
}

void update_ue_info(NFAPI_MESSAGE_T *msg, size_t index, const RX_UE_INFORMATION_TAG *ue_info, const RNTI rnti) {
    pthread_mutex_lock(&msg->lock);
    struct UE_INFO *ue = get_ue_info(msg, index);
    if (ue && ue != msg->tiered_pool[TIERED_POOL_SIZE - 1]) {
        ue->ue_info = *ue_info;
        ue->rnti = rnti;
    }
    pthread_mutex_unlock(&msg->lock);
}

void iterate_ue_infos(NFAPI_MESSAGE_T *msg, void(*func)(const struct UE_INFO*)) {
    pthread_mutex_lock(&msg->lock);
    for (size_t i = 0; i < msg->current_size; ++i) {
        func(get_ue_info(msg, i));
    }
    pthread_mutex_unlock(&msg->lock);
}

void calculate_average_crcflag(NFAPI_MESSAGE_T *msg) {
    size_t count = msg->current_size;
    bool total_flags = 0;
    if (count > 0) {
        iterate_ue_infos(msg, [](const struct UE_INFO* ue) {
            total_flags += ue->crcflag.flag;
        });
        double average = static_cast<double>(total_flags) / count;
        printf("Average CRCFLAG: %.2f\n", average);
    }
}

