// Memory pool for dynamic list management
typedef struct MemPool {
    void *buffer;
    size_t capacity;
    size_t used;
    size_t next_idx;
} MemPool_T;

MemPool_T* mempool_create(size_t initial_capacity) {
    MemPool_T *mempool = malloc(sizeof(MemPool_T));
    if (!mempool) return NULL;
    mempool->buffer = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!mempool->buffer) {
        free(mempool);
        return NULL;
    }
    mempool->capacity = initial_capacity;
    mempool->used = 0;
    mempool->next_idx = 0;
    return mempool;
}

void* mempool_pop(MemPool_T *mempool) {
    if (mempool->used == 0) return NULL;
    void *data = &((NFAPI_CRC_INDICATION_PDU_T *)mempool->buffer)[mempool->next_idx];
    mempool->used--;
    mempool->next_idx = (mempool->next_idx + 1) % mempool->capacity;
    return data;
}

void mempool_push(MemPool_T *mempool, void *data) {
    if (mempool->used == mempool->capacity) {
        size_t new_capacity = mempool->capacity * 2;
        void *new_buffer = realloc(mempool->buffer, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_buffer) return;
        mempool->buffer = new_buffer;
        mempool->capacity = new_capacity;
    }
    ((NFAPI_CRC_INDICATION_PDU_T *)mempool->buffer)[mempool->next_idx] = *((NFAPI_CRC_INDICATION_PDU_T*)data);
    mempool->used++;
