    int bearer_id;
    unsigned char nas_pdu[1024]; // Adjust size as needed
    pthread_mutex_t lock;
};

static void* generate_random(void *arg) {
    UeSessionData *session = (UeSessionData*) arg;
    int i;

    for (i = 0; i < sizeof(session->nas_pdu); ++i)
        session->nas_pdu[i] = rand();

    return NULL;
}

int init_sessions(UeSessionData **sessions, int capacity, pthread_t *threads) {
    int i, rc;

    if (!(sessions && capacity > 0))
        return -1; // Invalid arguments

    *sessions = calloc(capacity, sizeof(**sessions));
    if (!*sessions) {
        fprintf(stderr, "Error: Failed to allocate memory for sessions.\n");
        return -1;
    }

    for (i = 0; i < capacity; ++i) {
        rc = pthread_mutex_init(&(*sessions)[i].lock, NULL);
        if (rc != 0) {
            fprintf(stderr, "Error: Failed to initialize mutex for session %d.\n", i);
            return -1;
        }
    }

    for (i = 0; i < capacity; ++i) {
        rc = pthread_create(&threads[i], NULL, generate_random, &((*sessions)[i]));
        if (rc != 0) {
            fprintf(stderr, "Error: Failed to create thread for session %d.\n", i);
            return -1;
        }
    }

    // Wait for all threads to complete before returning
    for (i = 0; i < capacity; ++i)
        pthread_join(threads[i], NULL);

    return 0;
}
