#else
#define MAX_STRUCTURES 500000
#endif

static Record* pool = NULL;
static size_t used = 0;
static size_t capacity = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init_pool(size_t size, int key_min, int key_max, int nested_key_min, int nested_state_min, int nested_state_max) {
    if (size > MAX_STRUCTURES) {
        fprintf(stderr, "Error: Pool size exceeds the maximum limit\n");
        return;
    }

    capacity = size;
    pool = mmap(NULL, sizeof(Record) * capacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool == MAP_FAILED) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return;
    }

    for (size_t i = 0; i < capacity; ++i) {
        Record* rec = pool + i;
        rec->offset = i;
        rec->key = key_min + (rand() % (key_max - key_min + 1));
        rec->nested = NULL;
    }
}

Record* get_record(void) {
    pthread_mutex_lock(&lock);
    if (used < capacity) {
        Record* rec = pool + used++;
        rec->nested = calloc(1, sizeof(Record));
        if (!rec->nested) {
            fprintf(stderr, "Error: Memory allocation failed for nested record\n");
            --used;
        }
        return rec;
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

void update_state(Record* rec, State state) {
    if (rec->nested) {
        rec->nested->state = state;
    } else {
        fprintf(stderr, "Error: Trying to update the state of a non-nested record\n");
    }
}
