#include <iostream>
#include <vector>
#include <cstdlib>
#include <cstring>

struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
};

class ListManager {
public:
    // Constructor
    ListManager() : data(nullptr), size(0) {}

    // Destructor for proper memory deallocation
    ~ListManager() { clear(); }

    // Add element to the list
    void addElement(const NFAPI_CRC_INDICATION_PDU_T& element) {
        if (size == 0) {
            data = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)));
            data[0] = element;
            size++;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* newData = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(realloc(data, (size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T)));
            if (!newData) {
                std::cerr << "Error allocating memory" << std::endl;
                exit(EXIT_FAILURE);
            }
            data = newData;
            data[size] = element;
            size++;
        }
    }

    // Remove element from the list at given index
    void removeElementAtIndex(unsigned int index) {
        if (index >= size || index < 0) {
            std::cerr << "Invalid index" << std::endl;
            return;
        }

        for (unsigned int i = index + 1; i < size; ++i) {
            data[i - 1] = data[i];
        }

        NFAPI_CRC_INDICATION_PDU_T* newData = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(realloc(data, (size - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T)));
        if (!newData) {
            std::cerr << "Error allocating memory" << std::endl;
            exit(EXIT_FAILURE);
        }
        data = newData;
        size--;
    }

    // Clear the list and deallocate memory
    void clear() {
        if (data) {
            free(data);
            data = nullptr;
            size = 0;
        }
    }

    // Serialize the list to a byte array
    std::vector<uint8_t> serialize() const {
        std::vector<uint8_t> buffer;

        for (const auto& element : data) {
            buffer.insert(buffer.end(), reinterpret_cast<const uint8_t*>(&element), reinterpret_cast<const uint8_t*>(&element + 1));
        }
        return buffer;
    }

private:
    NFAPI_CRC_INDICATION_PDU_T* data;
    unsigned int size;
};
