    if (!node) {
        fprintf(stderr, "Memory allocation failure\n");
        return NULL;
    }
    node->user_session.session_id = session_id;
    node->user_session.bearer_id = bearer_id;
    node->user_session.session_state = UserSession::ACTIVE;
    pthread_mutex_init(&node->user_session.mutex, NULL);
    node->next = NULL;
    return node;
}

