    if (!session_list->head) {
        session_list->head = node;
        session_list->tail = node;
    } else {
        session_list->tail->next = node;
        session_list->tail = node;
    }

    pthread_mutex_unlock(&session_list->list_mutex);
}

// Function to search for a UserSession with the given bearer_id, returning it if found and NULL otherwise
Node* find_session_by_bearer_id(const SessionList* session_list, const char* bearer_id) {
    pthread_mutex_lock(&session_list->list_mutex);
    Node* current = session_list->head;

    while (current != NULL) {
        if (!session_list->validate_bearer_id(current->user_session.bearer_id)) {
            pthread_mutex_unlock(&session_list->list_mutex);
            return NULL;
        }
        if (strcmp(current->user_session.bearer_id, bearer_id) == 0) {
            pthread_mutex_unlock(&session_list->list_mutex);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&session_list->list_mutex);
    return NULL;
}

