#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
#include <limits.h>

// Maximum allowed records in the collection
#define MAX_RECORDS (1024 * 1024)

// Define record structure
typedef struct Record {
    int key;
    int value;
    struct Record* next;
} Record;

// Global variables to keep track of unique keys and errors
int num_unique_keys = 0;
int num_errors = 0;

Record* head = NULL;
Record* tail = NULL;

// Function to generate a random number within the specified range
int rand_in_range(int min, int max) {
    return (rand() % ((max - min) + 1)) + min;
}

// Function to insert a record into the collection
Record* insert_record(int key) {
    Record* current = head;
    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        // Memory allocation error, increment error count and return NULL
        num_errors++;
        return NULL;
    }

    new_record->key = key;
    new_record->value = rand_in_range(1, INT_MAX);
    new_record->next = NULL;

    // No records in the collection yet or a duplicate key
    if (!head || head->key == key) {
        if (tail) {
            tail->next = new_record;
            tail = new_record;
        } else {
            head = new_record;
            tail = new_record;
        }
    } else {
        // Traverse the list to find an appropriate position for the new record
        while (current->next && current->next->key != key) {
            current = current->next;
        }
        if (!current->next) {
            // Reach end of the list, insert after last record
            current->next = new_record;
            tail = new_record;
        } else {
            // Found a position where key doesn't exist yet, insert new record there
            Record* temp = new_record;
            temp->next = current->next;
            current->next = temp;
        }
    }

    num_unique_keys++;
    return new_record;
}

// Function to manage the dynamic collection of records
void manage_collection(int max_records, int key_range) {
    srand(time(NULL));

    if (max_records <= 0 || key_range <= 0) {
        fprintf(stderr, "Invalid parameters provided.\n");
        return;
    }

    // If the collection exceeds the maximum allowed records, reset it by freeing memory and initializing head and tail to NULL
    if (num_unique_keys > max_records) {
        Record* current = head;
        while (head) {
            head = head->next;
            free(current);
            current = head;
        }
        head = tail = NULL;
        num_unique_keys = 0;
    }

    // Insert records until the collection reaches the maximum allowed records or a duplicate key is encountered
    for (int i = 0; i < key_range && num_unique_keys < max_records; ++i) {
        if (!insert_record(i)) {
            fprintf(stderr, "Memory allocation error.\n");
        }
    }

    // Log the number of unique keys successfully inserted and errors encountered during execution
    printf("Number of unique keys successfully inserted: %d\n", num_unique_keys);
    printf("Number of memory allocation errors: %d\n", num_errors);
}
