    if (!(session_array = mmap(NULL, sizeof(UeSessionData) * MAX_SESSIONS, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0))) {
        fprintf(stderr, "Memory allocation failure!\n");
        return;
    }

    pthread_mutex_init(&sessions_mutex, NULL);
}

UeSessionData* get_session() {
    UeSessionData* session = NULL;
    for (size_t i = 0; i < MAX_SESSIONS; ++i) {
        if (pthread_mutex_trylock(&session_array[i].mutex)) {
            session = &session_array[i];
            break;
        }
    }

    if (!session) {
        fprintf(stderr, "No available sessions. Increase the number of sessions or handle concurrency issues.\n");
        return NULL;
    }

    // Initialize session data and set unique ue_id and bearer_id
    session->ue_id = rand() % UINT64_MAX;
    session->bearer_id = rand() % UINT64_MAX;
    memset(session->nas_pdu, rand(), sizeof(session->nas_pdu));

    pthread_mutex_unlock(&sessions_mutex);
    return session;
}
