#include <boost/lockfree/queue.hpp>
#include <memory>
#include <list>
#include <mutex>
#include <atomic>

// Define LTE_UERadioResourceConfigDedicated_t structure here

struct CellIdentity final {
    std::atomic<unsigned int> cell_id; // Valid cell identity
    std::shared_ptr<LTE_UERadioResourceConfigDedicated_t> config; // Shared configuration pointer
};

class LteDynamicList {
private:
    using CellQueue = boost::lockfree::queue<std::unique_ptr<CellIdentity>>;
    std::mutex mtx_;
    CellQueue queue_;
    std::list<std::unique_ptr<CellIdentity>> cell_list_; // List for iterative access

public:
    void add(unsigned int cell_id, std::unique_ptr<LTE_UERadioResourceConfigDedicated_t> config) {
        CellIdentity* ptr;
        if (queue_.pop(ptr)) {
            std::unique_ptr<CellIdentity> new_cell(new CellIdentity());
            new_cell->cell_id = cell_id;
            new_cell->config = std::move(config);
            std::swap(*ptr, *new_cell); // Atomically swaps the unique pointers and updates the list
        } else {
            std::unique_ptr<CellIdentity> new_cell(new CellIdentity());
            new_cell->cell_id = cell_id;
            new_cell->config = std::move(config);
            std::lock_guard<std::mutex> lock(mtx_); // Lock for appending to the list
            cell_list_.push_back(std::move(new_cell));
        }
    }

    void remove(unsigned int cell_id) {
        std::unique_ptr<CellIdentity> cell;
        if (queue_.pop(cell)) {
            if (cell->cell_id == cell_id) {
                // Empty the shared configuration pointer to mark for removal from the list
                cell->config = nullptr;
