    ip.lock = PTHREAD_MUTEX_INITIALIZER;
    ip.integers = mmap(NULL, sizeof(uint16_t), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ip.integers == MAP_FAILED) return EXIT_FAILURE;
    ip.capacity = 8;
    ip.count = 0;

    // Spawn processing threads
    pthread_t threads[NUM_THREADS];
    for (size_t i = 0; i < NUM_THREADS; ++i)
        if (pthread_create(&threads[i], NULL, process_data, &ip) != 0) return EXIT_FAILURE;

    // Wait for threads to finish processing
    for (size_t i = 0; i < NUM_THREADS; ++i)
        pthread_join(threads[i], NULL);

    // Print the largest integer in the array and free resources
