// Define RX_FRAME_INFO structure
typedef struct {
    time_t timestamp;
    int rssi;
    int cqi;
    int mcs;
} RX_FRAME_INFO;

// Define PRTS structure with a linked list of RX_FRAME_INFO structures and a mutex for concurrency control
typedef struct PRTS {
    RX_FRAME_INFO *rx_frame_infos;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PRTS;

// Function to initialize a new PRTS with given initial capacity
PRTS* init_prts(size_t initial_capacity) {
    PRTS *prts = (PRTS *) malloc(sizeof(PRTS));
    prts->rx_frame_infos = (RX_FRAME_INFO *) malloc(initial_capacity * sizeof(RX_FRAME_INFO));
    prts->capacity = initial_capacity;
    prts->size = 0;
    pthread_mutex_init(&prts->lock, NULL);
    return prts;
}

// Function to append an RX_FRAME_INFO structure to the PRTS and update its size
void push_rx_frame_info(PRTS *prts, const RX_FRAME_INFO *frame) {
    pthread_mutex_lock(&prts->lock);

    // Allocate a new array if the current capacity is reached
    if (prts->size == prts->capacity) {
        size_t new_capacity = prts->capacity * 2;
        RX_FRAME_INFO *new_rx_frames = realloc(prts->rx_frame_infos, new_capacity * sizeof(RX_FRAME_INFO));
        if (new_rx_frames == NULL) {
            fprintf(stderr, "Failed to allocate memory for new capacity\n");
            pthread_mutex_unlock(&prts->lock);
            return;
        }
        prts->rx_frame_infos = new_rx_frames;
        prts->capacity = new_capacity;
    }

    // Add the frame to the linked list and update size
    prts->rx_frame_infos[prts->size] = *frame;
    prts->size++;

    pthread_mutex_unlock(&prts->lock);
}

// Function to destroy a PRTS and free its allocated memory
void destroy_prts(PRTS *prts) {
    if (prts != NULL) {
        free(prts->rx_frame_infos);
        free(prts);
    }
}
```

