NFAPI_CRC_INDICATION_PDU* create_ue_data(size_t N) {
    size_t i;
    NFAPI_CRC_INDICATION_PDU *ue_data = (NFAPI_CRC_INDICATION_PDU*) malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU));

    if (!ue_data) {
        perror("Error allocating memory\n");
