NFAPI_CRC_INDICATION_PDU_T* populate_crc_indications(unsigned int N) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    unsigned int i, unique_rntis[65536] = {0}, num_elements = 0;
    NFAPI_CRC_INDICATION_PDU_T *crc_indications;

    if (N > 1000) {
        log_error("Error: Requested number of elements exceeds the maximum capacity (1000).");
        return NULL;
    }

    crc_indications = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indications) {
        log_error("Error: Failed to allocate memory.");
        return NULL;
    }

    for (i = 0; i < N && num_elements < 65536; ++i) {
        pthread_mutex_lock(&mutex);
        while (unique_rntis[gen_rnti()] != 0) {}
        unique_rntis[gen_rnti()] = 1;
        crc_indications[i].rxi = i + 1;
        crc_indications[i].rnti = gen_rnti();
        crc_indications[i].crc_indication_rel8_tag = rand() % 256;
        crc_indications[i].crcflag = (rand() % 2) == 0;
        pthread_mutex_unlock(&mutex);
        num_elements++;
    }

    log_info("Processed %d elements.", num_elements);
    return crc_indications;
}
