typedef struct FILE_RECORD_T {
    int fd;
    time_t timestamp;
    uint32_t crc32;
    bool validity_flag;
} FILE_RECORD_T;

#define MAX_SIZE 1000
static FILE_RECORD_T* records = NULL;
static char** filepaths = NULL;
static int* indices = NULL;
static size_t num_records = 0;
static size_t num_filepaths = 0;
static size_t num_indices = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_data_structures(size_t size) {
    if (size > MAX_SIZE) {
        fprintf(stderr, "Error: Array size exceeds the maximum limit of %zu\n", MAX_SIZE);
        exit(1);
    }

    records = malloc(sizeof(FILE_RECORD_T) * size);
    filepaths = calloc(size, sizeof(char*));
    indices = malloc(size * sizeof(int));

    num_records = size;
    num_filepaths = size;
    num_indices = size;
}

void generate_unique_timestamp() {
    time_t unique_time;
    while (1) {
        unique_time = time(NULL);
        int found = 0;
        for (size_t i = 0; i < num_records; ++i) {
            if (unique_time == records[i].timestamp) {
                found = 1;
                break;
            }
        }
        if (!found) {
            break;
        }
    }
    records[num_records - 1].timestamp = unique_time;
}

uint32_t generate_unique_crc32() {
    static uint64_t seed = 0;
    const size_t buffer_size = 1 << 15;
    static char buffer[buffer_size];

    if (seed == 0) {
        seed = time(NULL);
    }

    for (size_t i = 0; i < num_records; ++i) {
        crc32_buf(buffer, sizeof(buffer), &seed);
    }

    return seed;
}

void populate_data_structures() {
    for (size_t i = 0; i < num_indices; ++i) {
        generate_unique_timestamp();
        records[i].crc32 = generate_unique_crc32();
        records[i].validity_flag = true;
    }
}

void resize(size_t new_size) {
    if (new_size <= num_records) return;

    FILE_RECORD_T* temp_records = realloc(records, sizeof(FILE_RECORD_T) * new_size);
    char** temp_filepaths = realloc(filepaths, sizeof(char*) * new_size);
    int* temp_indices = realloc(indices, sizeof(int) * new_size);

    if (!temp_records || !temp_filepaths || !temp_indices) {
        fprintf(stderr, "Error: Failed to allocate memory for data structures\n");
        exit(1);
    }

    records = temp_records;
    filepaths = temp_filepaths;
    indices = temp_indices;

    num_records += new_size - num_records;
    num_filepaths += new_size - num_filepaths;
    num_indices += new_size - num_indices;
}

void cleanup() {
    pthread_mutex_destroy(&mutex);

    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].fd > 0) close(records[i].fd);
    }

    free(records);
    free(filepaths);
    free(indices);
}
