static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static void* list = NULL;
static size_t count = 0;
static size_t capacity = 0;

void add_to_list(NFAPI_CRC_INDICATION_PDU_T* item) {
    pthread_mutex_lock(&list_mutex);
    if (count == capacity) {
        void** new_list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (capacity + 10));
        if (!new_list) {
            printf("Error: Out of memory\n");
            pthread_mutex_unlock(&list_mutex);
            return;
        }
        list = new_list;
        capacity += 10;
    }
    list[count] = *item;
    count++;
    printf("Added item to the list\n");
    pthread_mutex_unlock(&list_mutex);
}

void remove_from_list(size_t index) {
    pthread_mutex_lock(&list_mutex);
    if (index >= count || index < 0) {
        printf("Error: Invalid index\n");
        pthread_mutex_unlock(&list_mutex);
        return;
    }
    memmove(list + index, list + index + 1, (count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    count--;
    printf("Removed item from the list\n");
    pthread_mutex_unlock(&list_mutex);
}

