        free(current);
        total_allocated--;
        pthread_mutex_unlock(&list_mutex);
        return true;
    }

    while (current->next != NULL && current->next->data.rnti != rnti) {
        current = current->next;
    }

    if (current->next == NULL) {
        pthread_mutex_unlock(&list_mutex);
        return false;
    }

    ListNode* temp = current->next;
    current->next = temp->next;
    free(temp);
    total_allocated--;
    pthread_mutex_unlock(&list_mutex);
    return true;
