typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

#define LIST_TYPE SINGLY_LINKED_LIST // or ARRAY_BASED
#ifdef SINGLY_LINKED_LIST
    #define ELEMENT_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)
#else
    #define ELEMENT_SIZE (sizeof(NFAPI_CRC_INDICATION_PDU_T)*1024) // 1KB buffer for array elements
#endif

// Custom hash function
uint32_t custom_hash(uint16_t key) {
    uint32_t hash = 5381;
    int c;

    while (key >= 65536) {
        key -= 65536;
        hash = ((hash << 5) + hash) + key; /* hash * 33 + key */
    }
    for (c = 8; c > 0; c--) {
        key = (key << 3) + (key >> 0x1b);
        hash = ((hash << 5) + hash) + key; /* hash * 33 + key */
    }

    return hash % N; // Modulo the list size to get a valid index
}

NFAPI_CRC_INDICATION_PDU_T* create_list(uint64_t N) {
    if (N <= 0 || N > 1e6) {
        fprintf(stderr, "Invalid value for N: %" PRIu64 "\n", N);
        exit(EXIT_FAILURE);
    }

    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T **tail = &head;

    for (uint64_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *element = mmap(NULL, ELEMENT_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (element == MAP_FAILED) {
            perror("mmap");
            exit(EXIT_FAILURE);
        }

        element->RX_UE_INFORMATION_TAG = rand() % 65536;
        element->RNTI = rand() % 1024 + 1; // Valid range: 1 to 1023
        element->CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0;
        element->CRCFLAG = rand() % 2;
        element->next = NULL;

        if (*tail == NULL) {
            *tail = element;
        } else {
            (*tail)->next = element;
            tail = &((*tail)->next);
        }
    }

    return head;
}
