    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

struct queue {
    Node* head;
    Node* tail;
    int capacity;
    pthread_mutex_t mutex;
    bool (*callback)(int); // callback function to signal memory capacity reached
};

void create_queue(struct queue* q, int capacity) {
    q->head = NULL;
    q->tail = NULL;
    q->capacity = capacity;
    pthread_mutex_init(&q->mutex, NULL);
}

bool add_to_queue(struct queue* q, const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return false; // memory error

    new_node->data = *data;
    new_node->next = NULL;

    pthread_mutex_lock(&q->mutex);

    if (q->head == NULL) {
        q->head = new_node;
        q->tail = new_node;
    } else {
        q->tail->next = new_node;
        q->tail = new_node;
    }

    pthread_mutex_unlock(&q->mutex);

    return true;
}

NFAPI_CRC_INDICATION_PDU_T* pop_from_queue(struct queue* q) {
    Node* temp;
    NFAPI_CRC_INDICATION_PDU_T* data;

    pthread_mutex_lock(&q->mutex);

    if (q->head == NULL) {
        pthread_mutex_unlock(&q->mutex);
        return NULL;
    }

    temp = q->head;
    data = &temp->data;
    q->head = temp->next;

    if (q->head == NULL)
        q->tail = NULL;

    pthread_mutex_unlock(&q->mutex);

    free(temp); // free memory after using data

    return data;
}

void generate_data(NFAPI_CRC_INDICATION_PDU_T* data, int index) {
    data->rx_ue_information_tag = index;
    data->rnti = index * 1000 + getpid(); // make RNTI unique and time-sensitive
    data->crc_indication_rel8_tag.crcflag = rand() % 2;
}

void run(struct queue* q, int max_packages, bool (*callback)(int)) {
    create_queue(q, max_packages);
    for (int i = 0; i < max_packages; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data;
        generate_data(&data, i);
        add_to_queue(q, &data);
        if (q->head && q->callback && q->capacity == q->head->next - q->head)
            callback(i); // call the provided callback when memory capacity is reached
    }
}
