    LOG_RECORD_T *buffer;    // Circular buffer of log records
    size_t head;             // Index of the next free position in the buffer
    size_t tail;             // Index of the next record to be processed
    int fd;                  // File descriptor for remote logging (if applicable)
    void (*async_callback)(const LOG_RECORD_T*);// Asynchronous callback function, if needed
};

void logger_init(struct logger *logger, size_t max_buffer_size, int remote_log_enabled, void (*async_callback)(const LOG_RECORD_T*)) {
