void init_data_structures(size_t timestamps_count, size_t sensors_count, size_t measurements_count, float* calibration_params, char** error_msg) {
    long* timestamps = malloc(timestamps_count * sizeof(long));
    if (!timestamps) {
        *error_msg = "Memory allocation for timestamps failed";
        return;
    }

    float* sensors = calloc(sensors_count, sizeof(float));
    if (!sensors) {
        free(timestamps);
        *error_msg = "Memory allocation for sensors failed";
        return;
    }

    measurement* measurements = malloc(measurements_count * sizeof(measurement));
    if (!measurements) {
        free(timestamps);
        free(sensors);
        *error_msg = "Memory allocation for measurements failed";
        return;
    }

    // Validate timestamp range and initialize with zero
    if (sizeof(long) * CHAR_BIT < 32) {
        *error_msg = "Timestamp size is not 64-bit on this system.";
        free(timestamps);
        free(sensors);
        free(measurements);
        return;
    }
    for (size_t i = 0; i < timestamps_count; ++i) {
        if (timestamps[i] < 0 || LONG_MAX < timestamps[i]) {
            *error_msg = "Invalid timestamp value.";
            free(timestamps);
            free(sensors);
            free(measurements);
            return;
        }
    }

    // Validate sensor ID range and initialize with zero
    if (sizeof(int) < 16) {
        *error_msg = "Sensor ID size is not 16-bit on this system.";
        free(timestamps);
        free(sensors);
        free(measurements);
        return;
    }
    for (size_t i = 0; i < sensors_count; ++i) {
        if (sensors[i] < 0 || INT_MAX < sensors[i]) {
            *error_msg = "Invalid sensor ID value.";
            free(timestamps);
            free(sensors);
            free(measurements);
            return;
        }
    }

    // Fetch initial calibration parameters (optional)
    if (calibration_params && sensors_count > 0) {
        for (size_t i = 0; i < sensors_count; ++i) {
            if (!calibration_params[i]) {
                printf("No calibration parameter found for sensor ID %d. Using default value of 1.0.\n", i + 1);
                sensors[i] = 1.0f;
            } else {
                sensors[i] = calibration_params[i];
            }
        }
    }

    // Initialize measurements with zero and sensor IDs
    for (size_t i = 0; i < measurements_count; ++i) {
        measurements[i].timestamp = 0;
        measurements[i].sensor_id = -1;
        measurements[i].reading = 0.0f;
    }
}
