typedef struct IP_node {
    struct in_addr addr;
    struct NICP *nicp;
    struct IP_node *next;
} IP_node;

typedef struct NICP {
    char mac[18]; // MAC address as strings (e.g., "00:11:22:33:44:55")
    struct in_addr ip;
    int state;
    struct NICP *next;
} NICP;

IP_node *ip_head = NULL;
NICP *nicp_head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Helper function to generate a random interface state flag
int rand_state() {
    return rand() % 2;
}

// MAC address lookup function (external API call)
NICP* mac_lookup(const char* mac) {
    // Replace with actual API call logic
    if (!nicp_head) {
        strcpy(nicp_head->mac, mac);
        nicp_head->ip = (struct in_addr){{0}};
        nicp_head->state = rand_state();
        return nicp_head;
    }

    NICP *current = nicp_head;
    while (current->next) {
        current = current->next;
    }
    strcpy(current->next = malloc(sizeof(*current)), mac);
    current->next->state = rand_state();
    return current->next;
}

// Function to validate and process a single IP address
void process_ip(const char* ip) {
    struct in_addr addr;
    if (inet_pton(AF_INET, ip, &addr) <= 0) {
        printf("Warning: Invalid IP address %s\n", ip);
        return;
    }

    pthread_mutex_lock(&list_mutex);
    IP_node *new_ip = malloc(sizeof(*new_ip));
    new_ip->addr = addr;

    // MAC address lookup
    NICP *nicp = mac_lookup(new_ip->addr.s_addr ? ip : "default");
    new_ip->nicp = nicp;

    new_ip->next = ip_head;
    ip_head = new_ip;
    pthread_mutex_unlock(&list_mutex);
}

// Function to process a batch of IP addresses from standard input
void process_batch() {
    char buf[INET_ADDRSTRLEN];
    int count = 0, i = 0;

    while (fgets(buf + i, sizeof(buf) - i, stdin)) {
        if (!count++ || i == sizeof(buf) - 1) {
            process_ip(strchr(buf, '\n') ? buf : buf); // Process newline-delimited IP or fill buffer
            i = 0;
        } else
            i++;
    }
}

// Thread function to process multiple batches concurrently
void* worker_func() {
    while (1) {
        process_batch();
        usleep(1e6); // Sleep for 1ms to meet the time limit constraint
    }
}

int main() {
    pthread_t workers[NUM_WORKERS];

    for (size_t i = 0; i < NUM_WORKERS; ++i) {
        if (pthread_create(&workers[i], NULL, &worker_func, NULL)) {
            fprintf(stderr, "Error: Failed to create worker thread\n");
            return 1;
        }
    }

    // Process remaining input after creating all workers
    process_batch();

    for (size_t i = 0; i < NUM_WORKERS; ++i) {
        if (pthread_join(workers[i], NULL)) {
            fprintf(stderr, "Error: Failed to join worker thread\n");
            return 1;
        }
    }

    // Free resources and deallocate memory
    IP_node *current = ip_head;
    while (current) {
        IP_node *temp = current;
        current = current->next;
        free(temp);
    }

    NICP *nicp = nicp_head;
    while (nicp) {
        NICP *tmp = nicp;
        nicp = nicp->next;
        free(tmp);
    }

    return 0;
}
