struct TCP_CONNECTION_RECORD {
    in_port_t tcp_port;
    struct sockaddr_in ip_address;
    time_t timestamp;
};

typedef struct TCP_CONNECTION_QUEUE {
    struct TCP_CONNECTION_RECORD *records;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} TCP_CONNECTION_QUEUE;

TCP_CONNECTION_QUEUE* tcp_connection_queue_create(size_t initial_capacity) {
    TCP_CONNECTION_QUEUE *queue = malloc(sizeof(TCP_CONNECTION_QUEUE));
    if (!queue) {
        fprintf(stderr, "Error: Failed to allocate memory for TCP connection queue\n");
        return NULL;
    }

    queue->records = calloc(initial_capacity, sizeof(struct TCP_CONNECTION_RECORD));
    if (!queue->records) {
        fprintf(stderr, "Error: Failed to allocate memory for records in TCP connection queue\n");
        free(queue);
        return NULL;
    }

    pthread_mutex_init(&queue->lock, NULL);
    queue->size = 0;
    queue->capacity = initial_capacity;

    return queue;
}

void tcp_connection_queue_destroy(TCP_CONNECTION_QUEUE *queue) {
    free(queue->records);
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

size_t tcp_connection_queue_push(TCP_CONNECTION_QUEUE *queue, const struct TCP_CONNECTION_RECORD *record) {
    if (queue->size >= queue->capacity && queue->capacity < MAX_RECORDS) {
        fprintf(stderr, "Error: TCP connection queue is full. Increase the maximum capacity or consider upgrading the hardware\n");
        return 0;
    }

    pthread_mutex_lock(&queue->lock);

    if (queue->size < queue->capacity) {
        memcpy(&queue->records[queue->size], record, sizeof(struct TCP_CONNECTION_RECORD));
        queue->records[queue->size].timestamp = time(NULL);
        ++queue->size;
    }

    pthread_mutex_unlock(&queue->lock);

    return 1;
}

