typedef struct pdu_list_node {
    NFAPI_CRAC_INDICATION_PDU_T *pdu;
    struct pdu_list_node *next;
} pdu_list_node_t;

static size_t num_pdus = 0;
static pdu_list_node_t *head = NULL;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t buffer_not_full = PTHREAD_COND_INITIALIZER;
static pthread_cond_t buffer_not_empty = PTHREAD_COND_INITIALIZER;
static void *buffer; // Non-volatile memory region for temporary storage
static size_t buffer_size = 0;

void nfapi_crc_indication_pdu_list_init(size_t buffer_size) {
    this->buffer_size = buffer_size;
    if (posix_memalign((void**)&buffer, sysconf(_SC_PAGE_SIZE), buffer_size)) {
        fprintf(stderr, "Failed to allocate temporary storage\n");
        exit(EXIT_FAILURE);
    }
}

NFAPI_CRAC_INDICATION_PDU_T* nfapi_crc_indication_pdu_new() {
    NFAPI_CRAC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRAC_INDICATION_PDU_T));
    if (!pdu) {
        fprintf(stderr, "Failed to allocate PDU\n");
        exit(EXIT_FAILURE);
    }

    pdu->rx_ue_information_tag = RX_UE_INFORMATION_TAG_INVALID;
    pdu->rnti = 0;
    pdu->crc_indication_rel8_tag.crc_flag = rand() % 2;

    return pdu;
}

void nfapi_crc_indication_pdu_list_add(NFAPI_CRAC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list_mutex);

    while (num_pdus >= 10000) {
        pthread_cond_wait(&buffer_not_full, &list_mutex);
    }

    if (buffer_size > 0 && num_pdus + buffer_size >= 10000) {
        pdu_list_node_t *new_head = malloc(sizeof(pdu_list_node_t));
        new_head->pdu = pdu;
        new_head->next = head;

        if (num_pdus + buffer_size >= 10000) {
            memcpy(buffer, head, sizeof(NFAPI_CRAC_INDICATION_PDU_T) * num_pdus);
            free(head);
            head = new_head;
            num_pdus += buffer_size;
        } else {
            pdu_list_node_t *current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_head;
            num_pdus++;
        }
    } else {
        pdu_list_node_t *new_node = malloc(sizeof(pdu_list_node_t));
        if (!new_node) {
            fprintf(stderr, "Failed to allocate PDU list node\n");
            exit(EXIT_FAILURE);
        }
        new_node->pdu = pdu;
        new_node->next = head;
        head = new_node;
        num_pdus++;
    }

    pthread_mutex_unlock(&list_mutex);
    pthread_cond_signal(&buffer_not_empty);
}

NFAPI_CRAC_INDICATION_PDU_T* nfapi_crc_indication_pdu_list_pop() {
    pthread_mutex_lock(&list_mutex);

    if (num_pdus == 0) {
        pthread_cond_wait(&buffer_not_empty, &list_mutex);
    }

    pdu_list_node_t *current = head;
    NFAPI_CRAC_INDICATION_PDU_T *pdu = current->pdu;

    if (num_pdus == 1) {
        free(head);
        head = NULL;
        num_pdus--;
    } else {
        while (current->next != NULL && current->next->next != NULL) {
            current = current->next;
        }
        current->next = NULL;
        free(head);
        head = current;
        num_pdus--;
    }

    pthread_mutex_unlock(&list_mutex);
    pthread_cond_signal(&buffer_not_full);

    return pdu;
}
```

