(function () {
    const form = document.querySelector('form');
    let validators = {};
    let validationServiceUrl = 'https://validation-service.example.com/validate'; // Replace with actual service URL
    let validationServiceTimeout = 1000; // Timeout for asynchronous calls (in milliseconds)

    function registerValidator(field, validatorFunction) {
        validators[field] = validatorFunction;
    }

    function validateForm() {
        const formData = new FormData(form);

        return Promise.all([...formData].map(([field, value]) =>
            validators[field](value)
                .catch(() => true) // Fallback for validation service errors or unavailability
        ).reduce((valid, result) => valid && result));
    }

    function getValidator(field) {
        const fieldType = form.elements[field].type;

        switch (fieldType) {
            case 'text':
                return textFieldValidation;
            case 'email':
                return emailFieldValidation;
            case 'password':
                return passwordFieldValidation;
            // Add additional field types as needed
            default:
                return () => true; // Default to no validation for unsupported input types
        }
    }

    function textFieldValidation(value) {
        // Implement custom text field validation logic here
        return new Promise((resolve) => setTimeout(() => resolve(value.trim().length > 0), validationServiceTimeout));
    }

    function emailFieldValidation(value) {
        // Implement custom email field validation logic here
        const emailRegex = /^[\w-]+(\.[\w-]+)*@([\w-]+\.)+[a-zA-Z]{2,7}$/;
        return new Promise((resolve) => setTimeout(() => resolve(emailRegex.test(value)), validationServiceTimeout));
    }

    function passwordFieldValidation(value) {
        // Implement custom password field validation logic here
        const passwordRegex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&]).{8,}$/;
        return new Promise((resolve) => setTimeout(() => resolve(passwordRegex.test(value)), validationServiceTimeout));
    }

    function setupFormValidation() {
        form.addEventListener('input', handleFieldChange);
    }

    function handleFieldChange(event) {
        validateForm().then(valid => {
            if (valid) form.querySelectorAll('.error').forEach(node => node.remove());
            else handleInvalidFields();
        });
    }

    function handleInvalidFields() {
        const invalidFields = Array.from(form.querySelectorAll('.invalid'));
        let errorMessage;

        if (invalidFields.length > 1) {
            errorMessage = 'Please correct the errors in the following fields:';
        } else {
            errorMessage = `Please correct the error in this field:`;
        }

        invalidFields[0].classList.add('error');
        form.querySelector('.form-errors').textContent = errorMessage;
    }

    function setupForm() {
        form.addEventListener('submit', event => {
            event.preventDefault(); // Prevent the form from submitting normally

            validateForm().then(valid => {
                if (valid) form.submit();
            });
        });
    }

    registerValidator('email', emailFieldValidation);
    registerValidator('password', passwordFieldValidation);

    setupFormValidation();
    setupForm();
})();
