#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <sys/mman.h>

typedef struct {
    int key;
    int value;
    char *label;
} record;

void init_array(int *arr, size_t size) {
    for (size_t i = 0; i < size; ++i)
        arr[i] = i;
}

size_t get_memory_usage(void* ptr, size_t size) {
    return (size_t)(posix_memalign((void**)&ptr, getpagesize(), size) - size);
}

bool allocate_records(record** arr, size_t capacity, size_t *used, size_t max_kb) {
    if (*used + sizeof(record) > capacity * sizeof(record)) return false;

    void* ptr = mmap(0, (capacity * sizeof(record)), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!ptr) return false;

    *arr = ptr;
    *used += sizeof(record);
    size_t memory_usage = get_memory_usage(*arr, capacity * sizeof(record));

    if (memory_usage > max_kb) {
        munmap(*arr, capacity * sizeof(record));
        *arr = NULL;
        return false;
    }

    for (size_t i = 0; i < capacity; ++i) {
        record* rec = (*arr) + i;
        rec->value = rand() % 1000 + 1;
        asprintf(&rec->label, "Label_%ld", (long) time(NULL));
    }

    return true;
}

bool resize_offsets_and_keys(int** offsets, int* keys, size_t new_capacity, size_t *used) {
    if (!new_capacity) return false;

    int* new_offsets = realloc(*offsets, new_capacity * sizeof(int));
    if (!new_offsets) return false;
    *offsets = new_offsets;

    init_array(*offsets, new_capacity);

    int* new_keys = realloc(keys, new_capacity * sizeof(int));
    if (!new_keys) return false;
    keys = new_keys;

    *used += (new_capacity - (*used) / 2) * sizeof(int);
    return true;
}

void free_resources(record* arr, int* offsets, int* keys) {
    for (size_t i = 0; i < arr ? *((size_t*)arr) : 0; ++i) {
        free(arr[i].label);
    }
    free(arr);
    free(keys);
    munmap(*offsets, ((*offsets) - (int*)offsets) * sizeof(int));
}
