namespace RandomSystem {
    struct RandomGenerator {
        std::mt19937_64 engine;
        std::uniform_int_distribution<> dist;

        int seed;
        std::atomic<bool> alive{true};
        std::mutex mtx;

        static std::unordered_map<int, std::unique_ptr<RandomGenerator>> generators;
        static std::mutex genMapMtx;

        RandomGenerator(int seed) : engine(seed), dist(0, 1000) {
            std::lock_guard<std::mutex> lock(genMapMtx);
            generators[seed] = std::make_unique<RandomGenerator>(seed);
        }

        ~RandomGenerator() {
            std::lock_guard<std::mutex> lock(genMapMtx);
            if (alive.exchange(false)) {
                generators.erase(seed);
            }
        }

        static void registerGenerator(int seed, RandomGenerator* generator) {
            std::lock_guard<std::mutex> lock(genMapMtx);
            generators[seed] = std::unique_ptr<RandomGenerator>(generator);
        }

        static void deregisterGenerator(int seed) {
            std::lock_guard<std::mutex> lock(genMapMtx);
            if (generators.find(seed) != generators.end()) {
                generators[seed]->alive = false;
            }
        }

        static std::vector<int> generate(int count, int seed) {
            auto it = generators.find(seed);
            if (it == generators.end()) {
                new RandomGenerator(seed); // Create a new generator if not found
            }

            std::unique_lock<std::mutex> lock(it->second->mtx);
            std::vector<int> result;

            for (int i = 0; i < count; ++i) {
                result.push_back(it->second->dist(it->second->engine));
            }

            return result;
        }
    };

    std::unordered_map<int, std::unique_ptr<RandomGenerator>> RandomGenerator::generators;
    std::mutex RandomGenerator::genMapMtx;

