typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _CRC_GENERATOR_DATA {
    size_t num_structures;
    NFAPI_CRC_INDICATION_PDU_T** structures;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
    bool keep_running;
} CRC_GENERATOR_DATA;

void* crc_generator(void* arg) {
    CRC_GENERATOR_DATA* data = arg;
    while (data->keep_running) {
        pthread_mutex_lock(&data->mutex);
        if (data->num_structures < 10000 && malloc_used() < 5 * MB) {
            NFAPI_CRC_INDICATION_PDU_T* structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            structure->tag = gen_random_ue_information_tag();
            structure->rnti = gen_random_rnti();
            structure->crc_indication.crcflag = rand() % 2;
            data->structures[data->num_structures++] = structure;
        }
        pthread_mutex_unlock(&data->mutex);
        pthread_cond_signal(&data->cond_var);
        usleep(1000 * 1.0 - get_processing_latency());
    }
    return NULL;
}

void init_crc_generator(CRC_GENERATOR_DATA* data, int num_structures) {
    data->num_structures = num_structures;
    data->structures = malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (size_t i = 0; i < num_structures; ++i) {
        data->structures[i] = NULL;
    }
    pthread_mutex_init(&data->mutex, NULL);
    pthread_cond_init(&data->cond_var, NULL);
    data->keep_running = true;
}

void start_crc_generator(CRC_GENERATOR_DATA* data) {
    pthread_t thread;
    pthread_create(&thread, NULL, crc_generator, data);
}

void stop_crc_generator(CRC_GENERATOR_DATA* data) {
    data->keep_running = false;
    pthread_cond_broadcast(&data->cond_var);
    pthread_join(thread, NULL);
}
