import json
from typing import Any, Dict, Type

class JsonHandler:
    registries = {}

    @staticmethod
    def register(id: str, factory: type) -> None:
        if id in JsonHandler.registries:
            raise ValueError("ID already registered")
        JsonHandler.registries[id] = factory

    @classmethod
    def create(cls, id: str, **kwargs: Any) -> Any:
        factory = cls.registries.get(id)
        if not factory:
            raise ValueError("ID not found")
        return factory(**kwargs)

    @staticmethod
    def dump(obj: Any, *, skipkeys=None) -> str:
        return json.dumps(obj, skipkeys=skipkeys)

    @classmethod
    def load(cls, obj_str: str, cls_id: str = None) -> Any:
        if cls_id is not None:
            return JsonHandler.create(cls_id).from_json(obj_str)
        return json.loads(obj_str)
