using System;
using System.IO;
using System.Linq;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Newtonsoft.Json;
using System.Threading;
using System.Threading.Tasks;

public class ServiceManager
{
    private readonly ILogger<ServiceManager> _logger;
    private readonly IServiceCollection _services;
    private readonly string _configFilePath;

    public ServiceManager(ILoggerFactory loggerFactory, IServiceCollection services, IOptionsMonitor<ConfigOptions> config)
    {
        _logger = loggerFactory.CreateLogger<ServiceManager>();
        _services = services;
        _configFilePath = config.CurrentValue.PathToConfigurationFile;
    }

    public async Task RegisterAndStartAsync(CancellationToken cancellationToken)
    {
        if (!File.Exists(_configFilePath))
        {
            _logger.LogError("Service configuration file not found.");
            return;
        }

        try
        {
            var config = JsonConvert.DeserializeObject<ConfigOptions>(await File.ReadAllTextAsync(_configFilePath, cancellationToken));

            if (string.IsNullOrEmpty(config.ServiceName) || string.IsNullOrEmpty(config.LockFileLocation))
            {
                _logger.LogError("Invalid service configuration.");
                return;
            }

            var existingService = _services.FirstOrDefault(s => s.ServiceType == Type.GetType(config.ImplementationType));
            if (existingService != null && File.Exists(existingService.Metadata.GetServiceDescriptor().ImplementationFactoryMethod?.ReflectedType.GetFields()
                .FirstOrDefault(f => f.Name == config.LockFileLocation)?.GetValue(null) as string == config.LockFileLocation))
            {
                _logger.LogError("Another instance of the service is already active.");
                return;
            }

            _services.AddSingleton(config.ImplementationType);
            _services.AddHostedService<ServiceLifetimeManager>();

            await _services.BuildServiceProviderAsync(cancellationToken).ContinueWith(task =>
            {
                if (task.IsFaulted)
                {
                    _logger.LogError("Failed to build service provider.");
                }
                else
                {
                    using var serviceScope = task.Result.CreateScope();
                    var hostedService = serviceScope.ServiceProvider.GetService<IHostedService>();
                    hostedService?.StartAsync(cancellationToken);
                }
            });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error while parsing or validating the service configuration.");
        }
    }

    public void StopAsync()
    {
        _services.GetService<IHostedService>()?.StopAsync();
    }
}

public class ServiceLifetimeManager : IHostedService
{
    private readonly ILogger<ServiceLifetimeManager> _logger;
    private readonly string _lockFileLocation;

    public ServiceLifetimeManager(ILoggerFactory loggerFactory, IOptionsMonitor<ConfigOptions> config)
    {
        _logger = loggerFactory.CreateLogger<ServiceLifetimeManager>();
        _lockFileLocation = config.CurrentValue.LockFileLocation;
    }

    public Task StartAsync(CancellationToken cancellationToken)
    {
        lock (this)
        {
            if (File.Exists(_lockFileLocation))
            {
                _logger.LogInformation("Another instance of the service is already active, refusing to start.");
                return Task.CompletedTask;
            }

            File.WriteAllText(_lockFileLocation, DateTime.UtcNow.ToString());
        }

        return Task.CompletedTask;
    }

    public async Task StopAsync(CancellationToken cancellationToken)
    {
        if (File.Exists(_lockFileLocation))
        {
            File.Delete(_lockFileLocation);
        }

        // Implement monitoring and logging for graceful shutdown here.
    }
}

public class ConfigOptions
{
    public string PathToConfigurationFile { get; set; }
    public string ServiceName { get; set; }
    public string ImplementationType { get; set; }
    public string LockFileLocation { get; set; }
}
```

