#include <boost/serialization/utility.hpp>
#include <boost/archive/text_oarchive.hpp>
#include <boost/archive/text_iarchive.hpp>

struct USER_INFO {
    // Implement user info properties here
};
BOOST_SERIALIZATION_IMPLEMENT_ALL(USER_INFO, std::string)

struct SERVICE_LEVEL_AGREEMENT {
    // Implement service level agreement properties here
};
BOOST_SERIALIZATION_IMPLEMENT_ALL(SERVICE_LEVEL_AGREEMENT, std::string)

struct PROTOCOL_MESSAGE {
    // Implement protocol message properties here
};
BOOST_SERIALIZATION_IMPLEMENT_ALL(PROTOCOL_MESSAGE, std::string)

struct NETWORK_CONNECTION_REQUEST {
    USER_INFO userInfo;
    SERVICE_LEVEL_AGREEMENT serviceLevelAgreement;
    std::vector<PROTOCOL_MESSAGE> protocolMessages; // Max size determined by threshold
};
BOOST_SERIALIZATION_IMPLEMENT_ALL(NETWORK_CONNECTION_REQUEST)

class GarbageCollector {
private:
    std::queue<std::unique_ptr<NETWORK_CONNECTION_REQUEST>> queue;
    std::mutex mtx;
    std::condition_variable cv;
    std::atomic_size_t threshold;

public:
    void push(std::unique_ptr<NETWORK_CONNECTION_REQUEST> request) {
        // Push request to the garbage collector queue and notify waiting thread if necessary
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return queue.size() < threshold; });
        queue.push(std::move(request));
        lock.unlock();
        cv.notify_one();
    }

    std::unique_ptr<NETWORK_CONNECTION_REQUEST> pop() {
        // Pop a request from the garbage collector queue and return it, blocking if necessary
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return !queue.empty(); });
        auto result = std::move(queue.front());
        queue.pop();
        lock.unlock();
        return result;
    }
};

class NetworkConnectionPool {
private:
    std::vector<std::unique_ptr<NETWORK_CONNECTION_REQUEST>> connections;
    GarbageCollector garbageCollector;
    size_t threshold;
    std::mutex mtx;

public:
    NetworkConnectionPool(size_t initSize, size_t initialThreshold) : threshold(initialThreshold), mtx() {
        for (size_t i = 0; i < initSize; ++i) {
            connections.push_back(std::make_unique<NETWORK_CONNECTION_REQUEST>());
        }
    }

    void setThreshold(size_t newThreshold) {
        threshold = newThreshold;
        garbageCollector.push(std::move(connections[0])); // Transfer first connection to the garbage collector
        connections[0].reset(); // Reset the first connection in the pool
    }

    std::unique_ptr<NETWORK_CONNECTION_REQUEST> acquireConnection() {
        std::unique_lock<std::mutex> lock(mtx);
        if (connections.empty()) {
            auto request = garbageCollector.pop(); // Acquire a connection from the garbage collector, blocking if necessary
            if (!request) {
                return nullptr; // Return nullptr if no available connections
            }
        }
        std::unique_ptr<NETWORK_CONNECTION_REQUEST> result(std::move(connections[0]));
        connections[0].reset();
        lock.unlock();
        return result;
    }
};

void serialize(const NETWORK_CONNECTION_REQUEST& request, std::ostream& os) {
    boost::archive::text_oarchive oa(os);
    oa & request.userInfo;
    oa & request.serviceLevelAgreement;
    oa & boost::serialization::make_nvp("Protocol Messages", request.protocolMessages);
}

void deserialize(NETWORK_CONNECTION_REQUEST& request, std::istream& is) {
    boost::archive::text_iarchive ia(is);
    ia & request.userInfo;
    ia & request.serviceLevelAgreement;
    boost::serialization::nvp_iterator<std::vector<PROTOCOL_MESSAGE>> it = ia.template find_nvp("Protocol Messages");
    if (it != ia.end()) {
        it->second >> request.protocolMessages;
    }
}
