// Validation function with atomic operations to ensure thread safety.
void validate(NFAPI_CRC_INDICATION_PDU_T** list, size_t* count, NFAPI_CRC_INDICATION_PDU_T new) {
    pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;
    for (size_t i = 1; i < *count; ++i) {
        pthread_mutex_lock(&mtx);
        if ((*list)[i].RNTI == new.RNTI && i != (*count - 1)) { // If not the last element and duplicate RNTI detected
            (*((uint8_t*)&(*list)[i].CRC_INDICATION_REL8_TAG[0])) |= 0x2; // Set DUP_RNTI_FLAG
            pthread_mutex_unlock(&mtx);
            break;
        }
        pthread_mutex_unlock(&mtx);
    }
}

// Function to dynamically create and manage a linked list of NFAPI_CRC_INDICATION_PDU_T structures.
NFAPI_CRC_INDICATION_PDU_T** createList(size_t max_elements) {
    NFAPI_CRC_INDICATION_PDU_T **list = malloc(max_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) return NULL;

    for (size_t i = 0; i < max_elements; ++i) {
        list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list[i]) {
            while (i--) free(list[i]); // Clean up partially allocated memory
            free(list);
            return NULL;
        }
    }

