}

// Function to insert a new node into the linked list.
void pushBack(NFAPI_CRC_INDICATION_PDU_T** list, size_t* count, NFAPI_CRC_INDICATION_PDU_T new) {
    validate(list, count, new);

    pthread_mutex_lock(&(*list)[*count]->RX_UE_INFORMATION_TAG); // Lock the last element's RX_UE_INFORMATION_TAG to mark the end of the list.
    (*list)[*count] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!(*list)[*count]) { // Handle case where memory allocation fails after validation passes.
        free(new);
        while (--(*count)) free((*list)[*count]); // Clean up partially allocated memory
        free(list);
        return;
    }

    memcpy((*list)[*count], &new, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    (*count)++;
    pthread_mutex_unlock(&(*list)[*count - 1]->RX_UE_INFORMATION_TAG); // Unlock the last element's RX_UE_INFORMATION_TAG to signal end of insertion.
}
