typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t entries;
    size_t duplicates;
    size_t errors;
    NFAPI_CRC_INDICATION_PDU_T* list;
    pthread_mutex_t log_lock;
} LOGGER;

LOGGER logger;

void init_logger() {
    logger.entries = 0;
    logger.duplicates = 0;
    logger.errors = 0;
    logger.list = NULL;
    pthread_mutex_init(&logger.log_lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* create_entry(uint32_t tag, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T* entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!entry) {
        logger.errors++;
        return NULL;
    }
    entry->RX_UE_INFORMATION_TAG = tag;
    entry->RNTI = rnti;
    entry->CRC_INDICATION_REL8_TAG = rand() % 65536;
    entry->CRCFLAG = rand() % 2 == 0 ? true : false;
    pthread_mutex_init(&entry->lock, NULL);
    return entry;
}

bool validate_entry(NFAPI_CRC_INDICATION_PDU_T* entry) {
    if (!entry || !entry->RNTI || !entry->CRC_INDICATION_REL8_TAG) {
        logger.errors++;
        return false;
    }
    return true;
}

bool merge_or_discard(NFAPI_CRC_INDICATION_PDU_T** list, size_t len, NFAPI_CRC_INDICATION_PDU_T* new_entry) {
    bool merged = false;
    for (size_t i = 0; i < len; ++i) {
        if ((*list)[i].RNTI == new_entry->RNTI) {
            pthread_mutex_lock(&((*list)[i].lock));
            (*list)[i].CRCFLAG = new_entry->CRCFLAG;
            merged = true;
            break;
        }
    }

    if (!merged) {
        size_t new_len = len + 1;
        NFAPI_CRC_INDICATION_PDU_T* new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(*list, new_len * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            logger.errors++;
            return false;
        }
        *list = new_list;
        pthread_mutex_lock(&new_entry->lock);
        (*list)[len] = *new_entry;
        logger.entries++;
    } else {
        logger.duplicates++;
    }

    return true;
}

void add_entry(NFAPI_CRC_INDICATION_PDU_T* entry) {
    if (!validate_entry(entry)) {
        free(entry);
        return;
    }

    pthread_mutex_lock(&logger.log_lock);
    merge_or_discard((NFAPI_CRC_INDICATION_PDU_T**)&logger.list, logger.entries, entry);
    pthread_mutex_unlock(&logger.log_lock);
}

