        return NULL;
    }

    new_node->data = *data;
    new_node->prev = new_node->next = NULL;
    return new_node;
}

void insert_at_head(List* list, Node* node) {
    pthread_mutex_lock(&list->mutex);
    if (!list->head) {
        list->head = node;
        list->tail = node;
    } else {
        list->head->prev = node;
        node->next = list->head;
        list->head = node;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

void insert_at_tail(List* list, Node* node) {
    pthread_mutex_lock(&list->mutex);
    if (!list->head) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

void remove_node(List* list, Node* node) {
    pthread_mutex_lock(&list->mutex);
    if (node == list->head) {
        list->head = node->next;
        if (list->head)
            list->head->prev = NULL;
        else
            list->tail = NULL;
    } else if (node == list->tail) {
        list->tail = node->prev;
        if (list->tail)
            list->tail->next = NULL;
        else
            list->head = NULL;
    } else {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }

    free(node);
    list->size--;
    pthread_mutex_unlock(&list->mutex);
}

void resize_list(List* list, int new_capacity) {
    if (new_capacity <= list->size)
        return;

    Node **nodes = malloc(new_capacity * sizeof(Node*));
    int i;
    for (i = 0; i < list->size && i < new_capacity; ++i) {
        nodes[i] = list->head;
        if (list->head) {
            list->head = list->head->next;
            if (!list->head)
                list->tail = NULL;
        }
    }
    free(list->head);
    list->head = nodes;
    list->capacity = new_capacity;
}
```

