```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>
#define MAX_ENTRIES 10000
#define INITIAL_SIZE 4096
#define LOAD_FACTOR 0.75

typedef struct entry {
    char *key;
    size_t length;
    void *data;
} Entry;

struct hash_map {
    Entry *table;
    size_t size;
    size_t num_entries;
    pthread_mutex_t mutex;
};

typedef struct hash_map HashMap;

HashMap create_hash_map() {
    HashMap map = {0};
    map.table = malloc(INITIAL_SIZE * sizeof(Entry));
    if (!map.table) return (HashMap){0};
    map.size = INITIAL_SIZE;
    map.num_entries = 0;
    map.mutex = PTHREAD_MUTEX_INITIALIZER;
    return map;
}

size_t hash(const char *key, size_t table_size) {
    size_t h = 0;
    for (; *key != '\0'; ++key)
        h = ((h << 5) + h) + (*key);
    return h % table_size;
}

bool resize(HashMap *map) {
    Entry *new_table = realloc(map->table, (map->size * 2) * sizeof(Entry));
    if (!new_table) return false;
    map->size *= 2;
    map->table = new_table;
    return true;
}

void add_entry(HashMap *map, const char *key, size_t length, void *data) {
    pthread_mutex_lock(&map->mutex);
    if (map->num_entries >= map->size * LOAD_FACTOR && !resize(map)) {
        pthread_mutex_unlock(&map->mutex);
        return;
    }
    size_t index = hash(key, map->size);
    bool found = false;
    for (int i = index; ; ++i %= map->size) {
        if (!map->table[i].key || !strcmp(map->table[i].key, key)) {
            Entry *entry = &map->table[i];
            entry->key = strdup(key);
            entry->length = length;
            entry->data = data;
            ++map->num_entries;
            found = true;
            break;
        }
    }
    pthread_mutex_unlock(&map->mutex);
    if (!found) {
        fprintf(stderr, "Failed to add entry: %s\n", key);
    }
}

void iterate_and_print(const HashMap *map) {
    for (int i = 0; i < map->size; ++i) {
        if (map->table[i].key)
            printf("Key: %s, Length: %zu, Data: %p\n", map->table[i].key, map->table[i].length, map->table[i].data);
    }
}

void* get_new_entries(HashMap *map) {
    // Replace this function with an implementation for your external data source.
    return NULL;
}

int main() {
    HashMap map = create_hash_map();
    void *data;
    while (1) {
        pthread_mutex_lock(&map->mutex);
        Entry *entries = get_new_entries(&map);
        pthread_mutex_unlock(&map->mutex);
        if (!entries) break;
        for (Entry *entry = entries; entry; entry = entry->next) {
            add_entry(&map, entry->key, entry->length, &data);
            free(entry);
        }
    }
    iterate_and_print(&map);
    free(map.table);
    return 0;
}
