    if (cmd->pid > 0 && waitpid(cmd->pid, &cmd->status, WNOHANG) > 0) {
        log_command(cmd, WEXITED);
        free(cmd);
    }
}

int manage_commands(Command* commands[], int count, const char** envp) {
    union semun arg;
    sem_t semaphore;
    int max_concurrent = 8;
    int sem_value = max_concurrent;

    semget(&semaphore, 1, IPC_CREAT | 0600);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    signal(SIGHUP, signal_handler);

    while (1) {
        check_resources();

        arg.val = sem_value;
        if (semop(semaphore, &arg, sizeof(arg)) == 0) {
            // Find an available command slot
            int i;
            for (i = 0; i < count; ++i) {
                if (!commands[i]->pid) {
                    break;
                }
            }

            if (i != count) {
                pid_t cmd_pid = execute_command(commands[i], envp);
                if (cmd_pid > 0) {
                    commands[i]->pid = cmd_pid;
                    // Update semaphore with decremented value
                    arg.val = sem_value - 1;
                    semop(semaphore, &arg, sizeof(arg));
                }
            }
        }

        // Monitor background processes and log termination events
        int i;
        for (i = 0; i < count; ++i) {
            if (commands[i]->pid > 0 && waitpid(commands[i]->pid, &commands[i]->status, WNOHANG) > 0) {
                log_command(commands[i], commands[i]->status);
                cleanup_command(commands[i]);
            }
        }
    }

    semctl(semaphore, 0, IPC_RMID);
    return 0;
}
