#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    void* next;
} pool_node_t;

pool_node_t* memory_pool = NULL;
unsigned int pool_size = 0;

void init_memory_pool(unsigned int size) {
    unsigned int i;
    pool_node_t *head, *current, *new_node;

    head = (pool_node_t*)calloc(1, sizeof(pool_node_t));
    if (!head) {
        fprintf(stderr, "Error allocating memory for the memory pool\n");
        return;
    }

    head->next = NULL;
    current = head;

    for (i = 0; i < size - 1; ++i) {
        new_node = (pool_node_t*)calloc(1, sizeof(pool_node_t));
        if (!new_node) {
            fprintf(stderr, "Error allocating memory for a pool node\n");
            free_memory_pool(head);
            return;
        }

        current->next = new_node;
        current = new_node;
        current->next = NULL;
    }

    pool_size = size;
}

void* get_from_memory_pool() {
    pool_node_t *current;

    if (pool_size == 0) return NULL;

    current = memory_pool->next;
    memory_pool->next = current->next;
    pool_size--;
    return current;
}

void free_memory_pool(pool_node_t *head) {
    pool_node_t* to_free;
    pool_node_t* next;

    for (to_free = head->next; to_free != NULL; to_free = next) {
        next = to_free->next;
        free(to_free);
    }
}

void generate_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu, unsigned int rnti) {
    pdu->rx_ue_information_tag.present = RX_UE_INFORMATION_TAG_PRS;
    pdu->rx_ue_information_tag.choice.rx_ue_information.rnti = rnti;

    pdu->crc_indication_rel8_tag.present = CRC_INDICATION_REL8_TAG_PRS;
    pdu->crc_indication_rel8_tag.choice.crc_indication_rel8.crcflag = rand() % 2;
}

NFAPI_CRC_INDICATION_PDU_T* generate_pdus(unsigned int num) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list, *current;
    void *node;

    pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(num, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        fprintf(stderr, "Error allocating memory for PDUs\n");
        return NULL;
    }

    current = pdu_list;
    while (num > 0) {
        node = get_from_memory_pool();
        if (!node) {
            free(pdu_list);
            fprintf(stderr, "Out of memory\n");
            return NULL;
        }

        generate_pdu((NFAPI_CRC_INDICATION_PDU_T*)node, num);
        current->next = node;
        current = (NFAPI_CRC_INDICATION_PDU_T*)current->next;
        num--;
    }

    return pdu_list;
}
