async function uploadFileFromURL(url, serverUrl) {
    const fileStream = await (await fetch(url)).body.pipe(bl((err, res) => {
        if (err) throw err;
        return res;
    }));

    const fileName = `${Date.now()}_${fileStream._data.length}.tmp`;
    fs.writeFileSync(fileName, fileStream._data);

    await uploadFile(fileName, serverUrl);
    fs.unlinkSync(fileName);
}

async function uploadFile(filename, serverUrl) {
    if (currentUploadingFilesCount >= MAX_SIMULTANEOUS_UPLOADS) return;

    currentUploadingFilesCount++;
    const form = formData();
    form.append('file', fs.createReadStream(filename));

    try {
        const response = await axios.post(serverUrl, form);
        if (response.status === 200) {
            currentUploadingFilesCount--;
            return response.data.url;
        } else {
            throw new Error(`Server error: ${response.statusText}`);
        }
    } catch (err) {
        console.error(err.message);
        currentUploadingFilesCount--;
        return null;
    }
}

// Start multiple uploads if needed.
