    const uploadTasks = [];
    for (let i = 0; i < MAX_SIMULTANEOUS_UPLOADS && currentUploadingFilesCount < MAX_SIMULTANEOUS_UPLOADS; i++) {
        uploadTasks.push(`node upload-file.js ${urls[i]} ${serverUrl}`);
    }
    if (uploadTasks.length > 0) concurrently(...uploadTasks);
