void *generateStructure(void *arg) {
    while (true) {
        sleep(1); // Simulate network latency or external dependencies
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            fprintf(stderr, "Memory allocation failure\n");
            return NULL;
        }
        pdu->rx_ue_information_tag = rand(); // Set RX_UE_INFORMATION_TAG
        pdu->rnti = rand(); // Set RNTI
        pdu->crc_indication_rel8_tag.crcFlag = rand() % 10 + 2; // Set CRC_INDICATION_REL8_TAG with a non-zero and valid CRCFLAG
        if (pthread_mutex_lock(&mutex)) {
            fprintf(stderr, "Mutex lock failure\n");
            free(pdu);
            return NULL;
        }
        pthread_mutex_unlock(&mutex);
        return pdu;
    }
}

void populateNfaapiList(NFAPI_CRC_INDICATION_PDU_T **list, size_t listSize) {
    size_t successfulAttempts = 0;
    pthread_t threads[listSize];
    for (size_t i = 0; i < listSize; ++i) {
        if (pthread_create(&threads[i], NULL, generateStructure, NULL)) {
            fprintf(stderr, "Thread creation failure\n");
            return;
        }
    }
    for (size_t i = 0; i < listSize; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu;
        if (pthread_join(threads[i], (void **)&pdu)) {
            fprintf(stderr, "Thread join failure\n");
            return;
        }
        if (!pdu) continue; // Skip null pointers due to memory allocation failures
        list[successfulAttempts++] = pdu;
    }
}
