int populate_crc_indications(size_t N, const char *output_file) {
    size_t i;
    uint16_t unique_rntis[1000]; // Store all unique RNTIs in this array
    NFAPI_CRC_INDICATION_PDU_T *indications;

    if (N > 1000) {
        log_operation("Error: The number of elements exceeds the maximum limit of 1000.\n");
        return -1;
    }

    indications = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        log_operation("Error: Out of memory while allocating memory for CRC indications.\n");
        return -2;
    }

    for (i = 0; i < N; ++i) {
        bool rnti_found = false;
        do {
            // Generate a unique RNTI within the valid range of 0 to 65535
            indications[i].rnti = rand() & 0xFFFF;

            for (size_t j = 0; j < i; ++j) {
                if (indications[j].rnti == indications[i].rnti) {
                    rnti_found = true;
                    break;
                }
            }

            if (!rnti_found) {
                unique_rntis[total_elements++] = indications[i].rnti;
            }
        } while (rnti_found);
    }

    log_operation("Populated %zu CRC indications with total %zu unique RNTIs.\n", N, total_elements);

    if (output_file) {
        FILE *file = fopen(output_file, "w");
        if (!file) {
            log_operation("Error: Failed to open the output file for writing.\n");
            free(indications);
            return -3;
        }

        json_t *root = json_array();

        for (i = 0; i < N; ++i) {
            json_t *crci = json_pack("{{"
                                     "  \"rnti\": %" PRIu16 ","
                                     "  \"type\": %hu,"
                                     "  \"flags\": %hhu,"
                                     "  \"data\": [[%d]]}}",
                indications[i].rnti,
                indications[i].crc_indication_type,
                indications[i].flags,
                indications[i].data[0]);
            json_array_append(root, crci);
        }

