    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum { SUCCESS, FAILURE_NOMEM, FAILURE_RNTI, FAILURE_LOG } RESULT_ENUM;

#define MAX_ENTRIES 1000
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
int successful_allocations = 0;
int failed_allocations = 0;
int failed_rnti_allocations = 0;

// External data source for RNTI values
extern uint16_t get_rnti(void);

NFAPI_CRC_INDICATION_PDU_T* create_entry(void) {
    NFAPI_CRC_INDICATION_PDU_T* entry = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!entry) return NULL;

    entry->RX_UE_INFORMATION_TAG = rand() % UINT32_MAX;
    entry->RNTI = get_rnti();

    // Generate random CRCFLAG value
    entry->CRC_INDICATION_REL8_TAG[0] = (rand() % 256);
    entry->CRC_INDICATION_REL8_TAG[1] = (rand() % 256);
    entry->CRC_INDICATION_REL8_TAG[2] = (rand() % 256);
    entry->CRC_INDICATION_REL8_TAG[3] = (rand() % 256);
    entry->CRCFLAG = rand() % 2;

    return entry;
}

RESULT_ENUM create_and_populate_list(NFAPI_CRC_INDICATION_PDU_T** list, size_t* num_entries) {
    for (size_t i = 0; i < MAX_ENTRIES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* entry = create_entry();
        if (!entry) {
            failed_allocations++;
            return FAILURE_NOMEM;
        }

        // Check for RNTI availability
        if (entry->RNTI == 0) {
            failed_rnti_allocations++;
            free(entry);
            return FAILURE_RNTI;
        }

        if (!*list) {
            *list = entry;
            *num_entries = 1;
        } else {
