            if (!(*list)) {
                free(entry);
                failed_allocations++;
                return FAILURE_NOMEM;
            }
            (*list)[*num_entries - 1] = entry;
        }
    }

    successful_allocations += *num_entries;
    return SUCCESS;
}

void log_operation(RESULT_ENUM result) {
    pthread_mutex_lock(&log_mutex);

    switch (result) {
        case SUCCESS:
            printf("Successful allocation: %d\n", successful_allocations);
            break;
        case FAILURE_NOMEM:
            printf("Failure: Memory allocation failed\n");
            break;
        case FAILURE_RNTI:
            printf("Failure: RNTI unavailable\n");
            break;
        case FAILURE_LOG:
            // Unreachable, no need to handle this case in the log function
            break;
    }

    pthread_mutex_unlock(&log_mutex);
}
