class LogManager {
public:
    void pushOperation(const std::string& operation, bool success) {
        boost::mutex::scoped_lock lock(m_logMutex);
        m_operations.emplace_back(operation + " : Success=" + std::to_string(success));
    }

    void serializeLog() const {
        boost::mutex::scoped_lock lock(m_logMutex);
        if (m_operations.empty()) return;

        std::ofstream logFile("log.txt", std::ios::app);
        if (!logFile) return;

        auto start = std::chrono::high_resolution_clock::now();
        for (const auto& operation : m_operations) {
            logFile << operation << '\n';
        }
        auto end = std::chrono::high_resolution_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();
        std::cout << "Log serialization took: " << duration << " ms\n";
    }

private:
    std::vector<std::string> m_operations;
    boost::mutex m_logMutex;
};

class PDUList {
public:
    static constexpr int MAX_SIZE = 10000;

    PDUList(LogManager& logManager, unsigned int seed)
        : m_logManager(logManager), m_rand(seed), m_currentSize(0), m_allocatedSize(MAX_SIZE) {
        m_pduList = std::vector<NFAPI_CRC_INDICATION_PDU_T>(m_allocatedSize);
    }

    NFAPI_CRC_INDICATION_PDU_T* addPDU() {
        if (m_currentSize >= m_allocatedSize) {
            resize();
        }

        auto result = &m_pduList[m_currentSize++];
        m_logManager.pushOperation("Add PDU", true);
        return result;
    }

    void resize() {
        m_allocatedSize *= 2;
        std::vector<NFAPI_CRC_INDICATION_PDU_T> newList(m_allocatedSize);
        for (size_t i = 0; i < m_currentSize; ++i) {
            newList[i] = m_pduList[i];
        }
        m_pduList.swap(newList);
        m_logManager.pushOperation("Resize list", true);
    }

private:
    LogManager& m_logManager;
    std::random_device m_rd;
    std::mt19937 m_rand; // Mersenne Twister pseudo-random number engine
    std::vector<NFAPI_CRC_INDICATION_PDU_T> m_pduList;
    size_t m_currentSize = 0;
    size_t m_allocatedSize;
};
