} NFAPI_CRC_INDICATION_PDU;

NFAPI_CRC_INDICATION_PDU* createNode() {
    NFAPI_CRC_INDICATION_PDU* newNode = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!newNode) return NULL;

    newNode->next = NULL;
    newNode->crcIndicationTag.crci = 0;
    newNode->crcFlag = rand() % 2 == 0;

    return newNode;
}

void insertNode(NFAPI_CRC_INDICATION_PDU** head, NFAPI_CRC_INDICATION_PDU* node) {
    if (!head || !node) return;

    if (*head == NULL) {
        *head = node;
        return;
    }

    NFAPI_CRC_INDICATION_PDU* current = *head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = node;
}

void printList(NFAPI_CRC_INDICATION_PDU* head) {
    if (!head) return;

    NFAPI_CRC_INDICATION_PDU* current = head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: 0x%lX, RNTI: %u\n", current->tag, current->rnti);
        current = current->next;
    }
}

void freeList(NFAPI_CRC_INDICATION_PDU** head) {
    if (!head || !*head) return;

    NFAPI_CRC_INDICATION_PDU* current = *head;
    while (*head != NULL) {
        current = *head;
        *head = current->next;
        free(current);
    }
}
