bool init_log(const char* db_path) {
    int rc;
    rc = sqlite3_open(db_path, &logDB);
    if (rc) {
        fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(logDB));
        return false;
    }
    rc = sqlite3_exec(logDB, "CREATE TABLE IF NOT EXISTS log (" \
                                "id INTEGER PRIMARY KEY AUTOINCREMENT," \
                                "operation TEXT," \
                                "result BOOLEAN," \
                                "reason TEXT);", NULL, NULL, NULL);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", sqlite3_errmsg(logDB));
        return false;
    }
    return true;
}

void log_operation(const char* operation, bool success, const char* reason) {
    char* errMsg = NULL;
    sqlite3_stmt* stmt;
    int rc;

    rc = sqlite3_prepare_v2(logDB, "INSERT INTO log (operation, result, reason) VALUES (?, ?, ?)", -1, &stmt, &errMsg);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Cannot prepare statement: %s\n", errMsg);
        sqlite3_free(errMsg);
        return;
    }

    rc = sqlite3_bind_text(stmt, 1, operation, -1, SQLITE_TRANSIENT);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Failed to bind operation: %s\n", errMsg);
        return;
    }

    rc = sqlite3_bind_int(stmt, 2, success ? 1 : 0);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Failed to bind result: %s\n", errMsg);
        return;
    }

    rc = sqlite3_bind_text(stmt, 3, reason ? reason : "", -1, SQLITE_TRANSIENT);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Failed to bind reason: %s\n", errMsg);
        return;
    }

    rc = sqlite3_step(stmt);
    if (rc != SQLITE_DONE) {
        fprintf(stderr, "Execution failed: %s\n", errMsg);
    }

    sqlite3_finalize(stmt);
    sqlite3_free(errMsg);
}

