#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <sys/mman.h>

#define GROWTH_FACTOR 2
#define MAX_RECORDS 1000000
#define LRU_PURGE_INTERVAL 60 // seconds

typedef struct {
    int key;
    long offset;
    NFAPI_CRC_INDICATION_PDU_T data;
} record;

struct meta_field {
    void* value;
    size_t size;
};

typedef struct resource {
    record* data;
    struct meta_field* metadata;
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
} resource_pool;

void set_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pdu->CRCFLAG = rand() % 2;
}

resource_pool* create_resource_pool() {
    resource_pool* pool = malloc(sizeof(resource_pool));
    pool->capacity = 0;
    pool->count = 0;
    pool->data = NULL;
    pool->metadata = NULL;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* allocate(resource_pool* pool) {
    if (pool->capacity == pool->count) {
        size_t new_capacity = pool->capacity * GROWTH_FACTOR;
        if (new_capacity > MAX_RECORDS) {
            new_capacity = MAX_RECORDS;
        }
        record* new_data = realloc(pool->data, new_capacity * sizeof(record));
        struct meta_field* new_metadata = realloc(pool->metadata, new_capacity * sizeof(struct meta_field));
        if (new_data && new_metadata) {
            pool->data = new_data;
            pool->metadata = new_metadata;
            pool->capacity = new_capacity;
        } else {
            fprintf(stderr, "Failed to allocate memory\n");
        }
    }

    record* rec = &pool->data[pool->count];
    rec->key = 0;
    rec->offset = 0;
    set_crcflag(&rec->data);

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    // Populate NFAPI_CRC_INDICATION_PDU_T structure with data from external sources
    clock_gettime(CCLK_MONOTONIC, &end);
    double time_taken = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1_000_000_000;
    // Log the average time taken to initialize each record

    pool->count++;
    return rec;
}

void purge(resource_pool* pool) {
    if (clock() % LRU_PURGE_INTERVAL == 0) {
        size_t i, j;
        for (i = 0; i < pool->count - 1; ++i) {
            for (j = i + 1; j < pool->count; ++j) {
                if (pool->data[i].key > pool->data[j].key) {
                    record temp = pool->data[i];
                    pool->data[i] = pool->data[j];
                    pool->data[j] = temp;
                }
            }
        }
        size_t to_remove = pool->count / 10;
        for (size_t i = 0; i < to_remove; ++i) {
            free(pool->metadata[pool->count - 1].value);
            pool->metadata[pool->count - 1].value = NULL;
            pool->data[pool->count - 1] = pool->data[0];
            for (size_t j = 1; j < pool->capacity; ++j) {
                pool->metadata[j - 1] = pool->metadata[j];
            }
            --pool->count;
        }
    }
}

void delete(resource_pool* pool, void* record) {
    pthread_mutex_lock(&pool->lock);
    free(pool->metadata[(size_t)record - pool->data]->value);
    pool->metadata[(size_t)record - pool->data]->value = NULL;
    --pool->count;
    pthread_mutex_unlock(&pool->lock);
}

void add_metadata(resource_pool* pool, void* record, void* value, size_t size) {
    pthread_mutex_lock(&pool->lock);
    pool->metadata[(size_t)record - pool->data]->value = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    memcpy(pool->metadata[(size_t)record - pool->data]->value, value, size);
    pthread_mutex_unlock(&pool->lock);
}
```
