    *pdu_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pdu_list) return -1; // Memory allocation failure

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = create_new_pdu();
        if (!pdu) {
            free(*pdu_list);
            return -1; // Memory allocation failure
        }

        if (cache_contains(pdu->rnti)) {
            free(pdu);
            continue; // RNTI already exists in the cache, skip this iteration
        }

        insert_into_cache(pdu);
        (*pdu_list)[i] = *pdu;
    }

    return 0;
}

