        public void AddKeyAndIV(Guid keyId, Aes aes, byte[] iv)
        {
            lock (_lock)
            {
                if (_keyValuePairs.ContainsKey(keyId))
                    throw new InvalidOperationException($"A key ID '{keyId}' is already registered.");

                _keyValuePairs[keyId] = (aes, iv);
            }
