        public void ProcessMessagesAsync(IEnumerable<EncryptedMessage> messages, Guid keyId)
        {
            var keyValuePair = _keyValuePairs.GetValueOrDefault(keyId);

            if (keyValuePair == null)
                throw new InvalidOperationException($"A key ID '{keyId}' is not registered.");

            ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = _maxDegreeOfParallelism };
            Parallel.ForEach(messages, options, message => DecryptMessageAsync(message, keyValuePair));
        }

        private async Task DecryptMessageAsync(EncryptedMessage encryptedMessage, (Aes Aes, byte[] IV)) keyValuePair)
        {
