                    if (task.IsFaulted)
                        _logger.WriteLine($"Decryption failed for message '{encryptedMessage.Id}'. Error: {task.Exception?.Flatten().InnerExceptions.First().Message}");
                    else
                        _logger.WriteLine($"Successfully decrypted message '{encryptedMessage.Id}'.");
                });
            }
            catch (Exception ex)
            {
                _logger.WriteLine($"An error occurred while processing encrypted messages: {ex.Message}");
            }
        }

        private static async Task UsingCryptoStreamAsync(byte[] encryptedData, Aes aes, byte[] iv)
        {
            await using (var ms = new MemoryStream(encryptedData))
            using (var cs = new CryptoStream(ms, aes.CreateDecryptor(), CryptoStreamMode.Read))
            using (var reader = new StreamReader(cs))
            {
                var decryptedText = await reader.ReadToEndAsync();
                // Process the decrypted text here...
            }
        }
    }

    public record EncryptedMessage(Guid Id, byte[] EncryptedData);
}
