#include <stdbool.h>

typedef struct {
    RX_FRAME_HEADER header;
    char *payload; // dynamically allocated payload
    size_t payload_len;
} NFAPI_RX_FRAME_PDU_T;

typedef struct node {
    NFAPI_RX_FRAME_PDU_T data;
    struct node* next;
} Node;

Node* create_node(const RX_FRAME_HEADER* header, size_t payload_len) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) return nullptr;

    new_node->data.payload = (char*) malloc(payload_len);
    if (!new_node->data.payload) {
        free(new_node);
        return nullptr;
    }

    memcpy(&new_node->data.header, header, sizeof(RX_FRAME_HEADER));
    new_node->data.payload_len = payload_len;
    new_node->next = nullptr;

    return new_node;
}

void append_node(Node** head_ref, Node* new_node) {
    if (*head_ref == nullptr) {
        *head_ref = new_node;
        return;
    }

    Node* last = *head_ref;
    while (last->next != nullptr)
        last = last->next;

    last->next = new_node;
}

void print_list(const Node* head) {
    const Node* current = head;
    while (current != nullptr) {
        printf("RX Frame:\n");
        printf("\tHeader: %d, Sequence Number: %d\n",
            current->data.header.frameType, current->data.header.seqNum);
        printf("\tPayload Length: %zu\n", current->data.payload_len);
        current = current->next;
    }
}
