#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>
#include <sys/mman.h> // For POSIX memory management functions
#include <asynclogger/asynclogger.h> // Replace with your preferred asynchronous logging library

#define MAX_RNTIS 65536
#define NUM_THREADS 16

typedef struct {
    uint32_t rxiit;
    uint16_t rnti;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

struct thread_data {
    NFAPI_CRC_INDICATION_PDU_T** list;
    size_t* size;
    pthread_mutex_t* mutex;
    asynclogger_t* logger;
};

void create_and_populate_list(struct thread_data* data, size_t n) {
    *data->size = n;

    // Allocate memory for the list and initialize all elements to zero
    void* ptr = mmap(NULL, sizeof(NFAPI_CRC_INDICATION_PDU_T)*n, PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        asynclogger_error(data->logger, "Memory allocation failed");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = ptr;

    // Initialize mutexes for concurrent access protection
    for (size_t i = 0; i < n; ++i) {
        pthread_mutex_init(&data->mutex[i], NULL);
    }

    // Populate the list with valid structures
    for (size_t i = 0; i < *data->size; ++i) {
        pthread_mutex_lock(&data->mutex[i]);
        list[i].rxiit = time(NULL);
        list[i].rnti = rand() % MAX_RNTIS;
        list[i].crcflag = rand() % 2 == 0;
        pthread_mutex_unlock(&data->mutex[i]);

        // Validate RNTI uniqueness and handle duplicates gracefully
        for (size_t j = 0; j < i; ++j) {
            if (list[j].rnti == list[i].rnti) {
                asynclogger_warning(data->logger, "Duplicate RNTI encountered: %u", list[i].rnti);
                continue;
            }
        }
    }
}

// Create and populate the list using multiple threads
void* create_and_populate_multi_threaded(void* data) {
    struct thread_data* my_data = data;
    size_t chunk_size = *my_data->size / NUM_THREADS;

    // Allocate memory for the list chunks and lock mutexes for each chunk
    NFAPI_CRC_INDICATION_PDU_T** list_chunks = calloc(NUM_THREADS, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    pthread_mutex_t** mutex_chunks = calloc(NUM_THREADS, sizeof(pthread_mutex_t));
    for (size_t i = 0; i < NUM_THREADS; ++i) {
        list_chunks[i] = &((NFAPI_CRC_INDICATION_PDU_T*)my_data->list)[i * chunk_size];
        mutex_chunks[i] = &my_data->mutex[i * chunk_size];
    }

    // Populate the chunks concurrently using pthreads
    pthread_t threads[NUM_THREADS];
    for (size_t i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, populate_chunk, &list_chunks[i]);
    }

    // Wait for all threads to finish their work
    for (size_t i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(list_chunks);
    free(mutex_chunks);

    return NULL;
}

void* populate_chunk(void* data) {
    NFAPI_CRC_INDICATION_PDU_T** list = data;
    size_t chunk_size = *((struct thread_data**)data)->size / NUM_THREADS;

    for (size_t i = 0; i < chunk_size; ++i) {
        pthread_mutex_lock((&*((struct thread_data**)data)->mutex)[i]);
        (*list)[i].rxiit = time(NULL);
        (*list)[i].rnti = rand() % MAX_RNTIS;
        (*list)[i].crcflag = rand() % 2 == 0;
        pthread_mutex_unlock((&*((struct thread_data**)data)->mutex)[i]);
    }

    return NULL;
}
```

