    meta->size = size;
    meta->records = calloc(size, sizeof(Record*));
    return meta;
}

Summary *summary_alloc() {
    Summary *sum = malloc(sizeof(Summary));
    sum->count = 0;
    sum->avg = 0.0;
    return sum;
}

// Function to process the data structures
void manage_memory(Metadata **metadata, Summary **summary) {
    size_t i, j;

    for (i = 0; i < *metadata->size; ++i) {
        if (!(*metadata)[i]) continue; // Skip empty entries

        (*metadata)[i]->data = malloc((*((*metadata)[i]->records)->size)*sizeof(long));
        for (j = 0; j < (*((*metadata)[i]->records)->size); ++j) {
            (*(*metadata)[i]->data)[j] = ((*(*metadata)[i]->records)[j])->data[0];
            // Process the data as needed
        }
    }

    *summary = summary_alloc();
    for (i = 0; i < *metadata->size; ++i) {
        if (!(*metadata)[i]) continue;

        (*summary)->count += (*((*metadata)[i]->records)->size);

        long sum = 0;
        for (j = 0; j < (*((*metadata)[i]->records)->size); ++j)
            sum += ((*(*metadata)[i]->records)[j])->data[0];
        (*summary)->avg += (double)sum / (*metadata)[i]->key;
    }
}
