int wait_for_data(FILE* data) {
    int count = 0;
    while (count < MAX_RETRIES && fgetc(data) == EOF) {
        usleep(RETRY_DELAY * 1000); // sleep for retry delay before attempting again
        count++;
    }
    return feof(data) ? -1 : 0; // return -1 if timeout, 0 otherwise
}

int execute_command(const char* cmd, FILE** data) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 0;
    } else if (pid == 0) { // child process
        setsid();
        freopen("/dev/null", "r", stdin);
        freopen("/dev/null", "w", stdout);
        freopen("/dev/null", "w", stderr);
        dup2(*data, STDOUT_FILENO); // redirect command output to the given stream
        close(*data);
        execl("/bin/sh", "/bin/sh", "-c", cmd, NULL);
        perror("execl");
        _exit(EXIT_FAILURE);
    } else { // parent process
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status)) {
            return WEXITSTATUS(status);
        } else if (WIFSIGNALED(status)) {
            fprintf(stderr, "Child process terminated by signal %d\n", WTERMSIG(status));
        } else {
            perror("waitpid");
        }
    }
}

int run_command(const char* cmd) {
    FILE* pipe = popen(cmd, "r");
    if (!pipe) {
        perror("popen");
        return 0;
    }

    if (check_dependencies(...)) { // check for dependencies here
        pclose(pipe);
        return 1; // command depends on an unmet dependency, return error
    }

    int retries = MAX_RETRIES;
    do {
        if (wait_for_data(pipe) == -1) {
            if (--retries > 0) {
                fprintf(stderr, "Data source temporary unavailable. Retrying in %d ms...\n", RETRY_DELAY);
                usleep(RETRY_DELAY * 1000); // sleep for retry delay before attempting again
            } else {
                fprintf(stderr, "Failed to receive data from the command. Command execution aborted.\n");
                pclose(pipe);
                return 0;
            }
        } else {
            int exit_code = execute_command(cmd, &pipe);
            if (exit_code > 0) {
                pclose(pipe);
                return 1; // command executed successfully, return success
            } else {
                fprintf(stderr, "Command execution failed. Error: %s\n", strerror(errno));
            }
        }
    } while (retries > 0);

    pclose(pipe);
    return 0; // command execution failed after all retries are exhausted
}
