```c
#include <stdlib.h>
#include <pthread.h>

struct slab {
    void *pool;
    size_t obj_size;
    unsigned int objs_per_slab;
};

typedef struct slab Slab;

Slab* slab_create(size_t obj_size, unsigned int objs_per_slab) {
    Slab *slab = malloc(sizeof(Slab));
    if (!slab) return NULL;

    slab->obj_size = obj_size;
    slab->objs_per_slab = objs_per_slab;
    slab->pool = malloc(slab->objs_per_slab * slab->obj_size);

    if (!slab->pool) {
        free(slab);
        return NULL;
    }

    return slab;
}

void* slab_get(Slab *slab) {
    char *ptr = slab->pool + (slab->objs_per_slab * sizeof(void*));
    void *obj = ptr;

    if ((uintptr_t)(ptr + slab->obj_size) > (uintptr_t)(slab->pool + (slab->objs_per_slab * sizeof(void*))) ||
        !ptr) {
        return NULL;
    }

    memset(obj, 0, slab->obj_size);
    return obj;
}
```

2. Dynamic array management (with thread-safe concurrent access):

```c
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    Slab *slab;
    void **arr;
    unsigned int capacity, size;
    pthread_mutex_t mutex;
} DynArray;

DynArray* dynarray_create(size_t obj_size, unsigned int initial_capacity) {
    DynArray *arr = malloc(sizeof(DynArray));
    if (!arr) return NULL;

    arr->slab = slab_create(obj_size, initial_capacity);
    if (!arr->slab) {
        free(arr);
        return NULL;
    }

    arr->capacity = initial_capacity;
    arr->size = 0;
    arr->arr = arr->slab->pool;
    pthread_mutex_init(&arr->mutex, NULL);

    return arr;
}

void dynarray_push(DynArray *arr, void *obj) {
    pthread_mutex_lock(&arr->mutex);

    if (arr->size >= arr->capacity) {
        arr->capacity *= 2;
        arr->slab->objs_per_slab = arr->slab->objs_per_slab * 2;
        arr->slab->pool = realloc(arr->slab->pool, arr->capacity * arr->slab->obj_size);
    }

    void **ptr = arr->arr + arr->size;
    *ptr = obj;
    arr->size++;

    pthread_mutex_unlock(&arr->mutex);
}
```

