#include <libtiff/tiff.h>

TIFF* tiff_open(const char *filename, const char *mode) {
    TIFF *tif = TIFFOpen(filename, mode, "libtiff");

    if (!tif) return NULL;

    return tif;
}

int get_samples_per_pixel(TIFF *tif) {
    if (TIFFGetField(tif, TIFFTAG_SAMPLES_PER_PIXEL) == -1) {
        tiffError("Could not find SamplesPerPixel tag.");
    }

    return TIFFGetField(tif, TIFFTAG_SAMPLES_PER_PIXEL);
}

int get_bits_per_sample(TIFF *tif) {
    if (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE) == -1) {
        tiffError("Could not find BitsPerSample tag.");
    }

    return TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE);
}

void* get_additional_samples(TIFF *tif) {
    int bps = get_bits_per_sample(tif);
    size_t n_additional = 0;

    if (bps > 8) {
        tiffError("Unsupported number of bits per sample.");
        return NULL;
    }

    while (TIFFGetField(tif, TIFFTAG_SAMPLEFORMAT)) {
        n_additional++;
    }

    if (!n_additional) {
        tiffError("No additional samples found.");
        return NULL;
    }

    void *add_samples = malloc(TIFFGetField(tif, TIFFTAG_IMAGEWIDTH) * TIFFGetField(tif, TIFFTAG_IMAGELENGTH) * n_additional);

    if (!add_samples) {
        tiffError("Could not allocate memory for additional samples.");
        return NULL;
    }

    uint8_t *samples = calloc(TIFFGetField(tif, TIFFTAG_IMAGEWIDTH) * TIFFGetField(tif, TIFFTAG_IMAGELENGTH), 8);

    if (!samples) {
        tiffError("Could not allocate memory for samples.");
        free(add_samples);
        return NULL;
    }

    int ret = TIFFReadScanline(tif, samples, 0);

    if (ret == -1) {
        tiffError("Failed to read scanline.");
        free(add_samples);
        free(samples);
        return NULL;
    }

    memcpy(add_samples, &samples[TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE) * (TIFFGetField(tif, TIFFTAG_IMAGEWIDTH) * TIFFGetField(tif, TIFFTAG_IMAGELENGTH))], n_additional);
    free(samples);

    return add_samples;
}
