    pthread_mutex_lock(&allocator_lock);
    void* slab = mmap(NULL, getpagesize(), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (slab == MAP_FAILED) {
        // Handle error
    }

    LTE_PHY_RX_TARGET* target = (LTE_PHY_RX_TARGET*)slab;
    for (size_t i = 0; i < lte_target_count; ++i) {
        free_lte_target(target + i);
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)((char*)slab + lte_target_count * sizeof(LTE_PHY_RX_TARGET));
    for (size_t i = 0; i < nfapi_pdu_count; ++i) {
        free_nfapi_pdu(pdu + i);
    }

    munmap(slab, getpagesize());
    pthread_mutex_unlock(&allocator_lock);
}

