#define RNTI_MAX (UINT16_MAX / 2) // Ensure even values for RNTI
#define CRCI_CRCFLAG_VALID 0x01
#define CRCI_CRCFLAG_INVALID 0x00
#define LOG_LEVEL_DEBUG 0
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_WARNING 2
#define LOG_LEVEL_ERROR 3

typedef enum {
    CRC_INDICATION_REL8_TAG,
    // Add more tags as needed
} CRCI_TAG_T;

struct RNTI {
    uint16_t value;
};

struct NFAPI_CRC_INDICATION_PDU_T {
    CRCI_TAG_T tag;
    struct RNTI rnti;
    uint8_t crcflag;
};

int populateNFABundle(const char *filename, size_t *num_valid_items, struct NFAPI_CRC_INDICATION_PDU_T **pdus, int log_level) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    rewind(file);

    void *buffer = mmap(NULL, file_size, PROT_READ, MAP_PRIVATE, fileno(file), 0);
    if (buffer == MAP_FAILED) {
        perror("Error mapping file");
        fclose(file);
        return 2;
    }

    size_t buffer_index = 0;
    size_t num_loaded_items = 0;
    struct NFAPI_CRC_INDICATION_PDU_T *pdus_buffer = malloc(16 * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus_buffer) {
        perror("Error allocating memory for PDUs");
        munmap(buffer, file_size);
        fclose(file);
        return 3;
    }

    while (buffer_index < file_size) {
        struct NFAPI_CRC_INDICATION_PDU_T *pdu = &pdus_buffer[num_loaded_items];
        if (fread(pdu, sizeof(struct NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) {
            perror("Error reading PDUs");
            free(pdus_buffer);
            munmap(buffer, file_size);
            fclose(file);
            return 4;
        }

        if (pdu->tag != CRC_INDICATION_REL8_TAG) {
            continue; // Skip invalid PDUs
        }

        if ((pdu->rnti.value >= RNTI_MAX) || (pdu->rnti.value % 2)) {
            // Invalid RNTIs are skipped
            continue;
        }

        bool valid_crcflag = (pdu->crcflag == CRCI_CRCFLAG_VALID);

        if (!valid_crcflag && (log_level >= LOG_LEVEL_WARNING)) {
            printf("Warning: Invalid CRC flag value\n");
        }

        if (valid_crcflag) {
            num_loaded_items++;

            if ((num_loaded_items == pdus_buffer->size) && (pdus_buffer->size < num_loaded_items * 2)) {
                struct NFAPI_CRC_INDICATION_PDU_T *new_pdus_buffer = realloc(pdus_buffer, num_loaded_items * 2 * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
                if (!new_pdus_buffer) {
                    perror("Error reallocating memory for PDUs");
                    free(pdus_buffer);
                    munmap(buffer, file_size);
                    fclose(file);
                    return 5;
                }
                pdus_buffer = new_pdus_buffer;
            }
        }
    }

    *num_valid_items = num_loaded_items - (buffer_index / sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    *pdus = pdus_buffer;

    munmap(buffer, file_size);
    fclose(file);

    return 0;
}
