#include <stdlib.h>
#include <stdio.h>
#include <stdbool.h>

#define LTE_PHY_RX_TARGET 100
#define LTE_RX_SUBFRAME_INFO_CACHE_SIZE 4096

typedef struct {
    int subframes_count;
    LTE_RX_SUBFRAME_INFO* data;
} LTE_PHY_RX_TARGET;

// A simple LRU cache for LTE_RX_SUBFRAME_INFO arrays.
struct lru_cache {
    size_t capacity;
    size_t count;
    LTE_RX_SUBFRAME_INFO cache[LTE_RX_SUBFRAME_INFO_CACHE_SIZE];
    int head, tail;
};

void init_lru_cache(struct lru_cache* cache) {
    cache->head = 0;
    cache->tail = 0;
    cache->capacity = LTE_RX_SUBFRAME_INFO_CACHE_SIZE;
    cache->count = 0;
}

int lru_cache_get(struct lte_rx_subframe_info** result, struct lru_cache* cache, const int key) {
    for (int i = cache->head; i != cache->tail; i = (i + 1) % cache->capacity) {
        if (cache->cache[i].key == key) {
            *result = &cache->cache[i].data;
            // Move the accessed item to the head of the cache.
            cache->head = i;
            return 0;
        }
    }
    return -1;
}

int lru_cache_set(struct lte_rx_subframe_info** result, struct lru_cache* cache, const int key, LTE_RX_SUBFRAME_INFO* data) {
    for (int i = cache->head; i != cache->tail; i = (i + 1) % cache->capacity) {
        if (cache->cache[i].key == key) {
            *result = &cache->cache[i].data;
            // Replace the old data with the new one.
            cache->cache[i].data = data;
            // Move the accessed item to the head of the cache.
            cache->head = i;
            return 0;
        }
    }

    if (cache->count >= cache->capacity) {
        // Evict the least recently used item from the cache.
        int lru_index = (cache->tail + 1) % cache->capacity;
        *result = &cache->cache[lru_index].data;
        cache->count--;
    }

    cache->cache[cache->tail].key = key;
    *result = &cache->cache[cache->tail++].data;
    memcpy(*result, data, sizeof(LTE_RX_SUBFRAME_INFO));
    return 1;
}

void init_dynamic_array(LTE_PHY_RX_TARGET** targets, size_t* targets_count) {
    *targets = malloc(LTE_PHY_RX_TARGET * sizeof(LTE_PHY_RX_TARGET));
    (*targets)[0].subframes_count = 0;
    (*targets)[0].data = NULL;
    *targets_count = 1;

    struct lru_cache subframe_info_cache;
    init_lru_cache(&subframe_info_cache);

    for (size_t i = 1; i < LTE_PHY_RX_TARGET; ++i) {
        (*targets)[i].data = malloc(sizeof(LTE_RX_SUBFRAME_INFO));
        (*targets)[i].subframes_count = 0;
        // Allocate a new subframe info cache for each target if needed.
        if (i % 16 == 0) {
            init_lru_cache(&(*targets)[i].cache);
        } else {
            (*targets)[i].cache = &subframe_info_cache;
        }
    }
}
