void init_logging_service() {
    pthread_mutex_init(&log_service.lock, NULL);
    log_service.connected = false;
    log_service.cache = NULL;
    log_service.cache_size = 1024;
    log_service.cache_index = 0;
}

LogEventRecord* create_log_event(int event_id, time_t timestamp, enum SEVERITY_LEVEL severity, char* message) {
