    new_record->EVENT_ID = event_id;
    new_record->TIME_STAMP = timestamp;
    new_record->SEVERITY_LEVEL = severity;
    new_record->LOG_MESSAGE = message;
    new_record->next = NULL;
    return new_record;
}

