    if (!log_service.cache) {
        log_service.cache = new_record;
    } else {
        LogEventRecord *current = log_service.cache;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_record;
    }
    pthread_mutex_unlock(&log_service.lock);
}

