#define RECORD_BUFFER_SIZE 64
#define MAX_RECORDS (sizeof(void*) * (getpagesize() - sizeof(void*))) // Approximate number of records based on page size and pointer size
#define MEMORY_LIMIT (1024 * 1024 * 10) // Example memory limit: 10 MB

typedef struct record {
    int key;
    long offset;
    char buffer[RECORD_BUFFER_SIZE];
} Record;

struct mem_manager {
    Record* records;
    size_t num_records;
    size_t total_used;
    pthread_mutex_t mutex;
};

void init_mem_manager(struct mem_manager* manager, size_t max_records) {
    manager->records = malloc(max_records * sizeof(Record));
    manager->num_records = 0;
    manager->total_used = 0;
    pthread_mutex_init(&manager->mutex, NULL);
}

struct mem_record {
    struct mem_manager* manager;
    size_t index;
};

void* record_buffer(void* data) {
    struct mem_record* record = data;
    return &record->manager->records[record->index].buffer;
}

Record* allocate_record(struct mem_manager* manager, int key, long offset) {
    if (manager->total_used + sizeof(Record) + RECORD_BUFFER_SIZE > MEMORY_LIMIT) return NULL;

    Record* record = &manager->records[manager->num_records];
    record->key = key;
    record->offset = offset;

    manager->total_used += sizeof(Record) + RECORD_BUFFER_SIZE;
    manager->num_records++;

    return record;
}

void free_record(struct mem_manager* manager, Record* record) {
    pthread_mutex_lock(&manager->mutex);

    if (record >= manager->records && record < manager->records + manager->num_records) {
        manager->total_used -= sizeof(Record) + RECORD_BUFFER_SIZE;
        manager->num_records--;
    }

    pthread_mutex_unlock(&manager->mutex);
}

void reclaim_memory(struct mem_manager* manager) {
    if (manager->total_used <= MEMORY_LIMIT / 2 || manager->num_records < MAX_RECORDS) return;

    size_t num_to_free = manager->num_records - MAX_RECORDS;

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < num_to_free; ++i) {
        Record* record = &manager->records[i];
        memmove(&manager->records[i], &manager->records[i + num_to_free], sizeof(Record));
    }

    manager->num_records -= num_to_free;
    manager->total_used -= num_to_free * (sizeof(Record) + RECORD_BUFFER_SIZE);

    pthread_mutex_unlock(&manager->mutex);
}
```

This code provides a basic memory management structure for the task. The `mem_manager` struct holds an array of records, its current size, and total used bytes. It also has a mutex to ensure thread safety.

The `allocate_record()` function checks if there is enough available memory before allocating a new record. If not, it returns NULL. The record's key, offset, and buffer are initialized within the struct.

The `free_record()` function decrements the number of records and total used bytes when freeing a record.

The `reclaim_memory()` function reclaims memory if needed by moving records around and adjusting the total used bytes and number of records accordingly. This is done when memory usage exceeds half the limit or when there are more than MAX_RECORDS in use.

It's important to note that this code does not include any mechanisms for monitoring memory usage or performance metrics, which would require additional instrumentation. The code also assumes that access patterns are relatively uniform across records and does not handle extreme cases of cache thrashing caused by non-uniform access."]

