    deque->size = 0;
    return deque;
}

void destroy_deque(deque_t* deque) {
    // Iterate over the list and free memory
    if (!deque) return;

    deque_node_t* current = deque->head;
    while (current != NULL) {
        deque_node_t* temp = current;
        current = current->next;
        free(temp);
    }

    free(deque);
}

void enqueue(deque_t* deque, ue_context_t context) {
    // Add a node at the end of the list
    deque_node_t* new_node = malloc(sizeof(deque_node_t));
    if (!new_node) return;

    new_node->context = context;
    new_node->next = NULL;
    new_node->prev = deque->tail;

    if (is_empty(deque)) {
        deque->head = new_node;
    } else {
        deque->tail->next = new_node;
    }

    deque->tail = new_node;
    ++(deque->size);
}

ue_context_t* dequeue(deque_t* deque) {
    // Remove and return the first node from the list
    if (is_empty(deque)) return NULL;

    ue_context_t* context = &deque->head->context;
    deque_node_t* to_remove = deque->head;
    deque->head = deque->head->next;

    if (deque->head) {
        deque->head->prev = NULL;
    } else {
        deque->tail = NULL;
    }

    to_remove->next = NULL;
    --(deque->size);
    return context;
}

bool is_empty(const deque_t* deque) {
    if (!deque) return true;
    return deque->size == 0;
}
