    for (i = 0; i < num_records + 1; ++i) {
        longs[i] = i % constant;
    }

    // Initialize keys and indices
    for (i = 0, j = 0; i < num_records; ++i) {
        keys[j++] = i * multiplier;
        indices[i] = i;
    }

    // Initialize records
    for (i = 0; i < num_records; ++i) {
        records[i].long_ptr = &longs[indices[i]];
        records[i].integer = keys[i] + rand() % 100;
        records[i].char_buf = (char*)custom_malloc(1000);
        snprintf(records[i].char_buf, 1000, "%d%06ld%.*s", i, *records[i].long_ptr, 20, rand_strings());
