char* rand_strings() {
    static char rand_chars[256];
    static int idx = 0;
    if (idx == 256) {
        for (int i = 0; i < 256; ++i) {
            rand_chars[i] = (char)(rand() % 128);
        }
        idx = 0;
    }
    return &rand_chars[idx++];
}

