// Add a node with given RNTI if it doesn't exist or update it if it does
void add_or_update(NFAPI_CRC_INDICATION_PDU_T data) {
    list_node_t* current = &head; // Start from the head of the list
    while (current != &tail && current->next != &head) {
        if (current->next->data.rnti == data.rnti) { // If RNTI matches, update the data
            current->next->data = data;
            current->next->last_modified_time = time(NULL);
            current->next->last_modified_rnti = current->rnti;
            return;
        }
        current = current->next;
    }

    // If we reach the end of the list and no match is found, add a new node
    if (atomic_int_inc(&count) > MAX_LIST_SIZE) {
        // Handle the edge case where the list size exceeds the maximum allowed
        // For example, you could remove the oldest entry or drop the newest one based on timestamp
    }

    list_node_t* new_node = new_node(data);
    if (!new_node) return; // Handle memory allocation errors

    list_node_t* next = current->next;
    current->next = new_node;
    new_node->next = next;

    // If we added a new node at the end, update tail pointer
    if (!next) {
        tail = new_node;
        new_node->next = &head;
    }
}

// Remove a node with given RNTI
void remove(RNTI rnti) {
    list_node_t* current = &head;
    while (current != &tail && current->next != &head) {
        if (current->next->data.rnti == rnti) { // If RNTI matches, remove the data
            list_node_t* temp = current->next;
            current->next = temp->next;

            // Update tail pointer if we removed the last node before tail
            if (current->next == &head) tail = current;

            free(temp);
            atomic_int_dec(&count);
            return;
        }
        current = current->next;
    }
}
