typedef struct MemoryPool {
    size_t block_size;
    void* mem_start;
    void* current_block;
    size_t num_blocks;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->mem_start = calloc(1, block_size);
    if (!pool->mem_start) {
        free(pool);
        return NULL;
    }

    pool->current_block = pool->mem_start;
    pool->num_blocks = 1;
    return pool;
}

void* allocate_from_pool(MemoryPool* pool) {
    if (pool->current_block + pool->block_size <= pool->mem_end) {
        void* block = pool->current_block;
        pool->current_block += pool->block_size;
        return block;
    } else {
        // Reallocate memory for the pool when it becomes fragmented
        size_t new_size = pool->num_blocks * pool->block_size * 2;
        void* new_mem = realloc(pool->mem_start, new_size);
        if (!new_mem) return NULL;

        pool->mem_end = new_mem + new_size;
        pool->current_block = new_mem + (pool->num_blocks * pool->block_size);
        pool->num_blocks *= 2;
        return pool->current_block;
    }
}

void free_to_pool(MemoryPool* pool, void* ptr) {
    if (ptr >= pool->mem_start && ptr < pool->mem_end) {
        pool->current_block = ptr;
    }
}

