#include <random>
#include <thread>
#include <mutex>
#include <algorithm>

struct Record {
    int value;
};

void initData(std::vector<long>& offsets, std::vector<int>& keys, std::vector<Record>& records) {
    const size_t arraySize = 512;
    const size_t recordPerThread = arraySize / std::thread::hardware_concurrency();
    auto randEngine = std::random_device{}();
    std::mt19937 rng(randEngine());
    std::uniform_int_distribution<int> dist(0, 65535);

    std::mutex mtx;

    std::vector<Record> localRecords(recordPerThread);
    for (size_t i = 0; i < recordPerThread; ++i) {
        localRecords[i].value = dist(rng);
    }

    std::vector<long> offsets_(1024);
    std::vector<int> keys_(1024);
    std::vector<Record> finalRecords(arraySize);

    auto setFinalData = [&](size_t start, size_t length) {
        std::lock_guard<std::mutex> lock(mtx);
        std::copy_n(localRecords.begin() + start, length, finalRecords.begin());
        std::reverse_copy(finalRecords.begin(), finalRecords.begin() + length, keys_.begin() + start);
    };

    std::vector<std::thread> threads;
    for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
        size_t threadStart = i * recordPerThread;
        threads.emplace_back(setFinalData, threadStart, recordPerThread);
    }

    for (auto& t : threads) {
        if (t.joinable()) {
            t.join();
        }
    }

    offsets = std::move(offsets_);
    keys = std::move(keys_);
    records = finalRecords;
}
