#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int key;
    NFAPI_CRC_INDICATION_PDU_T data;
} record;

struct rolling_list {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    long *offsets;
    int *keys;
    record *records;
};

void rolling_list_init(struct rolling_list *list, size_t capacity) {
    list->capacity = capacity;
    list->count = 0;

    list->offsets = malloc(sizeof(long) * (capacity + 1));
    list->keys = malloc(sizeof(int) * capacity);
    list->records = malloc(sizeof(record) * capacity);

    pthread_mutex_init(&list->lock, NULL);
}

void rolling_list_destroy(struct rolling_list *list) {
    free(list->offsets);
    free(list->keys);
    free(list->records);
    pthread_mutex_destroy(&list->lock);
}

int get_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

record *rolling_list_get(struct rolling_list *list, size_t index) {
    record *record = &list->records[index];
    if (list->count == 0 || index >= list->capacity) {
        return NULL;
    }
    pthread_mutex_lock(&list->lock);
    int key = list->keys[index];
    record data = record{key, {RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, get_random(0, 1)}};
    pthread_mutex_unlock(&list->lock);
    return &data;
}

void rolling_list_add(struct rolling_list *list, record *record) {
    if (list->count >= list->capacity) {
        size_t index = (list->count - 1) % list->capacity;
        free(list->records[index.offsets[index]]);
        list->keys[index] = -1;
    }
    pthread_mutex_lock(&list->lock);
    long *current_offset = &list->offsets[list->count];
    int *current_key = &list->keys[list->count];
    record *current_record = list->records + list->count;
    *current_offset = index.offsets[index] + 1;
    *current_key = record->key;
    *current_record = *record;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}
