use tracing::{error, info, instrument, Instrument, span, Level};
use tokio::process::Command;
use tokio::task::spawn;
use tracing_subscriber::{fmt::layer, EnvFilter, Registry};
use panic_hook::PanicInfo;

#[derive(Serialize, Deserialize, Debug)]
struct AppConfig {
    name: String,
    path: String,
    args: Vec<String>,
}

#[tokio::main]
async fn run() -> Result<(), Box<dyn std::error::Error> {
    let mut filter_layer = layer()
        .with_filter(EnvFilter::from_default_env())
        .with_target(false);
    Registry::default().init().add_subscriber(filter_layer);

    let config_file = Path::new("config.json");
    let reader = BufReader::new(File::open(config_file).unwrap());
    let mut apps: Vec<AppConfig> = serde_json::from_reader(reader).unwrap();
    if apps.len() > 10 {
        error!("Configuration file contains more than 10 applications.");
        return Err(Box::new("Too many applications in the configuration"));
    }

    let mut reports: Vec<serde_json::Value> = Vec::new();

    for app in &apps {
        let span = span!(Level::INFO, "run_app", name = &app.name);
        info_span!(span).entered().instrument(|| {
            let command = Command::new(&app.path)
                .args(&app.args)
                .spawn()
                .instrument(|_, child| {
                    async move {
                        let start_time = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
                        let initial_rss = child.memory_info().resident_set_size();

                        match child.wait().await {
                            Ok(_) => {
                                let end_time = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
                                let final_rss = child.memory_info().resident_set_size();
                                let duration = end_time - start_time;

                                // Collect error, if any
                                let mut report = serde_json::Map::new();
                                report.insert("name".to_string(), serde_json::Value::String(app.name));
                                report.insert("start_time".to_string(), start_time);
                                report.insert("end_time".to_string(), end_time);
                                report.insert("duration".to_string(), duration);
                                report.insert("peak_rss".to_string(), serde_json::Value::Number(final_rss as f64));

                                match child.panic_info() {
                                    Some(panic) => {
                                        error!(?panic, "Application panic");
                                        report.insert("error".to_string(), serde_json::Value::String(format!("{}", panic)));
                                    }
                                    None => {}
                                }

                                reports.push(report);
                            }
                            Err(e) => {
                                error!(?e, "Application error");
                                let mut report = serde_json::Map::new();
                                report.insert("name".to_string(), serde_json::Value::String(app.name));
                                report.insert("error".to_string(), serde_json::Value::String(e.to_string()));
                                reports.push(report);
                            }
                        }
                    })
                });

            spawn(command).detach();
        });
    }

    // Wait for all tasks to complete before serializing and printing the results
    let _ = tokio::join_all(apps.len(), move |task| task.instrument(|_, child| {
        async move { child.await? }
    })).await;

    println!("{:#}", serde_json::to_string(&reports).unwrap());

    Ok(())
}
```

