} Record;

Record* records = NULL;
size_t num_records = 0;
size_t data_used = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void generate_record(Record *rec) {
    rec->key = rand() % 100 + 1;
    memset(rec->buffer, 0, RECORD_SIZE);
    for (size_t i = 0; i < RECORD_SIZE; ++i) {
        rec->buffer[i] = CHAR_SET[(rand() % (sizeof(CHAR_SET) - 1))];
    }
}

void* worker(void *arg) {
    while (num_records < MAX_RECORDS) {
        pthread_mutex_lock(&mutex);
        if (data_used + RECORD_SIZE > DATA_LIMIT) {
            pthread_mutex_unlock(&mutex);
            break;
        }
        Record *rec = &records[num_records];
        generate_record(rec);
        num_records++;
        data_used += RECORD_SIZE;
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

void initialize() {
    records = (Record*) malloc(MAX_RECORDS * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        exit(1);
    }
    pthread_t threads[MAX_THREADS];
    size_t num_threads = sysconf(_SC_NPROCESSORS_ONLINE);
    if (num_threads > MAX_THREADS) {
        num_threads = MAX_THREADS;
    }
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, worker, NULL);
    }
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void verify() {
    // Implement a mechanism to verify the integrity of the allocated data structures upon completion.
}

int main() {
    srand(time(NULL));
    initialize();
    verify();
    return 0;
}
