} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} node_t;

static node_t* head = NULL;
static size_t capacity = 0;
static size_t count = 0;
static const size_t max_capacity = 1024;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void nfapi_crc_indication_pdu_list_push(NFAPI_CRC_INDICATION_PDU_T pdu) {
    node_t* new_node = malloc(sizeof(node_t));
    if (!new_node) return;

    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list_mutex);
    if (count == capacity) {
        if (capacity >= max_capacity) {
            free(new_node);
            pthread_mutex_unlock(&list_mutex);
            return;
        }
        node_t** end = &head;
        while (*end) end = &((*end)->next);
        capacity++;
    }
    new_node->next = head;
    head = new_node;
    count++;
    pthread_mutex_unlock(&list_mutex);
}

bool nfapi_crc_indication_pdu_list_pop(NFAPI_CRFC_INDICATION_PDU_T* out) {
    pthread_mutex_lock(&list_mutex);
    if (count == 0) {
        pthread_mutex_unlock(&list_mutex);
        return false;
    }

    node_t* temp = head;
    *out = temp->data;
    head = temp->next;
    count--;
    free(temp);

    pthread_mutex_unlock(&list_mutex);
    return true;
}
```

