#include <string.h>

typedef struct Node {
    void* data; // dynamically allocated string or integer value
    int value;
    struct Node *next; // forward link for singly linked list mode
    struct Node *prev; // backward link for doubly linked list mode (optional)
} node_t;

// Memory Pool API (assume this is provided by a third-party library or custom implementation)
void* mempool_alloc(size_t size);
void mempool_free(void* ptr);

node_t* create_node(const char* data, int value) {
    node_t *new_node = (node_t*)mempool_alloc(sizeof(node_t));
    new_node->data = strdup(data);
    new_node->value = value;
    new_node->next = NULL;
    return new_node;
}

void switch_list_mode(node_t** list, int mode) {
    if (mode == 1) { // singly linked list
        ((node_t*)list)->prev = NULL;
    } else if (mode == 2) { // doubly linked list
        ((node_t*)list)->next = NULL;
    }
}

void insert_at_head(node_t** list, node_t* new_node) {
    new_node->next = *list;
    (*list) = new_node;
}

void insert_at_tail(node_t** list, node_t* new_node) {
    if (!*list) {
        *list = new_node;
        return;
    }
    node_t* current = *list;
    while (current->next) {
        current = current->next;
    }
    current->next = new_node;
}

void insert_at_position(node_t** list, int pos, node_t* new_node) {
    if (!pos) {
        insert_at_head(list, new_node);
        return;
    }
    node_t *current = *list;
    for (int i = 0; i < pos - 1 && current->next; ++i) {
        current = current->next;
    }
    if (!current->next) {
        insert_at_tail(list, new_node);
        return;
    }
    new_node->next = current->next;
    current->next = new_node;
}

void delete_range(node_t** list, int start, int end) {
    node_t *current = *list;
    for (int i = start; i < end && current; ++i) {
        if (i == start) {
            *list = current->next;
            current->next->prev = NULL;
            current->prev = NULL;
        } else if (current->next) {
            node_t* next = current->next;
            current->next = next->next;
            next->next->prev = current;
            next->prev = NULL;
            free(next->data);
            mempool_free(next);
        }
        current = current->next;
    }
}

node_t* search_by_value(const node_t** list, int value) {
    for (node_t *current = *list; current; current = current->next) {
        if (current->value == value) {
            return current;
        }
    }
    return NULL;
}

void free_list(node_t** list) {
    node_t* current = *list;
    while (current) {
        node_t* next = current->next;
        free(current->data);
        mempool_free(current);
        current = next;
    }
}
