// Custom memory pool for LTE_RX_SUBFRAME_INFO
typedef struct {
    void *pool;
    size_t free_count;
    size_t total_allocated;
} MemPool;

// Initialize custom memory pool
MemPool lte_rx_subframe_info_mempool_init(size_t initial_size) {
    MemPool pool = {.pool = mmap(NULL, initial_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0),
                    .free_count = initial_size,
                    .total_allocated = initial_size};
    return pool;
}

// Allocate from memory pool
void *lte_rx_subframe_info_mempool_alloc(MemPool *pool) {
    if (pool->free_count > 0) {
        void *result = (char *)pool->pool + (--pool->free_count);
        return result;
    } else {
        size_t new_size = pool->total_allocated * 2;
        pool->pool = realloc(pool->pool, new_size);
        if (!pool->pool) {
            // Handle error and log details
            syslog(LOG_ERR, "Memory allocation failed");
            exit(-1);
        }
        pool->free_count += new_size;
        return (char *)pool->pool + (--pool->free_count);
    }
}

// Free to memory pool
void lte_rx_subframe_info_mempool_free(MemPool *pool, void *ptr) {
    if (!pool || !ptr) {
        return;
    }

    char *p = (char *)ptr - ((char *)pool->pool - (char *)&pool->free_count);
    if (p >= pool->pool && p < (char *)pool->pool + pool->free_count) {
        ++pool->free_count;
    } else {
        // Handle error and log details
        syslog(LOG_ERR, "Invalid memory pool free request");
        exit(-1);
    }
}

