using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;
using Newtonsoft.Json;
using Newtonsoft.Json.Converters;
using Newtonsoft.Json.Serialization;

public class DeviceBase
{
    public int Id { get; set; }
}

[JsonConverter(typeof(CustomContractResolver))]
public abstract class NetworkDevice : DeviceBase
{
    // Common properties for all device types
}

public class Router : NetworkDevice
{
    public string GatewayIp { get; set; }
    // Other specific router properties
}

public class Switch : NetworkDevice
{
    public int PortCount { get; set; }
    // Other specific switch properties
}

// Custom ContractResolver for polymorphic deserialization
public class CustomContractResolver : DefaultContractResolver
{
    protected override JsonProperty CreateProperty(MemberInfo member, MemberSerialization memberSerialization)
    {
        var property = base.CreateProperty(member, memberSerialization);

        if (property.ValueProvider == null && member.DeclaringType != typeof(DeviceBase))
        {
            property.ValueProvider = new StaticValueProvider<NetworkDevice>(null as NetworkDevice);
        }

        return property;
    }
}

// CustomConverter for handling circular references
public class CircularReferenceHandler : DefaultContractResolver
{
    private readonly Dictionary<string, object> _circularReferenceCache = new();

    protected override JsonSerializer CreateJsonSerializer()
    {
        var serializer = base.CreateJsonSerializer();
        serializer.Converters.Add(new CircularReferenceConverter(_circularReferenceCache));
        return serializer;
    }
}

public class CircularReferenceConverter<T> : DefaultContractResolver, IContractResolver
{
    private readonly Dictionary<string, object> _circularReferenceCache;

    public CircularReferenceConverter(Dictionary<string, object> circularReferenceCache)
    {
