#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ITEMS 16
#define DEFAULT_PRODUCT_NAME "Unknown Product"

typedef struct Item {
    double value;
    char *name;
} Item;

typedef struct Collection {
    Item *items;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    char cache[MAX_ITEMS][256];
} Collection;

void init_collection(Collection* collection) {
    collection->capacity = MAX_ITEMS;
    collection->count = 0;
    collection->items = malloc(sizeof(Item) * collection->capacity);
    memset(collection->cache, 0, sizeof(collection->cache));
    pthread_mutex_init(&(collection->mutex), NULL);
}

void resize_collection(Collection* collection) {
    Item *new_items = realloc(collection->items, (collection->capacity + MAX_ITEMS) * sizeof(Item));
    if (!new_items) return;
    collection->items = new_items;
    collection->capacity += MAX_ITEMS;
}

void add_item(Collection* collection, double value, const char* name) {
    pthread_mutex_lock(&(collection->mutex));
    if (collection->count == collection->capacity) resize_collection(collection);

    // Cache product names to reduce API calls
    size_t index = collection->count;
    if (!strstr(name, collection->cache[index])) {
        strcpy(collection->cache[index], name);
        // Fetch product name from database here
    }

    collection->items[index].value = value;
    collection->items[index].name = (char*) malloc(strlen(name) + 1);
    strcpy(collection->items[index].name, name);
    collection->count++;

    pthread_mutex_unlock(&(collection->mutex));
}

Item* get_item(Collection* collection, size_t index) {
    pthread_mutex_lock(&(collection->mutex));
    Item *item = &collection->items[index];
    if (!item->name || !item->value) {
        item->value = 0.0;
        strcpy(item->name, DEFAULT_PRODUCT_NAME);
    }
    pthread_mutex_unlock(&(collection->mutex));
    return item;
}
```

