        if (!rnti_set[states[i]]) {
            NFAPI_CRC_INDICATION_PDU *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
            if (new_node == NULL) goto cleanup;

            new_node->RNTI = states[i];
            new_node->CRCFLAG = (rand() % 2) ? true : false;
            new_node->next = NULL;

            if (!head) {
                head = new_node;
                current = head;
            } else {
