            auto it = config.find(key);
            if (it != config.end())
                return it->second;
            throw std::invalid_argument("Invalid configuration key");
        }
    };

    class DataChunk {
    public:
        virtual ~DataChunk() {}
        virtual void decompress() = 0;
        virtual size_t size() const = 0;
    };

    class CompressedDataChunk : public DataChunk {
        unsigned char* data;
        size_t dataSize;

    public:
        CompressedDataChunk(const std::vector<unsigned char>& compressedData)
            : data(new unsigned char[compressedData.size()]), dataSize(0) {
            std::memcpy(data, &compressedData[0], compressedData.size());
            decompress();
        }

        void decompress() {
            uLongf destLen = dataSize;
            unsigned char* dest = data;
            uLongf sourceLen = dataSize;
            unsigned char* source = reinterpret_cast<unsigned char*>(data);

            auto status = uncompress(dest, &destLen, source, &sourceLen);
            if (status != Z_OK) {
                std::cerr << "Error decompressing data: " << status << std::endl;
                // Handle error
            }
        }

        size_t size() const override {
            return dataSize;
        }
    };

    class DataSource {
