        std::vector<std::unique_ptr<DataSource>> sources;
        std::map<std::string, double> chunkSummary;
        std::mutex summaryMutex;
        std::unique_ptr<boost::asio::io_context> ioContext;
        std::unique_ptr<DataChunkPool> dataPool;
        std::unique_ptr<ThreadSafeQueue<DataChunk*>> dataIncomingQueue;
        std::unique_ptr<std::function<void(const DataChunk&)>> dataValidator;
        unsigned seed;

    public:
        RealTimeDataProcessor(Config& config, const std::vector<std::string>& sourceHosts, int sourcePort, int numThreads)
            : DataSource(boost::asio::io_context(), config, sourceHosts[0], sourcePort), dataPool(new DataChunkPool()),
              dataIncomingQueue(new ThreadSafeQueue<DataChunk*>()), seed(std::time(NULL)) {
            for (const auto& host : sourceHosts)
                sources.emplace_back(std::make_unique<DataSource>(*this->ioContext, this->config, host, sourcePort));
            ioContext.reset(new boost::asio::io_context(numThreads));
        }

        void start() override {
            for (auto& source : sources)
                source->start();
            this->ioContext->run();
        }

        void stop() override {
            ioContext->stop();
            for (auto& source : sources)
                source->stop();
        }

