using Microsoft.Extensions.Logging;

[Route("api/[controller]")]
[ApiController]
public class ElementController : ControllerBase
{
    private readonly IElementService _elementService;
    private readonly ILogger<ElementController> _logger;

    public ElementController(IElementService elementService, ILogger<ElementController> logger)
    {
        _elementService = elementService;
        _logger = logger;
    }

    [HttpPost("{pageSectionId}/{elementId}")]
    public ActionResult Post([FromRoute] int pageSectionId, [FromRoute] int elementId, [FromBody] string htmlContent)
    {
        if (pageSectionId < 1 || pageSectionId > int.MaxValue / 2 || elementId < 0 || elementId > int.MaxValue / 4)
            return BadRequest($"Invalid parameters: pageSectionId={pageSectionId} and elementId={elementId}");

        if (!IsWellFormedHtml(htmlContent))
            return BadRequest("Invalid HTML content");

        var allowedTags = new List<string> { /* add your allowed tags here */ };
        var regex = string.Join("|", allowedTags);
        var tagsPattern = Regex.Compile($"<({regex})+>", RegexOptions.IgnoreCase | RegexOptions.Singleline);

        if (!tagsPattern.IsMatch(htmlContent))
            return BadRequest("HTML content contains unsupported tags");

        try
        {
            var result = _elementService.UpdateElementHtml(pageSectionId, elementId, htmlContent);
            if (result.Item1)
            {
                _logger.LogInformation($"Updated element {elementId} in page section {pageSectionId} for user {User.Identity.Name} at {DateTime.UtcNow:yyyy-MM-dd HH:mm:ss}");
                return Ok(result.Item2);
            }
            else
            {
                _logger.LogWarning($"Failed to update element {elementId} in page section {pageSectionId} for user {User.Identity.Name} at {DateTime.UtcNow:yyyy-MM-dd HH:mm:ss}: {result.Item2}");
                return StatusCode(500, result.Item2);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError($"An error occurred while updating element {elementId} in page section {pageSectionId} for user {User.Identity.Name} at {DateTime.UtcNow:yyyy-MM-dd HH:mm:ss}: {ex}");
            return StatusCode(500, "An internal server error occurred");
        }
    }

    private bool IsWellFormedHtml(string htmlContent)
    {
        try
        {
            var doc = new HtmlDocument();
            doc.LoadHtml(htmlContent);
            return true;
        }
        catch (Exception)
        {
            return false;
        }
    }
}
