#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <zip.h>
#include <stdlib.h>
#include <errno.h>
#include <inttypes.h>
#include <unistd.h>
#include <limits.h>

typedef struct {
    int compression_level;
    uintmax_t max_size_threshold;
} Options;

int compress_file(const char *filename, const char *target_dir, const Options *options) {
    ZIP *zip = NULL;
    zip_file_t *zip_file = NULL;
    struct stat file_stat, dir_stat;
    FILE *file = NULL;
    size_t read_bytes;
    char target_path[PATH_MAX];
    int error = 0;

    // Check if the directory exists and has sufficient space.
    snprintf(target_path, sizeof(target_path), "%s/%s", target_dir, zip_name);
    if (stat(target_path, &dir_stat) < 0 || S_ISDIR(dir_stat.st_mode)) {
        if (S_ISDIR(dir_stat.st_mode)) {
            // Directory exists, check available space.
            if ((dir_stat.st_size + sizeof(struct stat)) > dir_stat.st_blocks) {
                fprintf(stderr, "Error: Insufficient disk space in target directory.\n");
                error = 1;
                goto cleanup;
            }
        } else {
            // Target is not a directory, create it if it doesn't exist.
            mkdir(target_path, S_IRWXU | S_IRGRP | S_IROTH);
            if (errno != 0) {
                fprintf(stderr, "Error: Failed to create target directory: %s\n", strerror(errno));
                error = 1;
                goto cleanup;
            }
        }
    } else {
        // Target does not exist or is not a directory.
        fprintf(stderr, "Error: The specified target path is invalid.\n");
        error = 1;
        goto cleanup;
    }

    // Check if the file exists and has sufficient space in the source directory.
    if (stat(filename, &file_stat) < 0 || S_ISREG(file_stat.st_mode)) {
        if (S_ISREG(file_stat.st_mode)) {
            // File exists, check available space.
            if ((file_stat.st_size + sizeof(struct stat)) > file_stat.st_blocks) {
                fprintf(stderr, "Error: Insufficient disk space in source directory.\n");
                error = 1;
                goto cleanup;
            }
        } else {
            // File does not exist.
            fprintf(stderr, "Error: The specified file path is invalid.\n");
            error = 1;
            goto cleanup;
        }
    }

    zip = zip_open(target_path, 0, &error);
    if (!zip || error) {
        if (error == ZIP_ERRCODE_NOMEM) {
            fprintf(stderr, "Error: Failed to allocate memory for the ZIP archive.\n");
        } else {
            fprintf(stderr, "Error: Failed to create ZIP archive: %s\n", zip_get_error(zip));
        }
        error = 1;
        goto cleanup;
    }

    zip_file = zip_open_new_file(zip, filename, NULL /* compression method */, options->compression_level);
    if (!zip_file || error) {
        fprintf(stderr, "Error: Failed to open file for compression: %s\n", zip_get_error(zip));
        error = 1;
        goto cleanup;
    }

    file = fopen(filename, "rb");
    if (!file || error) {
        fprintf(stderr, "Error: Failed to open file for reading: %s\n", strerror(errno));
        error = 1;
        goto cleanup;
    }

    uintmax_t compressed_size = 0;
    while ((read_bytes = fread(zip_file->buffer, 1, sizeof(zip_file->buffer), file)) > 0) {
        if (compressed_size + read_bytes > options->max_size_threshold) {
            fprintf(stderr, "Error: The compressed size exceeded the maximum threshold.\n");
            error = 1;
            break;
        }

        zip_writeinbuffer(zip_file);
        compressed_size += read_bytes;
    }

cleanup:
    if (file) fclose(file);
    if (zip_file) zip_fclose(zip_file, 0);
    if (zip) zip_close(zip);

    return error ? -1 : 0;
}
```']

