typedef struct {
    long* offsets;
    size_t size;
} Offset;

typedef struct {
    int* keys;
    size_t count;
} Key;

typedef struct {
    int *value;
    Offset *offset;
    Key *key;
} Record;

#define MAX_OFFSETS 1000000
#define MAX_KEYS 1000000

Offset* initialize_offsets(size_t size) {
    if (size > MAX_OFFSETS) {
        fprintf(stderr, "Error: Array size exceeds predefined limit\n");
        return NULL;
    }

    Offset *offsets = malloc(sizeof(Offset) * size);
    if (!offsets) {
        perror("Memory allocation error");
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        offsets[i].offsets = malloc(sizeof(long) * OFFSET_SIZE);
        if (!offsets[i].offsets) {
            perror("Memory allocation error");
            free(offsets);
            return NULL;
        }
        offsets[i].size = OFFSET_SIZE;
    }

    return offsets;
}

Key* initialize_keys(size_t count) {
    if (count > MAX_KEYS) {
        fprintf(stderr, "Error: Key array count exceeds predefined limit\n");
        return NULL;
    }

    Key *keys = malloc(sizeof(Key) * count);
    if (!keys) {
        perror("Memory allocation error");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        keys[i].keys = malloc(sizeof(int) * KEY_SIZE);
        if (!keys[i].keys) {
            perror("Memory allocation error");
            free(keys);
            return NULL;
        }
        keys[i].count = KEY_SIZE;
    }

    return keys;
}

Record* initialize_records(size_t size, Offset *offsets, Key *keys) {
    if (!offsets || !keys) {
        perror("Invalid input parameters");
        return NULL;
    }

    Record *records = malloc(sizeof(Record) * size);
    if (!records) {
        perror("Memory allocation error");
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        records[i].value = malloc(sizeof(int));
        records[i].offset = &offsets[i];
        records[i].key = &keys[random() % count];

        // Efficient random number generation within a specified range
        *records[i].value = (rand() % RANGE) + MIN_VALUE;
    }

    return records;
}

void destroy(Offset *offsets, Key *keys, Record *records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}

Offset* init_and_allocate_data_structures(size_t offset_size, size_t key_count, size_t record_count, size_t OFFSET_SIZE, size_t KEY_SIZE, size_t RANGE) {
    Offset *offsets = initialize_offsets(offset_size);
    if (!offsets) goto cleanup;

    Key *keys = initialize_keys(key_count);
    if (!keys) goto cleanup;

    Record *records = initialize_records(record_count, offsets, keys);
    if (!records) goto cleanup;

    return offsets;

cleanup:
    destroy(offsets, keys, records);
    return NULL;
}
```

