#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    long* data;
    size_t size;
} offset;

typedef struct {
    int* data;
    size_t size;
} key;

typedef struct {
    int value;
    int key_index;
} record;

bool allocate_and_init(size_t config, offset** offsets, key** keys, record** records) {
    *offsets = malloc(config * sizeof(offset));
    if (!*offsets) {
        free_all(*keys, *records);
        return false;
    }
    for (size_t i = 0; i < config; ++i) {
        (*offsets)[i].data = malloc((config + 5) * sizeof(long));
        if (!(*offsets)[i].data) {
            free(*offsets);
            free_all(*keys, *records);
            return false;
        }
        memset((*offsets)[i].data, 0, (config + 5) * sizeof(long));
    }

    *keys = malloc(config / 2 * sizeof(key));
    if (!*keys) {
        free(*offsets);
        free_all(*records);
        return false;
    }
    for (size_t i = 0; i < config / 2; ++i) {
        (*keys)[i].data = malloc((config / 2) * sizeof(int));
        if (!(*keys)[i].data) {
            free(*offsets);
            free(*keys);
            free_all(*records);
            return false;
        }
        for (size_t j = 0; j < (config / 2); ++j)
            (*keys)[i].data[j] = i * 2 + j;
    }

    size_t total_size = config * sizeof(key) + config * sizeof(offset) + config / 2 * sizeof(record);
    *records = malloc(total_size);
    if (!*records) {
        free(*offsets);
        free(*keys);
        return false;
    }
    record* current_record = (record*)*records;

    srand(time(NULL));
    for (size_t i = 0, idx = 0; i < config; ++i) {
        size_t key_idx = (*keys)[idx].data[idx % ((config / 2))];
        current_record->value = (*offsets)[key_idx].data[idx % (config + 5)] + rand() % 201 - 100;
        current_record->key_index = key_idx;
        ++current_record;
        if ((idx + 1) % (config / 2) == 0)
            idx += (config / 2);
    }

    return true;
}

void free_all(key keys[], record records[]) {
    for (size_t i = 0; i < keys_size(keys); ++i)
        free(keys[i].data);
    free(keys);

    for (size_t i = 0; i < records_size(records); ++i)
        ; // Do nothing as the memory is already freed when records are allocated
}

size_t keys_size(key keys[]) { return keys ? (sizeof(keys) / sizeof(key)) : 0; }
size_t records_size(record records[]) { return records ? (sizeof(records) / sizeof(record)) : 0; }
