NFAPI_CRC_INDICATION_PDU_T* create_and_populate_nfaapi_crc_list(size_t N, uint32_t seed, size_t max_list_size) {
    if (N <= 0 || max_list_size <= 0) {
        fprintf(stderr, "Invalid input: N or max_list_size must be greater than zero.\n");
        return NULL;
    }

    // Allocate memory for the list and the required structures
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * max_list_size);
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for the list.\n");
        return NULL;
    }

    size_t num_structures = 0;
    for (size_t i = 0; i < max_list_size; ++i) {
        // Generate a new structure with unique RNTI and CRC_INDICATION_REL8_TAG values, and validate the RX_UE_INFORMATION_TAG
        NFAPI_CRC_INDICATION_PDU_T *structure = &list[i];
        uint32_t tag = generate_ue_tag(); // Generate UE-specific tag
        structure->RX_UE_INFORMATION_TAG = validate_rx_ue_information_tag(tag, "config.txt");
        structure->RNTI = generate_unique_rni(UINT16_MAX, NULL, 0);
        structure->CRC_INDICATION_REL8_TAG = rand() % 256;

        if (structure->RX_UE_INFORMATION_TAG != UINT32_MAX) {
            ++num_structures;
        }

        if (num_structures == N) break;
    }

    // Resize the list to the actual number of structures
    list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structures);

    return list;
}
